-- Run as an authorized migration in development or staging. No personal data.
begin;
create table if not exists public.humanology_catalog_releases (
  version text primary key,
  payload jsonb not null check (jsonb_typeof(payload->'cards') = 'array'
    and jsonb_typeof(payload->'benefits') = 'array'
    and payload->>'catalog_version' = version)
);
alter table public.humanology_catalog_releases enable row level security;
revoke all on public.humanology_catalog_releases from public, anon, authenticated;
grant select on public.humanology_catalog_releases to anon, authenticated;
do $policy$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public'
    and tablename = 'humanology_catalog_releases' and policyname = 'read_catalog_release') then
    create policy read_catalog_release on public.humanology_catalog_releases
      for select to anon, authenticated using (true);
  end if;
end $policy$;
insert into public.humanology_catalog_releases(version,payload) values
('2026-11-27.1', $catalog${"schema_version":1,"catalog_version":"2026-11-27.1","cards":[{"card_id":"walk-after-meals","title":"Take short walks after a meal","action":"Choose the walking schedule that matches your situation below.","tracking_prompt":"Log the walks. Glucose is optional if you already monitor it.","goals":["metabolic"],"benefit_ids":["walk-after-meals-1","walk-after-meals-2","walk-after-meals-3"],"eligibility_rule":"read_studied_population","studied_population":"Adults sitting after meals. The ten-minute meal-timed schedule was tested in adults with type 2 diabetes.","qualification":"The brief walking breaks were compared with sitting. The ten-minute walks after meals were compared with one daily walk in people with type 2 diabetes. Use your usual diabetes exercise precautions.","time_commitment":"From 12 minutes per meal in the break example, or one ten-minute walk after each main meal.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42070794","22374636","42586449","42627002","27747394","36715875"],"research_summary":"Walking breaks and meal-timed walks have separate glucose comparisons. A timing review adds context for exercise soon after meals.","source_notes":[{"source_id":"42070794","role":"Direct pooled result","summary":"Across 39 pooled studies, activity breaks reduced the post-meal glucose and insulin response. Walking showed the largest subgroup effects. The comparison between break frequencies does not establish a uniquely best schedule."},{"source_id":"22374636","role":"Direct result, different timing","summary":"Nineteen adults with overweight or obesity had lower five-hour glucose and insulin responses with two-minute walks every 20 minutes than with uninterrupted sitting. Use for the benefit and the 20-minute interval."},{"source_id":"42586449","role":"Supporting subgroup","summary":"Short bouts of accumulated activity reduced post-meal glucose and insulin versus sitting in 29 cohorts. Walking and shorter intervals appeared beneficial in exploratory subgroup analyses. Timing was not compared with a formal interaction test."},{"source_id":"42627002","role":"Direct result and interval","summary":"Sixteen sedentary men completed five-hour test-drink conditions. Two-minute walks every 30 minutes reduced glucose exposure by 6.4% and insulin by 18.2% versus sitting. The three-hour app window is an adaptation."},{"source_id":"27747394","role":"Direct, diabetes variant","summary":"Adults with type 2 diabetes had about 12% less three-hour post-meal glucose exposure with ten minutes of walking after each main meal than with one untimed daily walk. This comparison supplies no insulin estimate."},{"source_id":"36715875","role":"Timing review","summary":"Acute studies generally favored exercising after eating for glucose. Exercise types and schedules varied. This review cannot establish the three-hour break schedule or the type 2 diabetes trial’s specific comparison."}]},{"card_id":"brisk-walking","title":"Make brisk walking a weekly habit","action":"Build toward a brisk 30-minute walk on five days a week. This is one practical schedule within the range studied.","tracking_prompt":"Compare weekly averages if you already take home blood pressure readings.","goals":["heart","movement"],"benefit_ids":["brisk-walking-1","brisk-walking-2","brisk-walking-3"],"eligibility_rule":"read_studied_population","studied_population":"Sedentary or lightly active adults, including adults with hypertension.","qualification":"The 30-minute schedule is a practical example. Start at a level you can manage. Seek advice if you have unstable cardiac symptoms or restrictions on brisk exercise.","time_commitment":"Practical example: 30 minutes on five days weekly, about 150 minutes per week.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["33630309","42405260","17275896"],"research_summary":"The systolic-pressure estimate comes from 73 walking trials. Broader exercise comparisons did not refine the card’s walking prescription.","source_notes":[{"source_id":"33630309","role":"Pooled research","summary":"Walking programs lowered average systolic pressure in adults. The review judged the diastolic result less certain and used a range of schedules."},{"source_id":"42405260","role":"Direct pooled result","summary":"Across 17 trials in adults with hypertension, both pressure measures fell. The full paper reports a pooled diastolic difference of −4.67 mmHg (95% CI −6.26 to −3.08). Its suggested optimal dose was modeled across trials."},{"source_id":"17275896","role":"Pooled research","summary":"Controlled trials in previously sedentary adults measured gains in aerobic fitness after regular walking. This supports the fitness benefit separately from blood pressure."}]},{"card_id":"stairs","title":"Choose a stair-climbing routine","action":"Choose one of the two studied schedules shown below. The evidence for the single-session schedule comes from one small trial in young men.","tracking_prompt":"Log sessions and effort. Daily resting heart rate is a separate observation.","goals":["movement"],"benefit_ids":["stairs-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Inactive young adults. The single-session schedule was studied in young men with obesity.","qualification":"Vigorous exercise studied in inactive young adults. The single-session trial enrolled young men with obesity. Use a safe staircase, stop for dizziness or chest pain, and avoid if vigorous climbing is unsuitable.","time_commitment":"Three short climbs across the day, or one approximately ten-minute session. Choose a schedule below.","display_evidence_in_details":true,"blocked_if":["vigorous_exercise_restriction"],"research_source_ids":["30649897","38569204","40087042"],"research_summary":"Two small trials support stair snacks. One trial supports the single-session option. Campus feasibility and blood-flow-restriction studies answer different questions.","source_notes":[{"source_id":"30649897","role":"Tested schedule","summary":"Inactive young adults climbed 60 stairs three times daily, separated by one to four hours. Fitness improved after six weeks."},{"source_id":"38569204","role":"Tested schedule","summary":"The short stair-bout group improved peak oxygen uptake after six weeks. The paper also measured fat oxidation, which did not improve."},{"source_id":"40087042","role":"Direct, single-session option","summary":"Young men with obesity completed a four-week vigorous stair program. Peak oxygen uptake improved relative to the pattern in controls. The study found no change in body composition or metabolic variables."}]},{"card_id":"almonds","title":"Make almonds a daily snack","action":"If almonds fit your diet, try a handful daily for at least four weeks. Trials used a range of portions.","tracking_prompt":"Log servings. A lipid panel measures cholesterol.","goals":["heart"],"benefit_ids":["almonds-1","almonds-2","almonds-3"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults","qualification":"Do not use with a tree nut allergy. Nuts add calories; swap rather than add.","time_commitment":"One serving daily for at least four weeks.","display_evidence_in_details":true,"blocked_if":["tree_nut_allergy"],"research_source_ids":["40944180","12221048","19394473"],"research_summary":"The newer review covers 36 publications. An earlier, smaller review was less conclusive for LDL. Its trials should not be added to the newer count.","source_notes":[{"source_id":"40944180","role":"Direct pooled result","summary":"In 36 publications, daily almonds lowered LDL by about 5 mg/dL, total cholesterol by about 6 mg/dL, and ApoB by about 4.5 mg/dL relative to controls across varying amounts."},{"source_id":"12221048","role":"Direct LDL trial","summary":"Whole almonds used as snacks lowered LDL in adults with elevated cholesterol in a crossover comparison with control snacks. The tested amounts differed, so this trial does not fix a universal serving."},{"source_id":"19394473","role":"Earlier, less precise review","summary":"An earlier synthesis found lower total cholesterol and a borderline LDL estimate whose interval reached zero. The later, larger synthesis provides the card’s modest LDL estimate. Their evidence bases can overlap."}]},{"card_id":"sunscreen","title":"Use sunscreen daily","action":"Use broad-spectrum sunscreen according to its label, including reapplication directions.","tracking_prompt":"Log use. Short-term photos cannot measure the trial outcome.","goals":[],"benefit_ids":["sunscreen-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults under 55 in a sunny Australian town (n=903)","qualification":"One trial followed Australian adults for 4.5 years. A separate one-year study in Brazilian women tested a particular SPF 60 product twice daily.","time_commitment":"A minute or two a day. Tested for 4.5 years.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["23732711","37247191"],"research_summary":"One 4.5-year trial supports the long-term result. A one-year randomized study supports several facial signs. Shorter studies do not replicate the multi-year result.","source_notes":[{"source_id":"23732711","role":"Direct multi-year result","summary":"Australian adults assigned daily sunscreen showed less progression of skin aging at 4.5 years than those using it at their discretion. Assessors graded changes without knowing treatment assignment."},{"source_id":"37247191","role":"Related one-year study","summary":"Among 290 Brazilian women, twice-daily SPF 60 slowed progression of some facial aging signs versus usual care over one year. Cite only for that timeframe and regimen."}]},{"card_id":"caffeine","title":"Move caffeine earlier","action":"Log your last caffeinated drink, its size and your bedtime. Try moving that drink earlier. The timing depends on dose and individual response.","tracking_prompt":"Compare your sleep diary across similar nights.","goals":["sleep"],"benefit_ids":["caffeine-1","caffeine-2"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults, low-moderate habitual caffeine intake (dose-timing trial: 23 men)","qualification":"Dose, timing and individual clearance matter. Modeled cutoff times are estimates. The dose-timing trial enrolled 23 men and did not test 400 mg earlier than 12 hours before bed.","time_commitment":"No added activity time. Timing varies by caffeine dose and bedtime.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36870101","39377163","24235903"],"research_summary":"Two dose-timing trials and a review support sleep disruption after substantial caffeine. The 12-hour result comes from one small trial.","source_notes":[{"source_id":"36870101","role":"Pooled research","summary":"The review found less sleep after caffeine. Its beverage-specific cutoff estimates are modeled and cannot establish a safe cutoff for a 400 mg dose."},{"source_id":"39377163","role":"Direct dose–timing trial","summary":"Twenty-three men completed placebo and 100 mg or 400 mg conditions at 4, 8 or 12 hours before bed. The higher dose affected sleep initiation and architecture within 12 hours. No statistically clear disruption was detected with 100 mg."},{"source_id":"24235903","role":"Earlier controlled timing study","summary":"The study tested 400 mg at bedtime or three or six hours beforehand. Sleep was disrupted versus placebo even six hours before bed. The separate 12-hour finding comes from the later trial."}]},{"card_id":"resistance-sarcopenia","title":"Practice resistance exercises for sarcopenia","action":"For older adults with sarcopenia, one studied option was resistance exercise twice weekly for 12 weeks. If frail, choose exercises with a clinician.","tracking_prompt":"Track sessions and the same functional measure over time.","goals":["movement"],"benefit_ids":["resistance-sarcopenia-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Older adults with sarcopenia in controlled exercise trials.","qualification":"Ask a clinician first if frail.","time_commitment":"Twice weekly for 12 weeks in one trial.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42947012","41212331"],"research_summary":"A resistance-specific review pooled 24 trials. Strength and walking speed improved on average, although several changes were smaller than thresholds for a clinically important difference.","source_notes":[{"source_id":"42947012","role":"Direct, varied exercise programs","summary":"Twelve trials involving 652 adults with sarcopenia found gains in strength and walking speed with exercise. The study table includes resistance exercise twice weekly for 12 weeks and combined resistance and aerobic exercise three times weekly for 12 weeks."},{"source_id":"41212331","role":"Resistance-specific evidence","summary":"Across 24 trials in 951 older adults with sarcopenia, resistance exercise improved several strength and function measures. Average grip-strength and gait-speed improvements fell below the review’s thresholds for clinically important change."}]},{"card_id":"bath","title":"Take a warm bath or shower before bed","action":"Try a comfortably warm bath or shower for about 10 minutes, finishing one to two hours before bed.","tracking_prompt":"Record lights-out time and estimated minutes to fall asleep.","goals":["sleep"],"benefit_ids":["bath-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults studied in bedtime bathing or showering trials. Reviews differed in the populations they included.","qualification":"Use comfortable water and avoid overheating. Take care if prone to dizziness or falls. Reviews disagree about sleep onset.","time_commitment":"At least 10 min/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["31102877","42545422"],"research_summary":"Two reviews reached different conclusions about falling asleep sooner. The second search did not resolve that disagreement.","source_notes":[{"source_id":"31102877","role":"Pooled research","summary":"This review found shorter sleep-onset time after appropriately timed warm bathing or showering. Included studies varied in their designs."},{"source_id":"42545422","role":"Conflicting result","summary":"A newer synthesis of immersion trials found no significant improvement in sleep latency. It is included because it qualifies the earlier positive result."}]},{"card_id":"relax-muscles","title":"Practice progressive muscle relaxation for sleep","action":"Gently tense and release muscle groups in sequence. One trial in people with lung cancer used 30-minute sessions twice weekly for eight weeks.","tracking_prompt":"Rate sleep quality each morning.","goals":["sleep"],"benefit_ids":["relax-muscles-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults in relaxation studies, many with medical conditions.","qualification":"Low burden.","time_commitment":"30 minutes twice weekly for eight weeks in this example.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42625730","38494385","41633054","34569129"],"research_summary":"Reviews support better self-rated sleep, chiefly in clinical populations. An arthritis trial illustrates six weeks of practice in a different condition.","source_notes":[{"source_id":"42625730","role":"Direct, clinical populations","summary":"Across 14 trials, self-rated sleep improved on average with relaxation. Trial effects varied widely. Table 1 includes a 30-minute twice-weekly program for eight weeks in people with lung cancer and a 40-minute three-times-weekly program for six weeks in women with breast cancer."},{"source_id":"38494385","role":"Direct, clinical population","summary":"Chemotherapy patients with poor sleep who practiced progressive muscle relaxation scored better on self-rated sleep than a usual-care group. The population limits extrapolation."},{"source_id":"41633054","role":"Pooled research","summary":"Another synthesis found better sleep quality after progressive muscle relaxation. Trial effects varied substantially, and the two reviews may include the same participants."},{"source_id":"34569129","role":"Primary trial in a clinical population","summary":"People with rheumatoid arthritis assigned to six weeks of progressive muscle relaxation reported better sleep quality than controls. This is a primary example within a field already covered by reviews."}]},{"card_id":"cyclic-sighing","title":"Try five minutes of cyclic sighing","action":"For five minutes daily, inhale gently, add a short second inhale, then exhale slowly. Stop if you feel light-headed.","tracking_prompt":"Record mood before and after the session.","goals":["mood"],"benefit_ids":["cyclic-sighing-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults","qualification":"Breathe comfortably and stop if light-headed. The trial mostly recruited young adults.","time_commitment":"5 min/day, 28 days","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36630953"],"research_summary":"One month-long trial directly supports the five-minute routine and positive-mood result. Other sighing studies tested pain, anxiety or different practice schedules.","source_notes":[{"source_id":"36630953","role":"Direct, short-term mood","summary":"In a month-long remote randomized study, brief breathwork, especially exhale-focused cyclic sighing, improved positive mood more than the meditation comparison. The schedule was five minutes daily."}]},{"card_id":"cold-shower","title":"Finish a shower with cold water","action":"Participants ended their usual shower with 30 seconds of cold water daily for 30 days.","tracking_prompt":"Track sickness absence and days feeling ill separately.","goals":[],"benefit_ids":["cold-shower-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults 18-65 without severe comorbidity, no cold-shower habit (n=3,018)","qualification":"The trial involved adults without severe comorbidity. Ask a clinician before cold exposure if you have cardiovascular disease, uncontrolled blood pressure, arrhythmia or a condition aggravated by cold.","time_commitment":"30 seconds at the end of the shower, daily for 30 days.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["27631616","39879231"],"research_summary":"One large trial directly measured sick leave. A later review repeats that trial’s result. Participants reported a similar number of days feeling ill.","source_notes":[{"source_id":"27631616","role":"Direct, pooled durations","summary":"Sick-leave days were 29% lower across groups assigned 30–90 seconds of cold water at the end of showers. Self-reported illness days were comparable. The 29% was not estimated specifically for 30 seconds."},{"source_id":"39879231","role":"Review reusing the sick-leave trial","summary":"The review’s 29% lower sickness absence figure comes from the original shower trial. It provides no second independent test of that result. Other cold-immersion protocols answer different questions."}]},{"card_id":"meal-order","title":"Eat vegetables and protein before starch","action":"At a meal containing vegetables, protein and starch, eat the vegetables and protein first and the starch last.","tracking_prompt":"If you already monitor glucose, compare similar meals at the same time point.","goals":["metabolic"],"benefit_ids":["meal-order-1"],"eligibility_rule":"read_studied_population","studied_population":"People with type 2 or gestational diabetes; small healthy-adult crossover trials (PATTERN; Japanese set meals)","qualification":"Most participants had diabetes. Keep prescribed medications and diet instructions in mind when changing meal patterns.","time_commitment":"At meals. No extra activity time.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35210284","42045803","41837403"],"research_summary":"Small feeding studies support a smaller early glucose rise with carbohydrates last. A separate review in healthy adults also found acute effects. Two-hour and longer-term results remain uncertain.","source_notes":[{"source_id":"35210284","role":"Limits at two hours","summary":"In eight trials in people with type 2 diabetes there was little clear difference in two-hour plasma glucose or HbA1c. Retain as a limit on interpreting the earlier post-meal changes."},{"source_id":"42045803","role":"Pooled research","summary":"Studies in diabetes suggest smaller post-meal glucose excursions when carbohydrates come last. Heterogeneity and low certainty limit the inference."},{"source_id":"41837403","role":"Healthy-adult evidence","summary":"A review in healthy adults found that most studies reported a smaller acute glucose excursion when vegetables, fruit or protein preceded carbohydrates. The short feeding studies used several meal sequences."}]},{"card_id":"bedtime-list","title":"Write down tomorrow’s tasks","action":"Spend five minutes before bed writing specific tasks for the next few days.","tracking_prompt":"Log how long falling asleep seemed to take.","goals":["sleep"],"benefit_ids":["bedtime-list-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Healthy adults aged 18-30, sleep lab","qualification":"The comparison came from one laboratory night in young adults. Effects at home over several weeks remain uncertain.","time_commitment":"Five minutes before bed.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["29058942"],"research_summary":"One trial in 57 young adults tested five minutes of writing future tasks against writing completed tasks for one laboratory night. The search found no independent repeat of that comparison.","source_notes":[{"source_id":"29058942","role":"Direct, one-night comparison","summary":"Among 57 young adults, writing upcoming tasks for five minutes before bed led to faster objectively measured sleep onset than writing completed tasks. The trial had no group who did neither."}]},{"card_id":"kiwi","title":"Try two green kiwifruit a day","action":"If you have constipation, try two green kiwifruit a day for four weeks.","tracking_prompt":"Count complete bowel movements each week and log discomfort separately.","goals":["digestion"],"benefit_ids":["kiwi-1","kiwi-2"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with constipation","qualification":"Avoid with a kiwifruit allergy. Persistent or new bowel symptoms warrant evaluation.","time_commitment":"Two fruit daily for four weeks.","display_evidence_in_details":true,"blocked_if":["kiwifruit_allergy"],"research_source_ids":["36537785","34074830","21147704"],"research_summary":"Two trials support more complete bowel movements from baseline. An earlier four-week study also found more frequent bowel movements in people with IBS and constipation, using a broader measure.","source_notes":[{"source_id":"36537785","role":"Direct, change from baseline","summary":"Adults with functional constipation or IBS with constipation reported about 1.5–1.7 more complete spontaneous bowel movements per week than at baseline on two green kiwifruit daily. Overall gastrointestinal comfort also improved."},{"source_id":"34074830","role":"Direct for bowel frequency","summary":"In the US comparison all three groups improved in bowel frequency from baseline and responder rates were similar. In the kiwi group bloating and straining also improved. Those symptom outcomes are narrower than overall digestive comfort."},{"source_id":"21147704","role":"Related bowel-frequency outcome","summary":"In adults with constipation-predominant IBS, bowel movement frequency increased after four weeks of kiwifruit. This study measured defecation frequency, a broader outcome than complete spontaneous bowel movements."}]},{"card_id":"beans","title":"Add canned beans to meals","action":"Try one cup of canned beans daily for four weeks if this fits your diet.","tracking_prompt":"Track servings. A lipid panel measures the outcome.","goals":["heart"],"benefit_ids":["beans-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with LDL 3.0-5.0 mmol/L (n=73, mean age 48)","qualification":"Gas or bloating.","time_commitment":"One serving daily for four weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["34642756","17634169","1964898"],"research_summary":"One trial directly supports one cup daily for four weeks versus rice. An independent eight-week pinto-bean study also favored beans for LDL. The studies used different portions and comparisons.","source_notes":[{"source_id":"34642756","role":"Direct comparison","summary":"One cup of beans daily for four weeks produced a lower LDL than white rice. Half a cup did not clearly differ from rice. The trial also found no clear difference between the two portions."},{"source_id":"17634169","role":"Independent trial with a different portion","summary":"Sixteen adults with mild insulin resistance tried half a cup of pinto beans, black-eyed peas or carrots for eight weeks per condition. LDL fell more with pinto beans than carrots. The one-cup canned-bean card uses a different trial and comparator."},{"source_id":"1964898","role":"Different bean preparation and outcome","summary":"In 20 men with mildly high cholesterol, canned baked beans versus canned spaghetti did not clearly lower plasma total cholesterol. The abstract does not give an LDL result. This limits generalization to other canned products."}]},{"card_id":"salt-swap","title":"Use a potassium-enriched salt substitute","action":"After confirming that extra potassium is appropriate for you, replace your usual table or cooking salt with a potassium-enriched substitute.","tracking_prompt":"Log the swap and track home blood pressure if already measured.","goals":["heart"],"benefit_ids":["salt-swap-1","salt-swap-2"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults in 21 trials (about 32,000 people), including people with hypertension","qualification":"Extra potassium can be dangerous with kidney disease or potassium-raising medicines, including ACE inhibitors, ARBs and potassium-sparing diuretics. Check with a clinician or pharmacist before changing salts in these situations.","time_commitment":"Use in place of regular salt during usual food preparation.","display_evidence_in_details":true,"blocked_if":["kidney_disease","potassium_raising_medication","potassium_restriction"],"research_source_ids":["35945000","34459569","41578335"],"research_summary":"Blood pressure has support across multiple trials. A newer review found that evidence for cardiovascular events still relies heavily on the large Chinese trial.","source_notes":[{"source_id":"35945000","role":"Pooled research","summary":"Trials of potassium-enriched salt substitutes found lower systolic and diastolic pressure relative to regular salt."},{"source_id":"34459569","role":"Direct, high-risk population","summary":"With potassium-enriched salt there were about 29 versus 34 strokes per 1,000 person-years in rural Chinese participants with a prior stroke or who were at least 60 with hypertension. Follow-up averaged 4.74 years."},{"source_id":"41578335","role":"Broader review with overlapping trials","summary":"Across 34 trials, some potassium-enriched formulations probably lowered systolic pressure. Cardiovascular event evidence was dominated by one large Chinese trial. Do not count the stroke trial twice."}]},{"card_id":"whole-grains","title":"Choose whole-grain staples","action":"Swap some refined bread, rice or pasta for whole-grain versions. Studies used different grains and amounts.","tracking_prompt":"Track the foods you swap. A lipid panel measures the outcome.","goals":["heart"],"benefit_ids":["whole-grains-1","whole-grains-2"],"eligibility_rule":"read_studied_population","studied_population":"Adults","qualification":"Different grains and amounts were tested. Increase fiber gradually if it causes stomach discomfort.","time_commitment":"Daily food swap.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42743912","26269373"],"research_summary":"Two reviews found modest LDL and total cholesterol reductions. Their study periods overlap. The per-48-gram estimate comes from the newer review.","source_notes":[{"source_id":"42743912","role":"Pooled research","summary":"The review separately reports a small decrease in total cholesterol and LDL per 48 g/day of whole grains. Certainty differs between those outcomes."},{"source_id":"26269373","role":"Earlier pooled comparison","summary":"Whole-grain diets modestly lowered LDL and total cholesterol compared with non-whole-grain controls. The trial pool overlaps the period covered by the newer review."}]},{"card_id":"walk-for-ideas","title":"Walk while brainstorming","action":"Walk for a few minutes while generating ideas or brainstorm immediately afterward.","tracking_prompt":"Count distinct ideas on comparable prompts.","goals":["memory"],"benefit_ids":["walk-for-ideas-1"],"eligibility_rule":"read_studied_population","studied_population":"Mostly university and college students (1,036 participants)","qualification":"Most participants were students completing short lab tasks. The finding applies to generating ideas.","time_commitment":"A few minutes up to 20 minutes when you need ideas.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42127076","24749966"],"research_summary":"A review and primary experiments support generating more ideas during or shortly after walking. They do not establish better real-world problem solving.","source_notes":[{"source_id":"42127076","role":"Pooled research","summary":"Walking improved scores on idea-generation tasks, mostly in student samples. Results for convergent problem solving were uncertain."},{"source_id":"24749966","role":"Primary experimental example","summary":"Four experiments compared walking and sitting on idea-generation tasks. Walking improved creative ideation during or shortly after activity. The result depended on the task."}]},{"card_id":"water-flosser","title":"Clean between your teeth daily","action":"Use a powered interdental cleaner each day in addition to brushing, following the device instructions.","tracking_prompt":"Track bleeding over several weeks.","goals":[],"benefit_ids":["water-flosser-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with gingivitis (16 RCTs, 1,258 people), at least 28 days","qualification":"Minor gum trauma possible with mechanical devices.","time_commitment":"Once daily in addition to brushing, for at least four weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36562267","21387981"],"research_summary":"A review supports less bleeding when powered cleaning is added to brushing. An oral-irrigator trial compared different devices against floss.","source_notes":[{"source_id":"36562267","role":"Direct, adjunct to brushing","summary":"Trials in adults with gingivitis found less bleeding between teeth with powered interdental cleaning plus brushing than with brushing alone. Floss gave a comparable result."},{"source_id":"21387981","role":"Different active comparator","summary":"After four weeks, two oral-irrigator groups had less gingival bleeding than a floss group with manual brushing. This does not duplicate the brushing-alone comparison."}]},{"card_id":"social-break","title":"Take a week off social media","action":"Choose a seven-day break from the platforms studied or their equivalents. Arrange another way to stay in touch.","tracking_prompt":"Record wellbeing at the start and end of the week.","goals":["mood"],"benefit_ids":["social-break-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults, mean age 29.6 (154 people), not a clinical group","qualification":"The positive finding came from one short trial. A larger review found no clear average change in positive affect, negative affect or life satisfaction.","time_commitment":"Seven consecutive days.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35512731","40038410"],"research_summary":"One week-long trial found improved wellbeing. A review pooling abstinence studies found no consistent change in related wellbeing measures.","source_notes":[{"source_id":"35512731","role":"Controlled trial","summary":"One week away from selected social media platforms improved a wellbeing score compared with usual use. Follow-up was short."},{"source_id":"40038410","role":"Mixed broader findings","summary":"A systematic review of social-media breaks found no clear pooled benefit for positive affect, negative affect or life satisfaction. These related endpoints differ from the wellbeing scale of the one-week trial."}]},{"card_id":"toothbrush","title":"Use a powered toothbrush","action":"Use a powered toothbrush for your usual brushing and follow the device instructions.","tracking_prompt":"Log use. How clean your teeth feel is a personal observation.","goals":[],"benefit_ids":["toothbrush-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults (28 publications, single-brushing studies)","qualification":"The outcome is plaque removal immediately after brushing. Longer-term effects have a different evidence base.","time_commitment":"Usual brushing, about 2 times/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["34877772","16170978","31050195"],"research_summary":"Reviews of single-brushing experiments agree on a small plaque-removal benefit. The reviews can include the same participants.","source_notes":[{"source_id":"34877772","role":"Pooled research","summary":"Pooled single-brushing studies found slightly greater plaque removal with a powered toothbrush. This specific finding concerns immediate plaque removal."},{"source_id":"16170978","role":"Controlled trial","summary":"In a single-use crossover comparison, one battery-powered brush removed more plaque than a manual brush. The finding concerns the tested models."},{"source_id":"31050195","role":"Overlapping review","summary":"An earlier review of single-brushing comparisons favored powered brushes over manual brushes for plaque removal. Trials can overlap with the later review."}]},{"card_id":"screen-cap","title":"Set a daily phone screen-time cap","action":"Try a two-hour daily phone screen-time cap for three weeks if it fits your work and communication needs.","tracking_prompt":"Use your screen-time report and rate mood and sleep separately.","goals":["mood","sleep"],"benefit_ids":["screen-cap-1","screen-cap-2","screen-cap-3"],"eligibility_rule":"confirm_eligibility","studied_population":"Healthy university students, mean age 22.7 (n=111)","qualification":"Evidence comes from one unblinded trial in healthy university students. Keep access to essential communication.","time_commitment":"Cap of 2 h/day, 3 weeks","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["39985031","35389685"],"research_summary":"One student trial tested the two-hour cap and measured all three groups of outcomes. A separate intervention reducing smartphone use by one hour provides context for mood and wellbeing.","source_notes":[{"source_id":"39985031","role":"Direct, single sample","summary":"After three weeks, 111 students assigned to a daily two-hour phone cap or control differed on depressive symptoms, perceived stress, wellbeing and insomnia severity. The insomnia score differed by 2.59 points at the end. Several outcomes came from these same students."},{"source_id":"35389685","role":"Different reduction target","summary":"An experiment reducing daily smartphone use by one hour found improvements in depressive symptoms and wellbeing. It used a relative reduction rather than a two-hour daily cap and does not validate the card’s insomnia score."}]},{"card_id":"standing-stockings","title":"Use fitted stockings during standing shifts","action":"Use appropriately fitted graduated compression stockings during standing shifts if they are suitable for you.","tracking_prompt":"Record end-of-shift swelling or heaviness.","goals":[],"benefit_ids":["standing-stockings-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Healthcare workers on six-hour standing shifts and hairdressers exposed to prolonged standing.","qualification":"The finding concerns leg swelling during standing shifts. Check fit and seek advice about arterial circulation problems or skin disease.","time_commitment":"Standing work days, up to 12 months","display_evidence_in_details":true,"blocked_if":["compression_contraindicated"],"research_source_ids":["37458579","22451457"],"research_summary":"Two independent studies found less lower-leg swelling with stockings during standing work, one in healthcare workers and one in hairdressers.","source_notes":[{"source_id":"37458579","role":"Direct, occupational swelling","summary":"Graduated stockings countered increases in lower-leg volume in healthcare workers on standing shifts. Seventy-two participants completed data collection. The flight-clot outcome was outside this study."},{"source_id":"22451457","role":"Independent occupational crossover trial","summary":"In 108 hairdressers randomized to low-strength stockings and no-compression periods, lower-leg volume averaged 19 mL less with stockings. Symptoms also improved. This supports the swelling result in a second standing occupation."}]},{"card_id":"optimism","title":"Imagine your best possible future","action":"Spend five minutes a day for two weeks imagining your best possible future in relationships, personal life and work.","tracking_prompt":"Rate optimism before and after the two weeks.","goals":["mood"],"benefit_ids":["optimism-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults in studies of future-self imagery.","qualification":"The studied outcome was optimism on a questionnaire.","time_commitment":"5 min/day, 14 days","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["21450262","31545815","36724699"],"research_summary":"One trial supports the two-week imagery schedule. Another study found immediate optimism changes across writing and imagery formats.","source_notes":[{"source_id":"21450262","role":"Direct, tested schedule","summary":"Five minutes daily of imagining one’s best possible self increased self-rated optimism relative to imagining ordinary daily activities, both after one session and over two weeks."},{"source_id":"31545815","role":"Direct pooled result","summary":"Across different versions of the best-possible-self exercise, participants showed higher optimism on average than comparison groups. The pooled estimate spans different practice formats."},{"source_id":"36724699","role":"Different practice duration","summary":"An online study compared versions of best-possible-self practice. Writing and imagery produced similar immediate improvements in optimism. It did not test how long the effect lasts."}]},{"card_id":"bedtime-phone","title":"Put your phone away before bed","action":"Put your phone away for the last 30 minutes before bed for four weeks. The small trial included nightly enforcement.","tracking_prompt":"Record phone-free minutes and estimated time to fall asleep.","goals":["sleep"],"benefit_ids":["bedtime-phone-1","bedtime-phone-2","bedtime-phone-3"],"eligibility_rule":"confirm_eligibility","studied_population":"Young adults with poor sleep who regularly used their phone at bedtime.","qualification":"Research involved young adults with poor sleep and a habitual bedtime phone routine. Outcomes were self-reported.","time_commitment":"30 phone-free min/night","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32040492","29073407","41668954"],"research_summary":"One small trial directly supports the 30-minute restriction in young adults with poor sleep. Different evening media rules in athletes produced mixed sleep findings.","source_notes":[{"source_id":"32040492","role":"Direct, self-reported outcomes","summary":"In 38 young adults a reinforced bedtime phone restriction improved reported sleep onset, sleep quality and bedtime arousal. The groups’ average changes in onset differed by about ten minutes. The paper’s p = 0.049 is the end-of-study group comparison."},{"source_id":"29073407","role":"Null result in a different population","summary":"A four-week restriction on electronic media after 10 pm did not improve sleep habits in high-school athletes who already slept well. The rule, population and baseline sleep differed from the card trial."},{"source_id":"41668954","role":"Different exposure and comparison","summary":"Sixteen male elite soccer players compared two hours of pre-bed smartphone exposure with magazine reading. Sleep quality worsened during phone exposure. This does not establish the effects of a 30-minute cutoff on onset or bedtime arousal."}]},{"card_id":"blink","title":"Practice complete blinks","action":"Gently close, squeeze and open your eyes 15 times, three times daily for two weeks.","tracking_prompt":"Rate symptoms at the same time each day.","goals":[],"benefit_ids":["blink-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with dry eye (98 and 28 people)","qualification":"Evidence comes from short studies in people with dry eye. Seek eye care for persistent symptoms, pain or vision changes.","time_commitment":"3 x 15 repeats/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["40467388","32409236"],"research_summary":"Two short studies support symptom relief in dry eye. Blink-reminder software changes a different behavior from the card’s close–squeeze–open exercises.","source_notes":[{"source_id":"40467388","role":"Direct, selected schedule","summary":"Short studies in adults with dry eye found fewer symptoms and incomplete blinks with the selected 15 close–squeeze–open repeats three times a day. Several objective tear-film measures showed no significant change."},{"source_id":"32409236","role":"Related schedule","summary":"In a four-week before-and-after program, dry-eye symptoms improved. It used a different blink schedule and lacked a randomized no-exercise control."}]},{"card_id":"apples","title":"Try two whole apples daily","action":"Try two whole apples a day for eight weeks if this fits your diet.","tracking_prompt":"Track servings. Cholesterol requires a lipid panel.","goals":["heart"],"benefit_ids":["apples-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Mildly hypercholesterolemic adults, mean age 51 (n=40)","qualification":"One small trial in adults with mildly high cholesterol compared whole apples with an apple drink. A broader review combining apples and apple products found no clear overall LDL reduction.","time_commitment":"Daily, 8 weeks","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["31840162","23271615","35449537"],"research_summary":"One small trial supports the two-apple routine versus a matched drink. A second trial favored whole apples over clear juice. A broader review pooling apple products found an inconclusive overall LDL difference.","source_notes":[{"source_id":"31840162","role":"Direct, matched drink","summary":"Two whole apples daily resulted in modestly lower LDL than a matched apple drink after eight weeks in a small crossover trial of adults with mildly elevated cholesterol."},{"source_id":"23271615","role":"Related whole-fruit comparison","summary":"In 23 healthy volunteers, clear apple juice produced higher LDL than whole apples in a four-week crossover study. The whole-apple portion was 550 g daily. This differs from the card’s population and matched drink."},{"source_id":"35449537","role":"Mixed pooled evidence","summary":"Across trials of apples and apple-derived products, pooled LDL was 2.8 mg/dL lower, with a 95% interval from 5.78 lower to 0.17 higher. The overall result was inconclusive and the review mixed product forms."}]},{"card_id":"work-breaks","title":"Add four breaks to a desk shift","action":"Add four five-minute breaks spread across the shift. Participants also had their usual two longer breaks.","tracking_prompt":"Rate discomfort at the end of comparable shifts.","goals":[],"benefit_ids":["work-breaks-1"],"eligibility_rule":"read_studied_population","studied_population":"Data-entry workers (n=51)","qualification":"Two field studies tested supplementary breaks in data-entry work. They measured discomfort and eyestrain during the work period.","time_commitment":"20 extra min/workday","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["17514726","10877480"],"research_summary":"Two data-entry field studies support the four extra five-minute breaks. The search did not identify a stronger test of that schedule and eyestrain outcome.","source_notes":[{"source_id":"17514726","role":"Controlled trial","summary":"Data-entry workers reported less discomfort and eyestrain when four five-minute breaks were added to their usual breaks."},{"source_id":"10877480","role":"Direct occupational result","summary":"Data-entry operators reported smaller increases in discomfort and eyestrain during periods with four additional five-minute breaks. Data-entry performance was maintained."}]},{"card_id":"hummus","title":"Try an afternoon hummus snack","action":"The tested snack was hummus with pretzels, about 240 kcal, roughly three hours after lunch.","tracking_prompt":"Record hunger and evening snacks.","goals":["metabolic"],"benefit_ids":["hummus-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults, mean age 26 (n=39)","qualification":"One small, short trial in healthy young adults. The snack contains ingredients that may be unsuitable for people with food allergies.","time_commitment":"One snack about three hours after lunch.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32488233"],"research_summary":"One small trial tested the afternoon hummus-and-pretzels snack and later dessert snacking. A conference abstract describes a similar study by the same research group and was not counted as replication.","source_notes":[{"source_id":"32488233","role":"Direct, specified snack","summary":"Compared with no snack, hummus with pretzels reduced afternoon hunger in 39 healthy adults. Later dessert snacking was about 20% lower than after either no snack or granola bars. The measurement followed six days on each pattern."}]},{"card_id":"volunteer","title":"Try a structured volunteering session","action":"Join a structured session helping nursing-home residents if this is available and suits you.","tracking_prompt":"Rate loneliness before the session and at follow-up.","goals":["mood"],"benefit_ids":["volunteer-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults aged 59 to 79 (n=76)","qualification":"The intervention was a structured activity with older adults. Benefit was self-reported.","time_commitment":"Single session","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42054579","39855242"],"research_summary":"One trial tested a single nursing-home session. A separate, sustained volunteering program also reduced loneliness in older volunteers. The one-session effect is still based on one trial.","source_notes":[{"source_id":"42054579","role":"Direct, structured session","summary":"In a trial of 76 older adults, participants who helped nursing-home residents reported less loneliness within a day. The effect persisted at one month. The participants volunteered within a structured program."},{"source_id":"39855242","role":"Independent longer volunteering program","summary":"Older volunteers in a structured telephone program reported less loneliness than controls after a sustained intervention. Most effects were not sustained at later follow-up. This does not test one nursing-home visit."}]},{"card_id":"jumps","title":"Practice short sets of vertical jumps","action":"One tested example in young women was 10 maximal countermovement jumps, three nonconsecutive days a week for six months. Use only if high-impact activity is appropriate.","tracking_prompt":"Log sessions. Bone density is measured by DXA.","goals":["movement"],"benefit_ids":["jumps-1"],"eligibility_rule":"clinician_clearance","studied_population":"Healthy adults over 18 (review); example trial: healthy non-smoking young women aged 20-23","qualification":"High-impact exercise. Seek clinical advice if pregnant or if you have osteoporosis, a fracture history, joint or back problems, or restrictions on impact exercise. The specific schedule was studied in healthy young women.","time_commitment":"Under two minutes per session in the example trial, including rests. This was an estimate.","display_evidence_in_details":true,"blocked_if":["impact_exercise_restriction"],"research_source_ids":["38305252","16269526"],"research_summary":"A pooled analysis supports femoral-neck density. The ten-jump, three-days-a-week example comes from one trial. Other hip studies used different sites or schedules.","source_notes":[{"source_id":"38305252","role":"Pooled research","summary":"Across jump programs, the clearest density improvement was at the femoral neck. The programs varied; the review does not establish fracture prevention."},{"source_id":"16269526","role":"Direct, one specific regimen","summary":"In young women, femoral-neck density rose from baseline after six months of ten maximal jumps three times weekly. The pooled estimate on the card comes from the review of multiple programs."}]},{"card_id":"psyllium","title":"Use psyllium regularly","action":"Use the label for dosing and mixing. LDL trials used a median of about 10 g of psyllium daily. Take each dose with at least a full glass of water, and check medicine spacing with a pharmacist.","tracking_prompt":"Log bowel frequency if relevant. LDL requires a lipid panel.","goals":["heart","digestion"],"benefit_ids":["psyllium-1","psyllium-2"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults in lipid trials and adults with constipation. Benefits differ by population.","qualification":"Do not swallow dry powder. Avoid with swallowing difficulty or suspected bowel obstruction. Check label directions, fluid restrictions and medicine spacing with a pharmacist.","time_commitment":"Daily according to product directions. Trial doses and duration varied by outcome.","display_evidence_in_details":true,"blocked_if":["swallowing_difficulty","bowel_obstruction","fluid_restriction"],"research_source_ids":["30239559","35816465","8824651","41366295"],"research_summary":"Two lipid reviews support lower LDL, with overlapping trial periods. Separate constipation evidence supports improved bowel frequency with variable effect sizes.","source_notes":[{"source_id":"30239559","role":"Direct LDL result","summary":"Across 28 controlled trials, a median daily psyllium intake of about 10.2 g lowered LDL by 0.33 mmol/L on average. This is the lipid evidence on this two-benefit card."},{"source_id":"35816465","role":"Direct psyllium subgroup","summary":"In the psyllium subgroup, bowel frequency increased by about 3.08 per week, with a wide 95% interval of 0.61 to 5.54 and substantial variation. The overall fiber response rate cannot be attributed to psyllium alone."},{"source_id":"8824651","role":"Controlled trial","summary":"Adults with chronic constipation received psyllium or placebo for eight weeks. Stool frequency and consistency improved during psyllium treatment."},{"source_id":"41366295","role":"Later lipid review","summary":"A later synthesis also found lower LDL and total cholesterol with psyllium. It may reuse trials in the earlier review and offers no additional evidence on constipation."}]},{"card_id":"retrieval","title":"Practice recalling what you learn","action":"After learning new facts, test yourself and check the answers. One trial tested trainees immediately and twice more at intervals of about two weeks.","tracking_prompt":"Track how many answers you recall on a later test.","goals":["memory"],"benefit_ids":["retrieval-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults/students learning facts","qualification":"Research measured recall of practiced material on a later test.","time_commitment":"Three practice sessions in the example, the first immediately after learning.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["16719566","25150680","19930508","SPACED-2021"],"research_summary":"A review of 29 studies examined spacing retrieval practice. Delayed recall favored spaced over massed retrieval. One trainee trial supplies the three-session example.","source_notes":[{"source_id":"16719566","role":"Spacing evidence","summary":"Spacing learning episodes improved later retention compared with massed practice. Effective intervals depended on how much later learners were tested. This paper does not establish the feedback and self-testing schedule."},{"source_id":"25150680","role":"Retrieval evidence","summary":"Pooling testing-versus-restudy comparisons favored retrieval for later recall. This supports self-testing as an ingredient. The exact two-week spacing and feedback example comes from the trainee trial."},{"source_id":"19930508","role":"Direct combined example","summary":"Forty trainees completed repeated testing with feedback versus repeated study. The first session was immediate and two further sessions were roughly two weeks apart. Six-month scores averaged 39% versus 26% on the studied material."},{"source_id":"SPACED-2021","role":"Review of combined practice","summary":"A review of 29 studies found better later retention when retrieval sessions were spaced rather than massed. This supports the combined learning approach. The specific two-week interval remains a trial example."}]},{"card_id":"flight-stockings","title":"Wear fitted stockings on a long flight","action":"Use properly fitted below-knee graduated compression stockings during a long flight if appropriate for you. Check fit and suitability before travel.","tracking_prompt":"Log use. Symptoms cannot establish this outcome at home.","goals":[],"benefit_ids":["flight-stockings-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Long-haul flyers, especially higher-risk","qualification":"The measured benefit involved silent clots detected by screening. Seek guidance on fit and suitability if you have arterial circulation or skin problems.","time_commitment":"Put on once per flight","display_evidence_in_details":true,"blocked_if":["compression_contraindicated"],"research_source_ids":["33878207","11377600"],"research_summary":"Nine flight trials contributed screened clot outcomes. One primary trial illustrates what screening detected. Symptomatic clot prevention remains unestablished.","source_notes":[{"source_id":"33878207","role":"Pooled research","summary":"Flight trials found fewer symptomless leg clots on screening with compression stockings. They could not estimate protection against symptomatic events."},{"source_id":"11377600","role":"Primary flight trial","summary":"Screening after long-haul flights found symptomless calf clots in the no-stocking group and none in those wearing stockings. This early trial illustrates the review evidence and should not be counted on top of it."}]},{"card_id":"fall-hazards","title":"Arrange a home fall-hazard assessment","action":"Arrange a home assessment with a trained professional and follow through on the recommended changes.","tracking_prompt":"Log completed changes and any falls.","goals":["movement"],"benefit_ids":["fall-hazards-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Older adults living at home who have elevated fall risk.","qualification":"The benefit applies to higher-risk older adults living in the community, especially people who have fallen or need help with daily activities. Arrange a trained assessor and implement their recommendations.","time_commitment":"One assessment followed by the time required to implement changes.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["FALL","34463746","10591231"],"research_summary":"The high-risk subgroup in the Cochrane review provides the card estimate. Broader home-modification reviews include different baseline risks and outcomes.","source_notes":[{"source_id":"FALL","role":"Pooled research","summary":"Home assessment and actual hazard reduction reduced the rate of falls in higher-risk older adults living in the community. The effect differed by baseline risk."},{"source_id":"34463746","role":"Secondary result only","summary":"A home-hazard intervention lowered the rate of falls in a secondary analysis. The primary measure, time to first fall, did not differ clearly. Attach only to the fall-rate interpretation."},{"source_id":"10591231","role":"Controlled trial","summary":"An occupational therapist assessed and helped modify homes. The benefit was concentrated among older adults who had previously fallen."}]},{"card_id":"handwash","title":"Wash hands regularly","action":"Wet your hands, lather with soap and scrub all surfaces for at least 20 seconds. Rinse and dry. Wash at key times, including before eating and after using the bathroom.","tracking_prompt":"Log the occasions you want to remember.","goals":[],"benefit_ids":["handwash-1"],"eligibility_rule":"read_studied_population","studied_population":"Community and household populations studied in hand-hygiene programs.","qualification":"The research studied hygiene programs and usual-care comparisons. It does not isolate the effect of precisely 20 seconds of washing.","time_commitment":"At least 20 seconds of scrubbing, plus rinsing and drying.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["37121242","35445655","CDC-HANDWASH","34408031"],"research_summary":"Community handwashing-promotion studies found fewer respiratory infections in some settings. Another review’s smaller soap-only comparison was inconclusive. CDC supplies the scrub-time instruction.","source_notes":[{"source_id":"37121242","role":"Pooled research","summary":"Handwashing-with-soap promotion programs reduced respiratory infections in low- and middle-income settings. The review evaluates programs rather than one wash duration."},{"source_id":"35445655","role":"Uncertain frequency estimate","summary":"A model of six community studies estimated a 3% reduction in daily infection probability per extra hand-hygiene event. Even its 80% credible interval included no difference. This cannot support a precise risk reduction or a wash duration."},{"source_id":"CDC-HANDWASH","role":"Scrubbing instructions","summary":"CDC explains how to scrub all hand surfaces with soap for at least 20 seconds. This source supplies the technique."},{"source_id":"34408031","role":"Mixed soap-specific findings","summary":"In one review, the three soap-and-water trials showed no clear respiratory infection reduction compared with control. Sanitiser results were clearer. The settings and number of soap trials differ from the larger handwashing-promotion review."}]},{"card_id":"water-premeal","title":"Drink water before meals in a structured weight program","action":"The trial used 500 mL of water before main meals alongside a reduced-calorie diet. Only consider this if that fluid intake fits your care plan.","tracking_prompt":"Track the routine and weekly weight if relevant.","goals":["metabolic"],"benefit_ids":["water-premeal-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with obesity in primary care and adults aged 55–75 with overweight or obesity on a reduced-calorie diet.","qualification":"One trial used a reduced-calorie diet and the other provided weight-management advice. Avoid this fluid schedule if your clinician limits fluid or you have a condition requiring individualized intake.","time_commitment":"Before each main meal. The trial lasted 12 weeks.","display_evidence_in_details":true,"blocked_if":["fluid_restriction"],"research_source_ids":["19661958","26237305"],"research_summary":"Two independent 12-week trials tested 500 mL before meals alongside weight-management support. Both estimates favored water. In the primary-care trial the adjusted result included no difference.","source_notes":[{"source_id":"19661958","role":"Direct, combined program","summary":"Forty-eight adults aged 55–75 on a reduced-calorie diet were assigned to water before meals or diet alone. Weight loss over 12 weeks was about 2 kg greater with 500 mL water before each main meal."},{"source_id":"26237305","role":"Independent primary-care trial","summary":"Among 84 adults with obesity who received weight-management advice, 500 mL of water before main meals was associated with 1.3 kg more weight loss over 12 weeks than the attention control. The adjusted interval included no difference."}]},{"card_id":"drink-swap","title":"Replace a sugary drink with water","action":"Try replacing one sugary drink a day with plain water.","tracking_prompt":"Count how many sugary drinks you replace this week.","goals":["metabolic"],"benefit_ids":["drink-swap-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with overweight or obesity who regularly drink sugary beverages.","qualification":"The swap removes the sugar from that drink. In people with overweight or obesity, trials have not established how much weight, if any, is lost from switching to water.","time_commitment":"No extra time","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["38612997","22301929","35285920"],"research_summary":"Reviews that isolate water substitution find uncertain weight effects. Combined results for diet drinks and water cannot establish the water-only effect.","source_notes":[{"source_id":"38612997","role":"Inconclusive water-specific result","summary":"Replacing sugary drinks with water was associated with an estimated 0.81 kg lower weight in the relevant subgroup. Its 95% interval ran from 1.66 kg lower to 0.03 kg higher and includes no difference."},{"source_id":"22301929","role":"Inconclusive water-specific result","summary":"At six months mean weight loss in the water group did not clearly exceed the attention control. A separate positive analysis combined water and diet drinks. It cannot establish the effect of water alone."},{"source_id":"35285920","role":"Water-specific subgroup","summary":"Three trials in this review evaluated water in place of sugary drinks. Evidence for body weight was rated low certainty. Findings for low-calorie sweetened drinks cannot be attributed to water."}]},{"card_id":"eat-slowly","title":"Slow down at a meal","action":"Try eating a familiar meal more slowly, giving yourself time between bites.","tracking_prompt":"Record meal length and how full you feel.","goals":["metabolic"],"benefit_ids":["eat-slowly-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults who eat quickly and overeat","qualification":"Jaw/TMJ, dental, swallowing difficulty - do not force counts","time_commitment":"During a meal. Studies varied in pace.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["24847856","39279635","24388483"],"research_summary":"A meal-level review and laboratory studies support reduced intake in some meals. Methods for slowing eating vary, and the evidence does not establish lasting weight loss.","source_notes":[{"source_id":"24847856","role":"Direct pooled result","summary":"Experimental meals consumed more slowly were associated with lower intake on average than faster meals. The designs and methods for changing eating rate varied."},{"source_id":"39279635","role":"Related food-texture study","summary":"Researchers changed food texture to slow eating. Participants consumed less energy at those meals. This provides context for eating rate, while testing a different action from deliberately slowing down."},{"source_id":"24388483","role":"Controlled trial","summary":"A fast-versus-slow eating comparison found lower intake in the normal-weight subgroup. The group-by-weight interaction was not significant."}]},{"card_id":"three-good-things","title":"Write down three good things","action":"For one week, write down three things that went well each night and why they happened.","tracking_prompt":"Rate wellbeing before and after the week.","goals":["mood"],"benefit_ids":["three-good-things-1"],"eligibility_rule":"read_studied_population","studied_population":"General adults seeking small mood lift","qualification":"Different gratitude exercises have been studied. Average wellbeing effects were small and depended on the comparison activity.","time_commitment":"A few minutes each evening for one week.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["40627390","16045394","37217328"],"research_summary":"One online trial supports the nightly exercise. A different prompting schedule produced small positive-affect changes in healthcare workers, with no clear life-satisfaction benefit.","source_notes":[{"source_id":"40627390","role":"Broader gratitude research","summary":"Across 163 samples, diverse gratitude exercises produced a small average wellbeing improvement. This estimate includes many exercises and should not be presented as the effect of writing three good things."},{"source_id":"16045394","role":"Direct, specific exercise","summary":"The full report describes a week of writing three things that went well and why. Participants reported greater happiness at later follow-ups than those writing about early memories. This is the link for the exact exercise."},{"source_id":"37217328","role":"Different schedule and outcomes","summary":"Healthcare workers were prompted three times weekly to name good things. Positive affect showed a small improvement. Life satisfaction and depressive symptoms did not clearly differ between groups. This differs from nightly writing about why events happened."}]},{"card_id":"mindfulness","title":"Try a brief guided mindfulness practice","action":"Try a guided meditation for about ten minutes daily for eight weeks.","tracking_prompt":"Rate perceived stress weekly.","goals":["mood"],"benefit_ids":["mindfulness-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Employees with mild to moderate stress.","qualification":"The workplace trial used a guided meditation app for eight weeks. Stop if distress increases and seek appropriate support.","time_commitment":"10 min/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["39808431","31237569","34962055"],"research_summary":"Trials in employees and students found lower perceived stress with guided digital mindfulness compared with waiting-list controls.","source_notes":[{"source_id":"39808431","role":"Direct, tested prescription","summary":"In 1,458 stressed employees, assignment to an app providing ten minutes of daily meditation for eight weeks improved perceived stress compared with waiting list. Actual usage varied."},{"source_id":"31237569","role":"Direct, student sample","summary":"Stressed college students assigned to an app-based mindfulness program reported lower perceived stress than a wait-list group. This extends the finding to another study population."},{"source_id":"34962055","role":"Independent student trial","summary":"Working university students assigned to an eight-week mindfulness app reported lower stress than wait-listed students. It supports perceived stress in a different sample."}]},{"card_id":"left-side","title":"Try positional therapy for nighttime reflux","action":"In one trial, adults wore a device at night for two weeks that prompted them to turn away from their right side. Choosing the left side yourself is a less-tested option.","tracking_prompt":"Record nighttime reflux symptoms.","goals":["digestion"],"benefit_ids":["left-side-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with nocturnal reflux","qualification":"The controlled trial used a device that discouraged right-side sleeping. The benefit of choosing the left side without a device is less certain.","time_commitment":"During sleep. The device trial lasted two weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35301135","37969463"],"research_summary":"The direct symptom result comes from a two-week device trial. Other positioning devices or combined incline-and-side approaches do not isolate choosing the left side unaided.","source_notes":[{"source_id":"35301135","role":"Controlled trial","summary":"A wearable device encouraged left-side sleep for two weeks. Nighttime reflux symptoms improved relative to a sham device."},{"source_id":"37969463","role":"Review including the same trial","summary":"The review found evidence linking left-side position to lower acid exposure and summarized the same device trial that reported symptom relief. It adds context without providing another independent device trial."}]},{"card_id":"music","title":"Listen to music before bed","action":"Try listening to calming recorded music for about 30–45 minutes at bedtime. Studies used different selections and schedules.","tracking_prompt":"Rate sleep quality the next morning.","goals":["sleep"],"benefit_ids":["music-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with sleep difficulties.","qualification":"Research supports perceived sleep quality. Objective sleep duration and sleep stages remain uncertain.","time_commitment":"About 30–45 minutes at bedtime.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36000763","15660547","18426457","30676671"],"research_summary":"A Cochrane review supports better self-rated sleep quality. Another trial reported better perceived sleep but an inconclusive result on its primary insomnia-severity measure.","source_notes":[{"source_id":"36000763","role":"Pooled research","summary":"A Cochrane review found better perceived sleep quality among adults with insomnia symptoms. Objective sleep measurements were less conclusive."},{"source_id":"15660547","role":"Direct primary example","summary":"Older adults listening to soothing bedtime music reported better sleep quality over the intervention period than controls. Perceived sleep quality was the relevant endpoint."},{"source_id":"18426457","role":"Direct primary example","summary":"Young adults with sleep complaints who listened to 45 minutes of relaxing classical music at bedtime for three weeks reported improved sleep quality on a questionnaire."},{"source_id":"30676671","role":"Mixed findings across sleep measures","summary":"In adults with insomnia, bedtime music improved perceived sleep on a secondary measure. The primary comparison on insomnia severity was inconclusive, and objective sleep measures showed no change."}]},{"card_id":"smell-training","title":"Practice smell training","action":"After evaluation for persistent postviral smell loss, one approach is to gently smell four familiar scents twice daily. Research protocols included 12-week training blocks and longer programs. Avoid irritants and direct nasal application.","tracking_prompt":"Log sessions and which scents you can identify.","goals":[],"benefit_ids":["smell-training-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with persistent post-viral smell loss","qualification":"Persistent or unexplained smell loss merits clinical assessment. Avoid putting oils or other substances inside your nose.","time_commitment":"Twice daily. Training duration varied across studies.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32567798","23929687","32660334","42311058"],"research_summary":"A postviral review and a separate review of ten post-COVID trials support improved smell-test performance. The training protocols and viral causes differ.","source_notes":[{"source_id":"32567798","role":"Direct review, varied protocols","summary":"An evidence review recommends repeated odor training for postviral smell loss based on changes in measured olfactory function. Protocols and odor sets differed across the studies."},{"source_id":"23929687","role":"Different duration and comparison","summary":"People with postinfectious smell loss trained with stronger or weaker odors for 18 weeks. Improvement on testing was more common in the higher-concentration arm. Both groups trained, limiting inference about training versus usual care."},{"source_id":"32660334","role":"Postviral training review","summary":"Across four pooled studies, trained participants were more likely than controls to improve by a clinically important amount on an odor test. Training protocols varied."},{"source_id":"42311058","role":"Post-COVID subgroup","summary":"Ten randomized trials in post-COVID smell loss found a small average improvement in objective smell scores. The finding applies to this postviral subgroup across varied protocols."}]},{"card_id":"prunes","title":"Try prunes for constipation","action":"The studied schedule was 50 g of prunes twice daily for three weeks in adults with constipation.","tracking_prompt":"Count complete bowel movements weekly.","goals":["digestion"],"benefit_ids":["prunes-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Chronic constipation; 37 women, 3 men; mean age 38","qualification":"A small crossover trial tested this exact schedule. A second comparison also observed improved bowel frequency from baseline. Large servings may cause bloating or loose stools.","time_commitment":"Two daily portions for three weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["21323688","34074830"],"research_summary":"Two constipation studies support the bowel-frequency finding. Trials in other populations measuring total stools do not directly replicate the complete spontaneous bowel movement outcome.","source_notes":[{"source_id":"21323688","role":"Direct exact schedule","summary":"Forty adults with constipation crossed over between dried plums and psyllium. Fifty grams of dried plums twice daily for three weeks improved complete spontaneous bowel movements and stool consistency relative to psyllium."},{"source_id":"34074830","role":"Direct for bowel frequency","summary":"Adults with constipation ate 100 g of prunes daily for four weeks. Bowel frequency improved from baseline, with similar response rates across treatments. The other trial tested 50 g twice daily for three weeks."}]},{"card_id":"cystitis","title":"Add water for recurrent cystitis prevention","action":"The trial added 1.5 L of water daily to usual intake in selected women drinking under 1.5 L of fluid daily. Confirm that the eligibility and fluid plan fit.","tracking_prompt":"Log episodes diagnosed by a clinician. This routine is for prevention.","goals":[],"benefit_ids":["cystitis-1"],"eligibility_rule":"clinician_clearance","studied_population":"Premenopausal women with recurrent cystitis and usual total fluid intake below 1.5 L/day. See the full eligibility criteria.","qualification":"Prevention in healthy premenopausal women with at least three symptomatic episodes in the prior year, at least one culture-confirmed, and low usual fluid intake. Exclude current symptoms, pregnancy, breastfeeding and fluid restriction. New urinary symptoms require assessment.","time_commitment":"Extra water spread throughout the day for 12 months in the trial.","display_evidence_in_details":true,"blocked_if":["current_urinary_symptoms","pregnancy","breastfeeding","fluid_restriction"],"research_source_ids":["30285042","31988085"],"research_summary":"One water-only trial directly supports the extra 1.5 L daily in this population. A broader fluid review found fewer episodes overall, with uncertainty about who had any recurrence at one year.","source_notes":[{"source_id":"30285042","role":"Direct prevention trial","summary":"Among 140 premenopausal women with recurrent cystitis and low fluid intake, adding 1.5 L of water daily resulted in 1.7 versus 3.2 episodes on average over a year. The study concerned prevention."},{"source_id":"31988085","role":"Broader recurrence review","summary":"A review of increased fluid intake found fewer recurrent urinary infections overall. At 12 months the difference in the proportion with any recurrence was inconclusive. It pools different fluid interventions and does not independently verify the card’s exact water dose."}]},{"card_id":"dash","title":"Build meals around the DASH pattern","action":"Build meals around vegetables, fruit, whole grains and low-fat dairy, with less saturated fat. Use the studied dietary pattern as the reference.","tracking_prompt":"Track adherence and average home blood pressure.","goals":["heart"],"benefit_ids":["dash-1","dash-2"],"eligibility_rule":"read_studied_population","studied_population":"Adults SBP <160 and DBP 80–95 mmHg","qualification":"Adapt to allergies and prescribed diets. Kidney disease or potassium/fluid restrictions require clinical dietary advice; do not change medication. ","time_commitment":"A daily eating pattern. Shopping and preparation time vary.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["9099655","32330233"],"research_summary":"A controlled feeding trial and a DASH-specific review support lower blood pressure. Reviews of multiple dietary patterns add little to this specific comparison.","source_notes":[{"source_id":"9099655","role":"Direct feeding trial","summary":"With sodium intake and body weight held constant, participants assigned the DASH combination diet saw greater reductions in systolic and diastolic pressure than those on the control diet."},{"source_id":"32330233","role":"Pooled research","summary":"Randomized trials of the DASH pattern found lower systolic and diastolic pressure. Sodium intake and other trial conditions varied."}]},{"card_id":"walking-breaks","title":"Break up a seated workday with walks","action":"Choose a studied schedule below. The blood pressure and fatigue findings apply to the light walking schedules.","tracking_prompt":"Log walks and rate fatigue at the same time on comparable days.","goals":["heart","mood","energy"],"benefit_ids":["walking-breaks-1","walking-breaks-2","walking-breaks-3"],"eligibility_rule":"read_studied_population","studied_population":"Sedentary adults completing prolonged sitting days. The exact age and health criteria varied by schedule.","qualification":"These were short laboratory comparisons with prolonged sitting. The studies did not establish a lasting blood-pressure or mood effect.","time_commitment":"Five minutes per break on the chosen schedule.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36728338","27809874","37682412"],"research_summary":"Laboratory studies support same-day effects of walking breaks. A broader blood-pressure review cannot assign mood or fatigue effects to particular schedules.","source_notes":[{"source_id":"36728338","role":"Direct light-walk schedules","summary":"In 11 adults, light walks interrupted laboratory sitting and lowered same-day systolic pressure. Figure 3 supports fatigue and mood findings for the five-minute light-walk schedules. Preserve the separate moderate-walk citation."},{"source_id":"27809874","role":"Direct moderate-walk schedule","summary":"Thirty sedentary adults completed uninterrupted sitting and two activity conditions. Six hourly five-minute moderate walks improved self-rated mood and reduced fatigue compared with sitting. A morning half-hour walk did not show those same results."},{"source_id":"37682412","role":"Broader sitting-break evidence","summary":"Pooled laboratory studies found that interrupting prolonged sitting attenuated increases in blood pressure. The interventions varied. It does not establish mood changes or a particular walking schedule."}]},{"card_id":"one-brisk-walk","title":"Try a ten-minute brisk walk","action":"Take one ten-minute walk at a self-selected brisk pace if appropriate.","tracking_prompt":"Rate fatigue before and shortly after the walk.","goals":["energy"],"benefit_ids":["one-brisk-walk-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Active college-aged adults; mean 21.3; eligible 18–53","qualification":"One study in active young adults measured fatigue immediately afterward.","time_commitment":"One ten-minute walk.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["30087839"],"research_summary":"One small study directly supports lower fatigue after a ten-minute walk versus before the walk. Earlier walking studies emphasized energy or tension, and stair studies changed the activity.","source_notes":[{"source_id":"30087839","role":"Controlled trial","summary":"After a ten-minute brisk walk, young adults reported less fatigue than before. The study reported an overall group-by-time interaction and within-group changes."}]},{"card_id":"nap","title":"Try a brief post-lunch nap opportunity","action":"Allow 15 minutes for a post-lunch nap. The research tested an opportunity to sleep in young adults after restricted sleep.","tracking_prompt":"Record sleepiness afterward.","goals":["energy"],"benefit_ids":["nap-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Young adults after a night of restricted sleep.","qualification":"Allow time to wake fully. The finding comes from young adults after a short night and cannot establish fitness to drive.","time_commitment":"One 15-minute opportunity to sleep, plus time to wake fully.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["11007448","16796222","11322712"],"research_summary":"Short lab trials after restricted sleep support improved afternoon alertness. The study allowing a 15-minute nap opportunity differs from studies timing actual sleep.","source_notes":[{"source_id":"11007448","role":"Direct, nap opportunity","summary":"Twelve students after a restricted night were less sleepy at two afternoon assessments when allowed a 15-minute post-lunch nap than when kept awake. They slept an average of 10.2 minutes."},{"source_id":"16796222","role":"Related duration measure","summary":"After restricted sleep, ten minutes of actual nap sleep improved immediate alertness in a small lab trial. Five, 20 and 30 minutes had different effects. The 15-minute time allowance is supported by the other paper."},{"source_id":"11322712","role":"Related nap duration","summary":"After restricted sleep, ten minutes of afternoon sleep improved subjective alertness immediately. Some testing after a 30-minute nap showed early grogginess. Time asleep differs from a 15-minute opportunity to nap."}]},{"card_id":"oats","title":"Choose oats with a stated beta-glucan amount","action":"Choose oat foods that state their oat beta-glucan content. Use the label to reach about 3 g per day. Total fiber on the label is a different measure.","tracking_prompt":"Log the labeled amount. A lipid panel measures the outcome.","goals":["heart"],"benefit_ids":["oats-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with dyslipidemia","qualification":"Use the labeled amount of oat beta-glucan. Products vary widely. People who need gluten-free foods should choose appropriately labeled oats.","time_commitment":"Daily food choice; at least several weeks in trials.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["25411276","27724985","20660224","35631184"],"research_summary":"Several reviews support lower LDL with oat beta-glucan, with overlapping trials. The product, processing and amount of beta-glucan affect applicability.","source_notes":[{"source_id":"25411276","role":"Pooled research","summary":"Controlled trials using at least 3 g/day of oat beta-glucan found lower LDL compared with control diets. The active amount refers specifically to oat beta-glucan."},{"source_id":"27724985","role":"Pooled research","summary":"A second oat beta-glucan synthesis reported lower LDL across 58 trials. The two syntheses may include many of the same trials."},{"source_id":"20660224","role":"Direct, product-specific result","summary":"Cereals providing 3 g daily of high- or medium-molecular-weight oat beta-glucan lowered LDL by about 5%. The low-molecular-weight preparation was less effective."},{"source_id":"35631184","role":"Overlapping lipid review","summary":"A review in adults with high cholesterol found lower average LDL with oat beta-glucan. Dose, product and study duration varied, and earlier reviews may include the same trials."}]},{"card_id":"pelvic-floor","title":"Follow a supervised pelvic-floor training plan","action":"Arrange supervised training with a qualified clinician. NICE recommends a program lasting at least three months, with at least eight contractions three times a day, adapted to the person.","tracking_prompt":"Keep a bladder diary if recommended.","goals":[],"benefit_ids":["pelvic-floor-1"],"eligibility_rule":"clinician_clearance","studied_population":"Women with stress urinary incontinence.","qualification":"For women with stress urinary incontinence. A clinician should check technique and tailor the program. Supervision is part of the recommendation.","time_commitment":"Three sets daily for at least three months, with supervision.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["30288727","NICE"],"research_summary":"Controlled trials support improved stress incontinence. NICE supplies the supervised schedule. Supervised-versus-unsupervised studies ask a different question.","source_notes":[{"source_id":"30288727","role":"Pooled research","summary":"A Cochrane review compared pelvic-floor training with inactive controls and found symptom improvement in women with stress incontinence."},{"source_id":"NICE","role":"Supervised training schedule","summary":"Sections 1.4.4–1.4.5 recommend at least three months of supervised training for women with stress or mixed incontinence and at least eight contractions three times daily. This is guidance on the program rather than an independent effect estimate."}]},{"card_id":"handgrip","title":"Practice isometric handgrip training","action":"Start with a qualified exercise professional to set the grip force. One example uses four two-minute holds at about 30% of maximum, with three-minute rests, on three days weekly for at least eight weeks.","tracking_prompt":"Log sessions and average blood pressure measured at rest.","goals":["heart"],"benefit_ids":["handgrip-1"],"eligibility_rule":"clinician_clearance","studied_population":"Normotensive and hypertensive adults","qualification":"A suitable force-measuring device and an initial supervised session are needed. Breathe normally. Uncontrolled blood pressure, recent cardiac events or exercise restrictions require clinical assessment. The systolic result is more consistent across reviews than the diastolic result.","time_commitment":"Four two-minute holds plus recoveries, three days weekly for at least eight weeks.","display_evidence_in_details":true,"blocked_if":["exercise_restriction"],"research_source_ids":["41922197","28033302","34140663"],"research_summary":"Reviews support lower resting systolic pressure on average. A smaller review in treated hypertension found an inconclusive diastolic effect.","source_notes":[{"source_id":"41922197","role":"Direct pooled result","summary":"In 31 studies, systolic and diastolic pressure were lower by about 5.4 and 2.7 mmHg on average. Results differed markedly across studies. The four-set protocol is an evidence-informed example."},{"source_id":"28033302","role":"Controlled trial","summary":"Eight weeks of handgrip training at 30% maximum was compared with lower intensity. Systolic pressure fell within the higher-intensity group; its diastolic change was not significant."},{"source_id":"34140663","role":"Endpoint-specific uncertainty","summary":"Across trials in people with treated hypertension, handgrip training lowered resting systolic pressure, while the diastolic estimate was imprecise. Keep the diastolic result qualified."}]},{"card_id":"tai-chi","title":"Join a fall-prevention tai chi program","action":"Choose an instructor-led tai chi program designed for fall prevention. One trial offered classes three times weekly for six months. A second tested a twice-weekly therapeutic program for 24 weeks.","tracking_prompt":"Record class attendance and any falls.","goals":["movement"],"benefit_ids":["tai-chi-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Inactive community adults aged 70–92","qualification":"For older adults at elevated fall risk who can participate in a supervised class. The benefit pertains to tested fall-prevention programs.","time_commitment":"Instructor-led classes for about six months.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["15814861","30208396","37736087"],"research_summary":"Structured programs reduce falls in older adults across trials. Keep evidence on all falls separate from the particular trial measuring repeat falling.","source_notes":[{"source_id":"15814861","role":"Controlled trial","summary":"Older adults in a supervised tai chi program had fewer repeated falls compared with stretching over six months."},{"source_id":"30208396","role":"Related total-fall result","summary":"Among 670 older adults at increased fall risk, twice-weekly therapeutic tai ji quan produced fewer falls than stretching over 24 weeks. Its primary endpoint counted all falls. Cite the earlier trial specifically for repeat falling."},{"source_id":"37736087","role":"Broader fall prevention evidence","summary":"A pooled analysis favored tai chi for preventing falls in older adults across differing programs. Total falls and balance outcomes cannot be substituted for repeat falling on the card."}]},{"card_id":"neck-strength","title":"Follow a taught resistance routine for neck and shoulder pain","action":"Ask a physical therapist to teach the studied elastic-band lateral raise and progression. The short schedule used one slow set for up to two minutes on five workdays per week for ten weeks. A longer tested option appears in the details.","tracking_prompt":"Track pain on the same scale once a week and record training days.","goals":["movement"],"benefit_ids":["neck-strength-1"],"eligibility_rule":"clinician_clearance","studied_population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","qualification":"The trial included initial therapist instruction and planned resistance progression. Seek assessment for new, severe or unexplained pain.","time_commitment":"Two or twelve minutes per session, five workdays weekly for ten weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["21177034","25574172"],"research_summary":"One trial directly supports the tested workday routine, with a companion report for the instructions. Muscle-activity findings do not independently establish pain relief.","source_notes":[{"source_id":"21177034","role":"Controlled trial","summary":"Symptomatic workers received taught progressive band exercises for two or twelve minutes on workdays. Both groups reported less neck or shoulder pain than controls."},{"source_id":"25574172","role":"Tested exercise instructions","summary":"The companion report describes the same workplace intervention, including technique, progression, and sets for the two-minute and twelve-minute options."}]},{"card_id":"sleep-extension","title":"Work with a counselor to extend short sleep","action":"With individualized sleep counseling, plan enough time in bed to allow about 8.5 hours nightly and review the plan at follow-up. The trial enrolled habitual short sleepers with overweight.","tracking_prompt":"Track sleep opportunity and sleep duration separately. A food diary cannot reproduce the trial’s energy-balance measurement.","goals":["sleep","metabolic"],"benefit_ids":["sleep-extension-1","sleep-extension-2"],"eligibility_rule":"clinician_clearance","studied_population":"Adults 21–40, BMI 25–29.9, habitual sleep <6.5 h/night; no sleep apnea or insomnia","qualification":"The study enrolled adults aged 21–40 with overweight who usually slept less than 6.5 hours. Insomnia and sleep apnea were excluded. The trial included individualized counseling and follow-up.","time_commitment":"Nightly for two weeks after individualized counseling.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35129580","34507028"],"research_summary":"A broader review supports increased sleep duration. The objectively estimated energy-intake result remains tied to one two-week trial in short sleepers with overweight.","source_notes":[{"source_id":"35129580","role":"Controlled trial","summary":"Individualized counseling increased measured sleep duration and reduced energy intake over two weeks in short-sleeping adults with overweight. Both results came from the same trial."},{"source_id":"34507028","role":"Broader research","summary":"Sleep-extension interventions increased sleep duration across populations, with substantial variation. This review does not establish lower energy intake."}]},{"card_id":"slow-breathing","title":"Practice slow breathing","action":"Sit comfortably and breathe slowly, about 10 breaths a minute or fewer, for 10 to 15 minutes a day.","tracking_prompt":"Log sessions. Add home blood pressure readings if you already take them.","goals":["heart"],"benefit_ids":["slow-breathing-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with high or high-normal blood pressure, in 17 trials of device-guided and unguided slow breathing.","qualification":"Breathe gently. Stop if you feel light-headed.","time_commitment":"10 to 15 minutes a day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["31331557"],"research_summary":"Pooled trials found a small average drop in blood pressure with regular slow breathing. Results varied a lot between studies, and some device trials had manufacturer involvement.","source_notes":[{"source_id":"31331557","role":"Direct pooled result","summary":"In 17 studies of people with high or high-normal blood pressure, slow breathing lowered systolic pressure by about 5.6 mmHg and diastolic by about 3 mmHg. Heterogeneity was high."}]},{"card_id":"humming","title":"Hum on the out-breath","action":"Breathe in through your nose, then hum gently as you breathe out. Repeat for a few minutes and notice how you feel.","tracking_prompt":"Note how calm you feel afterward. This is a personal experiment.","goals":[],"benefit_ids":[],"eligibility_rule":"read_studied_population","studied_population":"Ten healthy adults in a laboratory measurement of nasal nitric oxide.","qualification":"Stop if you feel light-headed.","time_commitment":"A few minutes","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["12119224"],"research_summary":"Humming raises nitric oxide in the nose many times over in a lab measurement. No study here tested a health benefit, so treat this as a personal experiment.","source_notes":[{"source_id":"12119224","role":"Mechanism only","summary":"Nasal nitric oxide rose about 15-fold during humming in ten healthy adults. The study measured no symptom or health outcome, so it does not support a health claim."}]},{"card_id":"acupuncture-migraine","title":"Try acupuncture for migraine","action":"Book a course of at least six sessions with a licensed acupuncturist, and keep a record of your migraine days.","tracking_prompt":"Log each session and count migraine days per month.","goals":[],"benefit_ids":["acupuncture-migraine-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with episodic migraine in 22 trials (4,985 people).","qualification":"Use a licensed practitioner. Tell them if you take blood thinners.","time_commitment":"At least six sessions, usually weekly","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["27351677"],"research_summary":"Across 22 trials, people having acupuncture had fewer migraine days than people with usual care. Compared with sham acupuncture the extra benefit was small.","source_notes":[{"source_id":"27351677","role":"Direct pooled result","summary":"Migraine days fell from about six a month to about three and a half with acupuncture, versus four with sham or preventive drugs and five with usual care. 50% of people responded to acupuncture and 41% to sham. Moderate-quality evidence."}]},{"card_id":"weighted-blanket","title":"Sleep under a weighted blanket","action":"Sleep under a heavy weighted blanket every night for four weeks. The trial used a chain blanket of about 8 kg.","tracking_prompt":"Note how you slept each morning.","goals":["sleep"],"benefit_ids":["weighted-blanket-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with insomnia and depression, bipolar disorder, generalized anxiety or ADHD (120 people).","qualification":"You should be able to lift it off yourself easily.","time_commitment":"Every night","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32536366"],"research_summary":"One randomized trial found a heavy blanket reduced insomnia severity more than a light one over four weeks, in adults with insomnia and a mental health condition. It has not been repeated yet.","source_notes":[{"source_id":"32536366","role":"Direct result, single trial","summary":"120 adults with insomnia and a psychiatric condition. After 4 weeks, 59% responded with a heavy chain blanket versus 5% with a light blanket. No serious adverse events."}]},{"card_id":"stair-walk-energy","title":"Walk the stairs for energy","action":"When you feel flat, walk up and down stairs at an easy pace for ten minutes.","tracking_prompt":"Rate your energy before and after.","goals":["energy"],"benefit_ids":["stair-walk-energy-1"],"eligibility_rule":"read_studied_population","studied_population":"18 chronically sleep-deprived college women in a crossover study.","qualification":"Hold the rail and go at an easy pace. Stop if you feel dizzy or short of breath.","time_commitment":"10 minutes","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["PHYSBEH-2017-STAIRS"],"research_summary":"In one small study, ten minutes of easy stair walking made sleep-deprived young women feel more energetic than a small dose of caffeine. The boost was brief.","source_notes":[{"source_id":"PHYSBEH-2017-STAIRS","role":"Direct result, small crossover","summary":"18 sleep-deprived college women. Ten minutes of low-to-moderate stair walking raised feelings of energy more than 50 mg caffeine or placebo. Attention and memory did not improve."}]},{"card_id":"drawing-memory","title":"Draw it to remember it","action":"When you need to remember a list or new words, draw a quick sketch of each item instead of writing it out.","tracking_prompt":"Try recalling the items later and count how many you remember.","goals":["memory"],"benefit_ids":["drawing-memory-1"],"eligibility_rule":"read_studied_population","studied_population":"University students in seven laboratory free-recall experiments.","qualification":"Quick sketches are enough. Drawing skill did not matter in the studies.","time_commitment":"A few seconds per item","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["26444654"],"research_summary":"Across seven lab experiments, people remembered words better when they drew them than when they wrote them out. The tests were short and mostly in students.","source_notes":[{"source_id":"26444654","role":"Direct result, lab experiments","summary":"In seven free-recall experiments, drawn words were recalled better than written ones. The benefit held across several comparison tasks."}]},{"card_id":"toilet-footstool","title":"Raise your feet on the toilet","action":"Put a small footstool in front of the toilet and rest your feet on it so your knees are above your hips.","tracking_prompt":"Note how easy each bowel movement felt.","goals":["digestion"],"benefit_ids":["toilet-footstool-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adult volunteers who logged bowel movements for four weeks.","qualification":"See a doctor about new or lasting bowel changes.","time_commitment":"No extra time","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["30346317"],"research_summary":"In one small study of healthy adults, using a footstool shortened time on the toilet and reduced straining. People with constipation were not studied.","source_notes":[{"source_id":"30346317","role":"Direct result, uncontrolled crossover","summary":"Healthy volunteers recorded bowel movements for two weeks without and two weeks with a footstool. With the stool they reported less straining, shorter duration and more complete emptying."}]},{"card_id":"abdominal-massage","title":"Massage your belly for constipation","action":"Lying down, gently massage your belly in slow clockwise circles for about ten minutes.","tracking_prompt":"Note bowel movements and how comfortable you feel.","goals":["digestion"],"benefit_ids":["abdominal-massage-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with functional chronic constipation.","qualification":"Skip it if you have belly pain that hasn’t been checked. See a doctor about new or lasting bowel changes.","time_commitment":"About 10 minutes, several times a week","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35554601","39531948"],"research_summary":"A placebo-controlled trial and a review of small trials found abdominal massage eased constipation symptoms. Techniques and schedules varied.","source_notes":[{"source_id":"35554601","role":"Direct result","summary":"Adults with functional chronic constipation improved more with abdominal massage than with a placebo treatment over four weeks."},{"source_id":"39531948","role":"Pooled research","summary":"Pooled small randomized trials in adults with chronic constipation favored abdominal massage. Methods varied."}]}],"benefits":[{"benefit_id":"walk-after-meals-1","card_id":"walk-after-meals","statement":"Smaller rise in blood glucose in the hours after a meal compared with continued sitting","goals":["metabolic"],"population":"Sedentary adults, mostly healthy or overweight/obese adults in lab test meals","comparator":"Uninterrupted sitting","timeframe":"Acute, hours after a single test meal","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42070794/","https://pubmed.ncbi.nlm.nih.gov/22374636/","https://pubmed.ncbi.nlm.nih.gov/42586449/","https://pubmed.ncbi.nlm.nih.gov/42627002/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["42070794","22374636","42586449","42627002"]},{"benefit_id":"walk-after-meals-2","card_id":"walk-after-meals","statement":"Smaller insulin response after a meal","goals":["metabolic"],"population":"Sedentary adults, mostly healthy or overweight/obese adults in lab test meals","comparator":"Uninterrupted sitting","timeframe":"Acute, hours after a single test meal","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42070794/","https://pubmed.ncbi.nlm.nih.gov/22374636/","https://pubmed.ncbi.nlm.nih.gov/42586449/","https://pubmed.ncbi.nlm.nih.gov/42627002/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["42070794","22374636","42586449","42627002"]},{"benefit_id":"walk-after-meals-3","card_id":"walk-after-meals","statement":"Lower post-meal glucose in adults with type 2 diabetes when walking after meals compared with one untimed daily walk","goals":["metabolic"],"population":"Adults with type 2 diabetes, mean age 60; mean duration 10 years","comparator":"one 30-minute daily walk without specified timing","timeframe":"3-hour meal windows during 2-week periods","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27747394/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":"type_2_diabetes","display_scope":"variant","source_ids":["27747394"]},{"benefit_id":"brisk-walking-1","card_id":"brisk-walking","statement":"Lower resting systolic blood pressure on average after several months","goals":["heart"],"population":"Adults in controlled walking programs, including adults with hypertension.","comparator":"No-exercise control","timeframe":"15 weeks mean","source_urls":["https://pubmed.ncbi.nlm.nih.gov/33630309/","https://pubmed.ncbi.nlm.nih.gov/42405260/"],"evidence_label":"Strong evidence","effect_detail":"About 4.1 mmHg lower systolic pressure than control, pooled across 73 trials (95% CI 3.0–5.2 lower).","audience_filter":null,"display_scope":"card","source_ids":["33630309","42405260"]},{"benefit_id":"brisk-walking-2","card_id":"brisk-walking","statement":"Lower resting diastolic pressure among adults with hypertension","goals":["heart"],"population":"Adults with hypertension","comparator":"Non-exercise controls in pooled RCTs","timeframe":"At least 12 weeks program","source_urls":["https://pubmed.ncbi.nlm.nih.gov/33630309/","https://pubmed.ncbi.nlm.nih.gov/42405260/"],"evidence_label":"Research supported","effect_detail":"The hypertension-specific review estimated about 4.7 mmHg lower diastolic pressure, with low certainty about magnitude.","audience_filter":"hypertension","display_scope":"card","source_ids":["33630309","42405260"]},{"benefit_id":"brisk-walking-3","card_id":"brisk-walking","statement":"Improved aerobic fitness in previously sedentary adults","goals":["movement"],"population":"Previously sedentary adults in regular walking programs.","comparator":"Nonwalking control groups.","timeframe":"Across multiweek walking programs.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/17275896/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["17275896"]},{"benefit_id":"stairs-1","card_id":"stairs","statement":"Better aerobic fitness in inactive young adults","goals":["movement"],"population":"Inactive young adults (Jenkins 2019, Yin 2024: sedentary young adults; Han 2025: inactive young men with obesity, n=12 vs 12). Older adults, women-only samples and clinical groups not covered.","comparator":"No-exercise control (also vs MICT in Yin)","timeframe":"Four to six weeks, depending on the trial schedule.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30649897/","https://pubmed.ncbi.nlm.nih.gov/38569204/","https://pubmed.ncbi.nlm.nih.gov/40087042/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["30649897","38569204","40087042"]},{"benefit_id":"almonds-1","card_id":"almonds","statement":"Slightly lower LDL cholesterol","goals":["heart"],"population":"Adults without cardiovascular disease (healthy or with cardiometabolic risk factors)","comparator":"Control","timeframe":"4 to 72 weeks (median not extracted)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40944180/","https://pubmed.ncbi.nlm.nih.gov/12221048/","https://pubmed.ncbi.nlm.nih.gov/19394473/"],"evidence_label":"Strong evidence","effect_detail":"About 5 mg/dL lower LDL on average.","audience_filter":null,"display_scope":"card","source_ids":["40944180","12221048","19394473"]},{"benefit_id":"almonds-2","card_id":"almonds","statement":"Slightly lower total cholesterol","goals":["heart"],"population":"Adults without cardiovascular disease (healthy or with cardiometabolic risk factors)","comparator":"Control","timeframe":"4 to 72 weeks (median not extracted)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40944180/","https://pubmed.ncbi.nlm.nih.gov/19394473/"],"evidence_label":"Strong evidence","effect_detail":"About 6 mg/dL lower total cholesterol on average.","audience_filter":null,"display_scope":"card","source_ids":["40944180","19394473"]},{"benefit_id":"almonds-3","card_id":"almonds","statement":"Slightly lower apolipoprotein B","goals":["heart"],"population":"Adults without cardiovascular disease (healthy or with cardiometabolic risk factors)","comparator":"Control","timeframe":"4 to 72 weeks (median not extracted)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40944180/"],"evidence_label":"Research supported","effect_detail":"About 4.5 mg/dL lower ApoB in the pooled comparisons.","audience_filter":null,"display_scope":"card","source_ids":["40944180"]},{"benefit_id":"sunscreen-1","card_id":"sunscreen","statement":"Slower visible skin aging over several years in a sunny climate","goals":[],"population":"Healthy adults, esp. fair-skinned, high-UV exposure","comparator":"Discretionary sunscreen","timeframe":"4.5 years","source_urls":["https://pubmed.ncbi.nlm.nih.gov/23732711/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["23732711"]},{"benefit_id":"caffeine-1","card_id":"caffeine","statement":"Late caffeine can reduce objectively measured sleep","goals":["sleep"],"population":"Healthy adults, low-moderate habitual caffeine","comparator":"Placebo (within-person crossover in key trial)","timeframe":"Acute (single doses) to 14 days","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36870101/","https://pubmed.ncbi.nlm.nih.gov/39377163/","https://pubmed.ncbi.nlm.nih.gov/24235903/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36870101","39377163","24235903"]},{"benefit_id":"caffeine-2","card_id":"caffeine","statement":"A 400 mg dose disrupted some sleep measures even 12 hours before bedtime in a small trial","goals":["sleep"],"population":"Healthy men in a small randomized crossover trial.","comparator":"Placebo at the same time before bedtime.","timeframe":"Single doses","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39377163/"],"evidence_label":"Research supported","effect_detail":"The highest tested dose was 400 mg, and 12 hours was the longest interval tested.","audience_filter":null,"display_scope":"card","source_ids":["39377163"]},{"benefit_id":"resistance-sarcopenia-1","card_id":"resistance-sarcopenia","statement":"Resistance-based programs improved strength and walking speed on average. A separate review found several average gains were below thresholds for clinically important change.","goals":["movement"],"population":"Adults with sarcopenia","comparator":"Control","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42947012/","https://pubmed.ncbi.nlm.nih.gov/41212331/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["42947012","41212331"]},{"benefit_id":"bath-1","card_id":"bath","statement":"May shorten time to fall asleep, although reviews disagree","goals":["sleep"],"population":"Adults (mixed health status)","comparator":"No heating","timeframe":"Acute-nightly","source_urls":["https://pubmed.ncbi.nlm.nih.gov/31102877/","https://pubmed.ncbi.nlm.nih.gov/42545422/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["31102877","42545422"]},{"benefit_id":"relax-muscles-1","card_id":"relax-muscles","statement":"Better self-rated sleep quality in trials largely involving people with medical conditions","goals":["sleep"],"population":"Adults, but studies were largely patients (cancer, dialysis), PSQI self-report; adults aged 55+ not significant","comparator":"Control","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42625730/","https://pubmed.ncbi.nlm.nih.gov/38494385/","https://pubmed.ncbi.nlm.nih.gov/41633054/","https://pubmed.ncbi.nlm.nih.gov/34569129/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["42625730","38494385","41633054","34569129"]},{"benefit_id":"cyclic-sighing-1","card_id":"cyclic-sighing","statement":"Improved self-rated positive mood in one month-long trial","goals":["mood"],"population":"Adults 18+, mostly Stanford undergraduates; major medical/psychiatric conditions and pregnancy excluded.","comparator":"5 minutes/day mindfulness meditation","timeframe":"daily pre/post sessions over 28 days","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36630953/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36630953"]},{"benefit_id":"cold-shower-1","card_id":"cold-shower","statement":"Fewer self-reported days absent from work due to sickness in one trial, with no reduction in days feeling ill","goals":[],"population":"Healthy adults 18-65, no severe comorbidity","comparator":"Normal warm shower","timeframe":"90 days","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27631616/"],"evidence_label":"Research supported","effect_detail":"About 29% fewer self-reported sick-leave days relative to controls. Illness days were similar.","audience_filter":null,"display_scope":"card","source_ids":["27631616"]},{"benefit_id":"meal-order-1","card_id":"meal-order","statement":"Smaller early post-meal glucose rise in some short feeding studies","goals":["metabolic"],"population":"Adults with T2D or prediabetes first; healthy adults","comparator":"Carbohydrate-first, same meal","timeframe":"Single meal, 0-180 min","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35210284/","https://pubmed.ncbi.nlm.nih.gov/42045803/","https://pubmed.ncbi.nlm.nih.gov/41837403/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35210284","42045803","41837403"]},{"benefit_id":"bedtime-list-1","card_id":"bedtime-list","statement":"Faster sleep onset in one sleep-lab trial compared with writing about completed tasks","goals":["sleep"],"population":"Healthy adults aged 18–30","comparator":"five-minute list of recently completed activities","timeframe":"single laboratory night","source_urls":["https://pubmed.ncbi.nlm.nih.gov/29058942/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["29058942"]},{"benefit_id":"kiwi-1","card_id":"kiwi","statement":"More complete spontaneous bowel movements from baseline in adults with constipation","goals":["digestion"],"population":"Adults with functional constipation or IBS-C","comparator":"Change from baseline in active-comparator studies. Superiority over psyllium or prunes was not established.","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36537785/","https://pubmed.ncbi.nlm.nih.gov/34074830/"],"evidence_label":"Research supported","effect_detail":"About 1.5–1.7 additional complete spontaneous bowel movements per week from baseline in the larger trial.","audience_filter":null,"display_scope":"card","source_ids":["36537785","34074830"]},{"benefit_id":"kiwi-2","card_id":"kiwi","statement":"Possible improvement in overall digestive comfort","goals":["digestion"],"population":"Adults with functional constipation or IBS-C","comparator":"Baseline or active comparators in constipation studies; results depend on the questionnaire and domain.","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36537785/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36537785"]},{"benefit_id":"beans-1","card_id":"beans","statement":"Lower LDL relative to a rice comparison in one trial in adults with elevated LDL","goals":["heart"],"population":"Adults with LDL 3.0-5.0 mmol/L (n=73, mean age 48)","comparator":"1 cup white rice daily (crossover); half cup of beans also tested","timeframe":"4 weeks per period","source_urls":["https://pubmed.ncbi.nlm.nih.gov/34642756/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["34642756"]},{"benefit_id":"salt-swap-1","card_id":"salt-swap","statement":"Lower average blood pressure compared with ordinary salt","goals":["heart"],"population":"Adults (21 trials, 31,949 people; effect similar with and without a history of hypertension)","comparator":"Regular salt","timeframe":"Months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35945000/","https://pubmed.ncbi.nlm.nih.gov/41578335/"],"evidence_label":"Strong evidence","effect_detail":"About 4.6 mmHg lower systolic and 1.6 mmHg lower diastolic pressure on average.","audience_filter":null,"display_scope":"card","source_ids":["35945000","41578335"]},{"benefit_id":"salt-swap-2","card_id":"salt-swap","statement":"Fewer strokes in a large trial in older high-risk adults in rural China","goals":["heart"],"population":"Adults >=60 with high BP, or prior stroke, who cook at home","comparator":"Usual salt","timeframe":"4.74 years","source_urls":["https://pubmed.ncbi.nlm.nih.gov/34459569/"],"evidence_label":"Research supported","effect_detail":"About 29 versus 34 strokes per 1,000 person-years in the high-risk trial population.","audience_filter":"high_stroke_risk_trial_population","display_scope":"card","source_ids":["34459569"]},{"benefit_id":"whole-grains-1","card_id":"whole-grains","statement":"Small average reduction in LDL across trials of different whole grains","goals":["heart"],"population":"Adults","comparator":"Comparator diets in randomized whole-grain trials.","timeframe":"During controlled dietary interventions of varying duration.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42743912/","https://pubmed.ncbi.nlm.nih.gov/26269373/"],"evidence_label":"Research supported","effect_detail":"Each additional 48 g/day corresponded to about 0.07 mmol/L lower LDL (95% CI 0.05–0.10 lower).","audience_filter":null,"display_scope":"card","source_ids":["42743912","26269373"]},{"benefit_id":"whole-grains-2","card_id":"whole-grains","statement":"Small average reduction in total cholesterol across randomized trials","goals":["heart"],"population":"Adults","comparator":"Comparator diets in randomized whole-grain trials.","timeframe":"During controlled dietary interventions of varying duration.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42743912/","https://pubmed.ncbi.nlm.nih.gov/26269373/"],"evidence_label":"Strong evidence","effect_detail":"Each additional 48 g/day corresponded to about 0.10 mmol/L lower total cholesterol (95% CI 0.07–0.13 lower).","audience_filter":null,"display_scope":"card","source_ids":["42743912","26269373"]},{"benefit_id":"walk-for-ideas-1","card_id":"walk-for-ideas","statement":"More ideas on divergent-thinking tasks during or just after a walk","goals":["memory"],"population":"Mostly university and college students (1,036 participants); few other adults","comparator":"Sitting","timeframe":"Acute: single walk of about 2 to 20 minutes; effect measured during or immediately after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42127076/","https://pubmed.ncbi.nlm.nih.gov/24749966/"],"evidence_label":"Research supported","effect_detail":"The review found better divergent-thinking scores, with considerable uncertainty about the size. Most participants were students.","audience_filter":null,"display_scope":"card","source_ids":["42127076","24749966"]},{"benefit_id":"water-flosser-1","card_id":"water-flosser","statement":"Less bleeding between teeth in adults with gingivitis compared with brushing alone","goals":[],"population":"Adults with gingivitis (16 RCTs, 1,258); not shown in people with healthy gums","comparator":"Brushing alone","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36562267/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36562267"]},{"benefit_id":"social-break-1","card_id":"social-break","statement":"One one-week trial found better self-reported wellbeing. Across abstinence studies, effects on related wellbeing measures were mixed.","goals":["mood"],"population":"Adults, mean age 29.6 (online recruitment)","comparator":"Usual social media use","timeframe":"1 week","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35512731/","https://pubmed.ncbi.nlm.nih.gov/40038410/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35512731","40038410"]},{"benefit_id":"toothbrush-1","card_id":"toothbrush","statement":"Slightly more plaque removed in a single brushing compared with a manual brush","goals":[],"population":"Healthy adults in 28 publications","comparator":"Manual toothbrush","timeframe":"Single brushing","source_urls":["https://pubmed.ncbi.nlm.nih.gov/34877772/","https://pubmed.ncbi.nlm.nih.gov/16170978/","https://pubmed.ncbi.nlm.nih.gov/31050195/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["34877772","16170978","31050195"]},{"benefit_id":"screen-cap-1","card_id":"screen-cap","statement":"Lower depressive symptom scores in a three-week trial in healthy students","goals":["mood"],"population":"Healthy students, mean age 22.7 (n=111; 58 intervention, 53 control)","comparator":"Usual smartphone use (no restriction)","timeframe":"3 weeks; follow-up 6 weeks after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39985031/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["39985031"]},{"benefit_id":"screen-cap-2","card_id":"screen-cap","statement":"Lower self-reported insomnia severity in the same trial","goals":["sleep"],"population":"Healthy students, mean age 22.7 (n=111; 58 intervention, 53 control)","comparator":"Usual smartphone use (no restriction)","timeframe":"3 weeks; follow-up 6 weeks after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39985031/"],"evidence_label":"Research supported","effect_detail":"About 2.6 points better on the Insomnia Severity Index after three weeks in the studied students.","audience_filter":null,"display_scope":"card","source_ids":["39985031"]},{"benefit_id":"screen-cap-3","card_id":"screen-cap","statement":"Possible short-term improvement in wellbeing and stress","goals":["mood"],"population":"Healthy students, mean age 22.7 (n=111; 58 intervention, 53 control)","comparator":"Usual smartphone use (no restriction)","timeframe":"3 weeks; follow-up 6 weeks after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39985031/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["39985031"]},{"benefit_id":"standing-stockings-1","card_id":"standing-stockings","statement":"Less lower-leg swelling during standing work in trials of healthcare workers and hairdressers.","goals":[],"population":"Healthcare workers on six-hour standing shifts and hairdressers exposed to prolonged standing.","comparator":"No stockings","timeframe":"During standing work, with follow-up up to 12 months in the healthcare-worker trial.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/37458579/","https://pubmed.ncbi.nlm.nih.gov/22451457/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["37458579","22451457"]},{"benefit_id":"optimism-1","card_id":"optimism","statement":"Higher short-term self-rated optimism","goals":["mood"],"population":"Adults (age, n not in abstract)","comparator":"Imagining daily activities for the same time","timeframe":"2 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/21450262/","https://pubmed.ncbi.nlm.nih.gov/31545815/","https://pubmed.ncbi.nlm.nih.gov/36724699/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["21450262","31545815","36724699"]},{"benefit_id":"bedtime-phone-1","card_id":"bedtime-phone","statement":"Faster self-reported sleep onset","goals":["sleep"],"population":"Young adults (~21 y) with poor sleep (PSQI>5) and >30 min bedtime phone habit; China; n=38","comparator":"No instruction (usual phone use)","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32040492/"],"evidence_label":"Early evidence","effect_detail":"The groups differed by about ten minutes in their average improvement from baseline. The separate comparison of their final sleep-onset times gave p = 0.049.","audience_filter":null,"display_scope":"card","source_ids":["32040492"]},{"benefit_id":"bedtime-phone-2","card_id":"bedtime-phone","statement":"Better self-reported sleep quality","goals":["sleep"],"population":"Young adults (~21 y) with poor sleep (PSQI>5) and >30 min bedtime phone habit; China; n=38","comparator":"No instruction (usual phone use)","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32040492/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32040492"]},{"benefit_id":"bedtime-phone-3","card_id":"bedtime-phone","statement":"Less pre-sleep arousal","goals":["sleep"],"population":"Young adults (~21 y) with poor sleep (PSQI>5) and >30 min bedtime phone habit; China; n=38","comparator":"No instruction (usual phone use)","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32040492/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32040492"]},{"benefit_id":"blink-1","card_id":"blink","statement":"Less discomfort in short studies of adults with dry eye","goals":[],"population":"Adults with dry eye symptoms (98 and 100 participants in two trials)","comparator":"Artificial tears only (Arita); other blinking regimens (Wolffsohn)","timeframe":"3 days to 2 weeks (+2 weeks after stopping)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40467388/","https://pubmed.ncbi.nlm.nih.gov/32409236/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["40467388","32409236"]},{"benefit_id":"apples-1","card_id":"apples","statement":"Slightly lower LDL in one trial in adults with mildly elevated cholesterol","goals":["heart"],"population":"Mildly hypercholesterolemic adults (n=40; mean age 51)","comparator":"Energy-matched apple control beverage","timeframe":"8 weeks per phase","source_urls":["https://pubmed.ncbi.nlm.nih.gov/31840162/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["31840162"]},{"benefit_id":"work-breaks-1","card_id":"work-breaks","statement":"Less reported discomfort and eyestrain in data-entry workers","goals":[],"population":"Data-entry workers (n=51)","comparator":"Conventional breaks only (Galinsky); reference group with 3-min breaks (Nakphet)","timeframe":"4 weeks (Galinsky); 60 min (Nakphet)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/17514726/","https://pubmed.ncbi.nlm.nih.gov/10877480/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["17514726","10877480"]},{"benefit_id":"hummus-1","card_id":"hummus","statement":"Less hunger and later dessert snacking in a small trial","goals":["metabolic"],"population":"Healthy adults, mean age 26, BMI 24 (n=39)","comparator":"No snack; granola bar snack","timeframe":"6 days per pattern; outcomes measured on day 7","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32488233/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32488233"]},{"benefit_id":"volunteer-1","card_id":"volunteer","statement":"Less self-reported loneliness in one trial of adults aged 59–79","goals":["mood"],"population":"Older adults aged 59 to 79 (n=76)","comparator":"Control group (no volunteering)","timeframe":"24 h, 8 days, 1 week, 1 month","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42054579/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["42054579"]},{"benefit_id":"jumps-1","card_id":"jumps","statement":"Improved femoral-neck bone density across jump-training programs","goals":["movement"],"population":"Adults","comparator":"Control","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/38305252/","https://pubmed.ncbi.nlm.nih.gov/16269526/"],"evidence_label":"Strong evidence","effect_detail":"Pooled programs improved femoral-neck density by about 1.5%. Fracture prevention was untested.","audience_filter":null,"display_scope":"card","source_ids":["38305252","16269526"]},{"benefit_id":"psyllium-1","card_id":"psyllium","statement":"Lower LDL cholesterol across controlled trials","goals":["heart"],"population":"Adults with constipation; raised LDL","comparator":"Control","timeframe":"3+ weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30239559/","https://pubmed.ncbi.nlm.nih.gov/41366295/"],"evidence_label":"Strong evidence","effect_detail":"About 0.33 mmol/L (13 mg/dL) lower LDL in a review of 28 trials.","audience_filter":null,"display_scope":"card","source_ids":["30239559","41366295"]},{"benefit_id":"psyllium-2","card_id":"psyllium","statement":"Improved bowel frequency in adults with constipation","goals":["digestion"],"population":"Adults with constipation; raised LDL","comparator":"Control","timeframe":"4+ weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35816465/","https://pubmed.ncbi.nlm.nih.gov/8824651/"],"evidence_label":"Research supported","effect_detail":"About three more bowel movements weekly, but the estimate ranged from roughly 0.6 to 5.5 and varied widely across trials.","audience_filter":"constipation","display_scope":"card","source_ids":["35816465","8824651"]},{"benefit_id":"retrieval-1","card_id":"retrieval","statement":"Better delayed recall of material practiced across spaced sessions","goals":["memory"],"population":"Medical trainees in the combined-schedule trial. Broader learning studies tested spacing or retrieval separately.","comparator":"Repeated study of the same material on the same schedule in the trainee trial. The spacing review compared spaced and massed retrieval.","timeframe":"Final test about six months after teaching in the example trial.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/19930508/","https://doi.org/10.1007/s10648-020-09572-8"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["19930508","SPACED-2021"]},{"benefit_id":"flight-stockings-1","card_id":"flight-stockings","statement":"Fewer ultrasound-detected symptomless leg clots on flights longer than five hours","goals":[],"population":"Long-haul flyers, especially higher-risk","comparator":"No stockings","timeframe":"Flight >5 h","source_urls":["https://pubmed.ncbi.nlm.nih.gov/33878207/","https://pubmed.ncbi.nlm.nih.gov/11377600/"],"evidence_label":"Strong evidence","effect_detail":"Three screened passengers had a symptomless clot with stockings versus 47 without, across nine trials. The trials could not determine the effect on symptomatic events.","audience_filter":null,"display_scope":"card","source_ids":["33878207","11377600"]},{"benefit_id":"fall-hazards-1","card_id":"fall-hazards","statement":"Fewer falls among higher-risk older adults when home hazards are assessed and addressed","goals":["movement"],"population":"Community-dwelling older adults at higher risk of falls.","comparator":"Usual care or control without targeted home-hazard reduction.","timeframe":"During follow-up in the included trials, commonly around one year.","source_urls":["https://www.cochrane.org/evidence/CD013258_reducing-fall-hazards-within-environment","https://pubmed.ncbi.nlm.nih.gov/34463746/","https://pubmed.ncbi.nlm.nih.gov/10591231/"],"evidence_label":"Strong evidence","effect_detail":"About 38% fewer falls per person-time among higher-risk older adults, rate ratio 0.62 (95% CI 0.56–0.70).","audience_filter":null,"display_scope":"card","source_ids":["FALL","34463746","10591231"]},{"benefit_id":"handwash-1","card_id":"handwash","statement":"Handwashing-promotion programs reduced respiratory infections in some community settings. A smaller review of soap-and-water comparisons found no clear reduction.","goals":[],"population":"Participants in community handwashing-promotion studies in low- and middle-income countries.","comparator":"No handwashing promotion","timeframe":"Trial periods","source_urls":["https://pubmed.ncbi.nlm.nih.gov/37121242/","https://pubmed.ncbi.nlm.nih.gov/34408031/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["37121242","34408031"]},{"benefit_id":"water-premeal-1","card_id":"water-premeal","statement":"Premeal water may modestly increase weight loss over 12 weeks alongside weight-management support. The second trial’s adjusted estimate included no difference.","goals":["metabolic"],"population":"Adults with obesity in primary care and adults aged 55–75 with overweight or obesity on a reduced-calorie diet.","comparator":"Diet alone in one trial and an attention control with weight-management advice in the other.","timeframe":"12 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/19661958/","https://pubmed.ncbi.nlm.nih.gov/26237305/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["19661958","26237305"]},{"benefit_id":"drink-swap-1","card_id":"drink-swap","statement":"Studies have not established a clear weight-loss benefit from replacing sugary drinks with water.","goals":["metabolic"],"population":"Adults with overweight or obesity in water-substitution trials.","comparator":"Usual intake or a comparison program, depending on the trial.","timeframe":"Follow-up varied. The CHOICE trial followed participants for six months.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/38612997/","https://pubmed.ncbi.nlm.nih.gov/22301929/","https://pubmed.ncbi.nlm.nih.gov/35285920/"],"evidence_label":"Early evidence","effect_detail":"The pooled estimate for replacing sugary drinks with water was 0.81 kg lower, with a 95% interval from 1.66 kg lower to 0.03 kg higher.","audience_filter":null,"display_scope":"research_only","source_ids":["38612997","22301929","35285920"]},{"benefit_id":"eat-slowly-1","card_id":"eat-slowly","statement":"Lower intake during some experimental meals","goals":["metabolic"],"population":"Adults participating in experimental meals.","comparator":"Faster eating","timeframe":"Single lab meal","source_urls":["https://pubmed.ncbi.nlm.nih.gov/24847856/","https://pubmed.ncbi.nlm.nih.gov/24388483/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["24847856","24388483"]},{"benefit_id":"three-good-things-1","card_id":"three-good-things","statement":"Participants in one online trial reported greater happiness at later follow-ups after writing three good things each evening for a week.","goals":["mood"],"population":"Adult volunteers in an online positive-psychology trial.","comparator":"Writing about early memories.","timeframe":"Follow-up through six months.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/16045394/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["16045394"]},{"benefit_id":"mindfulness-1","card_id":"mindfulness","statement":"Lower self-reported stress in studied programs","goals":["mood"],"population":"Employees with mild to moderate stress in a digital meditation trial.","comparator":"Waitlist / active control","timeframe":"8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39808431/","https://pubmed.ncbi.nlm.nih.gov/31237569/","https://pubmed.ncbi.nlm.nih.gov/34962055/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["39808431","31237569","34962055"]},{"benefit_id":"left-side-1","card_id":"left-side","statement":"Fewer nighttime reflux symptoms with a device that encouraged left-side sleep compared with a sham device","goals":["digestion"],"population":"Adults with nocturnal reflux","comparator":"Sham device","timeframe":"2 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35301135/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35301135"]},{"benefit_id":"music-1","card_id":"music","statement":"Better self-rated sleep quality in adults with sleep difficulty","goals":["sleep"],"population":"Adults with insomnia - felt sleep quality","comparator":"No treatment / usual care","timeframe":"3 days-3 months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36000763/","https://pubmed.ncbi.nlm.nih.gov/15660547/","https://pubmed.ncbi.nlm.nih.gov/18426457/","https://pubmed.ncbi.nlm.nih.gov/30676671/"],"evidence_label":"Research supported","effect_detail":"Sleep quality improved by about 2.8 points on the Pittsburgh Sleep Quality Index relative to controls, across 10 trials.","audience_filter":null,"display_scope":"card","source_ids":["36000763","15660547","18426457","30676671"]},{"benefit_id":"smell-training-1","card_id":"smell-training","statement":"Possible improvement on smell tests in people with persistent post-viral smell loss","goals":[],"population":"Adults with persistent post-viral smell loss","comparator":"Varied across the studies in the review.","timeframe":"Varied by training program.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32567798/","https://pubmed.ncbi.nlm.nih.gov/32660334/","https://pubmed.ncbi.nlm.nih.gov/42311058/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32567798","32660334","42311058"]},{"benefit_id":"prunes-1","card_id":"prunes","statement":"Small studies in adults with constipation found more complete spontaneous bowel movements during prune consumption.","goals":["digestion"],"population":"Chronic constipation; 37 women, 3 men; mean age 38","comparator":"psyllium 11 g twice daily; both provided about 6 g fiber","timeframe":"3 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/21323688/","https://pubmed.ncbi.nlm.nih.gov/34074830/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["21323688","34074830"]},{"benefit_id":"cystitis-1","card_id":"cystitis","statement":"Fewer recurrent cystitis episodes over a year in premenopausal women with low fluid intake and frequent previous episodes","goals":[],"population":"Healthy premenopausal women ≥18, ≥3 clinician-documented symptomatic cystitis episodes in prior year, ≥1 culture-confirmed; no current symptoms; usual TOTAL beverages <1.5 L/day. Trial additionally required 24-hour urine <1.2 L and, after amendment, osmolality ≥500 mOsm/kg.","comparator":"no additional fluids","timeframe":"12 months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30285042/"],"evidence_label":"Research supported","effect_detail":"About 1.5 fewer confirmed episodes per participant over one year compared with usual fluid intake.","audience_filter":null,"display_scope":"card","source_ids":["30285042"]},{"benefit_id":"dash-1","card_id":"dash","statement":"Lower systolic blood pressure versus a typical control diet","goals":["heart"],"population":"Adults SBP <160 and DBP 80–95 mmHg","comparator":"control diet","timeframe":"8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/9099655/","https://pubmed.ncbi.nlm.nih.gov/32330233/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["9099655","32330233"]},{"benefit_id":"dash-2","card_id":"dash","statement":"Lower diastolic blood pressure versus the same control diet","goals":["heart"],"population":"Adults SBP <160 and DBP 80–95 mmHg","comparator":"control diet","timeframe":"8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/9099655/","https://pubmed.ncbi.nlm.nih.gov/32330233/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["9099655","32330233"]},{"benefit_id":"walking-breaks-1","card_id":"walking-breaks","statement":"Lower same-day systolic pressure in tested light walking-break schedules","goals":["heart"],"population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","comparator":"uninterrupted sitting on a separate randomized test day","timeframe":"Across the 8-hour test day","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["36728338"]},{"benefit_id":"walking-breaks-2","card_id":"walking-breaks","statement":"Better self-rated mood over a seated day in tested schedules","goals":["mood"],"population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","comparator":"uninterrupted sitting on a separate randomized test day","timeframe":"Across the 8-hour test day","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/","https://pubmed.ncbi.nlm.nih.gov/27809874/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["36728338","27809874"]},{"benefit_id":"walking-breaks-3","card_id":"walking-breaks","statement":"Less self-reported fatigue during tested light or moderate walking-break schedules","goals":["energy"],"population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","comparator":"uninterrupted sitting on a separate randomized test day","timeframe":"Across the 8-hour test day","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/","https://pubmed.ncbi.nlm.nih.gov/27809874/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["36728338","27809874"]},{"benefit_id":"one-brisk-walk-1","card_id":"one-brisk-walk","statement":"Young adults reported less fatigue after a ten-minute brisk walk than before it, in one small trial","goals":["energy"],"population":"Active college-aged adults; mean 21.3; eligible 18–53","comparator":"Three randomized groups: walking, meditation or sitting. The walking-group follow-up test compared fatigue before and after walking.","timeframe":"immediately after 10-minute bout","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30087839/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["30087839"]},{"benefit_id":"nap-1","card_id":"nap","statement":"Less afternoon sleepiness in a small trial after a short night","goals":["energy"],"population":"Healthy students, mean22.1; previous night restricted to4h, measured3.5h","comparator":"awake reading during corresponding15minutes","timeframe":"30 and120minutes after nap; first assessment30minutes, not proven onset","source_urls":["https://pubmed.ncbi.nlm.nih.gov/11007448/","https://pubmed.ncbi.nlm.nih.gov/16796222/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["11007448","16796222"]},{"benefit_id":"oats-1","card_id":"oats","statement":"Lower LDL cholesterol with at least 3 g daily of oat beta-glucan in controlled trials","goals":["heart"],"population":"Adults with dyslipidemia","comparator":"Control diets without added oat beta-glucan.","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/25411276/","https://pubmed.ncbi.nlm.nih.gov/27724985/","https://pubmed.ncbi.nlm.nih.gov/20660224/","https://pubmed.ncbi.nlm.nih.gov/35631184/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["25411276","27724985","20660224","35631184"]},{"benefit_id":"pelvic-floor-1","card_id":"pelvic-floor","statement":"Improved stress urinary incontinence in women receiving pelvic-floor muscle training","goals":[],"population":"Women with stress urinary incontinence.","comparator":"No treatment or inactive control.","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30288727/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["30288727"]},{"benefit_id":"handgrip-1","card_id":"handgrip","statement":"Lower resting blood pressure after regular handgrip training","goals":["heart"],"population":"Adults with and without hypertension","comparator":"Non-exercise control","timeframe":"8+ weeks; RCT 4 weeks ambulatory","source_urls":["https://pubmed.ncbi.nlm.nih.gov/41922197/","https://pubmed.ncbi.nlm.nih.gov/28033302/","https://pubmed.ncbi.nlm.nih.gov/34140663/"],"evidence_label":"Research supported","effect_detail":"The pooled estimate was about 5 mmHg lower systolic pressure. Individual trial effects varied substantially.","audience_filter":null,"display_scope":"card","source_ids":["41922197","28033302","34140663"]},{"benefit_id":"tai-chi-1","card_id":"tai-chi","statement":"Fewer repeated falls in community-dwelling older adults compared with stretching","goals":["movement"],"population":"Inactive community adults aged 70–92","comparator":"stretching program","timeframe":"6 months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/15814861/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["15814861"]},{"benefit_id":"neck-strength-1","card_id":"neck-strength","statement":"Less neck and shoulder pain after a therapist-taught progressive exercise program in symptomatic workers","goals":["movement"],"population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","comparator":"weekly general health information","timeframe":"10 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/21177034/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["21177034"]},{"benefit_id":"sleep-extension-1","card_id":"sleep-extension","statement":"Longer objectively measured sleep among habitual short sleepers with overweight","goals":["sleep"],"population":"Adults 21–40, BMI 25–29.9, habitual sleep <6.5 h/night; no sleep apnea or insomnia","comparator":"habitual sleep with study contact","timeframe":"2-week intervention","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35129580/","https://pubmed.ncbi.nlm.nih.gov/34507028/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35129580","34507028"]},{"benefit_id":"sleep-extension-2","card_id":"sleep-extension","statement":"Lower measured energy intake over two weeks in the same group","goals":["metabolic"],"population":"Adults 21–40, BMI 25–29.9, habitual sleep <6.5 h/night; no sleep apnea or insomnia","comparator":"habitual sleep with study contact","timeframe":"2-week intervention","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35129580/"],"evidence_label":"Research supported","effect_detail":"About 270 fewer kcal per day on average than controls over the two-week intervention. Long-term weight change was outside this endpoint.","audience_filter":null,"display_scope":"card","source_ids":["35129580"]},{"benefit_id":"slow-breathing-1","card_id":"slow-breathing","statement":"Small average drop in blood pressure with regular slow breathing","goals":["heart"],"population":"Adults with high or high-normal blood pressure","comparator":"Usual care or control conditions","timeframe":"Weeks of regular practice","source_urls":["https://pubmed.ncbi.nlm.nih.gov/31331557/"],"evidence_label":"Early evidence","effect_detail":"About 5.6 mmHg systolic and 3 mmHg diastolic on average; results varied widely.","audience_filter":null,"display_scope":"card","source_ids":["31331557"]},{"benefit_id":"acupuncture-migraine-1","card_id":"acupuncture-migraine","statement":"Fewer migraine days with a course of acupuncture","goals":[],"population":"Adults with episodic migraine","comparator":"Usual care, sham acupuncture or preventive drugs","timeframe":"At least 8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27351677/"],"evidence_label":"Research supported","effect_detail":"About 3.5 migraine days a month versus 5 with usual care and 4 with sham; small advantage over sham.","audience_filter":null,"display_scope":"card","source_ids":["27351677"]},{"benefit_id":"weighted-blanket-1","card_id":"weighted-blanket","statement":"Less severe insomnia in adults with insomnia and a mental health condition","goals":["sleep"],"population":"Adults with insomnia and depression, bipolar disorder, anxiety or ADHD","comparator":"A light blanket","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32536366/"],"evidence_label":"Early evidence","effect_detail":"59% responded versus 5% with a light blanket.","audience_filter":null,"display_scope":"card","source_ids":["32536366"]},{"benefit_id":"stair-walk-energy-1","card_id":"stair-walk-energy","statement":"Felt more energetic right after ten minutes of stair walking","goals":["energy"],"population":"Sleep-deprived young women","comparator":"50 mg caffeine or placebo","timeframe":"Immediately afterward","source_urls":["https://doi.org/10.1016/j.physbeh.2017.03.013"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["PHYSBEH-2017-STAIRS"]},{"benefit_id":"drawing-memory-1","card_id":"drawing-memory","statement":"Better recall of drawn words than written words","goals":["memory"],"population":"University students in laboratory tests","comparator":"Writing the same words","timeframe":"Minutes after learning","source_urls":["https://pubmed.ncbi.nlm.nih.gov/26444654/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["26444654"]},{"benefit_id":"toilet-footstool-1","card_id":"toilet-footstool","statement":"Less straining and less time on the toilet with a footstool","goals":["digestion"],"population":"Healthy adults","comparator":"The same people without the stool","timeframe":"Two weeks each","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30346317/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["30346317"]},{"benefit_id":"abdominal-massage-1","card_id":"abdominal-massage","statement":"Eased constipation symptoms in adults with functional constipation","goals":["digestion"],"population":"Adults with functional chronic constipation","comparator":"Placebo treatment or usual care","timeframe":"About four weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35554601/","https://pubmed.ncbi.nlm.nih.gov/39531948/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35554601","39531948"]}],"variants":[{"variant_id":"stairs-1","card_id":"stairs","action":"Three times a day, at least 1 hour apart, climb stairs fast: about 60 steps (about 3 flights) or about 30 seconds all-out (about 6 flights). Do this 3 days a week for 6 weeks.","time":"About 3 bouts x 20-30 s = 1 to 1.5 min of climbing per day on 3 days a week.","population":"Sedentary young adults (Jenkins n=12/arm; Yin n=14 snacks, 15 control)","benefit_ids":["stairs-1"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30649897/","https://pubmed.ncbi.nlm.nih.gov/38569204/"],"source_ids":["30649897","38569204"]},{"variant_id":"stairs-2","card_id":"stairs","action":"One session: 3 minutes easy warm-up, then climb stairs fast for 20 seconds, recover 2 minutes, repeat 3 times. 5 days a week for 4 weeks.","time":"3 min warm-up + 3 x 20 s climbing (1 min) + 2 x 2 min recoveries (4 min) = 8 min; with a third recovery, about 10 min per day.","population":"Inactive young men with obesity (n=12 vs 12 control, age ~26, BMI ~27)","benefit_ids":["stairs-1"],"schedule_evidence":"This exact schedule was studied in one small trial in young men. Other stair schedules help support the broader fitness finding.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40087042/"],"source_ids":["40087042"]},{"variant_id":"walking-breaks-1","card_id":"walking-breaks","action":"Across an eight-hour sitting day, take a five-minute light walk every 30 minutes. The experiment used a level treadmill at 2 mph (3.2 km/h); a flat-route walk is a practical adaptation.","time":"Repeated throughout 8 hours. Budget up to 80 minutes walking plus transitions; this is a scheduling allowance, not a verified trial bout count.","population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","benefit_ids":["walking-breaks-1","walking-breaks-2","walking-breaks-3"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/"],"source_ids":["36728338"]},{"variant_id":"walking-breaks-2","card_id":"walking-breaks","action":"Across an eight-hour sitting day, take a five-minute light walk every 60 minutes. The study used a level treadmill at 2 mph (3.2 km/h); ordinary flat-route walking is an adaptation.","time":"Repeated throughout 8 hours. Budget up to 40 minutes walking plus transitions; scheduling allowance, not a verified trial bout count.","population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","benefit_ids":["walking-breaks-1","walking-breaks-2","walking-breaks-3"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/"],"source_ids":["36728338"]},{"variant_id":"walking-breaks-3","card_id":"walking-breaks","action":"Walk for five minutes at moderate effort, once each hour for six bouts. Aim for the studied perceived effort of 12–13 on the 6–20 Borg scale: somewhat hard. The study used individualized treadmill speed/incline.","time":"30 minutes of walking across a 6-hour day, plus transitions. One experimental day per condition.","population":"Healthy sedentary adults 25–50, BMI 18.5–29.9; 21 women/9 men","benefit_ids":["walking-breaks-2","walking-breaks-3"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27809874/"],"source_ids":["27809874"]},{"variant_id":"walk-after-meals-1","card_id":"walk-after-meals","action":"One practical option is a two-minute easy walk every 30 minutes for three hours after a meal. The trial tested that interval for five hours.","time":"Six two-minute walks total 12 minutes in the three-hour example.","population":"Adults interrupting prolonged sitting after a meal.","benefit_ids":["walk-after-meals-1","walk-after-meals-2"],"schedule_evidence":"Two minutes every 30 minutes was tested for five hours after a standardized drink in sedentary men. Three hours is a shorter app example.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42627002/"],"source_ids":["42627002"]},{"variant_id":"walk-after-meals-2","card_id":"walk-after-meals","action":"Walk ten minutes after each main meal.","time":"Three ten-minute walks per day in the trial.","population":"Adults with type 2 diabetes for whom walking is suitable.","benefit_ids":["walk-after-meals-3"],"schedule_evidence":"Tested against one 30-minute daily walk without specified meal timing.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27747394/"],"audience_filter":"type_2_diabetes","source_ids":["27747394"]},{"variant_id":"neck-strength-1","card_id":"neck-strength","action":"Tested package: initially therapist-taught lateral raises with elastic tubing, one slow set up to fatigue or 2 minutes, 5 workdays/week for 10 weeks; resistance progressed using a manual. Do not substitute an arbitrary band routine.","time":"","population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","benefit_ids":["neck-strength-1"],"schedule_evidence":"Studied with initial therapist instruction and a progression plan.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/25574172/","https://pubmed.ncbi.nlm.nih.gov/21177034/"],"source_ids":["25574172","21177034"]},{"variant_id":"neck-strength-2","card_id":"neck-strength","action":"Tested package: initially therapist-taught lateral raises, 5–6 sets of 8–12 repetitions, new sets about every 2 minutes, 12 minutes/session, 5 workdays/week for 10 weeks; manual-guided resistance progression.","time":"","population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","benefit_ids":["neck-strength-1"],"schedule_evidence":"Studied with initial therapist instruction and a progression plan.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/25574172/","https://pubmed.ncbi.nlm.nih.gov/21177034/"],"source_ids":["25574172","21177034"]}],"research_sources":[{"source_id":"10591231","title":"Home visits by an occupational therapist for assessment and modification of environmental hazards: a randomized trial of falls prevention.","url":"https://pubmed.ncbi.nlm.nih.gov/10591231/","year":"1999","role":"Controlled trial","what_it_shows":"An occupational therapist assessed and helped modify homes. The benefit was concentrated among older adults who had previously fallen.","authors":"Cumming RG, Thomas M, Szonyi G, Salkeld G, O'Neill E, Westbury C, Frampton G.","doi":"10.1111/j.1532-5415.1999.tb01556.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"10877480","title":"A field study of supplementary rest breaks for data-entry operators.","url":"https://pubmed.ncbi.nlm.nih.gov/10877480/","year":"2000","role":"Direct occupational result","what_it_shows":"Data-entry operators reported smaller increases in discomfort and eyestrain during periods with four additional five-minute breaks. Data-entry performance was maintained.","authors":"Galinsky TL, Swanson NG, Sauter SL, Hurrell JJ, Schleifer LM.","doi":"10.1080/001401300184297","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"11007448","title":"Maintenance of alertness and performance by a brief nap after lunch under prior sleep deficit.","url":"https://pubmed.ncbi.nlm.nih.gov/11007448/","year":"2000","role":"Direct, nap opportunity","what_it_shows":"Twelve students after a restricted night were less sleepy at two afternoon assessments when allowed a 15-minute post-lunch nap than when kept awake. They slept an average of 10.2 minutes.","authors":"Takahashi M, Arito H.","doi":"10.1093/sleep/23.6.1h","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"12221048","title":"Dose response of almonds on coronary heart disease risk factors: blood lipids, oxidized low-density lipoproteins, lipoprotein(a), homocysteine, and pulmonary nitric oxide: a randomized, controlled, crossover trial.","url":"https://pubmed.ncbi.nlm.nih.gov/12221048/","year":"2002","role":"Direct LDL trial","what_it_shows":"Whole almonds used as snacks lowered LDL in adults with elevated cholesterol in a crossover comparison with control snacks. The tested amounts differed, so this trial does not fix a universal serving.","authors":"Jenkins DJ, Kendall CW, Marchie A, Parker TL, Connelly PW, Qian W, Haight JS, Faulkner D, Vidgen E, Lapsley KG, Spiller GA.","doi":"10.1161/01.cir.0000028421.91733.20","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"15660547","title":"Music improves sleep quality in older adults.","url":"https://pubmed.ncbi.nlm.nih.gov/15660547/","year":"2005","role":"Direct primary example","what_it_shows":"Older adults listening to soothing bedtime music reported better sleep quality over the intervention period than controls. Perceived sleep quality was the relevant endpoint.","authors":"Lai HL, Good M.","doi":"10.1111/j.1365-2648.2004.03281.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"15814861","title":"Tai Chi and fall reductions in older adults: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/15814861/","year":"2005","role":"Controlled trial","what_it_shows":"Older adults in a supervised tai chi program had fewer repeated falls compared with stretching over six months.","authors":"Li F, Harmer P, Fisher KJ, McAuley E, Chaumeton N, Eckstrom E, Wilson NL.","doi":"10.1093/gerona/60.2.187","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"16045394","title":"Positive psychology progress: empirical validation of interventions.","url":"https://pubmed.ncbi.nlm.nih.gov/16045394/","year":"2005","role":"Direct, specific exercise","what_it_shows":"The full report describes a week of writing three things that went well and why. Participants reported greater happiness at later follow-ups than those writing about early memories. This is the link for the exact exercise.","authors":"Seligman ME, Steen TA, Park N, Peterson C.","doi":"10.1037/0003-066x.60.5.410","review_basis":"Abstract and original paper, three-good-things exercise","publication_type":"Primary study"},{"source_id":"16170978","title":"Comparative efficacy of a new battery-powered toothbrush and a commercially available manual toothbrush on the removal of established supragingival plaque: a single-use crossover study in adults.","url":"https://pubmed.ncbi.nlm.nih.gov/16170978/","year":"2005","role":"Controlled trial","what_it_shows":"In a single-use crossover comparison, one battery-powered brush removed more plaque than a manual brush. The finding concerns the tested models.","authors":"Singh S, Rustogi KN, Chaknis P, Petrone ME, DeVizio W, Proskin HM.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"16269526","title":"Effect of low-repetition jump training on bone mineral density in young women.","url":"https://pubmed.ncbi.nlm.nih.gov/16269526/","year":"2006","role":"Direct, one specific regimen","what_it_shows":"In young women, femoral-neck density rose from baseline after six months of ten maximal jumps three times weekly. The pooled estimate on the card comes from the review of multiple programs.","authors":"Kato T, Terashima T, Yamashita T, Hatanaka Y, Honda A, Umemura Y.","doi":"10.1152/japplphysiol.00666.2005","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"16719566","title":"Distributed practice in verbal recall tasks: A review and quantitative synthesis.","url":"https://pubmed.ncbi.nlm.nih.gov/16719566/","year":"2006","role":"One component, spacing","what_it_shows":"Spacing learning episodes improved later retention compared with massed practice. Effective intervals depended on how much later learners were tested. This paper does not establish the feedback and self-testing schedule.","authors":"Cepeda NJ, Pashler H, Vul E, Wixted JT, Rohrer D.","doi":"10.1037/0033-2909.132.3.354","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"16796222","title":"A brief afternoon nap following nocturnal sleep restriction: which nap duration is most recuperative?","url":"https://pubmed.ncbi.nlm.nih.gov/16796222/","year":"2006","role":"Related duration measure","what_it_shows":"After restricted sleep, ten minutes of actual nap sleep improved immediate alertness in a small lab trial. Five, 20 and 30 minutes had different effects. The 15-minute time allowance is supported by the other paper.","authors":"Brooks A, Lack L.","doi":"10.1093/sleep/29.6.831","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"17275896","title":"The effect of walking on fitness, fatness and resting blood pressure: a meta-analysis of randomised, controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/17275896/","year":"2007","role":"Pooled research","what_it_shows":"Controlled trials in previously sedentary adults measured gains in aerobic fitness after regular walking. This supports the fitness benefit separately from blood pressure.","authors":"Murphy MH, Nevill AM, Murtagh EM, Holder RL.","doi":"10.1016/j.ypmed.2006.12.008","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"17514726","title":"Supplementary breaks and stretching exercises for data entry operators: a follow-up field study.","url":"https://pubmed.ncbi.nlm.nih.gov/17514726/","year":"2007","role":"Controlled trial","what_it_shows":"Data-entry workers reported less discomfort and eyestrain when four five-minute breaks were added to their usual breaks.","authors":"Galinsky T, Swanson N, Sauter S, Dunkin R, Hurrell J, Schleifer L.","doi":"10.1002/ajim.20472","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"18426457","title":"Music improves sleep quality in students.","url":"https://pubmed.ncbi.nlm.nih.gov/18426457/","year":"2008","role":"Direct primary example","what_it_shows":"Young adults with sleep complaints who listened to 45 minutes of relaxing classical music at bedtime for three weeks reported improved sleep quality on a questionnaire.","authors":"Harmat L, Takács J, Bódizs R, Bódizs R.","doi":"10.1111/j.1365-2648.2008.04602.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"19661958","title":"Water consumption increases weight loss during a hypocaloric diet intervention in middle-aged and older adults.","url":"https://pubmed.ncbi.nlm.nih.gov/19661958/","year":"2010","role":"Direct, combined program","what_it_shows":"Forty-eight adults aged 55–75 on a reduced-calorie diet were assigned to water before meals or diet alone. Weight loss over 12 weeks was about 2 kg greater with 500 mL water before each main meal.","authors":"Dennis EA, Dengo AL, Comber DL, Flack KD, Savla J, Davy KP, Davy BM.","doi":"10.1038/oby.2009.235","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"19930508","title":"Repeated testing improves long-term retention relative to repeated study: a randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/19930508/","year":"2009","role":"Direct combined example","what_it_shows":"Forty trainees completed repeated testing with feedback versus repeated study. The first session was immediate and two further sessions were roughly two weeks apart. Six-month scores averaged 39% versus 26% on the studied material.","authors":"Larsen DP, Butler AC, Roediger HL.","doi":"10.1111/j.1365-2923.2009.03518.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"20660224","title":"Physicochemical properties of oat β-glucan influence its ability to reduce serum LDL cholesterol in humans: a randomized clinical trial.","url":"https://pubmed.ncbi.nlm.nih.gov/20660224/","year":"2010","role":"Direct, product-specific result","what_it_shows":"Cereals providing 3 g daily of high- or medium-molecular-weight oat beta-glucan lowered LDL by about 5%. The low-molecular-weight preparation was less effective.","authors":"Wolever TM, Tosh SM, Gibbs AL, Brand-Miller J, Duncan AM, Hart V, Lamarche B, Thomson BA, Duss R, Wood PJ.","doi":"10.3945/ajcn.2010.29174","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21177034","title":"Effectiveness of small daily amounts of progressive resistance training for frequent neck/shoulder pain: randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/21177034/","year":"2011","role":"Controlled trial","what_it_shows":"Symptomatic workers received taught progressive band exercises for two or twelve minutes on workdays. Both groups reported less neck or shoulder pain than controls.","authors":"Andersen LL, Saervoll CA, Mortensen OS, Poulsen OM, Hannerz H, Zebis MK.","doi":"10.1016/j.pain.2010.11.016","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21323688","title":"Randomised clinical trial: dried plums (prunes) vs. psyllium for constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/21323688/","year":"2011","role":"Direct exact schedule","what_it_shows":"Forty adults with constipation crossed over between dried plums and psyllium. Fifty grams of dried plums twice daily for three weeks improved complete spontaneous bowel movements and stool consistency relative to psyllium.","authors":"Attaluri A, Donahoe R, Valestin J, Brown K, Rao SS.","doi":"10.1111/j.1365-2036.2011.04594.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21450262","title":"Become more optimistic by imagining a best possible self: effects of a two week intervention.","url":"https://pubmed.ncbi.nlm.nih.gov/21450262/","year":"2011","role":"Direct, tested schedule","what_it_shows":"Five minutes daily of imagining one’s best possible self increased self-rated optimism relative to imagining ordinary daily activities, both after one session and over two weeks.","authors":"Meevissen YM, Peters ML, Alberts HJ.","doi":"10.1016/j.jbtep.2011.02.012","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"22301929","title":"Replacing caloric beverages with water or diet beverages for weight loss in adults: main results of the Choose Healthy Options Consciously Everyday (CHOICE) randomized clinical trial.","url":"https://pubmed.ncbi.nlm.nih.gov/22301929/","year":"2012","role":"Inconclusive water-specific result","what_it_shows":"At six months mean weight loss in the water group did not clearly exceed the attention control. A separate positive analysis combined water and diet drinks. It cannot establish the effect of water alone.","authors":"Tate DF, Turner-McGrievy G, Lyons E, Stevens J, Erickson K, Polzien K, Diamond M, Wang X, Popkin B.","doi":"10.3945/ajcn.111.026278","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"22374636","title":"Breaking up prolonged sitting reduces postprandial glucose and insulin responses.","url":"https://pubmed.ncbi.nlm.nih.gov/22374636/","year":"2012","role":"Direct result, different timing","what_it_shows":"Nineteen adults with overweight or obesity had lower five-hour glucose and insulin responses with two-minute walks every 20 minutes than with uninterrupted sitting. Use for the benefit and the 20-minute interval.","authors":"Dunstan DW, Kingwell BA, Larsen R, Healy GN, Cerin E, Hamilton MT, Shaw JE, Bertovic DA, Zimmet PZ, Salmon J, Owen N.","doi":"10.2337/dc11-1931","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"23732711","title":"Sunscreen and prevention of skin aging: a randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","year":"2013","role":"Direct multi-year result","what_it_shows":"Australian adults assigned daily sunscreen showed less progression of skin aging at 4.5 years than those using it at their discretion. Assessors graded changes without knowing treatment assignment.","authors":"Hughes MC, Williams GM, Baker P, Green AC.","doi":"10.7326/0003-4819-158-11-201306040-00002","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"23929687","title":"Olfactory training is helpful in postinfectious olfactory loss: a randomized, controlled, multicenter study.","url":"https://pubmed.ncbi.nlm.nih.gov/23929687/","year":"2014","role":"Different comparison and duration","what_it_shows":"People with postinfectious smell loss trained with stronger or weaker odors for 18 weeks. Improvement on testing was more common in the higher-concentration arm. Both groups trained, limiting inference about training versus usual care.","authors":"Damm M, Pikart LK, Reimann H, Burkert S, Göktas Ö, Haxel B, Frey S, Charalampakis I, Beule A, Renner B, Hummel T, Hüttenbrink KB.","doi":"10.1002/lary.24340","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"24388483","title":"Slower eating speed lowers energy intake in normal-weight but not overweight/obese subjects.","url":"https://pubmed.ncbi.nlm.nih.gov/24388483/","year":"2014","role":"Controlled trial","what_it_shows":"A fast-versus-slow eating comparison found lower intake in the normal-weight subgroup. The group-by-weight interaction was not significant.","authors":"Shah M, Copeland J, Dart L, Adams-Huet B, James A, Rhea D.","doi":"10.1016/j.jand.2013.11.002","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"24847856","title":"A systematic review and meta-analysis examining the effect of eating rate on energy intake and hunger.","url":"https://pubmed.ncbi.nlm.nih.gov/24847856/","year":"2014","role":"Direct pooled result","what_it_shows":"Experimental meals consumed more slowly were associated with lower intake on average than faster meals. The designs and methods for changing eating rate varied.","authors":"Robinson E, Almiron-Roig E, Rutters F, de Graaf C, Forde CG, Tudur Smith C, Nolan SJ, Jebb SA.","doi":"10.3945/ajcn.113.081745","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"25150680","title":"The effect of testing versus restudy on retention: a meta-analytic review of the testing effect.","url":"https://pubmed.ncbi.nlm.nih.gov/25150680/","year":"2014","role":"One component, retrieval","what_it_shows":"Pooling testing-versus-restudy comparisons favored retrieval for later recall. This supports self-testing as an ingredient. The exact two-week spacing and feedback example comes from the trainee trial.","authors":"Rowland CA.","doi":"10.1037/a0037559","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"25411276","title":"Cholesterol-lowering effects of oat β-glucan: a meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/25411276/","year":"2014","role":"Pooled research","what_it_shows":"Controlled trials using at least 3 g/day of oat beta-glucan found lower LDL compared with control diets. The active amount refers specifically to oat beta-glucan.","authors":"Whitehead A, Beck EJ, Tosh S, Wolever TM.","doi":"10.3945/ajcn.114.086108","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"27631616","title":"The Effect of Cold Showering on Health and Work: A Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/27631616/","year":"2016","role":"Direct, pooled durations","what_it_shows":"Sick-leave days were 29% lower across groups assigned 30–90 seconds of cold water at the end of showers. Self-reported illness days were comparable. The 29% was not estimated specifically for 30 seconds.","authors":"Buijze GA, Sierevelt IN, van der Heijden BC, Dijkgraaf MG, Frings-Dresen MH.","doi":"10.1371/journal.pone.0161749","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"27724985","title":"The effect of oat β-glucan on LDL-cholesterol, non-HDL-cholesterol and apoB for CVD risk reduction: a systematic review and meta-analysis of randomised-controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/27724985/","year":"2016","role":"Pooled research","what_it_shows":"A second oat beta-glucan synthesis reported lower LDL across 58 trials. The two syntheses may include many of the same trials.","authors":"Ho HV, Sievenpiper JL, Zurbau A, Blanco Mejia S, Jovanovski E, Au-Yeung F, Jenkins AL, Vuksan V.","doi":"10.1017/s000711451600341x","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"27747394","title":"Advice to walk after meals is more effective for lowering postprandial glycaemia in type 2 diabetes mellitus than advice that does not specify timing: a randomised crossover study.","url":"https://pubmed.ncbi.nlm.nih.gov/27747394/","year":"2016","role":"Direct, diabetes variant","what_it_shows":"Adults with type 2 diabetes had about 12% less three-hour post-meal glucose exposure with ten minutes of walking after each main meal than with one untimed daily walk. This comparison supplies no insulin estimate.","authors":"Reynolds AN, Mann JI, Williams S, Venn BJ.","doi":"10.1007/s00125-016-4085-2","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"27809874","title":"Effect of frequent interruptions of prolonged sitting on self-perceived levels of energy, mood, food cravings and cognitive function.","url":"https://pubmed.ncbi.nlm.nih.gov/27809874/","year":"2016","role":"Direct moderate-walk schedule","what_it_shows":"Thirty sedentary adults completed uninterrupted sitting and two activity conditions. Six hourly five-minute moderate walks improved self-rated mood and reduced fatigue compared with sitting. A morning half-hour walk did not show those same results.","authors":"Bergouignan A, Legget KT, De Jong N, Kealey E, Nikolovski J, Groppel JL, Jordan C, O'Day R, Hill JO, Bessesen DH.","doi":"10.1186/s12966-016-0437-z","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"28033302","title":"The efficacy of isometric resistance training utilizing handgrip exercise for blood pressure management: A randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/28033302/","year":"2016","role":"Controlled trial","what_it_shows":"Eight weeks of handgrip training at 30% maximum was compared with lower intensity. Systolic pressure fell within the higher-intensity group; its diastolic change was not significant.","authors":"Carlson DJ, Inder J, Palanisamy SKA, McFarlane JR, Dieberg G, Smart NA.","doi":"10.1097/md.0000000000005791","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"29058942","title":"The effects of bedtime writing on difficulty falling asleep: A polysomnographic study comparing to-do lists and completed activity lists.","url":"https://pubmed.ncbi.nlm.nih.gov/29058942/","year":"2018","role":"Direct, one-night comparison","what_it_shows":"Among 57 young adults, writing upcoming tasks for five minutes before bed led to faster objectively measured sleep onset than writing completed tasks. The trial had no group who did neither.","authors":"Scullin MK, Krueger ML, Ballard HK, Pruett N, Bliwise DL.","doi":"10.1037/xge0000374","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30087839","title":"Experimental effects of brief, single bouts of walking and meditation on mood profile in young adults.","url":"https://pubmed.ncbi.nlm.nih.gov/30087839/","year":"2018","role":"Controlled trial","what_it_shows":"After a ten-minute brisk walk, young adults reported less fatigue than before. The study reported an overall group-by-time interaction and within-group changes.","authors":"Edwards MK, Loprinzi PD.","doi":"10.15171/hpp.2018.23","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30208396","title":"Effectiveness of a Therapeutic Tai Ji Quan Intervention vs a Multimodal Exercise Intervention to Prevent Falls Among Older Adults at High Risk of Falling: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/30208396/","year":"2018","role":"Related fall endpoint","what_it_shows":"Among 670 older adults at increased fall risk, twice-weekly therapeutic tai ji quan produced fewer falls than stretching over 24 weeks. Its primary endpoint counted all falls. Cite the earlier trial specifically for repeat falling.","authors":"Li F, Harmer P, Fitzgerald K, Eckstrom E, Akers L, Chou LS, Pidgeon D, Voit J, Winters-Stone K.","doi":"10.1001/jamainternmed.2018.3915","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30239559","title":"Effect of psyllium (Plantago ovata) fiber on LDL cholesterol and alternative lipid targets, non-HDL cholesterol and apolipoprotein B: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/30239559/","year":"2018","role":"Direct LDL result","what_it_shows":"Across 28 controlled trials, a median daily psyllium intake of about 10.2 g lowered LDL by 0.33 mmol/L on average. This is the lipid evidence on this two-benefit card.","authors":"Jovanovski E, Yashpal S, Komishon A, Zurbau A, Blanco Mejia S, Ho HVT, Li D, Sievenpiper J, Duvnjak L, Vuksan V.","doi":"10.1093/ajcn/nqy115","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"30285042","title":"Effect of Increased Daily Water Intake in Premenopausal Women With Recurrent Urinary Tract Infections: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/30285042/","year":"2018","role":"Direct prevention trial","what_it_shows":"Among 140 premenopausal women with recurrent cystitis and low fluid intake, adding 1.5 L of water daily resulted in 1.7 versus 3.2 episodes on average over a year. The study concerned prevention.","authors":"Hooton TM, Vecchio M, Iroz A, Tack I, Dornic Q, Seksek I, Lotan Y.","doi":"10.1001/jamainternmed.2018.4204","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30288727","title":"Pelvic floor muscle training versus no treatment, or inactive control treatments, for urinary incontinence in women.","url":"https://pubmed.ncbi.nlm.nih.gov/30288727/","year":"2018","role":"Pooled research","what_it_shows":"A Cochrane review compared pelvic-floor training with inactive controls and found symptom improvement in women with stress incontinence.","authors":"Dumoulin C, Cacciari LP, Hay-Smith EJC.","doi":"10.1002/14651858.cd005654.pub4","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"30649897","title":"Do stair climbing exercise \"snacks\" improve cardiorespiratory fitness?","url":"https://pubmed.ncbi.nlm.nih.gov/30649897/","year":"2019","role":"Tested schedule","what_it_shows":"Inactive young adults climbed 60 stairs three times daily, separated by one to four hours. Fitness improved after six weeks.","authors":"Jenkins EM, Nairn LN, Skelly LE, Little JP, Gibala MJ.","doi":"10.1139/apnm-2018-0675","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"31102877","title":"Before-bedtime passive body heating by warm shower or bath to improve sleep: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/31102877/","year":"2019","role":"Pooled research","what_it_shows":"This review found shorter sleep-onset time after appropriately timed warm bathing or showering. Included studies varied in their designs.","authors":"Haghayegh S, Khoshnevis S, Smolensky MH, Diller KR, Castriotta RJ.","doi":"10.1016/j.smrv.2019.04.008","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31237569","title":"Efficacy of the Mindfulness Meditation Mobile App \"Calm\" to Reduce Stress Among College Students: Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/31237569/","year":"2019","role":"Direct, student sample","what_it_shows":"Stressed college students assigned to an app-based mindfulness program reported lower perceived stress than a wait-list group. This extends the finding to another study population.","authors":"Huberty J, Green J, Glissmann C, Larkey L, Puzia M, Lee C.","doi":"10.2196/14273","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"31545815","title":"Effects of the Best Possible Self intervention: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/31545815/","year":"2019","role":"Direct pooled result","what_it_shows":"Across different versions of the best-possible-self exercise, participants showed higher optimism on average than comparison groups. The pooled estimate spans different practice formats.","authors":"Carrillo A, Rubio-Aparicio M, Molinari G, Enrique Á, Sánchez-Meca J, Baños RM.","doi":"10.1371/journal.pone.0222386","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31840162","title":"Two apples a day lower serum cholesterol and improve cardiometabolic biomarkers in mildly hypercholesterolemic adults: a randomized, controlled, crossover trial.","url":"https://pubmed.ncbi.nlm.nih.gov/31840162/","year":"2020","role":"Direct, matched drink","what_it_shows":"Two whole apples daily resulted in modestly lower LDL than a matched apple drink after eight weeks in a small crossover trial of adults with mildly elevated cholesterol.","authors":"Koutsos A, Riccadonna S, Ulaszewska MM, Franceschi P, Trošt K, Galvin A, Braune T, Fava F, Perenzoni D, Mattivi F, Tuohy KM, Lovegrove JA.","doi":"10.1093/ajcn/nqz282","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32040492","title":"Effect of restricting bedtime mobile phone use on sleep, arousal, mood, and working memory: A randomized pilot trial.","url":"https://pubmed.ncbi.nlm.nih.gov/32040492/","year":"2020","role":"Direct, self-reported outcomes","what_it_shows":"In 38 young adults a reinforced bedtime phone restriction improved reported sleep onset, sleep quality and bedtime arousal. The groups’ average changes in onset differed by about ten minutes. The paper’s p = 0.049 is the end-of-study group comparison.","authors":"He JW, Tu ZH, Xiao L, Su T, Tang YX.","doi":"10.1371/journal.pone.0228756","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Primary study"},{"source_id":"32330233","title":"Dietary Approaches to Stop Hypertension (DASH) Diet and Blood Pressure Reduction in Adults with and without Hypertension: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/32330233/","year":"2020","role":"Pooled research","what_it_shows":"Randomized trials of the DASH pattern found lower systolic and diastolic pressure. Sodium intake and other trial conditions varied.","authors":"Filippou CD, Tsioufis CP, Thomopoulos CG, Mihas CC, Dimitriadis KS, Sotiropoulou LI, Chrysochoou CA, Nihoyannopoulos PI, Tousoulis DM.","doi":"10.1093/advances/nmaa041","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"32409236","title":"Therapeutic benefits of blinking exercises in dry eye disease.","url":"https://pubmed.ncbi.nlm.nih.gov/32409236/","year":"2021","role":"Related schedule","what_it_shows":"In a four-week before-and-after program, dry-eye symptoms improved. It used a different blink schedule and lacked a randomized no-exercise control.","authors":"Kim AD, Muntz A, Lee J, Wang MTM, Craig JP.","doi":"10.1016/j.clae.2020.04.014","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32488233","title":"An Afternoon Hummus Snack Affects Diet Quality, Appetite, and Glycemic Control in Healthy Adults.","url":"https://pubmed.ncbi.nlm.nih.gov/32488233/","year":"2020","role":"Direct, specified snack","what_it_shows":"Compared with no snack, hummus with pretzels reduced afternoon hunger in 39 healthy adults. Later dessert snacking was about 20% lower than after either no snack or granola bars. The measurement followed six days on each pattern.","authors":"Reister EJ, Leidy HJ.","doi":"10.1093/jn/nxaa139","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32567798","title":"Treatment of post-viral olfactory dysfunction: an evidence-based review with recommendations.","url":"https://pubmed.ncbi.nlm.nih.gov/32567798/","year":"2020","role":"Direct review, varied protocols","what_it_shows":"An evidence review recommends repeated odor training for postviral smell loss based on changes in measured olfactory function. Protocols and odor sets differed across the studies.","authors":"Hura N, Xie DX, Choby GW, Schlosser RJ, Orlov CP, Seal SM, Rowan NR.","doi":"10.1002/alr.22624","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"33630309","title":"Walking for hypertension.","url":"https://pubmed.ncbi.nlm.nih.gov/33630309/","year":"2021","role":"Pooled research","what_it_shows":"Walking programs lowered average systolic pressure in adults. The review judged the diastolic result less certain and used a range of schedules.","authors":"Lee LL, Mulvaney CA, Wong YKY, Chan ES, Watson MC, Lin HH.","doi":"10.1002/14651858.cd008823.pub2","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"33878207","title":"Compression stockings for preventing deep vein thrombosis in airline passengers.","url":"https://pubmed.ncbi.nlm.nih.gov/33878207/","year":"2021","role":"Pooled research","what_it_shows":"Flight trials found fewer symptomless leg clots on screening with compression stockings. They could not estimate protection against symptomatic events.","authors":"Clarke MJ, Broderick C, Hopewell S, Juszczak E, Eisinga A.","doi":"10.1002/14651858.cd004002.pub4","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34074830","title":"Exploratory Comparative Effectiveness Trial of Green Kiwifruit, Psyllium, or Prunes in US Patients With Chronic Constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/34074830/","year":"2021","role":"Direct for bowel frequency","what_it_shows":"In the US comparison all three groups improved in bowel frequency from baseline and responder rates were similar. In the kiwi group bloating and straining also improved. Those symptom outcomes are narrower than overall digestive comfort.","authors":"Chey SW, Chey WD, Jackson K, Eswaran S.","doi":"10.14309/ajg.0000000000001149","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34459569","title":"Effect of Salt Substitution on Cardiovascular Events and Death.","url":"https://pubmed.ncbi.nlm.nih.gov/34459569/","year":"2021","role":"Direct, high-risk population","what_it_shows":"With potassium-enriched salt there were about 29 versus 34 strokes per 1,000 person-years in rural Chinese participants with a prior stroke or who were at least 60 with hypertension. Follow-up averaged 4.74 years.","authors":"Neal B, Wu Y, Feng X, Zhang R, Zhang Y, Shi J, Zhang J, Tian M, Huang L, Li Z, Yu Y, Zhao Y, Zhou B, Sun J, Liu Y, Yin X, Hao Z, Yu J, Li KC, Zhang X, Duan P, Wang F, Ma B, Shi W, Di Tanna GL, Stepien S, Shan S, Pearson SA, Li N, Yan LL, Labarthe D, Elliott P.","doi":"10.1056/nejmoa2105675","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34463746","title":"Home Hazard Removal to Reduce Falls Among Community-Dwelling Older Adults: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/34463746/","year":"2021","role":"Secondary result only","what_it_shows":"A home-hazard intervention lowered the rate of falls in a secondary analysis. The primary measure, time to first fall, did not differ clearly. Attach only to the fall-rate interpretation.","authors":"Stark S, Keglovits M, Somerville E, Hu YL, Barker A, Sykora D, Yan Y.","doi":"10.1001/jamanetworkopen.2021.22044","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34507028","title":"Behavioral interventions to extend sleep duration: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/34507028/","year":"2021","role":"Broader research","what_it_shows":"Sleep-extension interventions increased sleep duration across populations, with substantial variation. This review does not establish lower energy intake.","authors":"Baron KG, Duffecy J, Reutrakul S, Levenson JC, McFarland MM, Lee S, Qeadan F.","doi":"10.1016/j.smrv.2021.101532","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34642756","title":"Canned Beans Decrease Serum Total and LDL Cholesterol in Adults with Elevated LDL Cholesterol in a 4-wk Multicenter, Randomized, Crossover Study.","url":"https://pubmed.ncbi.nlm.nih.gov/34642756/","year":"2021","role":"Direct comparison","what_it_shows":"One cup of beans daily for four weeks produced a lower LDL than white rice. Half a cup did not clearly differ from rice. The trial also found no clear difference between the two portions.","authors":"Doma KM, Dolinar KF, Dan Ramdath D, Wolever TMS, Duncan AM.","doi":"10.1093/jn/nxab323","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34877772","title":"The efficacy of powered toothbrushes: A systematic review and network meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/34877772/","year":"2022","role":"Pooled research","what_it_shows":"Pooled single-brushing studies found slightly greater plaque removal with a powered toothbrush. This specific finding concerns immediate plaque removal.","authors":"Thomassen TMJA, Van der Weijden FGA, Slot DE.","doi":"10.1111/idh.12563","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35129580","title":"Effect of Sleep Extension on Objectively Assessed Energy Intake Among Adults With Overweight in Real-life Settings: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/35129580/","year":"2022","role":"Controlled trial","what_it_shows":"Individualized counseling increased measured sleep duration and reduced energy intake over two weeks in short-sleeping adults with overweight. Both results came from the same trial.","authors":"Tasali E, Wroblewski K, Kahn E, Kilkus J, Schoeller DA.","doi":"10.1001/jamainternmed.2021.8098","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35210284","title":"Efficacy of a meal sequence in patients with type 2 diabetes: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35210284/","year":"2022","role":"Limitation, later time point","what_it_shows":"In eight trials in people with type 2 diabetes there was little clear difference in two-hour plasma glucose or HbA1c. Retain as a limit on interpreting the earlier post-meal changes.","authors":"Okami Y, Tsunoda H, Watanabe J, Kataoka Y.","doi":"10.1136/bmjdrc-2021-002534","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35301135","title":"Sleep Positional Therapy for Nocturnal Gastroesophageal Reflux: A Double-Blind, Randomized, Sham-Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/35301135/","year":"2022","role":"Controlled trial","what_it_shows":"A wearable device encouraged left-side sleep for two weeks. Nighttime reflux symptoms improved relative to a sham device.","authors":"Schuitenmaker JM, Kuipers T, Oude Nijhuis RAB, Schijven MP, Smout AJPM, Fockens P, Bredenoord AJ.","doi":"10.1016/j.cgh.2022.02.058","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35445655","title":"The effect of hand hygiene frequency on reducing acute respiratory infections in the community: a meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35445655/","year":"2022","role":"Inconclusive frequency analysis","what_it_shows":"A model of six community studies estimated a 3% reduction in daily infection probability per extra hand-hygiene event. Even its 80% credible interval included no difference. This cannot support a precise risk reduction or a wash duration.","authors":"Mo Y, Pham TM, Lim C, Horby P, Stewardson AJ, Harbarth S, Scott GM, Cooper BS.","doi":"10.1017/s0950268822000516","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35512731","title":"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/35512731/","year":"2022","role":"Controlled trial","what_it_shows":"One week away from selected social media platforms improved a wellbeing score compared with usual use. Follow-up was short.","authors":"Lambert J, Barnstable G, Minter E, Cooper J, McEwan D.","doi":"10.1089/cyber.2021.0324","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35816465","title":"The Effect of Fiber Supplementation on Chronic Constipation in Adults: An Updated Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/35816465/","year":"2022","role":"Direct psyllium subgroup","what_it_shows":"In the psyllium subgroup, bowel frequency increased by about 3.08 per week, with a wide 95% interval of 0.61 to 5.54 and substantial variation. The overall fiber response rate cannot be attributed to psyllium alone.","authors":"van der Schoot A, Drysdale C, Whelan K, Dimidi E.","doi":"10.1093/ajcn/nqac184","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"35945000","title":"Effects of salt substitutes on clinical outcomes: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35945000/","year":"2022","role":"Pooled research","what_it_shows":"Trials of potassium-enriched salt substitutes found lower systolic and diastolic pressure relative to regular salt.","authors":"Yin X, Rodgers A, Perkovic A, Huang L, Li KC, Yu J, Wu Y, Wu JHY, Marklund M, Huffman MD, Miranda JJ, Miranda JJ, Di Tanna GL, Labarthe D, Elliott P, Tian M, Neal B.","doi":"10.1136/heartjnl-2022-321332","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"36000763","title":"Listening to music for insomnia in adults.","url":"https://pubmed.ncbi.nlm.nih.gov/36000763/","year":"2022","role":"Pooled research","what_it_shows":"A Cochrane review found better perceived sleep quality among adults with insomnia symptoms. Objective sleep measurements were less conclusive.","authors":"Jespersen KV, Pando-Naude V, Koenig J, Jennum P, Vuust P.","doi":"10.1002/14651858.cd010459.pub3","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"36537785","title":"Consumption of 2 Green Kiwifruits Daily Improves Constipation and Abdominal Comfort-Results of an International Multicenter Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/36537785/","year":"2023","role":"Direct, change from baseline","what_it_shows":"Adults with functional constipation or IBS with constipation reported about 1.5–1.7 more complete spontaneous bowel movements per week than at baseline on two green kiwifruit daily. Overall gastrointestinal comfort also improved.","authors":"Gearry R, Fukudo S, Barbara G, Kuhn-Sherlock B, Ansell J, Blatchford P, Eady S, Wallace A, Butts C, Cremon C, Barbaro MR, Pagano I, Okawa Y, Muratubaki T, Okamoto T, Fuda M, Endo Y, Kano M, Kanazawa M, Nakaya N, Nakaya K, Drummond L.","doi":"10.14309/ajg.0000000000002124","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Primary study"},{"source_id":"36562267","title":"Efficacy of power-driven interdental cleaning tools: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/36562267/","year":"2023","role":"Direct, adjunct to brushing","what_it_shows":"Trials in adults with gingivitis found less bleeding between teeth with powered interdental cleaning plus brushing than with brushing alone. Floss gave a comparable result.","authors":"Edlund P, Bertl K, Pandis N, Stavropoulos A.","doi":"10.1002/cre2.691","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"36630953","title":"Brief structured respiration practices enhance mood and reduce physiological arousal.","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","year":"2023","role":"Direct, short-term mood","what_it_shows":"In a month-long remote randomized study, brief breathwork, especially exhale-focused cyclic sighing, improved positive mood more than the meditation comparison. The schedule was five minutes daily.","authors":"Balban MY, Neri E, Kogon MM, Weed L, Nouriani B, Jo B, Holl G, Zeitzer JM, Spiegel D, Huberman AD.","doi":"10.1016/j.xcrm.2022.100895","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"36728338","title":"Breaking Up Prolonged Sitting to Improve Cardiometabolic Risk: Dose-Response Analysis of a Randomized Crossover Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/36728338/","year":"2023","role":"Direct light-walk schedules","what_it_shows":"In 11 adults, light walks interrupted laboratory sitting and lowered same-day systolic pressure. Figure 3 supports fatigue and mood findings for the five-minute light-walk schedules. Preserve the separate moderate-walk citation.","authors":"Duran AT, Friel CP, Serafini MA, Ensari I, Cheung YK, Diaz KM.","doi":"10.1249/mss.0000000000003109","review_basis":"Abstract and full-text results, Figure 3","publication_type":"Primary study"},{"source_id":"36870101","title":"The effect of caffeine on subsequent sleep: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/36870101/","year":"2023","role":"Pooled research","what_it_shows":"The review found less sleep after caffeine. Its beverage-specific cutoff estimates are modeled and cannot establish a safe cutoff for a 400 mg dose.","authors":"Gardiner C, Weakley J, Burke LM, Roach GD, Sargent C, Maniar N, Townshend A, Halson SL.","doi":"10.1016/j.smrv.2023.101764","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37121242","title":"Effectiveness of handwashing with soap for preventing acute respiratory infections in low-income and middle-income countries: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/37121242/","year":"2023","role":"Pooled research","what_it_shows":"Handwashing-with-soap promotion programs reduced respiratory infections in low- and middle-income settings. The review evaluates programs rather than one wash duration.","authors":"Ross I, Bick S, Ayieko P, Dreibelbis R, Wolf J, Freeman MC, Allen E, Brauer M, Cumming O.","doi":"10.1016/s0140-6736(23)00021-1","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37247191","title":"Impact on facial skin aging signs of a 1-year standardized photoprotection over a classical skin care routine in skin phototypes II-VI individuals: A prospective randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/37247191/","year":"2023","role":"Related, one-year result","what_it_shows":"Among 290 Brazilian women, twice-daily SPF 60 slowed progression of some facial aging signs versus usual care over one year. Cite only for that timeframe and regimen.","authors":"Flament F, Mercurio DG, Catalan E, Bouhadanna E, Delaunay C, Miranda DF, Passeron T.","doi":"10.1111/jdv.19230","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"37458579","title":"Randomized controlled trial on occupational graduated compression clinical and cost-effectiveness.","url":"https://pubmed.ncbi.nlm.nih.gov/37458579/","year":"2023","role":"Direct, occupational swelling","what_it_shows":"Graduated stockings countered increases in lower-leg volume in healthcare workers on standing shifts. Seventy-two participants completed data collection. The flight-clot outcome was outside this study.","authors":"Gianesini S, Vagnoni E, Cavicchi C, Chi YW, Pagani A, Tessari M, Zamboni P, Menegatti E.","doi":"10.23736/s0392-9590.23.05030-7","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"37969463","title":"Left lateral decubitus sleeping position is associated with improved gastroesophageal reflux disease symptoms: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/37969463/","year":"2023","role":"Overlapping review","what_it_shows":"The review found evidence linking left-side position to lower acid exposure and summarized the same device trial that reported symptom relief. It adds context without providing another independent device trial.","authors":"Simadibrata DM, Lesmana E, Amangku BR, Wardoyo MP, Simadibrata M.","doi":"10.12998/wjcc.v11.i30.7329","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"38305252","title":"Skeletal site-specific effects of jump training on bone mineral density in adults: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/38305252/","year":"2023","role":"Pooled research","what_it_shows":"Across jump programs, the clearest density improvement was at the femoral neck. The programs varied; the review does not establish fracture prevention.","authors":"Florence GE, Oosthuyse T, Bosch AN.","doi":"10.1080/02640414.2024.2312052","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"38494385","title":"The Effect of Progressive Muscle Relaxation Exercises on Sleep Quality in Cancer Patients Undergoing Chemotherapy: A Randomized Controlled Study.","url":"https://pubmed.ncbi.nlm.nih.gov/38494385/","year":"2024","role":"Direct, clinical population","what_it_shows":"Chemotherapy patients with poor sleep who practiced progressive muscle relaxation scored better on self-rated sleep than a usual-care group. The population limits extrapolation.","authors":"Sarı E, Gündogdu F, Semerci R.","doi":"10.1016/j.soncn.2024.151620","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"38569204","title":"Exercise snacks are a time-efficient alternative to moderate-intensity continuous training for improving cardiorespiratory fitness but not maximal fat oxidation in inactive adults: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/38569204/","year":"2024","role":"Tested schedule","what_it_shows":"The short stair-bout group improved peak oxygen uptake after six weeks. The paper also measured fat oxidation, which did not improve.","authors":"Yin M, Deng S, Chen Z, Zhang B, Zheng H, Bai M, Li H, Zhang X, Deng J, Liu Q, Little JP, Li Y.","doi":"10.1139/apnm-2023-0593","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"38612997","title":"Water Intake and Adiposity Outcomes among Overweight and Obese Individuals: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/38612997/","year":"2024","role":"Inconclusive water-specific result","what_it_shows":"Replacing sugary drinks with water was associated with an estimated 0.81 kg lower weight in the relevant subgroup. Its 95% interval ran from 1.66 kg lower to 0.03 kg higher and includes no difference.","authors":"Chen QY, Khil J, Keum N.","doi":"10.3390/nu16070963","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"39279635","title":"Consistent effect of eating rate on food and energy intake across twenty-four <i>ad libitum</i> meals.","url":"https://pubmed.ncbi.nlm.nih.gov/39279635/","year":"2024","role":"Related, different intervention","what_it_shows":"Researchers changed food texture to slow eating. Participants consumed less energy at those meals. This provides context for eating rate, while testing a different action from deliberately slowing down.","authors":"Heuven LAJ, van Bruinessen M, Tang CS, Stieger M, Lasschuijt MP, Forde CG.","doi":"10.1017/s0007114524001478","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39377163","title":"Dose and timing effects of caffeine on subsequent sleep: a randomized clinical crossover trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39377163/","year":"2025","role":"Direct dose–timing trial","what_it_shows":"Twenty-three men completed placebo and 100 mg or 400 mg conditions at 4, 8 or 12 hours before bed. The higher dose affected sleep initiation and architecture within 12 hours. No statistically clear disruption was detected with 100 mg.","authors":"Gardiner CL, Weakley J, Burke LM, Fernandez F, Johnston RD, Leota J, Russell S, Munteanu G, Townshend A, Halson SL.","doi":"10.1093/sleep/zsae230","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39808431","title":"Digital Meditation to Target Employee Stress: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39808431/","year":"2025","role":"Direct, tested prescription","what_it_shows":"In 1,458 stressed employees, assignment to an app providing ten minutes of daily meditation for eight weeks improved perceived stress compared with waiting list. Actual usage varied.","authors":"Radin RM, Vacarro J, Fromer E, Ahmadi SE, Guan JY, Fisher SM, Pressman SD, Hunter JF, Sweeny K, Tomiyama AJ, Hofschneider LT, Zawadzki MJ, Gavrilova L, Epel ES, Prather AA.","doi":"10.1001/jamanetworkopen.2024.54435","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39985031","title":"Smartphone screen time reduction improves mental health: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39985031/","year":"2025","role":"Direct, single sample","what_it_shows":"After three weeks, 111 students assigned to a daily two-hour phone cap or control differed on depressive symptoms, perceived stress, wellbeing and insomnia severity. The insomnia score differed by 2.59 points at the end. Several outcomes came from these same students.","authors":"Pieh C, Humer E, Hoenigl A, Schwab J, Mayerhofer D, Dale R, Haider K.","doi":"10.1186/s12916-025-03944-z","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"40038410","title":"The effects of social media abstinence on affective well-being and life satisfaction: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/40038410/","year":"2025","role":"Mixed findings","what_it_shows":"A systematic review of social-media breaks found no clear pooled benefit for positive affect, negative affect or life satisfaction. These related endpoints differ from the wellbeing scale of the one-week trial.","authors":"Lemahieu L, Vander Zwalmen Y, Mennes M, Koster EHW, Vanden Abeele MMP, Poels K.","doi":"10.1038/s41598-025-90984-3","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"40087042","title":"Effect of brief intense stair climbing on cardiorespiratory fitness and metabolic risk factors in inactive young men with obesity: A randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/40087042/","year":"2025","role":"Direct, single-session option","what_it_shows":"Young men with obesity completed a four-week vigorous stair program. Peak oxygen uptake improved relative to the pattern in controls. The study found no change in body composition or metabolic variables.","authors":"Han M, Yun J, Kuk JL, Lee S.","doi":"10.1016/j.numecd.2025.103902","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"40467388","title":"Optimisation of blinking exercises for dry eye disease.","url":"https://pubmed.ncbi.nlm.nih.gov/40467388/","year":"2025","role":"Direct, selected schedule","what_it_shows":"Short studies in adults with dry eye found fewer symptoms and incomplete blinks with the selected 15 close–squeeze–open repeats three times a day. Several objective tear-film measures showed no significant change.","authors":"Wolffsohn JS, Travé-Huarte S, Bahra I, Finch C, Anyaegbu U, Garcia-Porta N, Kingsnorth A.","doi":"10.1016/j.clae.2025.102453","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"40627390","title":"A meta-analysis of the effectiveness of gratitude interventions on well-being across cultures.","url":"https://pubmed.ncbi.nlm.nih.gov/40627390/","year":"2025","role":"Related, broader intervention","what_it_shows":"Across 163 samples, diverse gratitude exercises produced a small average wellbeing improvement. This estimate includes many exercises and should not be presented as the effect of writing three good things.","authors":"Choi H, Cha Y, McCullough ME, Coles NA, Oishi S.","doi":"10.1073/pnas.2425193122","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"40944180","title":"Blood Lipid Levels in Response to Almond Consumption: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/40944180/","year":"2025","role":"Direct pooled result","what_it_shows":"In 36 publications, daily almonds lowered LDL by about 5 mg/dL, total cholesterol by about 6 mg/dL, and ApoB by about 4.5 mg/dL relative to controls across varying amounts.","authors":"Musa-Veloso K, Gauntlett C, Geronimo K, Vicente I, Ho SPL.","doi":"10.3390/nu17172791","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"41633054","title":"Progressive muscle relaxation technique improves sleep quality and mental health: A systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/41633054/","year":"2026","role":"Pooled research","what_it_shows":"Another synthesis found better sleep quality after progressive muscle relaxation. Trial effects varied substantially, and the two reviews may include the same participants.","authors":"Donato KO, Falcão L, Nishizima A, Oliveira AS, Gonzalez JV, Ribeiro NN, Abbud C, Braga GA, Garrido G, Donato AO, Eckeli A, Cruz MME, Salles C.","doi":"10.1016/j.jpsychores.2026.112563","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"41922197","title":"The Optimal Dosage of Isometric Handgrip Exercise for Blood Pressure Reduction: Systematic Review and Meta-Analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/41922197/","year":"2026","role":"Direct pooled result","what_it_shows":"In 31 studies, systolic and diastolic pressure were lower by about 5.4 and 2.7 mmHg on average. Results differed markedly across studies. The four-set protocol is an evidence-informed example.","authors":"Lin CW, Jun IB, Igbo V, Babaniamansour A, Meng L, Lin CF, Jan YK.","doi":"10.1111/jch.70246","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42045803","title":"The Impact of Macronutrient Ordering on Postprandial Glycaemic Control in Diabetes: A Systematic Review.","url":"https://pubmed.ncbi.nlm.nih.gov/42045803/","year":"2026","role":"Pooled research","what_it_shows":"Studies in diabetes suggest smaller post-meal glucose excursions when carbohydrates come last. Heterogeneity and low certainty limit the inference.","authors":"McKenzie R, Sterling C, O'Hara H, Woodside J.","doi":"10.1002/edm2.70228","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42054579","title":"Single-session volunteering reduces loneliness in older adults: immediate and long-term effects.","url":"https://pubmed.ncbi.nlm.nih.gov/42054579/","year":"2026","role":"Direct, structured session","what_it_shows":"In a trial of 76 older adults, participants who helped nursing-home residents reported less loneliness within a day. The effect persisted at one month. The participants volunteered within a structured program.","authors":"Niu CC, Wu K, Yu J.","doi":"10.1093/geront/gnag083","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"42070794","title":"The Acute Effects of Interrupting Prolonged Sitting With Regular Activity Breaks on Postprandial Glucose and Insulin in Adults: A Systematic Review and Meta-Analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42070794/","year":"2026","role":"Direct pooled result","what_it_shows":"Across 39 pooled studies, activity breaks reduced the post-meal glucose and insulin response. Walking showed the largest subgroup effects. The comparison between break frequencies does not establish a uniquely best schedule.","authors":"Gale JT, Martin H, Haszard JJ, Peddie MC.","doi":"10.1111/obr.70152","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42127076","title":"The impact of walking on creative thinking: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42127076/","year":"2026","role":"Pooled research","what_it_shows":"Walking improved scores on idea-generation tasks, mostly in student samples. Results for convergent problem solving were uncertain.","authors":"Thabane A, Arora V, Boilard J, Sutoski A, Parpia S, Calic G, Busse JW, McKechnie T, Staibano P, Phillips M, Reiter-Palmon R, Bhandari M.","doi":"10.1371/journal.pone.0347878","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42405260","title":"The optimal dose of brisk walking for improving blood pressure in hypertensive patients: a systematic review and bayesian meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42405260/","year":"2026","role":"Direct pooled result","what_it_shows":"Across 17 trials in adults with hypertension, both pressure measures fell. The full paper reports a pooled diastolic difference of −4.67 mmHg (95% CI −6.26 to −3.08). Its suggested optimal dose was modeled across trials.","authors":"Wang J, Ma L, Lin Q, Yin Y.","doi":"10.7717/peerj.21478","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"42545422","title":"The effect of water immersion thermotherapy on sleep quality: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42545422/","year":"2026","role":"Mixed findings","what_it_shows":"A newer synthesis of immersion trials found no significant improvement in sleep latency. It is included because it qualifies the earlier positive result.","authors":"Chen H, Gao S, Chen W, Gao B.","doi":"10.1007/s00484-026-03281-7","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42586449","title":"Effects of short-bout accumulated exercise on postprandial metabolism in adults: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42586449/","year":"2026","role":"Supporting subgroup","what_it_shows":"Short bouts of accumulated activity reduced post-meal glucose and insulin versus sitting in 29 cohorts. Walking and shorter intervals appeared beneficial in exploratory subgroup analyses. Timing was not compared with a formal interaction test.","authors":"Gong J, Tan L, Wang Y, Yan J, Li Y.","doi":"10.1016/j.ctim.2026.103416","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42625730","title":"The effects of progressive muscle relaxation on sleep quality in adults: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42625730/","year":"2026","role":"Direct, clinical populations","what_it_shows":"Across 14 trials, self-rated sleep improved on average with relaxation. Trial effects varied widely. Table 1 includes a 30-minute twice-weekly program for eight weeks in people with lung cancer and a 40-minute three-times-weekly program for six weeks in women with breast cancer.","authors":"Li K, Chen S, Liu Y, Yu N.","doi":"10.3389/fpubh.2026.1906525","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"42627002","title":"Effects of breaking up prolonged sitting with light-intensity walking on postprandial glucose and lipid responses in sedentary adult men.","url":"https://pubmed.ncbi.nlm.nih.gov/42627002/","year":"2026","role":"Direct result and interval","what_it_shows":"Sixteen sedentary men completed five-hour test-drink conditions. Two-minute walks every 30 minutes reduced glucose exposure by 6.4% and insulin by 18.2% versus sitting. The three-hour app window is an adaptation.","authors":"Kim D, Kim E.","doi":"10.1080/02640414.2026.2722777","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"42743912","title":"Whole-grain consumption and cardiometabolic risk: a meta-analysis of randomized trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42743912/","year":"2026","role":"Pooled research","what_it_shows":"The review separately reports a small decrease in total cholesterol and LDL per 48 g/day of whole grains. Certainty differs between those outcomes.","authors":"Naghshi S, Kiani S, Ostadrahimi A, Jayedi A, Mobasseri M, Arefhosseini S, Tutunchi H, Aune D.","doi":"10.1093/eurheartj/ehag519","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42947012","title":"Effect of resistance, balance, and aerobic training on strength, mobility, balance, and quality of life in older adults with sarcopenia: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42947012/","year":"2026","role":"Direct, varied exercise programs","what_it_shows":"Twelve trials involving 652 adults with sarcopenia found gains in strength and walking speed with exercise. The study table includes resistance exercise twice weekly for 12 weeks and combined resistance and aerobic exercise three times weekly for 12 weeks.","authors":"Alsubaie SF, Nambi G.","doi":"10.1186/s12877-026-08020-6","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"8824651","title":"Effects of psyllium therapy on stool characteristics, colon transit and anorectal function in chronic idiopathic constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/8824651/","year":"1995","role":"Controlled trial","what_it_shows":"Adults with chronic constipation received psyllium or placebo for eight weeks. Stool frequency and consistency improved during psyllium treatment.","authors":"Ashraf W, Park F, Lof J, Quigley EM.","doi":"10.1111/j.1365-2036.1995.tb00433.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"9099655","title":"A clinical trial of the effects of dietary patterns on blood pressure. DASH Collaborative Research Group.","url":"https://pubmed.ncbi.nlm.nih.gov/9099655/","year":"1997","role":"Direct feeding trial","what_it_shows":"With sodium intake and body weight held constant, participants assigned the DASH combination diet saw greater reductions in systolic and diastolic pressure than those on the control diet.","authors":"Appel LJ, Moore TJ, Obarzanek E, Vollmer WM, Svetkey LP, Sacks FM, Bray GA, Vogt TM, Cutler JA, Windhauser MM, Lin PH, Karanja N.","doi":"10.1056/nejm199704173361601","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"FALL","title":"Environmental interventions for preventing falls in older people living in the community","url":"https://www.cochrane.org/evidence/CD013258_reducing-fall-hazards-within-environment","year":"2023","role":"Pooled research","what_it_shows":"Home assessment and actual hazard reduction reduced the rate of falls in higher-risk older adults living in the community. The effect differed by baseline risk.","authors":"","doi":"","review_basis":"Cochrane evidence summary","publication_type":"Review"},{"source_id":"NICE","title":"Urinary incontinence and pelvic organ prolapse in women: management, section 1.4","url":"https://www.nice.org.uk/guidance/ng123/chapter/recommendations","year":"2019","role":"Instruction guideline","what_it_shows":"Sections 1.4.4–1.4.5 recommend at least three months of supervised training for women with stress or mixed incontinence and at least eight contractions three times daily. This is guidance on the program rather than an independent effect estimate.","authors":"","doi":"","review_basis":"Guideline recommendations","publication_type":"Guideline"},{"source_id":"CDC-HANDWASH","title":"Hand Hygiene Frequently Asked Questions","url":"https://www.cdc.gov/clean-hands/faq/index.html","year":"2024","role":"Instruction source","what_it_shows":"CDC explains how to scrub all hand surfaces with soap for at least 20 seconds. This source supplies the technique.","authors":"","doi":"","review_basis":"Public guidance","publication_type":"Guideline"},{"source_id":"25574172","title":"Process Evaluation of Workplace Interventions with Physical Exercise to Reduce Musculoskeletal Disorders","url":"https://pubmed.ncbi.nlm.nih.gov/25574172/","year":"2014","role":"Instruction source","what_it_shows":"The companion report describes the same workplace intervention, including technique, progression, and sets for the two-minute and twelve-minute options.","authors":"","doi":"10.1155/2014/761363","review_basis":"Published exercise methods","publication_type":"Companion methods report"},{"source_id":"36715875","title":"After Dinner Rest a While, After Supper Walk a Mile? A Systematic Review with Meta-analysis on the Acute Postprandial Glycemic Response to Exercise Before and After Meal Ingestion in Healthy Subjects and Patients with Impaired Glucose Tolerance.","url":"https://pubmed.ncbi.nlm.nih.gov/36715875/","year":"2023","role":"Timing review","what_it_shows":"Acute studies generally favored exercising after eating for glucose. Exercise types and schedules varied. This review cannot establish the three-hour break schedule or the type 2 diabetes trial’s specific comparison.","authors":"Engeroff T, Groneberg DA, Wilke J.","doi":"10.1007/s40279-022-01808-7","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"19394473","title":"Almonds have a neutral effect on serum lipid profiles: a meta-analysis of randomized trials.","url":"https://pubmed.ncbi.nlm.nih.gov/19394473/","year":"2009","role":"Earlier, less precise review","what_it_shows":"An earlier synthesis found lower total cholesterol and a borderline LDL estimate whose interval reached zero. The later, larger synthesis provides the card’s modest LDL estimate. Their evidence bases can overlap.","authors":"Phung OJ, Makanji SS, White CM, Coleman CI.","doi":"10.1016/j.jada.2009.02.014","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"24235903","title":"Caffeine effects on sleep taken 0, 3, or 6 hours before going to bed.","url":"https://pubmed.ncbi.nlm.nih.gov/24235903/","year":"2013","role":"Earlier controlled timing study","what_it_shows":"The study tested 400 mg at bedtime or three or six hours beforehand. Sleep was disrupted versus placebo even six hours before bed. The separate 12-hour finding comes from the later trial.","authors":"Drake C, Roehrs T, Shambroom J, Roth T.","doi":"10.5664/jcsm.3170","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41212331","title":"Optimal resistance training prescriptions to improve muscle strength, physical function, and muscle mass in older adults diagnosed with sarcopenia: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/41212331/","year":"2025","role":"Resistance-specific evidence","what_it_shows":"Across 24 trials in 951 older adults with sarcopenia, resistance exercise improved several strength and function measures. Average grip-strength and gait-speed improvements fell below the review’s thresholds for clinically important change.","authors":"Yan R, Chen Y, Zhang R, He J, Lin W, Sun J, Li D.","doi":"10.1007/s40520-025-03235-w","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34569129","title":"The effect of progressive muscle relaxation on sleep quality and fatigue in patients with rheumatoid arthritis: A randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/34569129/","year":"2023","role":"Primary trial in a clinical population","what_it_shows":"People with rheumatoid arthritis assigned to six weeks of progressive muscle relaxation reported better sleep quality than controls. This is a primary example within a field already covered by reviews.","authors":"Kılıç N, Parlar Kılıç S.","doi":"10.1111/ijn.13015","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39879231","title":"Effects of cold-water immersion on health and wellbeing: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/39879231/","year":"2025","role":"Review reusing the sick-leave trial","what_it_shows":"The review’s 29% lower sickness absence figure comes from the original shower trial. It provides no second independent test of that result. Other cold-immersion protocols answer different questions.","authors":"Cain T, Brinsley J, Bennett H, Nelson M, Maher C, Singh B.","doi":"10.1371/journal.pone.0317615","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"41837403","title":"Effects of meal sequence intervention on blood glucose response in healthy adults: a systematic review.","url":"https://pubmed.ncbi.nlm.nih.gov/41837403/","year":"2026","role":"Healthy-adult evidence","what_it_shows":"A review in healthy adults found that most studies reported a smaller acute glucose excursion when vegetables, fruit or protein preceded carbohydrates. The short feeding studies used several meal sequences.","authors":"Kim J, Jang EH, Lee S.","doi":"10.7762/cnr.2025.0027","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"21147704","title":"Kiwifruit improves bowel function in patients with irritable bowel syndrome with constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/21147704/","year":"2010","role":"Related bowel-frequency outcome","what_it_shows":"In adults with constipation-predominant IBS, bowel movement frequency increased after four weeks of kiwifruit. This study measured defecation frequency, a broader outcome than complete spontaneous bowel movements.","authors":"Chang CC, Lin YT, Lu YT, Liu YS, Liu JF.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"17634169","title":"Pinto bean consumption reduces biomarkers for heart disease risk.","url":"https://pubmed.ncbi.nlm.nih.gov/17634169/","year":"2007","role":"Independent trial with a different portion","what_it_shows":"Sixteen adults with mild insulin resistance tried half a cup of pinto beans, black-eyed peas or carrots for eight weeks per condition. LDL fell more with pinto beans than carrots. The one-cup canned-bean card uses a different trial and comparator.","authors":"Winham DM, Hutchins AM, Johnston CS.","doi":"10.1080/07315724.2007.10719607","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"1964898","title":"Can eating baked beans lower plasma cholesterol?","url":"https://pubmed.ncbi.nlm.nih.gov/1964898/","year":"1990","role":"Different bean preparation and outcome","what_it_shows":"In 20 men with mildly high cholesterol, canned baked beans versus canned spaghetti did not clearly lower plasma total cholesterol. The abstract does not give an LDL result. This limits generalization to other canned products.","authors":"Cobiac L, McArthur R, Nestel PJ.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41578335","title":"Comparative effects of salt substitutes on blood pressure, cardiovascular events and mortality: a systematic review and network meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/41578335/","year":"2026","role":"Broader review with overlapping trials","what_it_shows":"Across 34 trials, some potassium-enriched formulations probably lowered systolic pressure. Cardiovascular event evidence was dominated by one large Chinese trial. Do not count the stroke trial twice.","authors":"Lai H, Nesrallah G, Guyatt GH, Vernooij RWM, Liu J, Zhao W, Hou L, Pan B, Huang J, Campbell NRC, Tian J, Yang K, Ge L, Johnston BC.","doi":"10.1186/s12916-026-04635-z","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"26269373","title":"Whole-grain and blood lipid changes in apparently healthy adults: a systematic review and meta-analysis of randomized controlled studies.","url":"https://pubmed.ncbi.nlm.nih.gov/26269373/","year":"2015","role":"Earlier pooled comparison","what_it_shows":"Whole-grain diets modestly lowered LDL and total cholesterol compared with non-whole-grain controls. The trial pool overlaps the period covered by the newer review.","authors":"Hollænder PL, Ross AB, Kristensen M.","doi":"10.3945/ajcn.115.109165","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"24749966","title":"Give your ideas some legs: the positive effect of walking on creative thinking.","url":"https://pubmed.ncbi.nlm.nih.gov/24749966/","year":"2014","role":"Primary experimental example","what_it_shows":"Four experiments compared walking and sitting on idea-generation tasks. Walking improved creative ideation during or shortly after activity. The result depended on the task.","authors":"Oppezzo M, Schwartz DL.","doi":"10.1037/a0036577","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21387981","title":"The effect of different interdental cleaning devices on gingival bleeding.","url":"https://pubmed.ncbi.nlm.nih.gov/21387981/","year":"2011","role":"Different active comparator","what_it_shows":"After four weeks, two oral-irrigator groups had less gingival bleeding than a floss group with manual brushing. This does not duplicate the brushing-alone comparison.","authors":"Rosema NA, Hennequin-Hoenderdos NL, Berchier CE, Slot DE, Lyle DM, van der Weijden GA.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"31050195","title":"How effective is a powered toothbrush as compared to a manual toothbrush? A systematic review and meta-analysis of single brushing exercises.","url":"https://pubmed.ncbi.nlm.nih.gov/31050195/","year":"2020","role":"Overlapping review","what_it_shows":"An earlier review of single-brushing comparisons favored powered brushes over manual brushes for plaque removal. Trials can overlap with the later review.","authors":"Elkerbout TA, Slot DE, Rosema NAM, Van der Weijden GA.","doi":"10.1111/idh.12401","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35389685","title":"Finding the \"sweet spot\" of smartphone use: Reduction or abstinence to increase well-being and healthy lifestyle?! An experimental intervention study.","url":"https://pubmed.ncbi.nlm.nih.gov/35389685/","year":"2023","role":"Different reduction target","what_it_shows":"An experiment reducing daily smartphone use by one hour found improvements in depressive symptoms and wellbeing. It used a relative reduction rather than a two-hour daily cap and does not validate the card’s insomnia score.","authors":"Brailovskaia J, Delveaux J, John J, Wicker V, Noveski A, Kim S, Schillack H, Margraf J.","doi":"10.1037/xap0000430","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"22451457","title":"Compression hosiery for occupational leg symptoms and leg volume: a randomized crossover trial in a cohort of hairdressers.","url":"https://pubmed.ncbi.nlm.nih.gov/22451457/","year":"2013","role":"Independent occupational crossover trial","what_it_shows":"In 108 hairdressers randomized to low-strength stockings and no-compression periods, lower-leg volume averaged 19 mL less with stockings. Symptoms also improved. This supports the swelling result in a second standing occupation.","authors":"Blazek C, Amsler F, Blaettler W, Keo HH, Baumgartner I, Willenberg T.","doi":"10.1258/phleb.2011.011108","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"36724699","title":"The effectiveness and equivalence of different versions of a brief online Best Possible Self (BPS) manipulation to temporary increase optimism and affect.","url":"https://pubmed.ncbi.nlm.nih.gov/36724699/","year":"2023","role":"Different practice duration","what_it_shows":"An online study compared versions of best-possible-self practice. Writing and imagery produced similar immediate improvements in optimism. It did not test how long the effect lasts.","authors":"Boselie JJLM, Vancleef LMG, van Hooren S, Peters ML.","doi":"10.1016/j.jbtep.2023.101837","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"29073407","title":"Restricted use of electronic media, sleep, performance, and mood in high school athletes--a randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/29073407/","year":"2015","role":"Null result in a different population","what_it_shows":"A four-week restriction on electronic media after 10 pm did not improve sleep habits in high-school athletes who already slept well. The rule, population and baseline sleep differed from the card trial.","authors":"Harris A, Gundersen H, Mørk-Andreassen P, Thun E, Bjorvatn B, Pallesen S.","doi":"10.1016/j.sleh.2015.09.011","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41668954","title":"Evening smartphone exposure impairs sleep quality and next-day performance in elite soccer players: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/41668954/","year":"2026","role":"Different exposure and comparison","what_it_shows":"Sixteen male elite soccer players compared two hours of pre-bed smartphone exposure with magazine reading. Sleep quality worsened during phone exposure. This does not establish the effects of a 30-minute cutoff on onset or bedtime arousal.","authors":"Dridi N, Souissi MA, Dridi R, Ceylan Hİ, Bragazzi NL, Salem A, Fekih S, Chtara M, Mkaouer B, Chtourou H, Dergaa I, Souissi N, Stefanica V, Żmijewski P, Morgans R.","doi":"10.5114/biolsport.2026.152348","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"23271615","title":"Intake of whole apples or clear apple juice has contrasting effects on plasma lipids in healthy volunteers.","url":"https://pubmed.ncbi.nlm.nih.gov/23271615/","year":"2013","role":"Related whole-fruit comparison","what_it_shows":"In 23 healthy volunteers, clear apple juice produced higher LDL than whole apples in a four-week crossover study. The whole-apple portion was 550 g daily. This differs from the card’s population and matched drink.","authors":"Ravn-Haren G, Dragsted LO, Buch-Andersen T, Jensen EN, Jensen RI, Németh-Balogh M, Paulovicsová B, Bergström A, Wilcks A, Licht TR, Markowski J, Bügel S.","doi":"10.1007/s00394-012-0489-z","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35449537","title":"Metabolic and Cardiovascular Benefits of Apple and Apple-Derived Products: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/35449537/","year":"2022","role":"Mixed pooled evidence","what_it_shows":"Across trials of apples and apple-derived products, pooled LDL was 2.8 mg/dL lower, with a 95% interval from 5.78 lower to 0.17 higher. The overall result was inconclusive and the review mixed product forms.","authors":"Kim SJ, Anh NH, Jung CW, Long NP, Park S, Cho YH, Yoon YC, Lee EG, Kim M, Son EY, Kim TH, Deng Y, Lim J, Kwon SW.","doi":"10.3389/fnut.2022.766155","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"39855242","title":"The effects of volunteering on loneliness among lonely older adults: the HEAL-HOA dual randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39855242/","year":"2025","role":"Independent longer volunteering program","what_it_shows":"Older volunteers in a structured telephone program reported less loneliness than controls after a sustained intervention. Most effects were not sustained at later follow-up. This does not test one nursing-home visit.","authors":"Yeung DY, Jiang D, Warner LM, Choi NG, Ho RTH, Kwok JYY, Chou KL.","doi":"10.1016/j.lanhl.2024.100664","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41366295","title":"Psyllium supplementation and lipid profiles: systematic review and dose-response meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/41366295/","year":"2025","role":"Later lipid review","what_it_shows":"A later synthesis also found lower LDL and total cholesterol with psyllium. It may reuse trials in the earlier review and offers no additional evidence on constipation.","authors":"Gholami Z, Paknahad Z.","doi":"10.1186/s12263-025-00786-5","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"SPACED-2021","title":"A Meta-Analytic Review of the Benefit of Spacing out Retrieval Practice Episodes on Retention","url":"https://doi.org/10.1007/s10648-020-09572-8","year":"2021","role":"Review of combined practice","what_it_shows":"A review of 29 studies found better later retention when retrieval sessions were spaced rather than massed. This supports the combined learning approach. The specific two-week interval remains a trial example.","authors":"Latimier A, Peyre H, Ramus F.","doi":"10.1007/s10648-020-09572-8","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"11377600","title":"Frequency and prevention of symptomless deep-vein thrombosis in long-haul flights: a randomised trial.","url":"https://pubmed.ncbi.nlm.nih.gov/11377600/","year":"2001","role":"Primary flight trial","what_it_shows":"Screening after long-haul flights found symptomless calf clots in the no-stocking group and none in those wearing stockings. This early trial illustrates the review evidence and should not be counted on top of it.","authors":"Scurr JH, Machin SJ, Bailey-King S, Mackie IJ, McDonald S, Smith PD.","doi":"10.1016/s0140-6736(00)04645-6","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34408031","title":"Soap versus sanitiser for preventing the transmission of acute respiratory infections in the community: a systematic review with meta-analysis and dose-response analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/34408031/","year":"2021","role":"Mixed soap-specific findings","what_it_shows":"In one review, the three soap-and-water trials showed no clear respiratory infection reduction compared with control. Sanitiser results were clearer. The settings and number of soap trials differ from the larger handwashing-promotion review.","authors":"Hoffmann T, Bakhit M, Krzyzaniak N, Del Mar C, Scott AM, Glasziou P.","doi":"10.1136/bmjopen-2020-046175","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"26237305","title":"Efficacy of water preloading before main meals as a strategy for weight loss in primary care patients with obesity: RCT.","url":"https://pubmed.ncbi.nlm.nih.gov/26237305/","year":"2015","role":"Independent primary-care trial","what_it_shows":"Among 84 adults with obesity who received weight-management advice, 500 mL of water before main meals was associated with 1.3 kg more weight loss over 12 weeks than the attention control. The adjusted interval included no difference.","authors":"Parretti HM, Aveyard P, Blannin A, Clifford SJ, Coleman SJ, Roalfe A, Daley AJ.","doi":"10.1002/oby.21167","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35285920","title":"Association of Low- and No-Calorie Sweetened Beverages as a Replacement for Sugar-Sweetened Beverages With Body Weight and Cardiometabolic Risk: A Systematic Review and Meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35285920/","year":"2022","role":"Water-specific subgroup","what_it_shows":"Three trials in this review evaluated water in place of sugary drinks. Evidence for body weight was rated low certainty. Findings for low-calorie sweetened drinks cannot be attributed to water.","authors":"McGlynn ND, Khan TA, Wang L, Zhang R, Chiavaroli L, Au-Yeung F, Lee JJ, Noronha JC, Comelli EM, Blanco Mejia S, Ahmed A, Malik VS, Hill JO, Leiter LA, Agarwal A, Jeppesen PB, Rahelic D, Kahleová H, Salas-Salvadó J, Kendall CWC, Sievenpiper JL.","doi":"10.1001/jamanetworkopen.2022.2092","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37217328","title":"\"Three Good Things\" Digital Intervention Among Health Care Workers: A Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/37217328/","year":"2023","role":"Different schedule and outcomes","what_it_shows":"Healthcare workers were prompted three times weekly to name good things. Positive affect showed a small improvement. Life satisfaction and depressive symptoms did not clearly differ between groups. This differs from nightly writing about why events happened.","authors":"Gold KJ, Dobson ML, Sen A.","doi":"10.1370/afm.2963","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34962055","title":"App-based mindfulness meditation reduces perceived stress and improves self-regulation in working university students: A randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/34962055/","year":"2022","role":"Independent student trial","what_it_shows":"Working university students assigned to an eight-week mindfulness app reported lower stress than wait-listed students. It supports perceived stress in a different sample.","authors":"Schulte-Frankenfeld PM, Trautwein FM.","doi":"10.1111/aphw.12328","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30676671","title":"A randomized controlled trial of bedtime music for insomnia disorder.","url":"https://pubmed.ncbi.nlm.nih.gov/30676671/","year":"2019","role":"Mixed findings across sleep measures","what_it_shows":"In adults with insomnia, bedtime music improved perceived sleep on a secondary measure. The primary comparison on insomnia severity was inconclusive, and objective sleep measures showed no change.","authors":"Jespersen KV, Otto M, Kringelbach M, Van Someren E, Vuust P.","doi":"10.1111/jsr.12817","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32660334","title":"Olfactory Training for Postviral Olfactory Dysfunction: Systematic Review and Meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/32660334/","year":"2021","role":"Postviral training review","what_it_shows":"Across four pooled studies, trained participants were more likely than controls to improve by a clinically important amount on an odor test. Training protocols varied.","authors":"Kattar N, Do TM, Unis GD, Migneron MR, Thomas AJ, McCoul ED.","doi":"10.1177/0194599820943550","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42311058","title":"Olfactory Training for COVID-19-Related Olfactory Dysfunction: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42311058/","year":"2026","role":"Post-COVID subgroup","what_it_shows":"Ten randomized trials in post-COVID smell loss found a small average improvement in objective smell scores. The finding applies to this postviral subgroup across varied protocols.","authors":"Albazee E, Aldawas G, Alzeeby M, Alebrahim AH, Alwael A.","doi":"10.4274/tao.2026.2026-3-27","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31988085","title":"Increased fluid intake to prevent urinary tract infections: systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/31988085/","year":"2020","role":"Broader recurrence review","what_it_shows":"A review of increased fluid intake found fewer recurrent urinary infections overall. At 12 months the difference in the proportion with any recurrence was inconclusive. It pools different fluid interventions and does not independently verify the card’s exact water dose.","authors":"Scott AM, Clark J, Mar CD, Glasziou P.","doi":"10.3399/bjgp20x708125","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37682412","title":"The Effect of Sitting Duration on Peripheral Blood Pressure Responses to Prolonged Sitting, With and Without Interruption: A Systematic Review and Meta-Analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/37682412/","year":"2024","role":"Broader sitting-break evidence","what_it_shows":"Pooled laboratory studies found that interrupting prolonged sitting attenuated increases in blood pressure. The interventions varied. It does not establish mood changes or a particular walking schedule.","authors":"Adams NT, Paterson C, Poles J, Higgins S, Stoner L.","doi":"10.1007/s40279-023-01915-z","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"11322712","title":"The short-term benefits of brief and long naps following nocturnal sleep restriction.","url":"https://pubmed.ncbi.nlm.nih.gov/11322712/","year":"2001","role":"Related nap duration","what_it_shows":"After restricted sleep, ten minutes of afternoon sleep improved subjective alertness immediately. Some testing after a 30-minute nap showed early grogginess. Time asleep differs from a 15-minute opportunity to nap.","authors":"Tietzel AJ, Lack LC.","doi":"10.1093/sleep/24.3.293","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35631184","title":"Effects of Oat Beta-Glucan Intake on Lipid Profiles in Hypercholesterolemic Adults: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/35631184/","year":"2022","role":"Overlapping lipid review","what_it_shows":"A review in adults with high cholesterol found lower average LDL with oat beta-glucan. Dose, product and study duration varied, and earlier reviews may include the same trials.","authors":"Yu J, Xia J, Yang C, Pan D, Xu D, Sun G, Xia H.","doi":"10.3390/nu14102043","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34140663","title":"Isometric handgrip exercise training reduces resting systolic blood pressure but does not interfere with diastolic blood pressure and heart rate variability in hypertensive subjects: a systematic review and meta-analysis of randomized clinical trials.","url":"https://pubmed.ncbi.nlm.nih.gov/34140663/","year":"2021","role":"Endpoint-specific uncertainty","what_it_shows":"Across trials in people with treated hypertension, handgrip training lowered resting systolic pressure, while the diastolic estimate was imprecise. Keep the diastolic result qualified.","authors":"Almeida JPAS, Bessa M, Lopes LTP, Gonçalves A, Roever L, Zanetti HR.","doi":"10.1038/s41440-021-00681-7","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37736087","title":"Tai Chi for fall prevention and balance improvement in older adults: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/37736087/","year":"2023","role":"Broader fall prevention evidence","what_it_shows":"A pooled analysis favored tai chi for preventing falls in older adults across differing programs. Total falls and balance outcomes cannot be substituted for repeat falling on the card.","authors":"Chen W, Li M, Li H, Lin Y, Feng Z.","doi":"10.3389/fpubh.2023.1236050","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31331557","title":"Device and non-device-guided slow breathing to reduce blood pressure: A systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/31331557/","year":"2019","role":"Pooled research","what_it_shows":"17 studies in people with hypertension or prehypertension. Slow breathing lowered systolic pressure by about 5.6 mmHg and diastolic by about 3.0 mmHg, with high heterogeneity between studies.","authors":"Chaddha A, Modaff D, Hooper-Lane C, Feldstein DA.","doi":"10.1016/j.ctim.2019.03.005","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Systematic review and meta-analysis"},{"source_id":"12119224","title":"Humming greatly increases nasal nitric oxide","url":"https://pubmed.ncbi.nlm.nih.gov/12119224/","year":"2002","role":"Mechanism study","what_it_shows":"In ten healthy volunteers, nasal nitric oxide was about 15 times higher while humming than during quiet exhalation. No health outcome was measured.","authors":"Weitzberg E, Lundberg JO.","doi":"10.1164/rccm.200203-232OC","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"27351677","title":"Acupuncture for the prevention of episodic migraine","url":"https://pubmed.ncbi.nlm.nih.gov/27351677/","year":"2016","role":"Pooled research","what_it_shows":"22 trials, 4,985 people with episodic migraine. Acupuncture reduced headache frequency compared with no acupuncture; the advantage over sham acupuncture was small (50% vs 41% responders). Moderate-quality evidence.","authors":"Linde K, Allais G, Brinkhaus B, Fei Y, Mehring M, Vertosick EA, Vickers A, White AR.","doi":"10.1002/14651858.CD001218.pub3","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Cochrane systematic review"},{"source_id":"32536366","title":"A randomized controlled study of weighted chain blankets for insomnia in psychiatric disorders","url":"https://pubmed.ncbi.nlm.nih.gov/32536366/","year":"2020","role":"Controlled trial","what_it_shows":"120 adults with insomnia and major depression, bipolar disorder, generalized anxiety or ADHD. After 4 weeks, a heavy chain blanket lowered insomnia severity more than a light one (large effect; 59% vs 5% responded). No serious adverse events.","authors":"Ekholm B, Spulber S, Adler M.","doi":"10.5664/jcsm.8636","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"PHYSBEH-2017-STAIRS","title":"Stair walking is more energizing than low dose caffeine in sleep deprived young women","url":"https://doi.org/10.1016/j.physbeh.2017.03.013","year":"2017","role":"Controlled trial","what_it_shows":"Crossover study in 18 chronically sleep-deprived college women. Ten minutes of low-to-moderate stair walking (about 30 floors) increased feelings of energy more than 50 mg caffeine or placebo. The effect was short-lived and attention and memory did not improve.","authors":"Randolph DD, O'Connor PJ.","doi":"10.1016/j.physbeh.2017.03.013","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"26444654","title":"The drawing effect: Evidence for reliable and robust memory benefits in free recall","url":"https://pubmed.ncbi.nlm.nih.gov/26444654/","year":"2016","role":"Experimental studies","what_it_shows":"Seven laboratory experiments, mostly with university students. Words that people drew were recalled better than words they wrote out.","authors":"Wammes JD, Meade ME, Fernandes MA.","doi":"10.1080/17470218.2015.1094494","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"30346317","title":"Implementation of a Defecation Posture Modification Device: Impact on Bowel Movement Patterns in Healthy Subjects","url":"https://pubmed.ncbi.nlm.nih.gov/30346317/","year":"2019","role":"Uncontrolled crossover study","what_it_shows":"Healthy volunteers logged bowel movements for two weeks without and two weeks with a toilet footstool. With the stool, they reported shorter time, less straining and more complete emptying. Healthy adults only; self-reported.","authors":"Modi RM, Hinton A, Pinkhas D, et al.","doi":"10.1097/MCG.0000000000001143","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"35554601","title":"Abdominal Massage in Functional Chronic Constipation: A Randomized Placebo-Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/35554601/","year":"2022","role":"Controlled trial","what_it_shows":"Adults with functional chronic constipation. Abdominal massage improved constipation severity and quality of life more than a placebo treatment over four weeks. The session schedule reported in reviews (10 minutes, three times weekly) was not checked against the full text.","authors":"Doğan IG, Gürşen C, Akbayrak T, et al.","doi":"10.1093/ptj/pzac058","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"39531948","title":"Effectiveness of abdominal massage on chronic constipation in adults: A systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/39531948/","year":"2025","role":"Pooled research","what_it_shows":"Pooled randomized trials in adults with chronic constipation. The authors concluded abdominal massage was effective; trials were small and varied in technique.","authors":"","doi":"","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Systematic review and meta-analysis"}]}$catalog$::jsonb)
on conflict (version) do nothing;
do $check$ begin
  if (select payload from public.humanology_catalog_releases where version='2026-11-27.1')
    is distinct from $catalog${"schema_version":1,"catalog_version":"2026-11-27.1","cards":[{"card_id":"walk-after-meals","title":"Take short walks after a meal","action":"Choose the walking schedule that matches your situation below.","tracking_prompt":"Log the walks. Glucose is optional if you already monitor it.","goals":["metabolic"],"benefit_ids":["walk-after-meals-1","walk-after-meals-2","walk-after-meals-3"],"eligibility_rule":"read_studied_population","studied_population":"Adults sitting after meals. The ten-minute meal-timed schedule was tested in adults with type 2 diabetes.","qualification":"The brief walking breaks were compared with sitting. The ten-minute walks after meals were compared with one daily walk in people with type 2 diabetes. Use your usual diabetes exercise precautions.","time_commitment":"From 12 minutes per meal in the break example, or one ten-minute walk after each main meal.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42070794","22374636","42586449","42627002","27747394","36715875"],"research_summary":"Walking breaks and meal-timed walks have separate glucose comparisons. A timing review adds context for exercise soon after meals.","source_notes":[{"source_id":"42070794","role":"Direct pooled result","summary":"Across 39 pooled studies, activity breaks reduced the post-meal glucose and insulin response. Walking showed the largest subgroup effects. The comparison between break frequencies does not establish a uniquely best schedule."},{"source_id":"22374636","role":"Direct result, different timing","summary":"Nineteen adults with overweight or obesity had lower five-hour glucose and insulin responses with two-minute walks every 20 minutes than with uninterrupted sitting. Use for the benefit and the 20-minute interval."},{"source_id":"42586449","role":"Supporting subgroup","summary":"Short bouts of accumulated activity reduced post-meal glucose and insulin versus sitting in 29 cohorts. Walking and shorter intervals appeared beneficial in exploratory subgroup analyses. Timing was not compared with a formal interaction test."},{"source_id":"42627002","role":"Direct result and interval","summary":"Sixteen sedentary men completed five-hour test-drink conditions. Two-minute walks every 30 minutes reduced glucose exposure by 6.4% and insulin by 18.2% versus sitting. The three-hour app window is an adaptation."},{"source_id":"27747394","role":"Direct, diabetes variant","summary":"Adults with type 2 diabetes had about 12% less three-hour post-meal glucose exposure with ten minutes of walking after each main meal than with one untimed daily walk. This comparison supplies no insulin estimate."},{"source_id":"36715875","role":"Timing review","summary":"Acute studies generally favored exercising after eating for glucose. Exercise types and schedules varied. This review cannot establish the three-hour break schedule or the type 2 diabetes trial’s specific comparison."}]},{"card_id":"brisk-walking","title":"Make brisk walking a weekly habit","action":"Build toward a brisk 30-minute walk on five days a week. This is one practical schedule within the range studied.","tracking_prompt":"Compare weekly averages if you already take home blood pressure readings.","goals":["heart","movement"],"benefit_ids":["brisk-walking-1","brisk-walking-2","brisk-walking-3"],"eligibility_rule":"read_studied_population","studied_population":"Sedentary or lightly active adults, including adults with hypertension.","qualification":"The 30-minute schedule is a practical example. Start at a level you can manage. Seek advice if you have unstable cardiac symptoms or restrictions on brisk exercise.","time_commitment":"Practical example: 30 minutes on five days weekly, about 150 minutes per week.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["33630309","42405260","17275896"],"research_summary":"The systolic-pressure estimate comes from 73 walking trials. Broader exercise comparisons did not refine the card’s walking prescription.","source_notes":[{"source_id":"33630309","role":"Pooled research","summary":"Walking programs lowered average systolic pressure in adults. The review judged the diastolic result less certain and used a range of schedules."},{"source_id":"42405260","role":"Direct pooled result","summary":"Across 17 trials in adults with hypertension, both pressure measures fell. The full paper reports a pooled diastolic difference of −4.67 mmHg (95% CI −6.26 to −3.08). Its suggested optimal dose was modeled across trials."},{"source_id":"17275896","role":"Pooled research","summary":"Controlled trials in previously sedentary adults measured gains in aerobic fitness after regular walking. This supports the fitness benefit separately from blood pressure."}]},{"card_id":"stairs","title":"Choose a stair-climbing routine","action":"Choose one of the two studied schedules shown below. The evidence for the single-session schedule comes from one small trial in young men.","tracking_prompt":"Log sessions and effort. Daily resting heart rate is a separate observation.","goals":["movement"],"benefit_ids":["stairs-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Inactive young adults. The single-session schedule was studied in young men with obesity.","qualification":"Vigorous exercise studied in inactive young adults. The single-session trial enrolled young men with obesity. Use a safe staircase, stop for dizziness or chest pain, and avoid if vigorous climbing is unsuitable.","time_commitment":"Three short climbs across the day, or one approximately ten-minute session. Choose a schedule below.","display_evidence_in_details":true,"blocked_if":["vigorous_exercise_restriction"],"research_source_ids":["30649897","38569204","40087042"],"research_summary":"Two small trials support stair snacks. One trial supports the single-session option. Campus feasibility and blood-flow-restriction studies answer different questions.","source_notes":[{"source_id":"30649897","role":"Tested schedule","summary":"Inactive young adults climbed 60 stairs three times daily, separated by one to four hours. Fitness improved after six weeks."},{"source_id":"38569204","role":"Tested schedule","summary":"The short stair-bout group improved peak oxygen uptake after six weeks. The paper also measured fat oxidation, which did not improve."},{"source_id":"40087042","role":"Direct, single-session option","summary":"Young men with obesity completed a four-week vigorous stair program. Peak oxygen uptake improved relative to the pattern in controls. The study found no change in body composition or metabolic variables."}]},{"card_id":"almonds","title":"Make almonds a daily snack","action":"If almonds fit your diet, try a handful daily for at least four weeks. Trials used a range of portions.","tracking_prompt":"Log servings. A lipid panel measures cholesterol.","goals":["heart"],"benefit_ids":["almonds-1","almonds-2","almonds-3"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults","qualification":"Do not use with a tree nut allergy. Nuts add calories; swap rather than add.","time_commitment":"One serving daily for at least four weeks.","display_evidence_in_details":true,"blocked_if":["tree_nut_allergy"],"research_source_ids":["40944180","12221048","19394473"],"research_summary":"The newer review covers 36 publications. An earlier, smaller review was less conclusive for LDL. Its trials should not be added to the newer count.","source_notes":[{"source_id":"40944180","role":"Direct pooled result","summary":"In 36 publications, daily almonds lowered LDL by about 5 mg/dL, total cholesterol by about 6 mg/dL, and ApoB by about 4.5 mg/dL relative to controls across varying amounts."},{"source_id":"12221048","role":"Direct LDL trial","summary":"Whole almonds used as snacks lowered LDL in adults with elevated cholesterol in a crossover comparison with control snacks. The tested amounts differed, so this trial does not fix a universal serving."},{"source_id":"19394473","role":"Earlier, less precise review","summary":"An earlier synthesis found lower total cholesterol and a borderline LDL estimate whose interval reached zero. The later, larger synthesis provides the card’s modest LDL estimate. Their evidence bases can overlap."}]},{"card_id":"sunscreen","title":"Use sunscreen daily","action":"Use broad-spectrum sunscreen according to its label, including reapplication directions.","tracking_prompt":"Log use. Short-term photos cannot measure the trial outcome.","goals":[],"benefit_ids":["sunscreen-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults under 55 in a sunny Australian town (n=903)","qualification":"One trial followed Australian adults for 4.5 years. A separate one-year study in Brazilian women tested a particular SPF 60 product twice daily.","time_commitment":"A minute or two a day. Tested for 4.5 years.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["23732711","37247191"],"research_summary":"One 4.5-year trial supports the long-term result. A one-year randomized study supports several facial signs. Shorter studies do not replicate the multi-year result.","source_notes":[{"source_id":"23732711","role":"Direct multi-year result","summary":"Australian adults assigned daily sunscreen showed less progression of skin aging at 4.5 years than those using it at their discretion. Assessors graded changes without knowing treatment assignment."},{"source_id":"37247191","role":"Related one-year study","summary":"Among 290 Brazilian women, twice-daily SPF 60 slowed progression of some facial aging signs versus usual care over one year. Cite only for that timeframe and regimen."}]},{"card_id":"caffeine","title":"Move caffeine earlier","action":"Log your last caffeinated drink, its size and your bedtime. Try moving that drink earlier. The timing depends on dose and individual response.","tracking_prompt":"Compare your sleep diary across similar nights.","goals":["sleep"],"benefit_ids":["caffeine-1","caffeine-2"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults, low-moderate habitual caffeine intake (dose-timing trial: 23 men)","qualification":"Dose, timing and individual clearance matter. Modeled cutoff times are estimates. The dose-timing trial enrolled 23 men and did not test 400 mg earlier than 12 hours before bed.","time_commitment":"No added activity time. Timing varies by caffeine dose and bedtime.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36870101","39377163","24235903"],"research_summary":"Two dose-timing trials and a review support sleep disruption after substantial caffeine. The 12-hour result comes from one small trial.","source_notes":[{"source_id":"36870101","role":"Pooled research","summary":"The review found less sleep after caffeine. Its beverage-specific cutoff estimates are modeled and cannot establish a safe cutoff for a 400 mg dose."},{"source_id":"39377163","role":"Direct dose–timing trial","summary":"Twenty-three men completed placebo and 100 mg or 400 mg conditions at 4, 8 or 12 hours before bed. The higher dose affected sleep initiation and architecture within 12 hours. No statistically clear disruption was detected with 100 mg."},{"source_id":"24235903","role":"Earlier controlled timing study","summary":"The study tested 400 mg at bedtime or three or six hours beforehand. Sleep was disrupted versus placebo even six hours before bed. The separate 12-hour finding comes from the later trial."}]},{"card_id":"resistance-sarcopenia","title":"Practice resistance exercises for sarcopenia","action":"For older adults with sarcopenia, one studied option was resistance exercise twice weekly for 12 weeks. If frail, choose exercises with a clinician.","tracking_prompt":"Track sessions and the same functional measure over time.","goals":["movement"],"benefit_ids":["resistance-sarcopenia-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Older adults with sarcopenia in controlled exercise trials.","qualification":"Ask a clinician first if frail.","time_commitment":"Twice weekly for 12 weeks in one trial.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42947012","41212331"],"research_summary":"A resistance-specific review pooled 24 trials. Strength and walking speed improved on average, although several changes were smaller than thresholds for a clinically important difference.","source_notes":[{"source_id":"42947012","role":"Direct, varied exercise programs","summary":"Twelve trials involving 652 adults with sarcopenia found gains in strength and walking speed with exercise. The study table includes resistance exercise twice weekly for 12 weeks and combined resistance and aerobic exercise three times weekly for 12 weeks."},{"source_id":"41212331","role":"Resistance-specific evidence","summary":"Across 24 trials in 951 older adults with sarcopenia, resistance exercise improved several strength and function measures. Average grip-strength and gait-speed improvements fell below the review’s thresholds for clinically important change."}]},{"card_id":"bath","title":"Take a warm bath or shower before bed","action":"Try a comfortably warm bath or shower for about 10 minutes, finishing one to two hours before bed.","tracking_prompt":"Record lights-out time and estimated minutes to fall asleep.","goals":["sleep"],"benefit_ids":["bath-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults studied in bedtime bathing or showering trials. Reviews differed in the populations they included.","qualification":"Use comfortable water and avoid overheating. Take care if prone to dizziness or falls. Reviews disagree about sleep onset.","time_commitment":"At least 10 min/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["31102877","42545422"],"research_summary":"Two reviews reached different conclusions about falling asleep sooner. The second search did not resolve that disagreement.","source_notes":[{"source_id":"31102877","role":"Pooled research","summary":"This review found shorter sleep-onset time after appropriately timed warm bathing or showering. Included studies varied in their designs."},{"source_id":"42545422","role":"Conflicting result","summary":"A newer synthesis of immersion trials found no significant improvement in sleep latency. It is included because it qualifies the earlier positive result."}]},{"card_id":"relax-muscles","title":"Practice progressive muscle relaxation for sleep","action":"Gently tense and release muscle groups in sequence. One trial in people with lung cancer used 30-minute sessions twice weekly for eight weeks.","tracking_prompt":"Rate sleep quality each morning.","goals":["sleep"],"benefit_ids":["relax-muscles-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults in relaxation studies, many with medical conditions.","qualification":"Low burden.","time_commitment":"30 minutes twice weekly for eight weeks in this example.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42625730","38494385","41633054","34569129"],"research_summary":"Reviews support better self-rated sleep, chiefly in clinical populations. An arthritis trial illustrates six weeks of practice in a different condition.","source_notes":[{"source_id":"42625730","role":"Direct, clinical populations","summary":"Across 14 trials, self-rated sleep improved on average with relaxation. Trial effects varied widely. Table 1 includes a 30-minute twice-weekly program for eight weeks in people with lung cancer and a 40-minute three-times-weekly program for six weeks in women with breast cancer."},{"source_id":"38494385","role":"Direct, clinical population","summary":"Chemotherapy patients with poor sleep who practiced progressive muscle relaxation scored better on self-rated sleep than a usual-care group. The population limits extrapolation."},{"source_id":"41633054","role":"Pooled research","summary":"Another synthesis found better sleep quality after progressive muscle relaxation. Trial effects varied substantially, and the two reviews may include the same participants."},{"source_id":"34569129","role":"Primary trial in a clinical population","summary":"People with rheumatoid arthritis assigned to six weeks of progressive muscle relaxation reported better sleep quality than controls. This is a primary example within a field already covered by reviews."}]},{"card_id":"cyclic-sighing","title":"Try five minutes of cyclic sighing","action":"For five minutes daily, inhale gently, add a short second inhale, then exhale slowly. Stop if you feel light-headed.","tracking_prompt":"Record mood before and after the session.","goals":["mood"],"benefit_ids":["cyclic-sighing-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults","qualification":"Breathe comfortably and stop if light-headed. The trial mostly recruited young adults.","time_commitment":"5 min/day, 28 days","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36630953"],"research_summary":"One month-long trial directly supports the five-minute routine and positive-mood result. Other sighing studies tested pain, anxiety or different practice schedules.","source_notes":[{"source_id":"36630953","role":"Direct, short-term mood","summary":"In a month-long remote randomized study, brief breathwork, especially exhale-focused cyclic sighing, improved positive mood more than the meditation comparison. The schedule was five minutes daily."}]},{"card_id":"cold-shower","title":"Finish a shower with cold water","action":"Participants ended their usual shower with 30 seconds of cold water daily for 30 days.","tracking_prompt":"Track sickness absence and days feeling ill separately.","goals":[],"benefit_ids":["cold-shower-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults 18-65 without severe comorbidity, no cold-shower habit (n=3,018)","qualification":"The trial involved adults without severe comorbidity. Ask a clinician before cold exposure if you have cardiovascular disease, uncontrolled blood pressure, arrhythmia or a condition aggravated by cold.","time_commitment":"30 seconds at the end of the shower, daily for 30 days.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["27631616","39879231"],"research_summary":"One large trial directly measured sick leave. A later review repeats that trial’s result. Participants reported a similar number of days feeling ill.","source_notes":[{"source_id":"27631616","role":"Direct, pooled durations","summary":"Sick-leave days were 29% lower across groups assigned 30–90 seconds of cold water at the end of showers. Self-reported illness days were comparable. The 29% was not estimated specifically for 30 seconds."},{"source_id":"39879231","role":"Review reusing the sick-leave trial","summary":"The review’s 29% lower sickness absence figure comes from the original shower trial. It provides no second independent test of that result. Other cold-immersion protocols answer different questions."}]},{"card_id":"meal-order","title":"Eat vegetables and protein before starch","action":"At a meal containing vegetables, protein and starch, eat the vegetables and protein first and the starch last.","tracking_prompt":"If you already monitor glucose, compare similar meals at the same time point.","goals":["metabolic"],"benefit_ids":["meal-order-1"],"eligibility_rule":"read_studied_population","studied_population":"People with type 2 or gestational diabetes; small healthy-adult crossover trials (PATTERN; Japanese set meals)","qualification":"Most participants had diabetes. Keep prescribed medications and diet instructions in mind when changing meal patterns.","time_commitment":"At meals. No extra activity time.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35210284","42045803","41837403"],"research_summary":"Small feeding studies support a smaller early glucose rise with carbohydrates last. A separate review in healthy adults also found acute effects. Two-hour and longer-term results remain uncertain.","source_notes":[{"source_id":"35210284","role":"Limits at two hours","summary":"In eight trials in people with type 2 diabetes there was little clear difference in two-hour plasma glucose or HbA1c. Retain as a limit on interpreting the earlier post-meal changes."},{"source_id":"42045803","role":"Pooled research","summary":"Studies in diabetes suggest smaller post-meal glucose excursions when carbohydrates come last. Heterogeneity and low certainty limit the inference."},{"source_id":"41837403","role":"Healthy-adult evidence","summary":"A review in healthy adults found that most studies reported a smaller acute glucose excursion when vegetables, fruit or protein preceded carbohydrates. The short feeding studies used several meal sequences."}]},{"card_id":"bedtime-list","title":"Write down tomorrow’s tasks","action":"Spend five minutes before bed writing specific tasks for the next few days.","tracking_prompt":"Log how long falling asleep seemed to take.","goals":["sleep"],"benefit_ids":["bedtime-list-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Healthy adults aged 18-30, sleep lab","qualification":"The comparison came from one laboratory night in young adults. Effects at home over several weeks remain uncertain.","time_commitment":"Five minutes before bed.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["29058942"],"research_summary":"One trial in 57 young adults tested five minutes of writing future tasks against writing completed tasks for one laboratory night. The search found no independent repeat of that comparison.","source_notes":[{"source_id":"29058942","role":"Direct, one-night comparison","summary":"Among 57 young adults, writing upcoming tasks for five minutes before bed led to faster objectively measured sleep onset than writing completed tasks. The trial had no group who did neither."}]},{"card_id":"kiwi","title":"Try two green kiwifruit a day","action":"If you have constipation, try two green kiwifruit a day for four weeks.","tracking_prompt":"Count complete bowel movements each week and log discomfort separately.","goals":["digestion"],"benefit_ids":["kiwi-1","kiwi-2"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with constipation","qualification":"Avoid with a kiwifruit allergy. Persistent or new bowel symptoms warrant evaluation.","time_commitment":"Two fruit daily for four weeks.","display_evidence_in_details":true,"blocked_if":["kiwifruit_allergy"],"research_source_ids":["36537785","34074830","21147704"],"research_summary":"Two trials support more complete bowel movements from baseline. An earlier four-week study also found more frequent bowel movements in people with IBS and constipation, using a broader measure.","source_notes":[{"source_id":"36537785","role":"Direct, change from baseline","summary":"Adults with functional constipation or IBS with constipation reported about 1.5–1.7 more complete spontaneous bowel movements per week than at baseline on two green kiwifruit daily. Overall gastrointestinal comfort also improved."},{"source_id":"34074830","role":"Direct for bowel frequency","summary":"In the US comparison all three groups improved in bowel frequency from baseline and responder rates were similar. In the kiwi group bloating and straining also improved. Those symptom outcomes are narrower than overall digestive comfort."},{"source_id":"21147704","role":"Related bowel-frequency outcome","summary":"In adults with constipation-predominant IBS, bowel movement frequency increased after four weeks of kiwifruit. This study measured defecation frequency, a broader outcome than complete spontaneous bowel movements."}]},{"card_id":"beans","title":"Add canned beans to meals","action":"Try one cup of canned beans daily for four weeks if this fits your diet.","tracking_prompt":"Track servings. A lipid panel measures the outcome.","goals":["heart"],"benefit_ids":["beans-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with LDL 3.0-5.0 mmol/L (n=73, mean age 48)","qualification":"Gas or bloating.","time_commitment":"One serving daily for four weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["34642756","17634169","1964898"],"research_summary":"One trial directly supports one cup daily for four weeks versus rice. An independent eight-week pinto-bean study also favored beans for LDL. The studies used different portions and comparisons.","source_notes":[{"source_id":"34642756","role":"Direct comparison","summary":"One cup of beans daily for four weeks produced a lower LDL than white rice. Half a cup did not clearly differ from rice. The trial also found no clear difference between the two portions."},{"source_id":"17634169","role":"Independent trial with a different portion","summary":"Sixteen adults with mild insulin resistance tried half a cup of pinto beans, black-eyed peas or carrots for eight weeks per condition. LDL fell more with pinto beans than carrots. The one-cup canned-bean card uses a different trial and comparator."},{"source_id":"1964898","role":"Different bean preparation and outcome","summary":"In 20 men with mildly high cholesterol, canned baked beans versus canned spaghetti did not clearly lower plasma total cholesterol. The abstract does not give an LDL result. This limits generalization to other canned products."}]},{"card_id":"salt-swap","title":"Use a potassium-enriched salt substitute","action":"After confirming that extra potassium is appropriate for you, replace your usual table or cooking salt with a potassium-enriched substitute.","tracking_prompt":"Log the swap and track home blood pressure if already measured.","goals":["heart"],"benefit_ids":["salt-swap-1","salt-swap-2"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults in 21 trials (about 32,000 people), including people with hypertension","qualification":"Extra potassium can be dangerous with kidney disease or potassium-raising medicines, including ACE inhibitors, ARBs and potassium-sparing diuretics. Check with a clinician or pharmacist before changing salts in these situations.","time_commitment":"Use in place of regular salt during usual food preparation.","display_evidence_in_details":true,"blocked_if":["kidney_disease","potassium_raising_medication","potassium_restriction"],"research_source_ids":["35945000","34459569","41578335"],"research_summary":"Blood pressure has support across multiple trials. A newer review found that evidence for cardiovascular events still relies heavily on the large Chinese trial.","source_notes":[{"source_id":"35945000","role":"Pooled research","summary":"Trials of potassium-enriched salt substitutes found lower systolic and diastolic pressure relative to regular salt."},{"source_id":"34459569","role":"Direct, high-risk population","summary":"With potassium-enriched salt there were about 29 versus 34 strokes per 1,000 person-years in rural Chinese participants with a prior stroke or who were at least 60 with hypertension. Follow-up averaged 4.74 years."},{"source_id":"41578335","role":"Broader review with overlapping trials","summary":"Across 34 trials, some potassium-enriched formulations probably lowered systolic pressure. Cardiovascular event evidence was dominated by one large Chinese trial. Do not count the stroke trial twice."}]},{"card_id":"whole-grains","title":"Choose whole-grain staples","action":"Swap some refined bread, rice or pasta for whole-grain versions. Studies used different grains and amounts.","tracking_prompt":"Track the foods you swap. A lipid panel measures the outcome.","goals":["heart"],"benefit_ids":["whole-grains-1","whole-grains-2"],"eligibility_rule":"read_studied_population","studied_population":"Adults","qualification":"Different grains and amounts were tested. Increase fiber gradually if it causes stomach discomfort.","time_commitment":"Daily food swap.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42743912","26269373"],"research_summary":"Two reviews found modest LDL and total cholesterol reductions. Their study periods overlap. The per-48-gram estimate comes from the newer review.","source_notes":[{"source_id":"42743912","role":"Pooled research","summary":"The review separately reports a small decrease in total cholesterol and LDL per 48 g/day of whole grains. Certainty differs between those outcomes."},{"source_id":"26269373","role":"Earlier pooled comparison","summary":"Whole-grain diets modestly lowered LDL and total cholesterol compared with non-whole-grain controls. The trial pool overlaps the period covered by the newer review."}]},{"card_id":"walk-for-ideas","title":"Walk while brainstorming","action":"Walk for a few minutes while generating ideas or brainstorm immediately afterward.","tracking_prompt":"Count distinct ideas on comparable prompts.","goals":["memory"],"benefit_ids":["walk-for-ideas-1"],"eligibility_rule":"read_studied_population","studied_population":"Mostly university and college students (1,036 participants)","qualification":"Most participants were students completing short lab tasks. The finding applies to generating ideas.","time_commitment":"A few minutes up to 20 minutes when you need ideas.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42127076","24749966"],"research_summary":"A review and primary experiments support generating more ideas during or shortly after walking. They do not establish better real-world problem solving.","source_notes":[{"source_id":"42127076","role":"Pooled research","summary":"Walking improved scores on idea-generation tasks, mostly in student samples. Results for convergent problem solving were uncertain."},{"source_id":"24749966","role":"Primary experimental example","summary":"Four experiments compared walking and sitting on idea-generation tasks. Walking improved creative ideation during or shortly after activity. The result depended on the task."}]},{"card_id":"water-flosser","title":"Clean between your teeth daily","action":"Use a powered interdental cleaner each day in addition to brushing, following the device instructions.","tracking_prompt":"Track bleeding over several weeks.","goals":[],"benefit_ids":["water-flosser-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with gingivitis (16 RCTs, 1,258 people), at least 28 days","qualification":"Minor gum trauma possible with mechanical devices.","time_commitment":"Once daily in addition to brushing, for at least four weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36562267","21387981"],"research_summary":"A review supports less bleeding when powered cleaning is added to brushing. An oral-irrigator trial compared different devices against floss.","source_notes":[{"source_id":"36562267","role":"Direct, adjunct to brushing","summary":"Trials in adults with gingivitis found less bleeding between teeth with powered interdental cleaning plus brushing than with brushing alone. Floss gave a comparable result."},{"source_id":"21387981","role":"Different active comparator","summary":"After four weeks, two oral-irrigator groups had less gingival bleeding than a floss group with manual brushing. This does not duplicate the brushing-alone comparison."}]},{"card_id":"social-break","title":"Take a week off social media","action":"Choose a seven-day break from the platforms studied or their equivalents. Arrange another way to stay in touch.","tracking_prompt":"Record wellbeing at the start and end of the week.","goals":["mood"],"benefit_ids":["social-break-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults, mean age 29.6 (154 people), not a clinical group","qualification":"The positive finding came from one short trial. A larger review found no clear average change in positive affect, negative affect or life satisfaction.","time_commitment":"Seven consecutive days.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35512731","40038410"],"research_summary":"One week-long trial found improved wellbeing. A review pooling abstinence studies found no consistent change in related wellbeing measures.","source_notes":[{"source_id":"35512731","role":"Controlled trial","summary":"One week away from selected social media platforms improved a wellbeing score compared with usual use. Follow-up was short."},{"source_id":"40038410","role":"Mixed broader findings","summary":"A systematic review of social-media breaks found no clear pooled benefit for positive affect, negative affect or life satisfaction. These related endpoints differ from the wellbeing scale of the one-week trial."}]},{"card_id":"toothbrush","title":"Use a powered toothbrush","action":"Use a powered toothbrush for your usual brushing and follow the device instructions.","tracking_prompt":"Log use. How clean your teeth feel is a personal observation.","goals":[],"benefit_ids":["toothbrush-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults (28 publications, single-brushing studies)","qualification":"The outcome is plaque removal immediately after brushing. Longer-term effects have a different evidence base.","time_commitment":"Usual brushing, about 2 times/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["34877772","16170978","31050195"],"research_summary":"Reviews of single-brushing experiments agree on a small plaque-removal benefit. The reviews can include the same participants.","source_notes":[{"source_id":"34877772","role":"Pooled research","summary":"Pooled single-brushing studies found slightly greater plaque removal with a powered toothbrush. This specific finding concerns immediate plaque removal."},{"source_id":"16170978","role":"Controlled trial","summary":"In a single-use crossover comparison, one battery-powered brush removed more plaque than a manual brush. The finding concerns the tested models."},{"source_id":"31050195","role":"Overlapping review","summary":"An earlier review of single-brushing comparisons favored powered brushes over manual brushes for plaque removal. Trials can overlap with the later review."}]},{"card_id":"screen-cap","title":"Set a daily phone screen-time cap","action":"Try a two-hour daily phone screen-time cap for three weeks if it fits your work and communication needs.","tracking_prompt":"Use your screen-time report and rate mood and sleep separately.","goals":["mood","sleep"],"benefit_ids":["screen-cap-1","screen-cap-2","screen-cap-3"],"eligibility_rule":"confirm_eligibility","studied_population":"Healthy university students, mean age 22.7 (n=111)","qualification":"Evidence comes from one unblinded trial in healthy university students. Keep access to essential communication.","time_commitment":"Cap of 2 h/day, 3 weeks","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["39985031","35389685"],"research_summary":"One student trial tested the two-hour cap and measured all three groups of outcomes. A separate intervention reducing smartphone use by one hour provides context for mood and wellbeing.","source_notes":[{"source_id":"39985031","role":"Direct, single sample","summary":"After three weeks, 111 students assigned to a daily two-hour phone cap or control differed on depressive symptoms, perceived stress, wellbeing and insomnia severity. The insomnia score differed by 2.59 points at the end. Several outcomes came from these same students."},{"source_id":"35389685","role":"Different reduction target","summary":"An experiment reducing daily smartphone use by one hour found improvements in depressive symptoms and wellbeing. It used a relative reduction rather than a two-hour daily cap and does not validate the card’s insomnia score."}]},{"card_id":"standing-stockings","title":"Use fitted stockings during standing shifts","action":"Use appropriately fitted graduated compression stockings during standing shifts if they are suitable for you.","tracking_prompt":"Record end-of-shift swelling or heaviness.","goals":[],"benefit_ids":["standing-stockings-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Healthcare workers on six-hour standing shifts and hairdressers exposed to prolonged standing.","qualification":"The finding concerns leg swelling during standing shifts. Check fit and seek advice about arterial circulation problems or skin disease.","time_commitment":"Standing work days, up to 12 months","display_evidence_in_details":true,"blocked_if":["compression_contraindicated"],"research_source_ids":["37458579","22451457"],"research_summary":"Two independent studies found less lower-leg swelling with stockings during standing work, one in healthcare workers and one in hairdressers.","source_notes":[{"source_id":"37458579","role":"Direct, occupational swelling","summary":"Graduated stockings countered increases in lower-leg volume in healthcare workers on standing shifts. Seventy-two participants completed data collection. The flight-clot outcome was outside this study."},{"source_id":"22451457","role":"Independent occupational crossover trial","summary":"In 108 hairdressers randomized to low-strength stockings and no-compression periods, lower-leg volume averaged 19 mL less with stockings. Symptoms also improved. This supports the swelling result in a second standing occupation."}]},{"card_id":"optimism","title":"Imagine your best possible future","action":"Spend five minutes a day for two weeks imagining your best possible future in relationships, personal life and work.","tracking_prompt":"Rate optimism before and after the two weeks.","goals":["mood"],"benefit_ids":["optimism-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults in studies of future-self imagery.","qualification":"The studied outcome was optimism on a questionnaire.","time_commitment":"5 min/day, 14 days","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["21450262","31545815","36724699"],"research_summary":"One trial supports the two-week imagery schedule. Another study found immediate optimism changes across writing and imagery formats.","source_notes":[{"source_id":"21450262","role":"Direct, tested schedule","summary":"Five minutes daily of imagining one’s best possible self increased self-rated optimism relative to imagining ordinary daily activities, both after one session and over two weeks."},{"source_id":"31545815","role":"Direct pooled result","summary":"Across different versions of the best-possible-self exercise, participants showed higher optimism on average than comparison groups. The pooled estimate spans different practice formats."},{"source_id":"36724699","role":"Different practice duration","summary":"An online study compared versions of best-possible-self practice. Writing and imagery produced similar immediate improvements in optimism. It did not test how long the effect lasts."}]},{"card_id":"bedtime-phone","title":"Put your phone away before bed","action":"Put your phone away for the last 30 minutes before bed for four weeks. The small trial included nightly enforcement.","tracking_prompt":"Record phone-free minutes and estimated time to fall asleep.","goals":["sleep"],"benefit_ids":["bedtime-phone-1","bedtime-phone-2","bedtime-phone-3"],"eligibility_rule":"confirm_eligibility","studied_population":"Young adults with poor sleep who regularly used their phone at bedtime.","qualification":"Research involved young adults with poor sleep and a habitual bedtime phone routine. Outcomes were self-reported.","time_commitment":"30 phone-free min/night","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32040492","29073407","41668954"],"research_summary":"One small trial directly supports the 30-minute restriction in young adults with poor sleep. Different evening media rules in athletes produced mixed sleep findings.","source_notes":[{"source_id":"32040492","role":"Direct, self-reported outcomes","summary":"In 38 young adults a reinforced bedtime phone restriction improved reported sleep onset, sleep quality and bedtime arousal. The groups’ average changes in onset differed by about ten minutes. The paper’s p = 0.049 is the end-of-study group comparison."},{"source_id":"29073407","role":"Null result in a different population","summary":"A four-week restriction on electronic media after 10 pm did not improve sleep habits in high-school athletes who already slept well. The rule, population and baseline sleep differed from the card trial."},{"source_id":"41668954","role":"Different exposure and comparison","summary":"Sixteen male elite soccer players compared two hours of pre-bed smartphone exposure with magazine reading. Sleep quality worsened during phone exposure. This does not establish the effects of a 30-minute cutoff on onset or bedtime arousal."}]},{"card_id":"blink","title":"Practice complete blinks","action":"Gently close, squeeze and open your eyes 15 times, three times daily for two weeks.","tracking_prompt":"Rate symptoms at the same time each day.","goals":[],"benefit_ids":["blink-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with dry eye (98 and 28 people)","qualification":"Evidence comes from short studies in people with dry eye. Seek eye care for persistent symptoms, pain or vision changes.","time_commitment":"3 x 15 repeats/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["40467388","32409236"],"research_summary":"Two short studies support symptom relief in dry eye. Blink-reminder software changes a different behavior from the card’s close–squeeze–open exercises.","source_notes":[{"source_id":"40467388","role":"Direct, selected schedule","summary":"Short studies in adults with dry eye found fewer symptoms and incomplete blinks with the selected 15 close–squeeze–open repeats three times a day. Several objective tear-film measures showed no significant change."},{"source_id":"32409236","role":"Related schedule","summary":"In a four-week before-and-after program, dry-eye symptoms improved. It used a different blink schedule and lacked a randomized no-exercise control."}]},{"card_id":"apples","title":"Try two whole apples daily","action":"Try two whole apples a day for eight weeks if this fits your diet.","tracking_prompt":"Track servings. Cholesterol requires a lipid panel.","goals":["heart"],"benefit_ids":["apples-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Mildly hypercholesterolemic adults, mean age 51 (n=40)","qualification":"One small trial in adults with mildly high cholesterol compared whole apples with an apple drink. A broader review combining apples and apple products found no clear overall LDL reduction.","time_commitment":"Daily, 8 weeks","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["31840162","23271615","35449537"],"research_summary":"One small trial supports the two-apple routine versus a matched drink. A second trial favored whole apples over clear juice. A broader review pooling apple products found an inconclusive overall LDL difference.","source_notes":[{"source_id":"31840162","role":"Direct, matched drink","summary":"Two whole apples daily resulted in modestly lower LDL than a matched apple drink after eight weeks in a small crossover trial of adults with mildly elevated cholesterol."},{"source_id":"23271615","role":"Related whole-fruit comparison","summary":"In 23 healthy volunteers, clear apple juice produced higher LDL than whole apples in a four-week crossover study. The whole-apple portion was 550 g daily. This differs from the card’s population and matched drink."},{"source_id":"35449537","role":"Mixed pooled evidence","summary":"Across trials of apples and apple-derived products, pooled LDL was 2.8 mg/dL lower, with a 95% interval from 5.78 lower to 0.17 higher. The overall result was inconclusive and the review mixed product forms."}]},{"card_id":"work-breaks","title":"Add four breaks to a desk shift","action":"Add four five-minute breaks spread across the shift. Participants also had their usual two longer breaks.","tracking_prompt":"Rate discomfort at the end of comparable shifts.","goals":[],"benefit_ids":["work-breaks-1"],"eligibility_rule":"read_studied_population","studied_population":"Data-entry workers (n=51)","qualification":"Two field studies tested supplementary breaks in data-entry work. They measured discomfort and eyestrain during the work period.","time_commitment":"20 extra min/workday","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["17514726","10877480"],"research_summary":"Two data-entry field studies support the four extra five-minute breaks. The search did not identify a stronger test of that schedule and eyestrain outcome.","source_notes":[{"source_id":"17514726","role":"Controlled trial","summary":"Data-entry workers reported less discomfort and eyestrain when four five-minute breaks were added to their usual breaks."},{"source_id":"10877480","role":"Direct occupational result","summary":"Data-entry operators reported smaller increases in discomfort and eyestrain during periods with four additional five-minute breaks. Data-entry performance was maintained."}]},{"card_id":"hummus","title":"Try an afternoon hummus snack","action":"The tested snack was hummus with pretzels, about 240 kcal, roughly three hours after lunch.","tracking_prompt":"Record hunger and evening snacks.","goals":["metabolic"],"benefit_ids":["hummus-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults, mean age 26 (n=39)","qualification":"One small, short trial in healthy young adults. The snack contains ingredients that may be unsuitable for people with food allergies.","time_commitment":"One snack about three hours after lunch.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32488233"],"research_summary":"One small trial tested the afternoon hummus-and-pretzels snack and later dessert snacking. A conference abstract describes a similar study by the same research group and was not counted as replication.","source_notes":[{"source_id":"32488233","role":"Direct, specified snack","summary":"Compared with no snack, hummus with pretzels reduced afternoon hunger in 39 healthy adults. Later dessert snacking was about 20% lower than after either no snack or granola bars. The measurement followed six days on each pattern."}]},{"card_id":"volunteer","title":"Try a structured volunteering session","action":"Join a structured session helping nursing-home residents if this is available and suits you.","tracking_prompt":"Rate loneliness before the session and at follow-up.","goals":["mood"],"benefit_ids":["volunteer-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults aged 59 to 79 (n=76)","qualification":"The intervention was a structured activity with older adults. Benefit was self-reported.","time_commitment":"Single session","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["42054579","39855242"],"research_summary":"One trial tested a single nursing-home session. A separate, sustained volunteering program also reduced loneliness in older volunteers. The one-session effect is still based on one trial.","source_notes":[{"source_id":"42054579","role":"Direct, structured session","summary":"In a trial of 76 older adults, participants who helped nursing-home residents reported less loneliness within a day. The effect persisted at one month. The participants volunteered within a structured program."},{"source_id":"39855242","role":"Independent longer volunteering program","summary":"Older volunteers in a structured telephone program reported less loneliness than controls after a sustained intervention. Most effects were not sustained at later follow-up. This does not test one nursing-home visit."}]},{"card_id":"jumps","title":"Practice short sets of vertical jumps","action":"One tested example in young women was 10 maximal countermovement jumps, three nonconsecutive days a week for six months. Use only if high-impact activity is appropriate.","tracking_prompt":"Log sessions. Bone density is measured by DXA.","goals":["movement"],"benefit_ids":["jumps-1"],"eligibility_rule":"clinician_clearance","studied_population":"Healthy adults over 18 (review); example trial: healthy non-smoking young women aged 20-23","qualification":"High-impact exercise. Seek clinical advice if pregnant or if you have osteoporosis, a fracture history, joint or back problems, or restrictions on impact exercise. The specific schedule was studied in healthy young women.","time_commitment":"Under two minutes per session in the example trial, including rests. This was an estimate.","display_evidence_in_details":true,"blocked_if":["impact_exercise_restriction"],"research_source_ids":["38305252","16269526"],"research_summary":"A pooled analysis supports femoral-neck density. The ten-jump, three-days-a-week example comes from one trial. Other hip studies used different sites or schedules.","source_notes":[{"source_id":"38305252","role":"Pooled research","summary":"Across jump programs, the clearest density improvement was at the femoral neck. The programs varied; the review does not establish fracture prevention."},{"source_id":"16269526","role":"Direct, one specific regimen","summary":"In young women, femoral-neck density rose from baseline after six months of ten maximal jumps three times weekly. The pooled estimate on the card comes from the review of multiple programs."}]},{"card_id":"psyllium","title":"Use psyllium regularly","action":"Use the label for dosing and mixing. LDL trials used a median of about 10 g of psyllium daily. Take each dose with at least a full glass of water, and check medicine spacing with a pharmacist.","tracking_prompt":"Log bowel frequency if relevant. LDL requires a lipid panel.","goals":["heart","digestion"],"benefit_ids":["psyllium-1","psyllium-2"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults in lipid trials and adults with constipation. Benefits differ by population.","qualification":"Do not swallow dry powder. Avoid with swallowing difficulty or suspected bowel obstruction. Check label directions, fluid restrictions and medicine spacing with a pharmacist.","time_commitment":"Daily according to product directions. Trial doses and duration varied by outcome.","display_evidence_in_details":true,"blocked_if":["swallowing_difficulty","bowel_obstruction","fluid_restriction"],"research_source_ids":["30239559","35816465","8824651","41366295"],"research_summary":"Two lipid reviews support lower LDL, with overlapping trial periods. Separate constipation evidence supports improved bowel frequency with variable effect sizes.","source_notes":[{"source_id":"30239559","role":"Direct LDL result","summary":"Across 28 controlled trials, a median daily psyllium intake of about 10.2 g lowered LDL by 0.33 mmol/L on average. This is the lipid evidence on this two-benefit card."},{"source_id":"35816465","role":"Direct psyllium subgroup","summary":"In the psyllium subgroup, bowel frequency increased by about 3.08 per week, with a wide 95% interval of 0.61 to 5.54 and substantial variation. The overall fiber response rate cannot be attributed to psyllium alone."},{"source_id":"8824651","role":"Controlled trial","summary":"Adults with chronic constipation received psyllium or placebo for eight weeks. Stool frequency and consistency improved during psyllium treatment."},{"source_id":"41366295","role":"Later lipid review","summary":"A later synthesis also found lower LDL and total cholesterol with psyllium. It may reuse trials in the earlier review and offers no additional evidence on constipation."}]},{"card_id":"retrieval","title":"Practice recalling what you learn","action":"After learning new facts, test yourself and check the answers. One trial tested trainees immediately and twice more at intervals of about two weeks.","tracking_prompt":"Track how many answers you recall on a later test.","goals":["memory"],"benefit_ids":["retrieval-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adults/students learning facts","qualification":"Research measured recall of practiced material on a later test.","time_commitment":"Three practice sessions in the example, the first immediately after learning.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["16719566","25150680","19930508","SPACED-2021"],"research_summary":"A review of 29 studies examined spacing retrieval practice. Delayed recall favored spaced over massed retrieval. One trainee trial supplies the three-session example.","source_notes":[{"source_id":"16719566","role":"Spacing evidence","summary":"Spacing learning episodes improved later retention compared with massed practice. Effective intervals depended on how much later learners were tested. This paper does not establish the feedback and self-testing schedule."},{"source_id":"25150680","role":"Retrieval evidence","summary":"Pooling testing-versus-restudy comparisons favored retrieval for later recall. This supports self-testing as an ingredient. The exact two-week spacing and feedback example comes from the trainee trial."},{"source_id":"19930508","role":"Direct combined example","summary":"Forty trainees completed repeated testing with feedback versus repeated study. The first session was immediate and two further sessions were roughly two weeks apart. Six-month scores averaged 39% versus 26% on the studied material."},{"source_id":"SPACED-2021","role":"Review of combined practice","summary":"A review of 29 studies found better later retention when retrieval sessions were spaced rather than massed. This supports the combined learning approach. The specific two-week interval remains a trial example."}]},{"card_id":"flight-stockings","title":"Wear fitted stockings on a long flight","action":"Use properly fitted below-knee graduated compression stockings during a long flight if appropriate for you. Check fit and suitability before travel.","tracking_prompt":"Log use. Symptoms cannot establish this outcome at home.","goals":[],"benefit_ids":["flight-stockings-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Long-haul flyers, especially higher-risk","qualification":"The measured benefit involved silent clots detected by screening. Seek guidance on fit and suitability if you have arterial circulation or skin problems.","time_commitment":"Put on once per flight","display_evidence_in_details":true,"blocked_if":["compression_contraindicated"],"research_source_ids":["33878207","11377600"],"research_summary":"Nine flight trials contributed screened clot outcomes. One primary trial illustrates what screening detected. Symptomatic clot prevention remains unestablished.","source_notes":[{"source_id":"33878207","role":"Pooled research","summary":"Flight trials found fewer symptomless leg clots on screening with compression stockings. They could not estimate protection against symptomatic events."},{"source_id":"11377600","role":"Primary flight trial","summary":"Screening after long-haul flights found symptomless calf clots in the no-stocking group and none in those wearing stockings. This early trial illustrates the review evidence and should not be counted on top of it."}]},{"card_id":"fall-hazards","title":"Arrange a home fall-hazard assessment","action":"Arrange a home assessment with a trained professional and follow through on the recommended changes.","tracking_prompt":"Log completed changes and any falls.","goals":["movement"],"benefit_ids":["fall-hazards-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Older adults living at home who have elevated fall risk.","qualification":"The benefit applies to higher-risk older adults living in the community, especially people who have fallen or need help with daily activities. Arrange a trained assessor and implement their recommendations.","time_commitment":"One assessment followed by the time required to implement changes.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["FALL","34463746","10591231"],"research_summary":"The high-risk subgroup in the Cochrane review provides the card estimate. Broader home-modification reviews include different baseline risks and outcomes.","source_notes":[{"source_id":"FALL","role":"Pooled research","summary":"Home assessment and actual hazard reduction reduced the rate of falls in higher-risk older adults living in the community. The effect differed by baseline risk."},{"source_id":"34463746","role":"Secondary result only","summary":"A home-hazard intervention lowered the rate of falls in a secondary analysis. The primary measure, time to first fall, did not differ clearly. Attach only to the fall-rate interpretation."},{"source_id":"10591231","role":"Controlled trial","summary":"An occupational therapist assessed and helped modify homes. The benefit was concentrated among older adults who had previously fallen."}]},{"card_id":"handwash","title":"Wash hands regularly","action":"Wet your hands, lather with soap and scrub all surfaces for at least 20 seconds. Rinse and dry. Wash at key times, including before eating and after using the bathroom.","tracking_prompt":"Log the occasions you want to remember.","goals":[],"benefit_ids":["handwash-1"],"eligibility_rule":"read_studied_population","studied_population":"Community and household populations studied in hand-hygiene programs.","qualification":"The research studied hygiene programs and usual-care comparisons. It does not isolate the effect of precisely 20 seconds of washing.","time_commitment":"At least 20 seconds of scrubbing, plus rinsing and drying.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["37121242","35445655","CDC-HANDWASH","34408031"],"research_summary":"Community handwashing-promotion studies found fewer respiratory infections in some settings. Another review’s smaller soap-only comparison was inconclusive. CDC supplies the scrub-time instruction.","source_notes":[{"source_id":"37121242","role":"Pooled research","summary":"Handwashing-with-soap promotion programs reduced respiratory infections in low- and middle-income settings. The review evaluates programs rather than one wash duration."},{"source_id":"35445655","role":"Uncertain frequency estimate","summary":"A model of six community studies estimated a 3% reduction in daily infection probability per extra hand-hygiene event. Even its 80% credible interval included no difference. This cannot support a precise risk reduction or a wash duration."},{"source_id":"CDC-HANDWASH","role":"Scrubbing instructions","summary":"CDC explains how to scrub all hand surfaces with soap for at least 20 seconds. This source supplies the technique."},{"source_id":"34408031","role":"Mixed soap-specific findings","summary":"In one review, the three soap-and-water trials showed no clear respiratory infection reduction compared with control. Sanitiser results were clearer. The settings and number of soap trials differ from the larger handwashing-promotion review."}]},{"card_id":"water-premeal","title":"Drink water before meals in a structured weight program","action":"The trial used 500 mL of water before main meals alongside a reduced-calorie diet. Only consider this if that fluid intake fits your care plan.","tracking_prompt":"Track the routine and weekly weight if relevant.","goals":["metabolic"],"benefit_ids":["water-premeal-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with obesity in primary care and adults aged 55–75 with overweight or obesity on a reduced-calorie diet.","qualification":"One trial used a reduced-calorie diet and the other provided weight-management advice. Avoid this fluid schedule if your clinician limits fluid or you have a condition requiring individualized intake.","time_commitment":"Before each main meal. The trial lasted 12 weeks.","display_evidence_in_details":true,"blocked_if":["fluid_restriction"],"research_source_ids":["19661958","26237305"],"research_summary":"Two independent 12-week trials tested 500 mL before meals alongside weight-management support. Both estimates favored water. In the primary-care trial the adjusted result included no difference.","source_notes":[{"source_id":"19661958","role":"Direct, combined program","summary":"Forty-eight adults aged 55–75 on a reduced-calorie diet were assigned to water before meals or diet alone. Weight loss over 12 weeks was about 2 kg greater with 500 mL water before each main meal."},{"source_id":"26237305","role":"Independent primary-care trial","summary":"Among 84 adults with obesity who received weight-management advice, 500 mL of water before main meals was associated with 1.3 kg more weight loss over 12 weeks than the attention control. The adjusted interval included no difference."}]},{"card_id":"drink-swap","title":"Replace a sugary drink with water","action":"Try replacing one sugary drink a day with plain water.","tracking_prompt":"Count how many sugary drinks you replace this week.","goals":["metabolic"],"benefit_ids":["drink-swap-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with overweight or obesity who regularly drink sugary beverages.","qualification":"The swap removes the sugar from that drink. In people with overweight or obesity, trials have not established how much weight, if any, is lost from switching to water.","time_commitment":"No extra time","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["38612997","22301929","35285920"],"research_summary":"Reviews that isolate water substitution find uncertain weight effects. Combined results for diet drinks and water cannot establish the water-only effect.","source_notes":[{"source_id":"38612997","role":"Inconclusive water-specific result","summary":"Replacing sugary drinks with water was associated with an estimated 0.81 kg lower weight in the relevant subgroup. Its 95% interval ran from 1.66 kg lower to 0.03 kg higher and includes no difference."},{"source_id":"22301929","role":"Inconclusive water-specific result","summary":"At six months mean weight loss in the water group did not clearly exceed the attention control. A separate positive analysis combined water and diet drinks. It cannot establish the effect of water alone."},{"source_id":"35285920","role":"Water-specific subgroup","summary":"Three trials in this review evaluated water in place of sugary drinks. Evidence for body weight was rated low certainty. Findings for low-calorie sweetened drinks cannot be attributed to water."}]},{"card_id":"eat-slowly","title":"Slow down at a meal","action":"Try eating a familiar meal more slowly, giving yourself time between bites.","tracking_prompt":"Record meal length and how full you feel.","goals":["metabolic"],"benefit_ids":["eat-slowly-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults who eat quickly and overeat","qualification":"Jaw/TMJ, dental, swallowing difficulty - do not force counts","time_commitment":"During a meal. Studies varied in pace.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["24847856","39279635","24388483"],"research_summary":"A meal-level review and laboratory studies support reduced intake in some meals. Methods for slowing eating vary, and the evidence does not establish lasting weight loss.","source_notes":[{"source_id":"24847856","role":"Direct pooled result","summary":"Experimental meals consumed more slowly were associated with lower intake on average than faster meals. The designs and methods for changing eating rate varied."},{"source_id":"39279635","role":"Related food-texture study","summary":"Researchers changed food texture to slow eating. Participants consumed less energy at those meals. This provides context for eating rate, while testing a different action from deliberately slowing down."},{"source_id":"24388483","role":"Controlled trial","summary":"A fast-versus-slow eating comparison found lower intake in the normal-weight subgroup. The group-by-weight interaction was not significant."}]},{"card_id":"three-good-things","title":"Write down three good things","action":"For one week, write down three things that went well each night and why they happened.","tracking_prompt":"Rate wellbeing before and after the week.","goals":["mood"],"benefit_ids":["three-good-things-1"],"eligibility_rule":"read_studied_population","studied_population":"General adults seeking small mood lift","qualification":"Different gratitude exercises have been studied. Average wellbeing effects were small and depended on the comparison activity.","time_commitment":"A few minutes each evening for one week.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["40627390","16045394","37217328"],"research_summary":"One online trial supports the nightly exercise. A different prompting schedule produced small positive-affect changes in healthcare workers, with no clear life-satisfaction benefit.","source_notes":[{"source_id":"40627390","role":"Broader gratitude research","summary":"Across 163 samples, diverse gratitude exercises produced a small average wellbeing improvement. This estimate includes many exercises and should not be presented as the effect of writing three good things."},{"source_id":"16045394","role":"Direct, specific exercise","summary":"The full report describes a week of writing three things that went well and why. Participants reported greater happiness at later follow-ups than those writing about early memories. This is the link for the exact exercise."},{"source_id":"37217328","role":"Different schedule and outcomes","summary":"Healthcare workers were prompted three times weekly to name good things. Positive affect showed a small improvement. Life satisfaction and depressive symptoms did not clearly differ between groups. This differs from nightly writing about why events happened."}]},{"card_id":"mindfulness","title":"Try a brief guided mindfulness practice","action":"Try a guided meditation for about ten minutes daily for eight weeks.","tracking_prompt":"Rate perceived stress weekly.","goals":["mood"],"benefit_ids":["mindfulness-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Employees with mild to moderate stress.","qualification":"The workplace trial used a guided meditation app for eight weeks. Stop if distress increases and seek appropriate support.","time_commitment":"10 min/day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["39808431","31237569","34962055"],"research_summary":"Trials in employees and students found lower perceived stress with guided digital mindfulness compared with waiting-list controls.","source_notes":[{"source_id":"39808431","role":"Direct, tested prescription","summary":"In 1,458 stressed employees, assignment to an app providing ten minutes of daily meditation for eight weeks improved perceived stress compared with waiting list. Actual usage varied."},{"source_id":"31237569","role":"Direct, student sample","summary":"Stressed college students assigned to an app-based mindfulness program reported lower perceived stress than a wait-list group. This extends the finding to another study population."},{"source_id":"34962055","role":"Independent student trial","summary":"Working university students assigned to an eight-week mindfulness app reported lower stress than wait-listed students. It supports perceived stress in a different sample."}]},{"card_id":"left-side","title":"Try positional therapy for nighttime reflux","action":"In one trial, adults wore a device at night for two weeks that prompted them to turn away from their right side. Choosing the left side yourself is a less-tested option.","tracking_prompt":"Record nighttime reflux symptoms.","goals":["digestion"],"benefit_ids":["left-side-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with nocturnal reflux","qualification":"The controlled trial used a device that discouraged right-side sleeping. The benefit of choosing the left side without a device is less certain.","time_commitment":"During sleep. The device trial lasted two weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35301135","37969463"],"research_summary":"The direct symptom result comes from a two-week device trial. Other positioning devices or combined incline-and-side approaches do not isolate choosing the left side unaided.","source_notes":[{"source_id":"35301135","role":"Controlled trial","summary":"A wearable device encouraged left-side sleep for two weeks. Nighttime reflux symptoms improved relative to a sham device."},{"source_id":"37969463","role":"Review including the same trial","summary":"The review found evidence linking left-side position to lower acid exposure and summarized the same device trial that reported symptom relief. It adds context without providing another independent device trial."}]},{"card_id":"music","title":"Listen to music before bed","action":"Try listening to calming recorded music for about 30–45 minutes at bedtime. Studies used different selections and schedules.","tracking_prompt":"Rate sleep quality the next morning.","goals":["sleep"],"benefit_ids":["music-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with sleep difficulties.","qualification":"Research supports perceived sleep quality. Objective sleep duration and sleep stages remain uncertain.","time_commitment":"About 30–45 minutes at bedtime.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36000763","15660547","18426457","30676671"],"research_summary":"A Cochrane review supports better self-rated sleep quality. Another trial reported better perceived sleep but an inconclusive result on its primary insomnia-severity measure.","source_notes":[{"source_id":"36000763","role":"Pooled research","summary":"A Cochrane review found better perceived sleep quality among adults with insomnia symptoms. Objective sleep measurements were less conclusive."},{"source_id":"15660547","role":"Direct primary example","summary":"Older adults listening to soothing bedtime music reported better sleep quality over the intervention period than controls. Perceived sleep quality was the relevant endpoint."},{"source_id":"18426457","role":"Direct primary example","summary":"Young adults with sleep complaints who listened to 45 minutes of relaxing classical music at bedtime for three weeks reported improved sleep quality on a questionnaire."},{"source_id":"30676671","role":"Mixed findings across sleep measures","summary":"In adults with insomnia, bedtime music improved perceived sleep on a secondary measure. The primary comparison on insomnia severity was inconclusive, and objective sleep measures showed no change."}]},{"card_id":"smell-training","title":"Practice smell training","action":"After evaluation for persistent postviral smell loss, one approach is to gently smell four familiar scents twice daily. Research protocols included 12-week training blocks and longer programs. Avoid irritants and direct nasal application.","tracking_prompt":"Log sessions and which scents you can identify.","goals":[],"benefit_ids":["smell-training-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Adults with persistent post-viral smell loss","qualification":"Persistent or unexplained smell loss merits clinical assessment. Avoid putting oils or other substances inside your nose.","time_commitment":"Twice daily. Training duration varied across studies.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32567798","23929687","32660334","42311058"],"research_summary":"A postviral review and a separate review of ten post-COVID trials support improved smell-test performance. The training protocols and viral causes differ.","source_notes":[{"source_id":"32567798","role":"Direct review, varied protocols","summary":"An evidence review recommends repeated odor training for postviral smell loss based on changes in measured olfactory function. Protocols and odor sets differed across the studies."},{"source_id":"23929687","role":"Different duration and comparison","summary":"People with postinfectious smell loss trained with stronger or weaker odors for 18 weeks. Improvement on testing was more common in the higher-concentration arm. Both groups trained, limiting inference about training versus usual care."},{"source_id":"32660334","role":"Postviral training review","summary":"Across four pooled studies, trained participants were more likely than controls to improve by a clinically important amount on an odor test. Training protocols varied."},{"source_id":"42311058","role":"Post-COVID subgroup","summary":"Ten randomized trials in post-COVID smell loss found a small average improvement in objective smell scores. The finding applies to this postviral subgroup across varied protocols."}]},{"card_id":"prunes","title":"Try prunes for constipation","action":"The studied schedule was 50 g of prunes twice daily for three weeks in adults with constipation.","tracking_prompt":"Count complete bowel movements weekly.","goals":["digestion"],"benefit_ids":["prunes-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Chronic constipation; 37 women, 3 men; mean age 38","qualification":"A small crossover trial tested this exact schedule. A second comparison also observed improved bowel frequency from baseline. Large servings may cause bloating or loose stools.","time_commitment":"Two daily portions for three weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["21323688","34074830"],"research_summary":"Two constipation studies support the bowel-frequency finding. Trials in other populations measuring total stools do not directly replicate the complete spontaneous bowel movement outcome.","source_notes":[{"source_id":"21323688","role":"Direct exact schedule","summary":"Forty adults with constipation crossed over between dried plums and psyllium. Fifty grams of dried plums twice daily for three weeks improved complete spontaneous bowel movements and stool consistency relative to psyllium."},{"source_id":"34074830","role":"Direct for bowel frequency","summary":"Adults with constipation ate 100 g of prunes daily for four weeks. Bowel frequency improved from baseline, with similar response rates across treatments. The other trial tested 50 g twice daily for three weeks."}]},{"card_id":"cystitis","title":"Add water for recurrent cystitis prevention","action":"The trial added 1.5 L of water daily to usual intake in selected women drinking under 1.5 L of fluid daily. Confirm that the eligibility and fluid plan fit.","tracking_prompt":"Log episodes diagnosed by a clinician. This routine is for prevention.","goals":[],"benefit_ids":["cystitis-1"],"eligibility_rule":"clinician_clearance","studied_population":"Premenopausal women with recurrent cystitis and usual total fluid intake below 1.5 L/day. See the full eligibility criteria.","qualification":"Prevention in healthy premenopausal women with at least three symptomatic episodes in the prior year, at least one culture-confirmed, and low usual fluid intake. Exclude current symptoms, pregnancy, breastfeeding and fluid restriction. New urinary symptoms require assessment.","time_commitment":"Extra water spread throughout the day for 12 months in the trial.","display_evidence_in_details":true,"blocked_if":["current_urinary_symptoms","pregnancy","breastfeeding","fluid_restriction"],"research_source_ids":["30285042","31988085"],"research_summary":"One water-only trial directly supports the extra 1.5 L daily in this population. A broader fluid review found fewer episodes overall, with uncertainty about who had any recurrence at one year.","source_notes":[{"source_id":"30285042","role":"Direct prevention trial","summary":"Among 140 premenopausal women with recurrent cystitis and low fluid intake, adding 1.5 L of water daily resulted in 1.7 versus 3.2 episodes on average over a year. The study concerned prevention."},{"source_id":"31988085","role":"Broader recurrence review","summary":"A review of increased fluid intake found fewer recurrent urinary infections overall. At 12 months the difference in the proportion with any recurrence was inconclusive. It pools different fluid interventions and does not independently verify the card’s exact water dose."}]},{"card_id":"dash","title":"Build meals around the DASH pattern","action":"Build meals around vegetables, fruit, whole grains and low-fat dairy, with less saturated fat. Use the studied dietary pattern as the reference.","tracking_prompt":"Track adherence and average home blood pressure.","goals":["heart"],"benefit_ids":["dash-1","dash-2"],"eligibility_rule":"read_studied_population","studied_population":"Adults SBP <160 and DBP 80–95 mmHg","qualification":"Adapt to allergies and prescribed diets. Kidney disease or potassium/fluid restrictions require clinical dietary advice; do not change medication. ","time_commitment":"A daily eating pattern. Shopping and preparation time vary.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["9099655","32330233"],"research_summary":"A controlled feeding trial and a DASH-specific review support lower blood pressure. Reviews of multiple dietary patterns add little to this specific comparison.","source_notes":[{"source_id":"9099655","role":"Direct feeding trial","summary":"With sodium intake and body weight held constant, participants assigned the DASH combination diet saw greater reductions in systolic and diastolic pressure than those on the control diet."},{"source_id":"32330233","role":"Pooled research","summary":"Randomized trials of the DASH pattern found lower systolic and diastolic pressure. Sodium intake and other trial conditions varied."}]},{"card_id":"walking-breaks","title":"Break up a seated workday with walks","action":"Choose a studied schedule below. The blood pressure and fatigue findings apply to the light walking schedules.","tracking_prompt":"Log walks and rate fatigue at the same time on comparable days.","goals":["heart","mood","energy"],"benefit_ids":["walking-breaks-1","walking-breaks-2","walking-breaks-3"],"eligibility_rule":"read_studied_population","studied_population":"Sedentary adults completing prolonged sitting days. The exact age and health criteria varied by schedule.","qualification":"These were short laboratory comparisons with prolonged sitting. The studies did not establish a lasting blood-pressure or mood effect.","time_commitment":"Five minutes per break on the chosen schedule.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["36728338","27809874","37682412"],"research_summary":"Laboratory studies support same-day effects of walking breaks. A broader blood-pressure review cannot assign mood or fatigue effects to particular schedules.","source_notes":[{"source_id":"36728338","role":"Direct light-walk schedules","summary":"In 11 adults, light walks interrupted laboratory sitting and lowered same-day systolic pressure. Figure 3 supports fatigue and mood findings for the five-minute light-walk schedules. Preserve the separate moderate-walk citation."},{"source_id":"27809874","role":"Direct moderate-walk schedule","summary":"Thirty sedentary adults completed uninterrupted sitting and two activity conditions. Six hourly five-minute moderate walks improved self-rated mood and reduced fatigue compared with sitting. A morning half-hour walk did not show those same results."},{"source_id":"37682412","role":"Broader sitting-break evidence","summary":"Pooled laboratory studies found that interrupting prolonged sitting attenuated increases in blood pressure. The interventions varied. It does not establish mood changes or a particular walking schedule."}]},{"card_id":"one-brisk-walk","title":"Try a ten-minute brisk walk","action":"Take one ten-minute walk at a self-selected brisk pace if appropriate.","tracking_prompt":"Rate fatigue before and shortly after the walk.","goals":["energy"],"benefit_ids":["one-brisk-walk-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Active college-aged adults; mean 21.3; eligible 18–53","qualification":"One study in active young adults measured fatigue immediately afterward.","time_commitment":"One ten-minute walk.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["30087839"],"research_summary":"One small study directly supports lower fatigue after a ten-minute walk versus before the walk. Earlier walking studies emphasized energy or tension, and stair studies changed the activity.","source_notes":[{"source_id":"30087839","role":"Controlled trial","summary":"After a ten-minute brisk walk, young adults reported less fatigue than before. The study reported an overall group-by-time interaction and within-group changes."}]},{"card_id":"nap","title":"Try a brief post-lunch nap opportunity","action":"Allow 15 minutes for a post-lunch nap. The research tested an opportunity to sleep in young adults after restricted sleep.","tracking_prompt":"Record sleepiness afterward.","goals":["energy"],"benefit_ids":["nap-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Young adults after a night of restricted sleep.","qualification":"Allow time to wake fully. The finding comes from young adults after a short night and cannot establish fitness to drive.","time_commitment":"One 15-minute opportunity to sleep, plus time to wake fully.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["11007448","16796222","11322712"],"research_summary":"Short lab trials after restricted sleep support improved afternoon alertness. The study allowing a 15-minute nap opportunity differs from studies timing actual sleep.","source_notes":[{"source_id":"11007448","role":"Direct, nap opportunity","summary":"Twelve students after a restricted night were less sleepy at two afternoon assessments when allowed a 15-minute post-lunch nap than when kept awake. They slept an average of 10.2 minutes."},{"source_id":"16796222","role":"Related duration measure","summary":"After restricted sleep, ten minutes of actual nap sleep improved immediate alertness in a small lab trial. Five, 20 and 30 minutes had different effects. The 15-minute time allowance is supported by the other paper."},{"source_id":"11322712","role":"Related nap duration","summary":"After restricted sleep, ten minutes of afternoon sleep improved subjective alertness immediately. Some testing after a 30-minute nap showed early grogginess. Time asleep differs from a 15-minute opportunity to nap."}]},{"card_id":"oats","title":"Choose oats with a stated beta-glucan amount","action":"Choose oat foods that state their oat beta-glucan content. Use the label to reach about 3 g per day. Total fiber on the label is a different measure.","tracking_prompt":"Log the labeled amount. A lipid panel measures the outcome.","goals":["heart"],"benefit_ids":["oats-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with dyslipidemia","qualification":"Use the labeled amount of oat beta-glucan. Products vary widely. People who need gluten-free foods should choose appropriately labeled oats.","time_commitment":"Daily food choice; at least several weeks in trials.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["25411276","27724985","20660224","35631184"],"research_summary":"Several reviews support lower LDL with oat beta-glucan, with overlapping trials. The product, processing and amount of beta-glucan affect applicability.","source_notes":[{"source_id":"25411276","role":"Pooled research","summary":"Controlled trials using at least 3 g/day of oat beta-glucan found lower LDL compared with control diets. The active amount refers specifically to oat beta-glucan."},{"source_id":"27724985","role":"Pooled research","summary":"A second oat beta-glucan synthesis reported lower LDL across 58 trials. The two syntheses may include many of the same trials."},{"source_id":"20660224","role":"Direct, product-specific result","summary":"Cereals providing 3 g daily of high- or medium-molecular-weight oat beta-glucan lowered LDL by about 5%. The low-molecular-weight preparation was less effective."},{"source_id":"35631184","role":"Overlapping lipid review","summary":"A review in adults with high cholesterol found lower average LDL with oat beta-glucan. Dose, product and study duration varied, and earlier reviews may include the same trials."}]},{"card_id":"pelvic-floor","title":"Follow a supervised pelvic-floor training plan","action":"Arrange supervised training with a qualified clinician. NICE recommends a program lasting at least three months, with at least eight contractions three times a day, adapted to the person.","tracking_prompt":"Keep a bladder diary if recommended.","goals":[],"benefit_ids":["pelvic-floor-1"],"eligibility_rule":"clinician_clearance","studied_population":"Women with stress urinary incontinence.","qualification":"For women with stress urinary incontinence. A clinician should check technique and tailor the program. Supervision is part of the recommendation.","time_commitment":"Three sets daily for at least three months, with supervision.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["30288727","NICE"],"research_summary":"Controlled trials support improved stress incontinence. NICE supplies the supervised schedule. Supervised-versus-unsupervised studies ask a different question.","source_notes":[{"source_id":"30288727","role":"Pooled research","summary":"A Cochrane review compared pelvic-floor training with inactive controls and found symptom improvement in women with stress incontinence."},{"source_id":"NICE","role":"Supervised training schedule","summary":"Sections 1.4.4–1.4.5 recommend at least three months of supervised training for women with stress or mixed incontinence and at least eight contractions three times daily. This is guidance on the program rather than an independent effect estimate."}]},{"card_id":"handgrip","title":"Practice isometric handgrip training","action":"Start with a qualified exercise professional to set the grip force. One example uses four two-minute holds at about 30% of maximum, with three-minute rests, on three days weekly for at least eight weeks.","tracking_prompt":"Log sessions and average blood pressure measured at rest.","goals":["heart"],"benefit_ids":["handgrip-1"],"eligibility_rule":"clinician_clearance","studied_population":"Normotensive and hypertensive adults","qualification":"A suitable force-measuring device and an initial supervised session are needed. Breathe normally. Uncontrolled blood pressure, recent cardiac events or exercise restrictions require clinical assessment. The systolic result is more consistent across reviews than the diastolic result.","time_commitment":"Four two-minute holds plus recoveries, three days weekly for at least eight weeks.","display_evidence_in_details":true,"blocked_if":["exercise_restriction"],"research_source_ids":["41922197","28033302","34140663"],"research_summary":"Reviews support lower resting systolic pressure on average. A smaller review in treated hypertension found an inconclusive diastolic effect.","source_notes":[{"source_id":"41922197","role":"Direct pooled result","summary":"In 31 studies, systolic and diastolic pressure were lower by about 5.4 and 2.7 mmHg on average. Results differed markedly across studies. The four-set protocol is an evidence-informed example."},{"source_id":"28033302","role":"Controlled trial","summary":"Eight weeks of handgrip training at 30% maximum was compared with lower intensity. Systolic pressure fell within the higher-intensity group; its diastolic change was not significant."},{"source_id":"34140663","role":"Endpoint-specific uncertainty","summary":"Across trials in people with treated hypertension, handgrip training lowered resting systolic pressure, while the diastolic estimate was imprecise. Keep the diastolic result qualified."}]},{"card_id":"tai-chi","title":"Join a fall-prevention tai chi program","action":"Choose an instructor-led tai chi program designed for fall prevention. One trial offered classes three times weekly for six months. A second tested a twice-weekly therapeutic program for 24 weeks.","tracking_prompt":"Record class attendance and any falls.","goals":["movement"],"benefit_ids":["tai-chi-1"],"eligibility_rule":"confirm_eligibility","studied_population":"Inactive community adults aged 70–92","qualification":"For older adults at elevated fall risk who can participate in a supervised class. The benefit pertains to tested fall-prevention programs.","time_commitment":"Instructor-led classes for about six months.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["15814861","30208396","37736087"],"research_summary":"Structured programs reduce falls in older adults across trials. Keep evidence on all falls separate from the particular trial measuring repeat falling.","source_notes":[{"source_id":"15814861","role":"Controlled trial","summary":"Older adults in a supervised tai chi program had fewer repeated falls compared with stretching over six months."},{"source_id":"30208396","role":"Related total-fall result","summary":"Among 670 older adults at increased fall risk, twice-weekly therapeutic tai ji quan produced fewer falls than stretching over 24 weeks. Its primary endpoint counted all falls. Cite the earlier trial specifically for repeat falling."},{"source_id":"37736087","role":"Broader fall prevention evidence","summary":"A pooled analysis favored tai chi for preventing falls in older adults across differing programs. Total falls and balance outcomes cannot be substituted for repeat falling on the card."}]},{"card_id":"neck-strength","title":"Follow a taught resistance routine for neck and shoulder pain","action":"Ask a physical therapist to teach the studied elastic-band lateral raise and progression. The short schedule used one slow set for up to two minutes on five workdays per week for ten weeks. A longer tested option appears in the details.","tracking_prompt":"Track pain on the same scale once a week and record training days.","goals":["movement"],"benefit_ids":["neck-strength-1"],"eligibility_rule":"clinician_clearance","studied_population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","qualification":"The trial included initial therapist instruction and planned resistance progression. Seek assessment for new, severe or unexplained pain.","time_commitment":"Two or twelve minutes per session, five workdays weekly for ten weeks.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["21177034","25574172"],"research_summary":"One trial directly supports the tested workday routine, with a companion report for the instructions. Muscle-activity findings do not independently establish pain relief.","source_notes":[{"source_id":"21177034","role":"Controlled trial","summary":"Symptomatic workers received taught progressive band exercises for two or twelve minutes on workdays. Both groups reported less neck or shoulder pain than controls."},{"source_id":"25574172","role":"Tested exercise instructions","summary":"The companion report describes the same workplace intervention, including technique, progression, and sets for the two-minute and twelve-minute options."}]},{"card_id":"sleep-extension","title":"Work with a counselor to extend short sleep","action":"With individualized sleep counseling, plan enough time in bed to allow about 8.5 hours nightly and review the plan at follow-up. The trial enrolled habitual short sleepers with overweight.","tracking_prompt":"Track sleep opportunity and sleep duration separately. A food diary cannot reproduce the trial’s energy-balance measurement.","goals":["sleep","metabolic"],"benefit_ids":["sleep-extension-1","sleep-extension-2"],"eligibility_rule":"clinician_clearance","studied_population":"Adults 21–40, BMI 25–29.9, habitual sleep <6.5 h/night; no sleep apnea or insomnia","qualification":"The study enrolled adults aged 21–40 with overweight who usually slept less than 6.5 hours. Insomnia and sleep apnea were excluded. The trial included individualized counseling and follow-up.","time_commitment":"Nightly for two weeks after individualized counseling.","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35129580","34507028"],"research_summary":"A broader review supports increased sleep duration. The objectively estimated energy-intake result remains tied to one two-week trial in short sleepers with overweight.","source_notes":[{"source_id":"35129580","role":"Controlled trial","summary":"Individualized counseling increased measured sleep duration and reduced energy intake over two weeks in short-sleeping adults with overweight. Both results came from the same trial."},{"source_id":"34507028","role":"Broader research","summary":"Sleep-extension interventions increased sleep duration across populations, with substantial variation. This review does not establish lower energy intake."}]},{"card_id":"slow-breathing","title":"Practice slow breathing","action":"Sit comfortably and breathe slowly, about 10 breaths a minute or fewer, for 10 to 15 minutes a day.","tracking_prompt":"Log sessions. Add home blood pressure readings if you already take them.","goals":["heart"],"benefit_ids":["slow-breathing-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with high or high-normal blood pressure, in 17 trials of device-guided and unguided slow breathing.","qualification":"Breathe gently. Stop if you feel light-headed.","time_commitment":"10 to 15 minutes a day","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["31331557"],"research_summary":"Pooled trials found a small average drop in blood pressure with regular slow breathing. Results varied a lot between studies, and some device trials had manufacturer involvement.","source_notes":[{"source_id":"31331557","role":"Direct pooled result","summary":"In 17 studies of people with high or high-normal blood pressure, slow breathing lowered systolic pressure by about 5.6 mmHg and diastolic by about 3 mmHg. Heterogeneity was high."}]},{"card_id":"humming","title":"Hum on the out-breath","action":"Breathe in through your nose, then hum gently as you breathe out. Repeat for a few minutes and notice how you feel.","tracking_prompt":"Note how calm you feel afterward. This is a personal experiment.","goals":[],"benefit_ids":[],"eligibility_rule":"read_studied_population","studied_population":"Ten healthy adults in a laboratory measurement of nasal nitric oxide.","qualification":"Stop if you feel light-headed.","time_commitment":"A few minutes","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["12119224"],"research_summary":"Humming raises nitric oxide in the nose many times over in a lab measurement. No study here tested a health benefit, so treat this as a personal experiment.","source_notes":[{"source_id":"12119224","role":"Mechanism only","summary":"Nasal nitric oxide rose about 15-fold during humming in ten healthy adults. The study measured no symptom or health outcome, so it does not support a health claim."}]},{"card_id":"acupuncture-migraine","title":"Try acupuncture for migraine","action":"Book a course of at least six sessions with a licensed acupuncturist, and keep a record of your migraine days.","tracking_prompt":"Log each session and count migraine days per month.","goals":[],"benefit_ids":["acupuncture-migraine-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with episodic migraine in 22 trials (4,985 people).","qualification":"Use a licensed practitioner. Tell them if you take blood thinners.","time_commitment":"At least six sessions, usually weekly","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["27351677"],"research_summary":"Across 22 trials, people having acupuncture had fewer migraine days than people with usual care. Compared with sham acupuncture the extra benefit was small.","source_notes":[{"source_id":"27351677","role":"Direct pooled result","summary":"Migraine days fell from about six a month to about three and a half with acupuncture, versus four with sham or preventive drugs and five with usual care. 50% of people responded to acupuncture and 41% to sham. Moderate-quality evidence."}]},{"card_id":"weighted-blanket","title":"Sleep under a weighted blanket","action":"Sleep under a heavy weighted blanket every night for four weeks. The trial used a chain blanket of about 8 kg.","tracking_prompt":"Note how you slept each morning.","goals":["sleep"],"benefit_ids":["weighted-blanket-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with insomnia and depression, bipolar disorder, generalized anxiety or ADHD (120 people).","qualification":"You should be able to lift it off yourself easily.","time_commitment":"Every night","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["32536366"],"research_summary":"One randomized trial found a heavy blanket reduced insomnia severity more than a light one over four weeks, in adults with insomnia and a mental health condition. It has not been repeated yet.","source_notes":[{"source_id":"32536366","role":"Direct result, single trial","summary":"120 adults with insomnia and a psychiatric condition. After 4 weeks, 59% responded with a heavy chain blanket versus 5% with a light blanket. No serious adverse events."}]},{"card_id":"stair-walk-energy","title":"Walk the stairs for energy","action":"When you feel flat, walk up and down stairs at an easy pace for ten minutes.","tracking_prompt":"Rate your energy before and after.","goals":["energy"],"benefit_ids":["stair-walk-energy-1"],"eligibility_rule":"read_studied_population","studied_population":"18 chronically sleep-deprived college women in a crossover study.","qualification":"Hold the rail and go at an easy pace. Stop if you feel dizzy or short of breath.","time_commitment":"10 minutes","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["PHYSBEH-2017-STAIRS"],"research_summary":"In one small study, ten minutes of easy stair walking made sleep-deprived young women feel more energetic than a small dose of caffeine. The boost was brief.","source_notes":[{"source_id":"PHYSBEH-2017-STAIRS","role":"Direct result, small crossover","summary":"18 sleep-deprived college women. Ten minutes of low-to-moderate stair walking raised feelings of energy more than 50 mg caffeine or placebo. Attention and memory did not improve."}]},{"card_id":"drawing-memory","title":"Draw it to remember it","action":"When you need to remember a list or new words, draw a quick sketch of each item instead of writing it out.","tracking_prompt":"Try recalling the items later and count how many you remember.","goals":["memory"],"benefit_ids":["drawing-memory-1"],"eligibility_rule":"read_studied_population","studied_population":"University students in seven laboratory free-recall experiments.","qualification":"Quick sketches are enough. Drawing skill did not matter in the studies.","time_commitment":"A few seconds per item","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["26444654"],"research_summary":"Across seven lab experiments, people remembered words better when they drew them than when they wrote them out. The tests were short and mostly in students.","source_notes":[{"source_id":"26444654","role":"Direct result, lab experiments","summary":"In seven free-recall experiments, drawn words were recalled better than written ones. The benefit held across several comparison tasks."}]},{"card_id":"toilet-footstool","title":"Raise your feet on the toilet","action":"Put a small footstool in front of the toilet and rest your feet on it so your knees are above your hips.","tracking_prompt":"Note how easy each bowel movement felt.","goals":["digestion"],"benefit_ids":["toilet-footstool-1"],"eligibility_rule":"read_studied_population","studied_population":"Healthy adult volunteers who logged bowel movements for four weeks.","qualification":"See a doctor about new or lasting bowel changes.","time_commitment":"No extra time","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["30346317"],"research_summary":"In one small study of healthy adults, using a footstool shortened time on the toilet and reduced straining. People with constipation were not studied.","source_notes":[{"source_id":"30346317","role":"Direct result, uncontrolled crossover","summary":"Healthy volunteers recorded bowel movements for two weeks without and two weeks with a footstool. With the stool they reported less straining, shorter duration and more complete emptying."}]},{"card_id":"abdominal-massage","title":"Massage your belly for constipation","action":"Lying down, gently massage your belly in slow clockwise circles for about ten minutes.","tracking_prompt":"Note bowel movements and how comfortable you feel.","goals":["digestion"],"benefit_ids":["abdominal-massage-1"],"eligibility_rule":"read_studied_population","studied_population":"Adults with functional chronic constipation.","qualification":"Skip it if you have belly pain that hasn’t been checked. See a doctor about new or lasting bowel changes.","time_commitment":"About 10 minutes, several times a week","display_evidence_in_details":true,"blocked_if":[],"research_source_ids":["35554601","39531948"],"research_summary":"A placebo-controlled trial and a review of small trials found abdominal massage eased constipation symptoms. Techniques and schedules varied.","source_notes":[{"source_id":"35554601","role":"Direct result","summary":"Adults with functional chronic constipation improved more with abdominal massage than with a placebo treatment over four weeks."},{"source_id":"39531948","role":"Pooled research","summary":"Pooled small randomized trials in adults with chronic constipation favored abdominal massage. Methods varied."}]}],"benefits":[{"benefit_id":"walk-after-meals-1","card_id":"walk-after-meals","statement":"Smaller rise in blood glucose in the hours after a meal compared with continued sitting","goals":["metabolic"],"population":"Sedentary adults, mostly healthy or overweight/obese adults in lab test meals","comparator":"Uninterrupted sitting","timeframe":"Acute, hours after a single test meal","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42070794/","https://pubmed.ncbi.nlm.nih.gov/22374636/","https://pubmed.ncbi.nlm.nih.gov/42586449/","https://pubmed.ncbi.nlm.nih.gov/42627002/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["42070794","22374636","42586449","42627002"]},{"benefit_id":"walk-after-meals-2","card_id":"walk-after-meals","statement":"Smaller insulin response after a meal","goals":["metabolic"],"population":"Sedentary adults, mostly healthy or overweight/obese adults in lab test meals","comparator":"Uninterrupted sitting","timeframe":"Acute, hours after a single test meal","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42070794/","https://pubmed.ncbi.nlm.nih.gov/22374636/","https://pubmed.ncbi.nlm.nih.gov/42586449/","https://pubmed.ncbi.nlm.nih.gov/42627002/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["42070794","22374636","42586449","42627002"]},{"benefit_id":"walk-after-meals-3","card_id":"walk-after-meals","statement":"Lower post-meal glucose in adults with type 2 diabetes when walking after meals compared with one untimed daily walk","goals":["metabolic"],"population":"Adults with type 2 diabetes, mean age 60; mean duration 10 years","comparator":"one 30-minute daily walk without specified timing","timeframe":"3-hour meal windows during 2-week periods","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27747394/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":"type_2_diabetes","display_scope":"variant","source_ids":["27747394"]},{"benefit_id":"brisk-walking-1","card_id":"brisk-walking","statement":"Lower resting systolic blood pressure on average after several months","goals":["heart"],"population":"Adults in controlled walking programs, including adults with hypertension.","comparator":"No-exercise control","timeframe":"15 weeks mean","source_urls":["https://pubmed.ncbi.nlm.nih.gov/33630309/","https://pubmed.ncbi.nlm.nih.gov/42405260/"],"evidence_label":"Strong evidence","effect_detail":"About 4.1 mmHg lower systolic pressure than control, pooled across 73 trials (95% CI 3.0–5.2 lower).","audience_filter":null,"display_scope":"card","source_ids":["33630309","42405260"]},{"benefit_id":"brisk-walking-2","card_id":"brisk-walking","statement":"Lower resting diastolic pressure among adults with hypertension","goals":["heart"],"population":"Adults with hypertension","comparator":"Non-exercise controls in pooled RCTs","timeframe":"At least 12 weeks program","source_urls":["https://pubmed.ncbi.nlm.nih.gov/33630309/","https://pubmed.ncbi.nlm.nih.gov/42405260/"],"evidence_label":"Research supported","effect_detail":"The hypertension-specific review estimated about 4.7 mmHg lower diastolic pressure, with low certainty about magnitude.","audience_filter":"hypertension","display_scope":"card","source_ids":["33630309","42405260"]},{"benefit_id":"brisk-walking-3","card_id":"brisk-walking","statement":"Improved aerobic fitness in previously sedentary adults","goals":["movement"],"population":"Previously sedentary adults in regular walking programs.","comparator":"Nonwalking control groups.","timeframe":"Across multiweek walking programs.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/17275896/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["17275896"]},{"benefit_id":"stairs-1","card_id":"stairs","statement":"Better aerobic fitness in inactive young adults","goals":["movement"],"population":"Inactive young adults (Jenkins 2019, Yin 2024: sedentary young adults; Han 2025: inactive young men with obesity, n=12 vs 12). Older adults, women-only samples and clinical groups not covered.","comparator":"No-exercise control (also vs MICT in Yin)","timeframe":"Four to six weeks, depending on the trial schedule.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30649897/","https://pubmed.ncbi.nlm.nih.gov/38569204/","https://pubmed.ncbi.nlm.nih.gov/40087042/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["30649897","38569204","40087042"]},{"benefit_id":"almonds-1","card_id":"almonds","statement":"Slightly lower LDL cholesterol","goals":["heart"],"population":"Adults without cardiovascular disease (healthy or with cardiometabolic risk factors)","comparator":"Control","timeframe":"4 to 72 weeks (median not extracted)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40944180/","https://pubmed.ncbi.nlm.nih.gov/12221048/","https://pubmed.ncbi.nlm.nih.gov/19394473/"],"evidence_label":"Strong evidence","effect_detail":"About 5 mg/dL lower LDL on average.","audience_filter":null,"display_scope":"card","source_ids":["40944180","12221048","19394473"]},{"benefit_id":"almonds-2","card_id":"almonds","statement":"Slightly lower total cholesterol","goals":["heart"],"population":"Adults without cardiovascular disease (healthy or with cardiometabolic risk factors)","comparator":"Control","timeframe":"4 to 72 weeks (median not extracted)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40944180/","https://pubmed.ncbi.nlm.nih.gov/19394473/"],"evidence_label":"Strong evidence","effect_detail":"About 6 mg/dL lower total cholesterol on average.","audience_filter":null,"display_scope":"card","source_ids":["40944180","19394473"]},{"benefit_id":"almonds-3","card_id":"almonds","statement":"Slightly lower apolipoprotein B","goals":["heart"],"population":"Adults without cardiovascular disease (healthy or with cardiometabolic risk factors)","comparator":"Control","timeframe":"4 to 72 weeks (median not extracted)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40944180/"],"evidence_label":"Research supported","effect_detail":"About 4.5 mg/dL lower ApoB in the pooled comparisons.","audience_filter":null,"display_scope":"card","source_ids":["40944180"]},{"benefit_id":"sunscreen-1","card_id":"sunscreen","statement":"Slower visible skin aging over several years in a sunny climate","goals":[],"population":"Healthy adults, esp. fair-skinned, high-UV exposure","comparator":"Discretionary sunscreen","timeframe":"4.5 years","source_urls":["https://pubmed.ncbi.nlm.nih.gov/23732711/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["23732711"]},{"benefit_id":"caffeine-1","card_id":"caffeine","statement":"Late caffeine can reduce objectively measured sleep","goals":["sleep"],"population":"Healthy adults, low-moderate habitual caffeine","comparator":"Placebo (within-person crossover in key trial)","timeframe":"Acute (single doses) to 14 days","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36870101/","https://pubmed.ncbi.nlm.nih.gov/39377163/","https://pubmed.ncbi.nlm.nih.gov/24235903/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36870101","39377163","24235903"]},{"benefit_id":"caffeine-2","card_id":"caffeine","statement":"A 400 mg dose disrupted some sleep measures even 12 hours before bedtime in a small trial","goals":["sleep"],"population":"Healthy men in a small randomized crossover trial.","comparator":"Placebo at the same time before bedtime.","timeframe":"Single doses","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39377163/"],"evidence_label":"Research supported","effect_detail":"The highest tested dose was 400 mg, and 12 hours was the longest interval tested.","audience_filter":null,"display_scope":"card","source_ids":["39377163"]},{"benefit_id":"resistance-sarcopenia-1","card_id":"resistance-sarcopenia","statement":"Resistance-based programs improved strength and walking speed on average. A separate review found several average gains were below thresholds for clinically important change.","goals":["movement"],"population":"Adults with sarcopenia","comparator":"Control","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42947012/","https://pubmed.ncbi.nlm.nih.gov/41212331/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["42947012","41212331"]},{"benefit_id":"bath-1","card_id":"bath","statement":"May shorten time to fall asleep, although reviews disagree","goals":["sleep"],"population":"Adults (mixed health status)","comparator":"No heating","timeframe":"Acute-nightly","source_urls":["https://pubmed.ncbi.nlm.nih.gov/31102877/","https://pubmed.ncbi.nlm.nih.gov/42545422/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["31102877","42545422"]},{"benefit_id":"relax-muscles-1","card_id":"relax-muscles","statement":"Better self-rated sleep quality in trials largely involving people with medical conditions","goals":["sleep"],"population":"Adults, but studies were largely patients (cancer, dialysis), PSQI self-report; adults aged 55+ not significant","comparator":"Control","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42625730/","https://pubmed.ncbi.nlm.nih.gov/38494385/","https://pubmed.ncbi.nlm.nih.gov/41633054/","https://pubmed.ncbi.nlm.nih.gov/34569129/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["42625730","38494385","41633054","34569129"]},{"benefit_id":"cyclic-sighing-1","card_id":"cyclic-sighing","statement":"Improved self-rated positive mood in one month-long trial","goals":["mood"],"population":"Adults 18+, mostly Stanford undergraduates; major medical/psychiatric conditions and pregnancy excluded.","comparator":"5 minutes/day mindfulness meditation","timeframe":"daily pre/post sessions over 28 days","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36630953/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36630953"]},{"benefit_id":"cold-shower-1","card_id":"cold-shower","statement":"Fewer self-reported days absent from work due to sickness in one trial, with no reduction in days feeling ill","goals":[],"population":"Healthy adults 18-65, no severe comorbidity","comparator":"Normal warm shower","timeframe":"90 days","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27631616/"],"evidence_label":"Research supported","effect_detail":"About 29% fewer self-reported sick-leave days relative to controls. Illness days were similar.","audience_filter":null,"display_scope":"card","source_ids":["27631616"]},{"benefit_id":"meal-order-1","card_id":"meal-order","statement":"Smaller early post-meal glucose rise in some short feeding studies","goals":["metabolic"],"population":"Adults with T2D or prediabetes first; healthy adults","comparator":"Carbohydrate-first, same meal","timeframe":"Single meal, 0-180 min","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35210284/","https://pubmed.ncbi.nlm.nih.gov/42045803/","https://pubmed.ncbi.nlm.nih.gov/41837403/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35210284","42045803","41837403"]},{"benefit_id":"bedtime-list-1","card_id":"bedtime-list","statement":"Faster sleep onset in one sleep-lab trial compared with writing about completed tasks","goals":["sleep"],"population":"Healthy adults aged 18–30","comparator":"five-minute list of recently completed activities","timeframe":"single laboratory night","source_urls":["https://pubmed.ncbi.nlm.nih.gov/29058942/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["29058942"]},{"benefit_id":"kiwi-1","card_id":"kiwi","statement":"More complete spontaneous bowel movements from baseline in adults with constipation","goals":["digestion"],"population":"Adults with functional constipation or IBS-C","comparator":"Change from baseline in active-comparator studies. Superiority over psyllium or prunes was not established.","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36537785/","https://pubmed.ncbi.nlm.nih.gov/34074830/"],"evidence_label":"Research supported","effect_detail":"About 1.5–1.7 additional complete spontaneous bowel movements per week from baseline in the larger trial.","audience_filter":null,"display_scope":"card","source_ids":["36537785","34074830"]},{"benefit_id":"kiwi-2","card_id":"kiwi","statement":"Possible improvement in overall digestive comfort","goals":["digestion"],"population":"Adults with functional constipation or IBS-C","comparator":"Baseline or active comparators in constipation studies; results depend on the questionnaire and domain.","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36537785/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36537785"]},{"benefit_id":"beans-1","card_id":"beans","statement":"Lower LDL relative to a rice comparison in one trial in adults with elevated LDL","goals":["heart"],"population":"Adults with LDL 3.0-5.0 mmol/L (n=73, mean age 48)","comparator":"1 cup white rice daily (crossover); half cup of beans also tested","timeframe":"4 weeks per period","source_urls":["https://pubmed.ncbi.nlm.nih.gov/34642756/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["34642756"]},{"benefit_id":"salt-swap-1","card_id":"salt-swap","statement":"Lower average blood pressure compared with ordinary salt","goals":["heart"],"population":"Adults (21 trials, 31,949 people; effect similar with and without a history of hypertension)","comparator":"Regular salt","timeframe":"Months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35945000/","https://pubmed.ncbi.nlm.nih.gov/41578335/"],"evidence_label":"Strong evidence","effect_detail":"About 4.6 mmHg lower systolic and 1.6 mmHg lower diastolic pressure on average.","audience_filter":null,"display_scope":"card","source_ids":["35945000","41578335"]},{"benefit_id":"salt-swap-2","card_id":"salt-swap","statement":"Fewer strokes in a large trial in older high-risk adults in rural China","goals":["heart"],"population":"Adults >=60 with high BP, or prior stroke, who cook at home","comparator":"Usual salt","timeframe":"4.74 years","source_urls":["https://pubmed.ncbi.nlm.nih.gov/34459569/"],"evidence_label":"Research supported","effect_detail":"About 29 versus 34 strokes per 1,000 person-years in the high-risk trial population.","audience_filter":"high_stroke_risk_trial_population","display_scope":"card","source_ids":["34459569"]},{"benefit_id":"whole-grains-1","card_id":"whole-grains","statement":"Small average reduction in LDL across trials of different whole grains","goals":["heart"],"population":"Adults","comparator":"Comparator diets in randomized whole-grain trials.","timeframe":"During controlled dietary interventions of varying duration.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42743912/","https://pubmed.ncbi.nlm.nih.gov/26269373/"],"evidence_label":"Research supported","effect_detail":"Each additional 48 g/day corresponded to about 0.07 mmol/L lower LDL (95% CI 0.05–0.10 lower).","audience_filter":null,"display_scope":"card","source_ids":["42743912","26269373"]},{"benefit_id":"whole-grains-2","card_id":"whole-grains","statement":"Small average reduction in total cholesterol across randomized trials","goals":["heart"],"population":"Adults","comparator":"Comparator diets in randomized whole-grain trials.","timeframe":"During controlled dietary interventions of varying duration.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42743912/","https://pubmed.ncbi.nlm.nih.gov/26269373/"],"evidence_label":"Strong evidence","effect_detail":"Each additional 48 g/day corresponded to about 0.10 mmol/L lower total cholesterol (95% CI 0.07–0.13 lower).","audience_filter":null,"display_scope":"card","source_ids":["42743912","26269373"]},{"benefit_id":"walk-for-ideas-1","card_id":"walk-for-ideas","statement":"More ideas on divergent-thinking tasks during or just after a walk","goals":["memory"],"population":"Mostly university and college students (1,036 participants); few other adults","comparator":"Sitting","timeframe":"Acute: single walk of about 2 to 20 minutes; effect measured during or immediately after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42127076/","https://pubmed.ncbi.nlm.nih.gov/24749966/"],"evidence_label":"Research supported","effect_detail":"The review found better divergent-thinking scores, with considerable uncertainty about the size. Most participants were students.","audience_filter":null,"display_scope":"card","source_ids":["42127076","24749966"]},{"benefit_id":"water-flosser-1","card_id":"water-flosser","statement":"Less bleeding between teeth in adults with gingivitis compared with brushing alone","goals":[],"population":"Adults with gingivitis (16 RCTs, 1,258); not shown in people with healthy gums","comparator":"Brushing alone","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36562267/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["36562267"]},{"benefit_id":"social-break-1","card_id":"social-break","statement":"One one-week trial found better self-reported wellbeing. Across abstinence studies, effects on related wellbeing measures were mixed.","goals":["mood"],"population":"Adults, mean age 29.6 (online recruitment)","comparator":"Usual social media use","timeframe":"1 week","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35512731/","https://pubmed.ncbi.nlm.nih.gov/40038410/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35512731","40038410"]},{"benefit_id":"toothbrush-1","card_id":"toothbrush","statement":"Slightly more plaque removed in a single brushing compared with a manual brush","goals":[],"population":"Healthy adults in 28 publications","comparator":"Manual toothbrush","timeframe":"Single brushing","source_urls":["https://pubmed.ncbi.nlm.nih.gov/34877772/","https://pubmed.ncbi.nlm.nih.gov/16170978/","https://pubmed.ncbi.nlm.nih.gov/31050195/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["34877772","16170978","31050195"]},{"benefit_id":"screen-cap-1","card_id":"screen-cap","statement":"Lower depressive symptom scores in a three-week trial in healthy students","goals":["mood"],"population":"Healthy students, mean age 22.7 (n=111; 58 intervention, 53 control)","comparator":"Usual smartphone use (no restriction)","timeframe":"3 weeks; follow-up 6 weeks after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39985031/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["39985031"]},{"benefit_id":"screen-cap-2","card_id":"screen-cap","statement":"Lower self-reported insomnia severity in the same trial","goals":["sleep"],"population":"Healthy students, mean age 22.7 (n=111; 58 intervention, 53 control)","comparator":"Usual smartphone use (no restriction)","timeframe":"3 weeks; follow-up 6 weeks after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39985031/"],"evidence_label":"Research supported","effect_detail":"About 2.6 points better on the Insomnia Severity Index after three weeks in the studied students.","audience_filter":null,"display_scope":"card","source_ids":["39985031"]},{"benefit_id":"screen-cap-3","card_id":"screen-cap","statement":"Possible short-term improvement in wellbeing and stress","goals":["mood"],"population":"Healthy students, mean age 22.7 (n=111; 58 intervention, 53 control)","comparator":"Usual smartphone use (no restriction)","timeframe":"3 weeks; follow-up 6 weeks after","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39985031/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["39985031"]},{"benefit_id":"standing-stockings-1","card_id":"standing-stockings","statement":"Less lower-leg swelling during standing work in trials of healthcare workers and hairdressers.","goals":[],"population":"Healthcare workers on six-hour standing shifts and hairdressers exposed to prolonged standing.","comparator":"No stockings","timeframe":"During standing work, with follow-up up to 12 months in the healthcare-worker trial.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/37458579/","https://pubmed.ncbi.nlm.nih.gov/22451457/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["37458579","22451457"]},{"benefit_id":"optimism-1","card_id":"optimism","statement":"Higher short-term self-rated optimism","goals":["mood"],"population":"Adults (age, n not in abstract)","comparator":"Imagining daily activities for the same time","timeframe":"2 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/21450262/","https://pubmed.ncbi.nlm.nih.gov/31545815/","https://pubmed.ncbi.nlm.nih.gov/36724699/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["21450262","31545815","36724699"]},{"benefit_id":"bedtime-phone-1","card_id":"bedtime-phone","statement":"Faster self-reported sleep onset","goals":["sleep"],"population":"Young adults (~21 y) with poor sleep (PSQI>5) and >30 min bedtime phone habit; China; n=38","comparator":"No instruction (usual phone use)","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32040492/"],"evidence_label":"Early evidence","effect_detail":"The groups differed by about ten minutes in their average improvement from baseline. The separate comparison of their final sleep-onset times gave p = 0.049.","audience_filter":null,"display_scope":"card","source_ids":["32040492"]},{"benefit_id":"bedtime-phone-2","card_id":"bedtime-phone","statement":"Better self-reported sleep quality","goals":["sleep"],"population":"Young adults (~21 y) with poor sleep (PSQI>5) and >30 min bedtime phone habit; China; n=38","comparator":"No instruction (usual phone use)","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32040492/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32040492"]},{"benefit_id":"bedtime-phone-3","card_id":"bedtime-phone","statement":"Less pre-sleep arousal","goals":["sleep"],"population":"Young adults (~21 y) with poor sleep (PSQI>5) and >30 min bedtime phone habit; China; n=38","comparator":"No instruction (usual phone use)","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32040492/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32040492"]},{"benefit_id":"blink-1","card_id":"blink","statement":"Less discomfort in short studies of adults with dry eye","goals":[],"population":"Adults with dry eye symptoms (98 and 100 participants in two trials)","comparator":"Artificial tears only (Arita); other blinking regimens (Wolffsohn)","timeframe":"3 days to 2 weeks (+2 weeks after stopping)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40467388/","https://pubmed.ncbi.nlm.nih.gov/32409236/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["40467388","32409236"]},{"benefit_id":"apples-1","card_id":"apples","statement":"Slightly lower LDL in one trial in adults with mildly elevated cholesterol","goals":["heart"],"population":"Mildly hypercholesterolemic adults (n=40; mean age 51)","comparator":"Energy-matched apple control beverage","timeframe":"8 weeks per phase","source_urls":["https://pubmed.ncbi.nlm.nih.gov/31840162/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["31840162"]},{"benefit_id":"work-breaks-1","card_id":"work-breaks","statement":"Less reported discomfort and eyestrain in data-entry workers","goals":[],"population":"Data-entry workers (n=51)","comparator":"Conventional breaks only (Galinsky); reference group with 3-min breaks (Nakphet)","timeframe":"4 weeks (Galinsky); 60 min (Nakphet)","source_urls":["https://pubmed.ncbi.nlm.nih.gov/17514726/","https://pubmed.ncbi.nlm.nih.gov/10877480/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["17514726","10877480"]},{"benefit_id":"hummus-1","card_id":"hummus","statement":"Less hunger and later dessert snacking in a small trial","goals":["metabolic"],"population":"Healthy adults, mean age 26, BMI 24 (n=39)","comparator":"No snack; granola bar snack","timeframe":"6 days per pattern; outcomes measured on day 7","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32488233/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32488233"]},{"benefit_id":"volunteer-1","card_id":"volunteer","statement":"Less self-reported loneliness in one trial of adults aged 59–79","goals":["mood"],"population":"Older adults aged 59 to 79 (n=76)","comparator":"Control group (no volunteering)","timeframe":"24 h, 8 days, 1 week, 1 month","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42054579/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["42054579"]},{"benefit_id":"jumps-1","card_id":"jumps","statement":"Improved femoral-neck bone density across jump-training programs","goals":["movement"],"population":"Adults","comparator":"Control","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/38305252/","https://pubmed.ncbi.nlm.nih.gov/16269526/"],"evidence_label":"Strong evidence","effect_detail":"Pooled programs improved femoral-neck density by about 1.5%. Fracture prevention was untested.","audience_filter":null,"display_scope":"card","source_ids":["38305252","16269526"]},{"benefit_id":"psyllium-1","card_id":"psyllium","statement":"Lower LDL cholesterol across controlled trials","goals":["heart"],"population":"Adults with constipation; raised LDL","comparator":"Control","timeframe":"3+ weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30239559/","https://pubmed.ncbi.nlm.nih.gov/41366295/"],"evidence_label":"Strong evidence","effect_detail":"About 0.33 mmol/L (13 mg/dL) lower LDL in a review of 28 trials.","audience_filter":null,"display_scope":"card","source_ids":["30239559","41366295"]},{"benefit_id":"psyllium-2","card_id":"psyllium","statement":"Improved bowel frequency in adults with constipation","goals":["digestion"],"population":"Adults with constipation; raised LDL","comparator":"Control","timeframe":"4+ weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35816465/","https://pubmed.ncbi.nlm.nih.gov/8824651/"],"evidence_label":"Research supported","effect_detail":"About three more bowel movements weekly, but the estimate ranged from roughly 0.6 to 5.5 and varied widely across trials.","audience_filter":"constipation","display_scope":"card","source_ids":["35816465","8824651"]},{"benefit_id":"retrieval-1","card_id":"retrieval","statement":"Better delayed recall of material practiced across spaced sessions","goals":["memory"],"population":"Medical trainees in the combined-schedule trial. Broader learning studies tested spacing or retrieval separately.","comparator":"Repeated study of the same material on the same schedule in the trainee trial. The spacing review compared spaced and massed retrieval.","timeframe":"Final test about six months after teaching in the example trial.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/19930508/","https://doi.org/10.1007/s10648-020-09572-8"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["19930508","SPACED-2021"]},{"benefit_id":"flight-stockings-1","card_id":"flight-stockings","statement":"Fewer ultrasound-detected symptomless leg clots on flights longer than five hours","goals":[],"population":"Long-haul flyers, especially higher-risk","comparator":"No stockings","timeframe":"Flight >5 h","source_urls":["https://pubmed.ncbi.nlm.nih.gov/33878207/","https://pubmed.ncbi.nlm.nih.gov/11377600/"],"evidence_label":"Strong evidence","effect_detail":"Three screened passengers had a symptomless clot with stockings versus 47 without, across nine trials. The trials could not determine the effect on symptomatic events.","audience_filter":null,"display_scope":"card","source_ids":["33878207","11377600"]},{"benefit_id":"fall-hazards-1","card_id":"fall-hazards","statement":"Fewer falls among higher-risk older adults when home hazards are assessed and addressed","goals":["movement"],"population":"Community-dwelling older adults at higher risk of falls.","comparator":"Usual care or control without targeted home-hazard reduction.","timeframe":"During follow-up in the included trials, commonly around one year.","source_urls":["https://www.cochrane.org/evidence/CD013258_reducing-fall-hazards-within-environment","https://pubmed.ncbi.nlm.nih.gov/34463746/","https://pubmed.ncbi.nlm.nih.gov/10591231/"],"evidence_label":"Strong evidence","effect_detail":"About 38% fewer falls per person-time among higher-risk older adults, rate ratio 0.62 (95% CI 0.56–0.70).","audience_filter":null,"display_scope":"card","source_ids":["FALL","34463746","10591231"]},{"benefit_id":"handwash-1","card_id":"handwash","statement":"Handwashing-promotion programs reduced respiratory infections in some community settings. A smaller review of soap-and-water comparisons found no clear reduction.","goals":[],"population":"Participants in community handwashing-promotion studies in low- and middle-income countries.","comparator":"No handwashing promotion","timeframe":"Trial periods","source_urls":["https://pubmed.ncbi.nlm.nih.gov/37121242/","https://pubmed.ncbi.nlm.nih.gov/34408031/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["37121242","34408031"]},{"benefit_id":"water-premeal-1","card_id":"water-premeal","statement":"Premeal water may modestly increase weight loss over 12 weeks alongside weight-management support. The second trial’s adjusted estimate included no difference.","goals":["metabolic"],"population":"Adults with obesity in primary care and adults aged 55–75 with overweight or obesity on a reduced-calorie diet.","comparator":"Diet alone in one trial and an attention control with weight-management advice in the other.","timeframe":"12 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/19661958/","https://pubmed.ncbi.nlm.nih.gov/26237305/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["19661958","26237305"]},{"benefit_id":"drink-swap-1","card_id":"drink-swap","statement":"Studies have not established a clear weight-loss benefit from replacing sugary drinks with water.","goals":["metabolic"],"population":"Adults with overweight or obesity in water-substitution trials.","comparator":"Usual intake or a comparison program, depending on the trial.","timeframe":"Follow-up varied. The CHOICE trial followed participants for six months.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/38612997/","https://pubmed.ncbi.nlm.nih.gov/22301929/","https://pubmed.ncbi.nlm.nih.gov/35285920/"],"evidence_label":"Early evidence","effect_detail":"The pooled estimate for replacing sugary drinks with water was 0.81 kg lower, with a 95% interval from 1.66 kg lower to 0.03 kg higher.","audience_filter":null,"display_scope":"research_only","source_ids":["38612997","22301929","35285920"]},{"benefit_id":"eat-slowly-1","card_id":"eat-slowly","statement":"Lower intake during some experimental meals","goals":["metabolic"],"population":"Adults participating in experimental meals.","comparator":"Faster eating","timeframe":"Single lab meal","source_urls":["https://pubmed.ncbi.nlm.nih.gov/24847856/","https://pubmed.ncbi.nlm.nih.gov/24388483/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["24847856","24388483"]},{"benefit_id":"three-good-things-1","card_id":"three-good-things","statement":"Participants in one online trial reported greater happiness at later follow-ups after writing three good things each evening for a week.","goals":["mood"],"population":"Adult volunteers in an online positive-psychology trial.","comparator":"Writing about early memories.","timeframe":"Follow-up through six months.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/16045394/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["16045394"]},{"benefit_id":"mindfulness-1","card_id":"mindfulness","statement":"Lower self-reported stress in studied programs","goals":["mood"],"population":"Employees with mild to moderate stress in a digital meditation trial.","comparator":"Waitlist / active control","timeframe":"8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/39808431/","https://pubmed.ncbi.nlm.nih.gov/31237569/","https://pubmed.ncbi.nlm.nih.gov/34962055/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["39808431","31237569","34962055"]},{"benefit_id":"left-side-1","card_id":"left-side","statement":"Fewer nighttime reflux symptoms with a device that encouraged left-side sleep compared with a sham device","goals":["digestion"],"population":"Adults with nocturnal reflux","comparator":"Sham device","timeframe":"2 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35301135/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35301135"]},{"benefit_id":"music-1","card_id":"music","statement":"Better self-rated sleep quality in adults with sleep difficulty","goals":["sleep"],"population":"Adults with insomnia - felt sleep quality","comparator":"No treatment / usual care","timeframe":"3 days-3 months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36000763/","https://pubmed.ncbi.nlm.nih.gov/15660547/","https://pubmed.ncbi.nlm.nih.gov/18426457/","https://pubmed.ncbi.nlm.nih.gov/30676671/"],"evidence_label":"Research supported","effect_detail":"Sleep quality improved by about 2.8 points on the Pittsburgh Sleep Quality Index relative to controls, across 10 trials.","audience_filter":null,"display_scope":"card","source_ids":["36000763","15660547","18426457","30676671"]},{"benefit_id":"smell-training-1","card_id":"smell-training","statement":"Possible improvement on smell tests in people with persistent post-viral smell loss","goals":[],"population":"Adults with persistent post-viral smell loss","comparator":"Varied across the studies in the review.","timeframe":"Varied by training program.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32567798/","https://pubmed.ncbi.nlm.nih.gov/32660334/","https://pubmed.ncbi.nlm.nih.gov/42311058/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["32567798","32660334","42311058"]},{"benefit_id":"prunes-1","card_id":"prunes","statement":"Small studies in adults with constipation found more complete spontaneous bowel movements during prune consumption.","goals":["digestion"],"population":"Chronic constipation; 37 women, 3 men; mean age 38","comparator":"psyllium 11 g twice daily; both provided about 6 g fiber","timeframe":"3 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/21323688/","https://pubmed.ncbi.nlm.nih.gov/34074830/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["21323688","34074830"]},{"benefit_id":"cystitis-1","card_id":"cystitis","statement":"Fewer recurrent cystitis episodes over a year in premenopausal women with low fluid intake and frequent previous episodes","goals":[],"population":"Healthy premenopausal women ≥18, ≥3 clinician-documented symptomatic cystitis episodes in prior year, ≥1 culture-confirmed; no current symptoms; usual TOTAL beverages <1.5 L/day. Trial additionally required 24-hour urine <1.2 L and, after amendment, osmolality ≥500 mOsm/kg.","comparator":"no additional fluids","timeframe":"12 months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30285042/"],"evidence_label":"Research supported","effect_detail":"About 1.5 fewer confirmed episodes per participant over one year compared with usual fluid intake.","audience_filter":null,"display_scope":"card","source_ids":["30285042"]},{"benefit_id":"dash-1","card_id":"dash","statement":"Lower systolic blood pressure versus a typical control diet","goals":["heart"],"population":"Adults SBP <160 and DBP 80–95 mmHg","comparator":"control diet","timeframe":"8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/9099655/","https://pubmed.ncbi.nlm.nih.gov/32330233/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["9099655","32330233"]},{"benefit_id":"dash-2","card_id":"dash","statement":"Lower diastolic blood pressure versus the same control diet","goals":["heart"],"population":"Adults SBP <160 and DBP 80–95 mmHg","comparator":"control diet","timeframe":"8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/9099655/","https://pubmed.ncbi.nlm.nih.gov/32330233/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["9099655","32330233"]},{"benefit_id":"walking-breaks-1","card_id":"walking-breaks","statement":"Lower same-day systolic pressure in tested light walking-break schedules","goals":["heart"],"population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","comparator":"uninterrupted sitting on a separate randomized test day","timeframe":"Across the 8-hour test day","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["36728338"]},{"benefit_id":"walking-breaks-2","card_id":"walking-breaks","statement":"Better self-rated mood over a seated day in tested schedules","goals":["mood"],"population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","comparator":"uninterrupted sitting on a separate randomized test day","timeframe":"Across the 8-hour test day","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/","https://pubmed.ncbi.nlm.nih.gov/27809874/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["36728338","27809874"]},{"benefit_id":"walking-breaks-3","card_id":"walking-breaks","statement":"Less self-reported fatigue during tested light or moderate walking-break schedules","goals":["energy"],"population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","comparator":"uninterrupted sitting on a separate randomized test day","timeframe":"Across the 8-hour test day","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/","https://pubmed.ncbi.nlm.nih.gov/27809874/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["36728338","27809874"]},{"benefit_id":"one-brisk-walk-1","card_id":"one-brisk-walk","statement":"Young adults reported less fatigue after a ten-minute brisk walk than before it, in one small trial","goals":["energy"],"population":"Active college-aged adults; mean 21.3; eligible 18–53","comparator":"Three randomized groups: walking, meditation or sitting. The walking-group follow-up test compared fatigue before and after walking.","timeframe":"immediately after 10-minute bout","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30087839/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["30087839"]},{"benefit_id":"nap-1","card_id":"nap","statement":"Less afternoon sleepiness in a small trial after a short night","goals":["energy"],"population":"Healthy students, mean22.1; previous night restricted to4h, measured3.5h","comparator":"awake reading during corresponding15minutes","timeframe":"30 and120minutes after nap; first assessment30minutes, not proven onset","source_urls":["https://pubmed.ncbi.nlm.nih.gov/11007448/","https://pubmed.ncbi.nlm.nih.gov/16796222/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["11007448","16796222"]},{"benefit_id":"oats-1","card_id":"oats","statement":"Lower LDL cholesterol with at least 3 g daily of oat beta-glucan in controlled trials","goals":["heart"],"population":"Adults with dyslipidemia","comparator":"Control diets without added oat beta-glucan.","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/25411276/","https://pubmed.ncbi.nlm.nih.gov/27724985/","https://pubmed.ncbi.nlm.nih.gov/20660224/","https://pubmed.ncbi.nlm.nih.gov/35631184/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["25411276","27724985","20660224","35631184"]},{"benefit_id":"pelvic-floor-1","card_id":"pelvic-floor","statement":"Improved stress urinary incontinence in women receiving pelvic-floor muscle training","goals":[],"population":"Women with stress urinary incontinence.","comparator":"No treatment or inactive control.","timeframe":"Weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30288727/"],"evidence_label":"Strong evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["30288727"]},{"benefit_id":"handgrip-1","card_id":"handgrip","statement":"Lower resting blood pressure after regular handgrip training","goals":["heart"],"population":"Adults with and without hypertension","comparator":"Non-exercise control","timeframe":"8+ weeks; RCT 4 weeks ambulatory","source_urls":["https://pubmed.ncbi.nlm.nih.gov/41922197/","https://pubmed.ncbi.nlm.nih.gov/28033302/","https://pubmed.ncbi.nlm.nih.gov/34140663/"],"evidence_label":"Research supported","effect_detail":"The pooled estimate was about 5 mmHg lower systolic pressure. Individual trial effects varied substantially.","audience_filter":null,"display_scope":"card","source_ids":["41922197","28033302","34140663"]},{"benefit_id":"tai-chi-1","card_id":"tai-chi","statement":"Fewer repeated falls in community-dwelling older adults compared with stretching","goals":["movement"],"population":"Inactive community adults aged 70–92","comparator":"stretching program","timeframe":"6 months","source_urls":["https://pubmed.ncbi.nlm.nih.gov/15814861/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["15814861"]},{"benefit_id":"neck-strength-1","card_id":"neck-strength","statement":"Less neck and shoulder pain after a therapist-taught progressive exercise program in symptomatic workers","goals":["movement"],"population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","comparator":"weekly general health information","timeframe":"10 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/21177034/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"variant","source_ids":["21177034"]},{"benefit_id":"sleep-extension-1","card_id":"sleep-extension","statement":"Longer objectively measured sleep among habitual short sleepers with overweight","goals":["sleep"],"population":"Adults 21–40, BMI 25–29.9, habitual sleep <6.5 h/night; no sleep apnea or insomnia","comparator":"habitual sleep with study contact","timeframe":"2-week intervention","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35129580/","https://pubmed.ncbi.nlm.nih.gov/34507028/"],"evidence_label":"Research supported","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35129580","34507028"]},{"benefit_id":"sleep-extension-2","card_id":"sleep-extension","statement":"Lower measured energy intake over two weeks in the same group","goals":["metabolic"],"population":"Adults 21–40, BMI 25–29.9, habitual sleep <6.5 h/night; no sleep apnea or insomnia","comparator":"habitual sleep with study contact","timeframe":"2-week intervention","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35129580/"],"evidence_label":"Research supported","effect_detail":"About 270 fewer kcal per day on average than controls over the two-week intervention. Long-term weight change was outside this endpoint.","audience_filter":null,"display_scope":"card","source_ids":["35129580"]},{"benefit_id":"slow-breathing-1","card_id":"slow-breathing","statement":"Small average drop in blood pressure with regular slow breathing","goals":["heart"],"population":"Adults with high or high-normal blood pressure","comparator":"Usual care or control conditions","timeframe":"Weeks of regular practice","source_urls":["https://pubmed.ncbi.nlm.nih.gov/31331557/"],"evidence_label":"Early evidence","effect_detail":"About 5.6 mmHg systolic and 3 mmHg diastolic on average; results varied widely.","audience_filter":null,"display_scope":"card","source_ids":["31331557"]},{"benefit_id":"acupuncture-migraine-1","card_id":"acupuncture-migraine","statement":"Fewer migraine days with a course of acupuncture","goals":[],"population":"Adults with episodic migraine","comparator":"Usual care, sham acupuncture or preventive drugs","timeframe":"At least 8 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27351677/"],"evidence_label":"Research supported","effect_detail":"About 3.5 migraine days a month versus 5 with usual care and 4 with sham; small advantage over sham.","audience_filter":null,"display_scope":"card","source_ids":["27351677"]},{"benefit_id":"weighted-blanket-1","card_id":"weighted-blanket","statement":"Less severe insomnia in adults with insomnia and a mental health condition","goals":["sleep"],"population":"Adults with insomnia and depression, bipolar disorder, anxiety or ADHD","comparator":"A light blanket","timeframe":"4 weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/32536366/"],"evidence_label":"Early evidence","effect_detail":"59% responded versus 5% with a light blanket.","audience_filter":null,"display_scope":"card","source_ids":["32536366"]},{"benefit_id":"stair-walk-energy-1","card_id":"stair-walk-energy","statement":"Felt more energetic right after ten minutes of stair walking","goals":["energy"],"population":"Sleep-deprived young women","comparator":"50 mg caffeine or placebo","timeframe":"Immediately afterward","source_urls":["https://doi.org/10.1016/j.physbeh.2017.03.013"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["PHYSBEH-2017-STAIRS"]},{"benefit_id":"drawing-memory-1","card_id":"drawing-memory","statement":"Better recall of drawn words than written words","goals":["memory"],"population":"University students in laboratory tests","comparator":"Writing the same words","timeframe":"Minutes after learning","source_urls":["https://pubmed.ncbi.nlm.nih.gov/26444654/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["26444654"]},{"benefit_id":"toilet-footstool-1","card_id":"toilet-footstool","statement":"Less straining and less time on the toilet with a footstool","goals":["digestion"],"population":"Healthy adults","comparator":"The same people without the stool","timeframe":"Two weeks each","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30346317/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["30346317"]},{"benefit_id":"abdominal-massage-1","card_id":"abdominal-massage","statement":"Eased constipation symptoms in adults with functional constipation","goals":["digestion"],"population":"Adults with functional chronic constipation","comparator":"Placebo treatment or usual care","timeframe":"About four weeks","source_urls":["https://pubmed.ncbi.nlm.nih.gov/35554601/","https://pubmed.ncbi.nlm.nih.gov/39531948/"],"evidence_label":"Early evidence","effect_detail":null,"audience_filter":null,"display_scope":"card","source_ids":["35554601","39531948"]}],"variants":[{"variant_id":"stairs-1","card_id":"stairs","action":"Three times a day, at least 1 hour apart, climb stairs fast: about 60 steps (about 3 flights) or about 30 seconds all-out (about 6 flights). Do this 3 days a week for 6 weeks.","time":"About 3 bouts x 20-30 s = 1 to 1.5 min of climbing per day on 3 days a week.","population":"Sedentary young adults (Jenkins n=12/arm; Yin n=14 snacks, 15 control)","benefit_ids":["stairs-1"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/30649897/","https://pubmed.ncbi.nlm.nih.gov/38569204/"],"source_ids":["30649897","38569204"]},{"variant_id":"stairs-2","card_id":"stairs","action":"One session: 3 minutes easy warm-up, then climb stairs fast for 20 seconds, recover 2 minutes, repeat 3 times. 5 days a week for 4 weeks.","time":"3 min warm-up + 3 x 20 s climbing (1 min) + 2 x 2 min recoveries (4 min) = 8 min; with a third recovery, about 10 min per day.","population":"Inactive young men with obesity (n=12 vs 12 control, age ~26, BMI ~27)","benefit_ids":["stairs-1"],"schedule_evidence":"This exact schedule was studied in one small trial in young men. Other stair schedules help support the broader fitness finding.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/40087042/"],"source_ids":["40087042"]},{"variant_id":"walking-breaks-1","card_id":"walking-breaks","action":"Across an eight-hour sitting day, take a five-minute light walk every 30 minutes. The experiment used a level treadmill at 2 mph (3.2 km/h); a flat-route walk is a practical adaptation.","time":"Repeated throughout 8 hours. Budget up to 80 minutes walking plus transitions; this is a scheduling allowance, not a verified trial bout count.","population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","benefit_ids":["walking-breaks-1","walking-breaks-2","walking-breaks-3"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/"],"source_ids":["36728338"]},{"variant_id":"walking-breaks-2","card_id":"walking-breaks","action":"Across an eight-hour sitting day, take a five-minute light walk every 60 minutes. The study used a level treadmill at 2 mph (3.2 km/h); ordinary flat-route walking is an adaptation.","time":"Repeated throughout 8 hours. Budget up to 40 minutes walking plus transitions; scheduling allowance, not a verified trial bout count.","population":"Sedentary adults ≥ 45; mean 57; 2 taking antihypertensives","benefit_ids":["walking-breaks-1","walking-breaks-2","walking-breaks-3"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/36728338/"],"source_ids":["36728338"]},{"variant_id":"walking-breaks-3","card_id":"walking-breaks","action":"Walk for five minutes at moderate effort, once each hour for six bouts. Aim for the studied perceived effort of 12–13 on the 6–20 Borg scale: somewhat hard. The study used individualized treadmill speed/incline.","time":"30 minutes of walking across a 6-hour day, plus transitions. One experimental day per condition.","population":"Healthy sedentary adults 25–50, BMI 18.5–29.9; 21 women/9 men","benefit_ids":["walking-breaks-2","walking-breaks-3"],"schedule_evidence":"Studied protocol. See source record.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27809874/"],"source_ids":["27809874"]},{"variant_id":"walk-after-meals-1","card_id":"walk-after-meals","action":"One practical option is a two-minute easy walk every 30 minutes for three hours after a meal. The trial tested that interval for five hours.","time":"Six two-minute walks total 12 minutes in the three-hour example.","population":"Adults interrupting prolonged sitting after a meal.","benefit_ids":["walk-after-meals-1","walk-after-meals-2"],"schedule_evidence":"Two minutes every 30 minutes was tested for five hours after a standardized drink in sedentary men. Three hours is a shorter app example.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/42627002/"],"source_ids":["42627002"]},{"variant_id":"walk-after-meals-2","card_id":"walk-after-meals","action":"Walk ten minutes after each main meal.","time":"Three ten-minute walks per day in the trial.","population":"Adults with type 2 diabetes for whom walking is suitable.","benefit_ids":["walk-after-meals-3"],"schedule_evidence":"Tested against one 30-minute daily walk without specified meal timing.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/27747394/"],"audience_filter":"type_2_diabetes","source_ids":["27747394"]},{"variant_id":"neck-strength-1","card_id":"neck-strength","action":"Tested package: initially therapist-taught lateral raises with elastic tubing, one slow set up to fatigue or 2 minutes, 5 workdays/week for 10 weeks; resistance progressed using a manual. Do not substitute an arbitrary band routine.","time":"","population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","benefit_ids":["neck-strength-1"],"schedule_evidence":"Studied with initial therapist instruction and a progression plan.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/25574172/","https://pubmed.ncbi.nlm.nih.gov/21177034/"],"source_ids":["25574172","21177034"]},{"variant_id":"neck-strength-2","card_id":"neck-strength","action":"Tested package: initially therapist-taught lateral raises, 5–6 sets of 8–12 repetitions, new sets about every 2 minutes, 12 minutes/session, 5 workdays/week for 10 weeks; manual-guided resistance progression.","time":"","population":"Workers ≥ 30 h/week with frequent neck/shoulder pain; 174 women, 24 men","benefit_ids":["neck-strength-1"],"schedule_evidence":"Studied with initial therapist instruction and a progression plan.","source_urls":["https://pubmed.ncbi.nlm.nih.gov/25574172/","https://pubmed.ncbi.nlm.nih.gov/21177034/"],"source_ids":["25574172","21177034"]}],"research_sources":[{"source_id":"10591231","title":"Home visits by an occupational therapist for assessment and modification of environmental hazards: a randomized trial of falls prevention.","url":"https://pubmed.ncbi.nlm.nih.gov/10591231/","year":"1999","role":"Controlled trial","what_it_shows":"An occupational therapist assessed and helped modify homes. The benefit was concentrated among older adults who had previously fallen.","authors":"Cumming RG, Thomas M, Szonyi G, Salkeld G, O'Neill E, Westbury C, Frampton G.","doi":"10.1111/j.1532-5415.1999.tb01556.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"10877480","title":"A field study of supplementary rest breaks for data-entry operators.","url":"https://pubmed.ncbi.nlm.nih.gov/10877480/","year":"2000","role":"Direct occupational result","what_it_shows":"Data-entry operators reported smaller increases in discomfort and eyestrain during periods with four additional five-minute breaks. Data-entry performance was maintained.","authors":"Galinsky TL, Swanson NG, Sauter SL, Hurrell JJ, Schleifer LM.","doi":"10.1080/001401300184297","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"11007448","title":"Maintenance of alertness and performance by a brief nap after lunch under prior sleep deficit.","url":"https://pubmed.ncbi.nlm.nih.gov/11007448/","year":"2000","role":"Direct, nap opportunity","what_it_shows":"Twelve students after a restricted night were less sleepy at two afternoon assessments when allowed a 15-minute post-lunch nap than when kept awake. They slept an average of 10.2 minutes.","authors":"Takahashi M, Arito H.","doi":"10.1093/sleep/23.6.1h","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"12221048","title":"Dose response of almonds on coronary heart disease risk factors: blood lipids, oxidized low-density lipoproteins, lipoprotein(a), homocysteine, and pulmonary nitric oxide: a randomized, controlled, crossover trial.","url":"https://pubmed.ncbi.nlm.nih.gov/12221048/","year":"2002","role":"Direct LDL trial","what_it_shows":"Whole almonds used as snacks lowered LDL in adults with elevated cholesterol in a crossover comparison with control snacks. The tested amounts differed, so this trial does not fix a universal serving.","authors":"Jenkins DJ, Kendall CW, Marchie A, Parker TL, Connelly PW, Qian W, Haight JS, Faulkner D, Vidgen E, Lapsley KG, Spiller GA.","doi":"10.1161/01.cir.0000028421.91733.20","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"15660547","title":"Music improves sleep quality in older adults.","url":"https://pubmed.ncbi.nlm.nih.gov/15660547/","year":"2005","role":"Direct primary example","what_it_shows":"Older adults listening to soothing bedtime music reported better sleep quality over the intervention period than controls. Perceived sleep quality was the relevant endpoint.","authors":"Lai HL, Good M.","doi":"10.1111/j.1365-2648.2004.03281.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"15814861","title":"Tai Chi and fall reductions in older adults: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/15814861/","year":"2005","role":"Controlled trial","what_it_shows":"Older adults in a supervised tai chi program had fewer repeated falls compared with stretching over six months.","authors":"Li F, Harmer P, Fisher KJ, McAuley E, Chaumeton N, Eckstrom E, Wilson NL.","doi":"10.1093/gerona/60.2.187","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"16045394","title":"Positive psychology progress: empirical validation of interventions.","url":"https://pubmed.ncbi.nlm.nih.gov/16045394/","year":"2005","role":"Direct, specific exercise","what_it_shows":"The full report describes a week of writing three things that went well and why. Participants reported greater happiness at later follow-ups than those writing about early memories. This is the link for the exact exercise.","authors":"Seligman ME, Steen TA, Park N, Peterson C.","doi":"10.1037/0003-066x.60.5.410","review_basis":"Abstract and original paper, three-good-things exercise","publication_type":"Primary study"},{"source_id":"16170978","title":"Comparative efficacy of a new battery-powered toothbrush and a commercially available manual toothbrush on the removal of established supragingival plaque: a single-use crossover study in adults.","url":"https://pubmed.ncbi.nlm.nih.gov/16170978/","year":"2005","role":"Controlled trial","what_it_shows":"In a single-use crossover comparison, one battery-powered brush removed more plaque than a manual brush. The finding concerns the tested models.","authors":"Singh S, Rustogi KN, Chaknis P, Petrone ME, DeVizio W, Proskin HM.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"16269526","title":"Effect of low-repetition jump training on bone mineral density in young women.","url":"https://pubmed.ncbi.nlm.nih.gov/16269526/","year":"2006","role":"Direct, one specific regimen","what_it_shows":"In young women, femoral-neck density rose from baseline after six months of ten maximal jumps three times weekly. The pooled estimate on the card comes from the review of multiple programs.","authors":"Kato T, Terashima T, Yamashita T, Hatanaka Y, Honda A, Umemura Y.","doi":"10.1152/japplphysiol.00666.2005","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"16719566","title":"Distributed practice in verbal recall tasks: A review and quantitative synthesis.","url":"https://pubmed.ncbi.nlm.nih.gov/16719566/","year":"2006","role":"One component, spacing","what_it_shows":"Spacing learning episodes improved later retention compared with massed practice. Effective intervals depended on how much later learners were tested. This paper does not establish the feedback and self-testing schedule.","authors":"Cepeda NJ, Pashler H, Vul E, Wixted JT, Rohrer D.","doi":"10.1037/0033-2909.132.3.354","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"16796222","title":"A brief afternoon nap following nocturnal sleep restriction: which nap duration is most recuperative?","url":"https://pubmed.ncbi.nlm.nih.gov/16796222/","year":"2006","role":"Related duration measure","what_it_shows":"After restricted sleep, ten minutes of actual nap sleep improved immediate alertness in a small lab trial. Five, 20 and 30 minutes had different effects. The 15-minute time allowance is supported by the other paper.","authors":"Brooks A, Lack L.","doi":"10.1093/sleep/29.6.831","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"17275896","title":"The effect of walking on fitness, fatness and resting blood pressure: a meta-analysis of randomised, controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/17275896/","year":"2007","role":"Pooled research","what_it_shows":"Controlled trials in previously sedentary adults measured gains in aerobic fitness after regular walking. This supports the fitness benefit separately from blood pressure.","authors":"Murphy MH, Nevill AM, Murtagh EM, Holder RL.","doi":"10.1016/j.ypmed.2006.12.008","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"17514726","title":"Supplementary breaks and stretching exercises for data entry operators: a follow-up field study.","url":"https://pubmed.ncbi.nlm.nih.gov/17514726/","year":"2007","role":"Controlled trial","what_it_shows":"Data-entry workers reported less discomfort and eyestrain when four five-minute breaks were added to their usual breaks.","authors":"Galinsky T, Swanson N, Sauter S, Dunkin R, Hurrell J, Schleifer L.","doi":"10.1002/ajim.20472","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"18426457","title":"Music improves sleep quality in students.","url":"https://pubmed.ncbi.nlm.nih.gov/18426457/","year":"2008","role":"Direct primary example","what_it_shows":"Young adults with sleep complaints who listened to 45 minutes of relaxing classical music at bedtime for three weeks reported improved sleep quality on a questionnaire.","authors":"Harmat L, Takács J, Bódizs R, Bódizs R.","doi":"10.1111/j.1365-2648.2008.04602.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"19661958","title":"Water consumption increases weight loss during a hypocaloric diet intervention in middle-aged and older adults.","url":"https://pubmed.ncbi.nlm.nih.gov/19661958/","year":"2010","role":"Direct, combined program","what_it_shows":"Forty-eight adults aged 55–75 on a reduced-calorie diet were assigned to water before meals or diet alone. Weight loss over 12 weeks was about 2 kg greater with 500 mL water before each main meal.","authors":"Dennis EA, Dengo AL, Comber DL, Flack KD, Savla J, Davy KP, Davy BM.","doi":"10.1038/oby.2009.235","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"19930508","title":"Repeated testing improves long-term retention relative to repeated study: a randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/19930508/","year":"2009","role":"Direct combined example","what_it_shows":"Forty trainees completed repeated testing with feedback versus repeated study. The first session was immediate and two further sessions were roughly two weeks apart. Six-month scores averaged 39% versus 26% on the studied material.","authors":"Larsen DP, Butler AC, Roediger HL.","doi":"10.1111/j.1365-2923.2009.03518.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"20660224","title":"Physicochemical properties of oat β-glucan influence its ability to reduce serum LDL cholesterol in humans: a randomized clinical trial.","url":"https://pubmed.ncbi.nlm.nih.gov/20660224/","year":"2010","role":"Direct, product-specific result","what_it_shows":"Cereals providing 3 g daily of high- or medium-molecular-weight oat beta-glucan lowered LDL by about 5%. The low-molecular-weight preparation was less effective.","authors":"Wolever TM, Tosh SM, Gibbs AL, Brand-Miller J, Duncan AM, Hart V, Lamarche B, Thomson BA, Duss R, Wood PJ.","doi":"10.3945/ajcn.2010.29174","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21177034","title":"Effectiveness of small daily amounts of progressive resistance training for frequent neck/shoulder pain: randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/21177034/","year":"2011","role":"Controlled trial","what_it_shows":"Symptomatic workers received taught progressive band exercises for two or twelve minutes on workdays. Both groups reported less neck or shoulder pain than controls.","authors":"Andersen LL, Saervoll CA, Mortensen OS, Poulsen OM, Hannerz H, Zebis MK.","doi":"10.1016/j.pain.2010.11.016","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21323688","title":"Randomised clinical trial: dried plums (prunes) vs. psyllium for constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/21323688/","year":"2011","role":"Direct exact schedule","what_it_shows":"Forty adults with constipation crossed over between dried plums and psyllium. Fifty grams of dried plums twice daily for three weeks improved complete spontaneous bowel movements and stool consistency relative to psyllium.","authors":"Attaluri A, Donahoe R, Valestin J, Brown K, Rao SS.","doi":"10.1111/j.1365-2036.2011.04594.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21450262","title":"Become more optimistic by imagining a best possible self: effects of a two week intervention.","url":"https://pubmed.ncbi.nlm.nih.gov/21450262/","year":"2011","role":"Direct, tested schedule","what_it_shows":"Five minutes daily of imagining one’s best possible self increased self-rated optimism relative to imagining ordinary daily activities, both after one session and over two weeks.","authors":"Meevissen YM, Peters ML, Alberts HJ.","doi":"10.1016/j.jbtep.2011.02.012","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"22301929","title":"Replacing caloric beverages with water or diet beverages for weight loss in adults: main results of the Choose Healthy Options Consciously Everyday (CHOICE) randomized clinical trial.","url":"https://pubmed.ncbi.nlm.nih.gov/22301929/","year":"2012","role":"Inconclusive water-specific result","what_it_shows":"At six months mean weight loss in the water group did not clearly exceed the attention control. A separate positive analysis combined water and diet drinks. It cannot establish the effect of water alone.","authors":"Tate DF, Turner-McGrievy G, Lyons E, Stevens J, Erickson K, Polzien K, Diamond M, Wang X, Popkin B.","doi":"10.3945/ajcn.111.026278","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"22374636","title":"Breaking up prolonged sitting reduces postprandial glucose and insulin responses.","url":"https://pubmed.ncbi.nlm.nih.gov/22374636/","year":"2012","role":"Direct result, different timing","what_it_shows":"Nineteen adults with overweight or obesity had lower five-hour glucose and insulin responses with two-minute walks every 20 minutes than with uninterrupted sitting. Use for the benefit and the 20-minute interval.","authors":"Dunstan DW, Kingwell BA, Larsen R, Healy GN, Cerin E, Hamilton MT, Shaw JE, Bertovic DA, Zimmet PZ, Salmon J, Owen N.","doi":"10.2337/dc11-1931","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"23732711","title":"Sunscreen and prevention of skin aging: a randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","year":"2013","role":"Direct multi-year result","what_it_shows":"Australian adults assigned daily sunscreen showed less progression of skin aging at 4.5 years than those using it at their discretion. Assessors graded changes without knowing treatment assignment.","authors":"Hughes MC, Williams GM, Baker P, Green AC.","doi":"10.7326/0003-4819-158-11-201306040-00002","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"23929687","title":"Olfactory training is helpful in postinfectious olfactory loss: a randomized, controlled, multicenter study.","url":"https://pubmed.ncbi.nlm.nih.gov/23929687/","year":"2014","role":"Different comparison and duration","what_it_shows":"People with postinfectious smell loss trained with stronger or weaker odors for 18 weeks. Improvement on testing was more common in the higher-concentration arm. Both groups trained, limiting inference about training versus usual care.","authors":"Damm M, Pikart LK, Reimann H, Burkert S, Göktas Ö, Haxel B, Frey S, Charalampakis I, Beule A, Renner B, Hummel T, Hüttenbrink KB.","doi":"10.1002/lary.24340","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"24388483","title":"Slower eating speed lowers energy intake in normal-weight but not overweight/obese subjects.","url":"https://pubmed.ncbi.nlm.nih.gov/24388483/","year":"2014","role":"Controlled trial","what_it_shows":"A fast-versus-slow eating comparison found lower intake in the normal-weight subgroup. The group-by-weight interaction was not significant.","authors":"Shah M, Copeland J, Dart L, Adams-Huet B, James A, Rhea D.","doi":"10.1016/j.jand.2013.11.002","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"24847856","title":"A systematic review and meta-analysis examining the effect of eating rate on energy intake and hunger.","url":"https://pubmed.ncbi.nlm.nih.gov/24847856/","year":"2014","role":"Direct pooled result","what_it_shows":"Experimental meals consumed more slowly were associated with lower intake on average than faster meals. The designs and methods for changing eating rate varied.","authors":"Robinson E, Almiron-Roig E, Rutters F, de Graaf C, Forde CG, Tudur Smith C, Nolan SJ, Jebb SA.","doi":"10.3945/ajcn.113.081745","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"25150680","title":"The effect of testing versus restudy on retention: a meta-analytic review of the testing effect.","url":"https://pubmed.ncbi.nlm.nih.gov/25150680/","year":"2014","role":"One component, retrieval","what_it_shows":"Pooling testing-versus-restudy comparisons favored retrieval for later recall. This supports self-testing as an ingredient. The exact two-week spacing and feedback example comes from the trainee trial.","authors":"Rowland CA.","doi":"10.1037/a0037559","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"25411276","title":"Cholesterol-lowering effects of oat β-glucan: a meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/25411276/","year":"2014","role":"Pooled research","what_it_shows":"Controlled trials using at least 3 g/day of oat beta-glucan found lower LDL compared with control diets. The active amount refers specifically to oat beta-glucan.","authors":"Whitehead A, Beck EJ, Tosh S, Wolever TM.","doi":"10.3945/ajcn.114.086108","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"27631616","title":"The Effect of Cold Showering on Health and Work: A Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/27631616/","year":"2016","role":"Direct, pooled durations","what_it_shows":"Sick-leave days were 29% lower across groups assigned 30–90 seconds of cold water at the end of showers. Self-reported illness days were comparable. The 29% was not estimated specifically for 30 seconds.","authors":"Buijze GA, Sierevelt IN, van der Heijden BC, Dijkgraaf MG, Frings-Dresen MH.","doi":"10.1371/journal.pone.0161749","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"27724985","title":"The effect of oat β-glucan on LDL-cholesterol, non-HDL-cholesterol and apoB for CVD risk reduction: a systematic review and meta-analysis of randomised-controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/27724985/","year":"2016","role":"Pooled research","what_it_shows":"A second oat beta-glucan synthesis reported lower LDL across 58 trials. The two syntheses may include many of the same trials.","authors":"Ho HV, Sievenpiper JL, Zurbau A, Blanco Mejia S, Jovanovski E, Au-Yeung F, Jenkins AL, Vuksan V.","doi":"10.1017/s000711451600341x","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"27747394","title":"Advice to walk after meals is more effective for lowering postprandial glycaemia in type 2 diabetes mellitus than advice that does not specify timing: a randomised crossover study.","url":"https://pubmed.ncbi.nlm.nih.gov/27747394/","year":"2016","role":"Direct, diabetes variant","what_it_shows":"Adults with type 2 diabetes had about 12% less three-hour post-meal glucose exposure with ten minutes of walking after each main meal than with one untimed daily walk. This comparison supplies no insulin estimate.","authors":"Reynolds AN, Mann JI, Williams S, Venn BJ.","doi":"10.1007/s00125-016-4085-2","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"27809874","title":"Effect of frequent interruptions of prolonged sitting on self-perceived levels of energy, mood, food cravings and cognitive function.","url":"https://pubmed.ncbi.nlm.nih.gov/27809874/","year":"2016","role":"Direct moderate-walk schedule","what_it_shows":"Thirty sedentary adults completed uninterrupted sitting and two activity conditions. Six hourly five-minute moderate walks improved self-rated mood and reduced fatigue compared with sitting. A morning half-hour walk did not show those same results.","authors":"Bergouignan A, Legget KT, De Jong N, Kealey E, Nikolovski J, Groppel JL, Jordan C, O'Day R, Hill JO, Bessesen DH.","doi":"10.1186/s12966-016-0437-z","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"28033302","title":"The efficacy of isometric resistance training utilizing handgrip exercise for blood pressure management: A randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/28033302/","year":"2016","role":"Controlled trial","what_it_shows":"Eight weeks of handgrip training at 30% maximum was compared with lower intensity. Systolic pressure fell within the higher-intensity group; its diastolic change was not significant.","authors":"Carlson DJ, Inder J, Palanisamy SKA, McFarlane JR, Dieberg G, Smart NA.","doi":"10.1097/md.0000000000005791","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"29058942","title":"The effects of bedtime writing on difficulty falling asleep: A polysomnographic study comparing to-do lists and completed activity lists.","url":"https://pubmed.ncbi.nlm.nih.gov/29058942/","year":"2018","role":"Direct, one-night comparison","what_it_shows":"Among 57 young adults, writing upcoming tasks for five minutes before bed led to faster objectively measured sleep onset than writing completed tasks. The trial had no group who did neither.","authors":"Scullin MK, Krueger ML, Ballard HK, Pruett N, Bliwise DL.","doi":"10.1037/xge0000374","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30087839","title":"Experimental effects of brief, single bouts of walking and meditation on mood profile in young adults.","url":"https://pubmed.ncbi.nlm.nih.gov/30087839/","year":"2018","role":"Controlled trial","what_it_shows":"After a ten-minute brisk walk, young adults reported less fatigue than before. The study reported an overall group-by-time interaction and within-group changes.","authors":"Edwards MK, Loprinzi PD.","doi":"10.15171/hpp.2018.23","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30208396","title":"Effectiveness of a Therapeutic Tai Ji Quan Intervention vs a Multimodal Exercise Intervention to Prevent Falls Among Older Adults at High Risk of Falling: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/30208396/","year":"2018","role":"Related fall endpoint","what_it_shows":"Among 670 older adults at increased fall risk, twice-weekly therapeutic tai ji quan produced fewer falls than stretching over 24 weeks. Its primary endpoint counted all falls. Cite the earlier trial specifically for repeat falling.","authors":"Li F, Harmer P, Fitzgerald K, Eckstrom E, Akers L, Chou LS, Pidgeon D, Voit J, Winters-Stone K.","doi":"10.1001/jamainternmed.2018.3915","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30239559","title":"Effect of psyllium (Plantago ovata) fiber on LDL cholesterol and alternative lipid targets, non-HDL cholesterol and apolipoprotein B: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/30239559/","year":"2018","role":"Direct LDL result","what_it_shows":"Across 28 controlled trials, a median daily psyllium intake of about 10.2 g lowered LDL by 0.33 mmol/L on average. This is the lipid evidence on this two-benefit card.","authors":"Jovanovski E, Yashpal S, Komishon A, Zurbau A, Blanco Mejia S, Ho HVT, Li D, Sievenpiper J, Duvnjak L, Vuksan V.","doi":"10.1093/ajcn/nqy115","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"30285042","title":"Effect of Increased Daily Water Intake in Premenopausal Women With Recurrent Urinary Tract Infections: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/30285042/","year":"2018","role":"Direct prevention trial","what_it_shows":"Among 140 premenopausal women with recurrent cystitis and low fluid intake, adding 1.5 L of water daily resulted in 1.7 versus 3.2 episodes on average over a year. The study concerned prevention.","authors":"Hooton TM, Vecchio M, Iroz A, Tack I, Dornic Q, Seksek I, Lotan Y.","doi":"10.1001/jamainternmed.2018.4204","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30288727","title":"Pelvic floor muscle training versus no treatment, or inactive control treatments, for urinary incontinence in women.","url":"https://pubmed.ncbi.nlm.nih.gov/30288727/","year":"2018","role":"Pooled research","what_it_shows":"A Cochrane review compared pelvic-floor training with inactive controls and found symptom improvement in women with stress incontinence.","authors":"Dumoulin C, Cacciari LP, Hay-Smith EJC.","doi":"10.1002/14651858.cd005654.pub4","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"30649897","title":"Do stair climbing exercise \"snacks\" improve cardiorespiratory fitness?","url":"https://pubmed.ncbi.nlm.nih.gov/30649897/","year":"2019","role":"Tested schedule","what_it_shows":"Inactive young adults climbed 60 stairs three times daily, separated by one to four hours. Fitness improved after six weeks.","authors":"Jenkins EM, Nairn LN, Skelly LE, Little JP, Gibala MJ.","doi":"10.1139/apnm-2018-0675","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"31102877","title":"Before-bedtime passive body heating by warm shower or bath to improve sleep: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/31102877/","year":"2019","role":"Pooled research","what_it_shows":"This review found shorter sleep-onset time after appropriately timed warm bathing or showering. Included studies varied in their designs.","authors":"Haghayegh S, Khoshnevis S, Smolensky MH, Diller KR, Castriotta RJ.","doi":"10.1016/j.smrv.2019.04.008","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31237569","title":"Efficacy of the Mindfulness Meditation Mobile App \"Calm\" to Reduce Stress Among College Students: Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/31237569/","year":"2019","role":"Direct, student sample","what_it_shows":"Stressed college students assigned to an app-based mindfulness program reported lower perceived stress than a wait-list group. This extends the finding to another study population.","authors":"Huberty J, Green J, Glissmann C, Larkey L, Puzia M, Lee C.","doi":"10.2196/14273","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"31545815","title":"Effects of the Best Possible Self intervention: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/31545815/","year":"2019","role":"Direct pooled result","what_it_shows":"Across different versions of the best-possible-self exercise, participants showed higher optimism on average than comparison groups. The pooled estimate spans different practice formats.","authors":"Carrillo A, Rubio-Aparicio M, Molinari G, Enrique Á, Sánchez-Meca J, Baños RM.","doi":"10.1371/journal.pone.0222386","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31840162","title":"Two apples a day lower serum cholesterol and improve cardiometabolic biomarkers in mildly hypercholesterolemic adults: a randomized, controlled, crossover trial.","url":"https://pubmed.ncbi.nlm.nih.gov/31840162/","year":"2020","role":"Direct, matched drink","what_it_shows":"Two whole apples daily resulted in modestly lower LDL than a matched apple drink after eight weeks in a small crossover trial of adults with mildly elevated cholesterol.","authors":"Koutsos A, Riccadonna S, Ulaszewska MM, Franceschi P, Trošt K, Galvin A, Braune T, Fava F, Perenzoni D, Mattivi F, Tuohy KM, Lovegrove JA.","doi":"10.1093/ajcn/nqz282","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32040492","title":"Effect of restricting bedtime mobile phone use on sleep, arousal, mood, and working memory: A randomized pilot trial.","url":"https://pubmed.ncbi.nlm.nih.gov/32040492/","year":"2020","role":"Direct, self-reported outcomes","what_it_shows":"In 38 young adults a reinforced bedtime phone restriction improved reported sleep onset, sleep quality and bedtime arousal. The groups’ average changes in onset differed by about ten minutes. The paper’s p = 0.049 is the end-of-study group comparison.","authors":"He JW, Tu ZH, Xiao L, Su T, Tang YX.","doi":"10.1371/journal.pone.0228756","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Primary study"},{"source_id":"32330233","title":"Dietary Approaches to Stop Hypertension (DASH) Diet and Blood Pressure Reduction in Adults with and without Hypertension: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/32330233/","year":"2020","role":"Pooled research","what_it_shows":"Randomized trials of the DASH pattern found lower systolic and diastolic pressure. Sodium intake and other trial conditions varied.","authors":"Filippou CD, Tsioufis CP, Thomopoulos CG, Mihas CC, Dimitriadis KS, Sotiropoulou LI, Chrysochoou CA, Nihoyannopoulos PI, Tousoulis DM.","doi":"10.1093/advances/nmaa041","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"32409236","title":"Therapeutic benefits of blinking exercises in dry eye disease.","url":"https://pubmed.ncbi.nlm.nih.gov/32409236/","year":"2021","role":"Related schedule","what_it_shows":"In a four-week before-and-after program, dry-eye symptoms improved. It used a different blink schedule and lacked a randomized no-exercise control.","authors":"Kim AD, Muntz A, Lee J, Wang MTM, Craig JP.","doi":"10.1016/j.clae.2020.04.014","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32488233","title":"An Afternoon Hummus Snack Affects Diet Quality, Appetite, and Glycemic Control in Healthy Adults.","url":"https://pubmed.ncbi.nlm.nih.gov/32488233/","year":"2020","role":"Direct, specified snack","what_it_shows":"Compared with no snack, hummus with pretzels reduced afternoon hunger in 39 healthy adults. Later dessert snacking was about 20% lower than after either no snack or granola bars. The measurement followed six days on each pattern.","authors":"Reister EJ, Leidy HJ.","doi":"10.1093/jn/nxaa139","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32567798","title":"Treatment of post-viral olfactory dysfunction: an evidence-based review with recommendations.","url":"https://pubmed.ncbi.nlm.nih.gov/32567798/","year":"2020","role":"Direct review, varied protocols","what_it_shows":"An evidence review recommends repeated odor training for postviral smell loss based on changes in measured olfactory function. Protocols and odor sets differed across the studies.","authors":"Hura N, Xie DX, Choby GW, Schlosser RJ, Orlov CP, Seal SM, Rowan NR.","doi":"10.1002/alr.22624","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"33630309","title":"Walking for hypertension.","url":"https://pubmed.ncbi.nlm.nih.gov/33630309/","year":"2021","role":"Pooled research","what_it_shows":"Walking programs lowered average systolic pressure in adults. The review judged the diastolic result less certain and used a range of schedules.","authors":"Lee LL, Mulvaney CA, Wong YKY, Chan ES, Watson MC, Lin HH.","doi":"10.1002/14651858.cd008823.pub2","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"33878207","title":"Compression stockings for preventing deep vein thrombosis in airline passengers.","url":"https://pubmed.ncbi.nlm.nih.gov/33878207/","year":"2021","role":"Pooled research","what_it_shows":"Flight trials found fewer symptomless leg clots on screening with compression stockings. They could not estimate protection against symptomatic events.","authors":"Clarke MJ, Broderick C, Hopewell S, Juszczak E, Eisinga A.","doi":"10.1002/14651858.cd004002.pub4","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34074830","title":"Exploratory Comparative Effectiveness Trial of Green Kiwifruit, Psyllium, or Prunes in US Patients With Chronic Constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/34074830/","year":"2021","role":"Direct for bowel frequency","what_it_shows":"In the US comparison all three groups improved in bowel frequency from baseline and responder rates were similar. In the kiwi group bloating and straining also improved. Those symptom outcomes are narrower than overall digestive comfort.","authors":"Chey SW, Chey WD, Jackson K, Eswaran S.","doi":"10.14309/ajg.0000000000001149","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34459569","title":"Effect of Salt Substitution on Cardiovascular Events and Death.","url":"https://pubmed.ncbi.nlm.nih.gov/34459569/","year":"2021","role":"Direct, high-risk population","what_it_shows":"With potassium-enriched salt there were about 29 versus 34 strokes per 1,000 person-years in rural Chinese participants with a prior stroke or who were at least 60 with hypertension. Follow-up averaged 4.74 years.","authors":"Neal B, Wu Y, Feng X, Zhang R, Zhang Y, Shi J, Zhang J, Tian M, Huang L, Li Z, Yu Y, Zhao Y, Zhou B, Sun J, Liu Y, Yin X, Hao Z, Yu J, Li KC, Zhang X, Duan P, Wang F, Ma B, Shi W, Di Tanna GL, Stepien S, Shan S, Pearson SA, Li N, Yan LL, Labarthe D, Elliott P.","doi":"10.1056/nejmoa2105675","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34463746","title":"Home Hazard Removal to Reduce Falls Among Community-Dwelling Older Adults: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/34463746/","year":"2021","role":"Secondary result only","what_it_shows":"A home-hazard intervention lowered the rate of falls in a secondary analysis. The primary measure, time to first fall, did not differ clearly. Attach only to the fall-rate interpretation.","authors":"Stark S, Keglovits M, Somerville E, Hu YL, Barker A, Sykora D, Yan Y.","doi":"10.1001/jamanetworkopen.2021.22044","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34507028","title":"Behavioral interventions to extend sleep duration: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/34507028/","year":"2021","role":"Broader research","what_it_shows":"Sleep-extension interventions increased sleep duration across populations, with substantial variation. This review does not establish lower energy intake.","authors":"Baron KG, Duffecy J, Reutrakul S, Levenson JC, McFarland MM, Lee S, Qeadan F.","doi":"10.1016/j.smrv.2021.101532","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34642756","title":"Canned Beans Decrease Serum Total and LDL Cholesterol in Adults with Elevated LDL Cholesterol in a 4-wk Multicenter, Randomized, Crossover Study.","url":"https://pubmed.ncbi.nlm.nih.gov/34642756/","year":"2021","role":"Direct comparison","what_it_shows":"One cup of beans daily for four weeks produced a lower LDL than white rice. Half a cup did not clearly differ from rice. The trial also found no clear difference between the two portions.","authors":"Doma KM, Dolinar KF, Dan Ramdath D, Wolever TMS, Duncan AM.","doi":"10.1093/jn/nxab323","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34877772","title":"The efficacy of powered toothbrushes: A systematic review and network meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/34877772/","year":"2022","role":"Pooled research","what_it_shows":"Pooled single-brushing studies found slightly greater plaque removal with a powered toothbrush. This specific finding concerns immediate plaque removal.","authors":"Thomassen TMJA, Van der Weijden FGA, Slot DE.","doi":"10.1111/idh.12563","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35129580","title":"Effect of Sleep Extension on Objectively Assessed Energy Intake Among Adults With Overweight in Real-life Settings: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/35129580/","year":"2022","role":"Controlled trial","what_it_shows":"Individualized counseling increased measured sleep duration and reduced energy intake over two weeks in short-sleeping adults with overweight. Both results came from the same trial.","authors":"Tasali E, Wroblewski K, Kahn E, Kilkus J, Schoeller DA.","doi":"10.1001/jamainternmed.2021.8098","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35210284","title":"Efficacy of a meal sequence in patients with type 2 diabetes: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35210284/","year":"2022","role":"Limitation, later time point","what_it_shows":"In eight trials in people with type 2 diabetes there was little clear difference in two-hour plasma glucose or HbA1c. Retain as a limit on interpreting the earlier post-meal changes.","authors":"Okami Y, Tsunoda H, Watanabe J, Kataoka Y.","doi":"10.1136/bmjdrc-2021-002534","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35301135","title":"Sleep Positional Therapy for Nocturnal Gastroesophageal Reflux: A Double-Blind, Randomized, Sham-Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/35301135/","year":"2022","role":"Controlled trial","what_it_shows":"A wearable device encouraged left-side sleep for two weeks. Nighttime reflux symptoms improved relative to a sham device.","authors":"Schuitenmaker JM, Kuipers T, Oude Nijhuis RAB, Schijven MP, Smout AJPM, Fockens P, Bredenoord AJ.","doi":"10.1016/j.cgh.2022.02.058","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35445655","title":"The effect of hand hygiene frequency on reducing acute respiratory infections in the community: a meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35445655/","year":"2022","role":"Inconclusive frequency analysis","what_it_shows":"A model of six community studies estimated a 3% reduction in daily infection probability per extra hand-hygiene event. Even its 80% credible interval included no difference. This cannot support a precise risk reduction or a wash duration.","authors":"Mo Y, Pham TM, Lim C, Horby P, Stewardson AJ, Harbarth S, Scott GM, Cooper BS.","doi":"10.1017/s0950268822000516","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35512731","title":"Taking a One-Week Break from Social Media Improves Well-Being, Depression, and Anxiety: A Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/35512731/","year":"2022","role":"Controlled trial","what_it_shows":"One week away from selected social media platforms improved a wellbeing score compared with usual use. Follow-up was short.","authors":"Lambert J, Barnstable G, Minter E, Cooper J, McEwan D.","doi":"10.1089/cyber.2021.0324","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35816465","title":"The Effect of Fiber Supplementation on Chronic Constipation in Adults: An Updated Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/35816465/","year":"2022","role":"Direct psyllium subgroup","what_it_shows":"In the psyllium subgroup, bowel frequency increased by about 3.08 per week, with a wide 95% interval of 0.61 to 5.54 and substantial variation. The overall fiber response rate cannot be attributed to psyllium alone.","authors":"van der Schoot A, Drysdale C, Whelan K, Dimidi E.","doi":"10.1093/ajcn/nqac184","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"35945000","title":"Effects of salt substitutes on clinical outcomes: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35945000/","year":"2022","role":"Pooled research","what_it_shows":"Trials of potassium-enriched salt substitutes found lower systolic and diastolic pressure relative to regular salt.","authors":"Yin X, Rodgers A, Perkovic A, Huang L, Li KC, Yu J, Wu Y, Wu JHY, Marklund M, Huffman MD, Miranda JJ, Miranda JJ, Di Tanna GL, Labarthe D, Elliott P, Tian M, Neal B.","doi":"10.1136/heartjnl-2022-321332","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"36000763","title":"Listening to music for insomnia in adults.","url":"https://pubmed.ncbi.nlm.nih.gov/36000763/","year":"2022","role":"Pooled research","what_it_shows":"A Cochrane review found better perceived sleep quality among adults with insomnia symptoms. Objective sleep measurements were less conclusive.","authors":"Jespersen KV, Pando-Naude V, Koenig J, Jennum P, Vuust P.","doi":"10.1002/14651858.cd010459.pub3","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"36537785","title":"Consumption of 2 Green Kiwifruits Daily Improves Constipation and Abdominal Comfort-Results of an International Multicenter Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/36537785/","year":"2023","role":"Direct, change from baseline","what_it_shows":"Adults with functional constipation or IBS with constipation reported about 1.5–1.7 more complete spontaneous bowel movements per week than at baseline on two green kiwifruit daily. Overall gastrointestinal comfort also improved.","authors":"Gearry R, Fukudo S, Barbara G, Kuhn-Sherlock B, Ansell J, Blatchford P, Eady S, Wallace A, Butts C, Cremon C, Barbaro MR, Pagano I, Okawa Y, Muratubaki T, Okamoto T, Fuda M, Endo Y, Kano M, Kanazawa M, Nakaya N, Nakaya K, Drummond L.","doi":"10.14309/ajg.0000000000002124","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Primary study"},{"source_id":"36562267","title":"Efficacy of power-driven interdental cleaning tools: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/36562267/","year":"2023","role":"Direct, adjunct to brushing","what_it_shows":"Trials in adults with gingivitis found less bleeding between teeth with powered interdental cleaning plus brushing than with brushing alone. Floss gave a comparable result.","authors":"Edlund P, Bertl K, Pandis N, Stavropoulos A.","doi":"10.1002/cre2.691","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"36630953","title":"Brief structured respiration practices enhance mood and reduce physiological arousal.","url":"https://pubmed.ncbi.nlm.nih.gov/36630953/","year":"2023","role":"Direct, short-term mood","what_it_shows":"In a month-long remote randomized study, brief breathwork, especially exhale-focused cyclic sighing, improved positive mood more than the meditation comparison. The schedule was five minutes daily.","authors":"Balban MY, Neri E, Kogon MM, Weed L, Nouriani B, Jo B, Holl G, Zeitzer JM, Spiegel D, Huberman AD.","doi":"10.1016/j.xcrm.2022.100895","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"36728338","title":"Breaking Up Prolonged Sitting to Improve Cardiometabolic Risk: Dose-Response Analysis of a Randomized Crossover Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/36728338/","year":"2023","role":"Direct light-walk schedules","what_it_shows":"In 11 adults, light walks interrupted laboratory sitting and lowered same-day systolic pressure. Figure 3 supports fatigue and mood findings for the five-minute light-walk schedules. Preserve the separate moderate-walk citation.","authors":"Duran AT, Friel CP, Serafini MA, Ensari I, Cheung YK, Diaz KM.","doi":"10.1249/mss.0000000000003109","review_basis":"Abstract and full-text results, Figure 3","publication_type":"Primary study"},{"source_id":"36870101","title":"The effect of caffeine on subsequent sleep: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/36870101/","year":"2023","role":"Pooled research","what_it_shows":"The review found less sleep after caffeine. Its beverage-specific cutoff estimates are modeled and cannot establish a safe cutoff for a 400 mg dose.","authors":"Gardiner C, Weakley J, Burke LM, Roach GD, Sargent C, Maniar N, Townshend A, Halson SL.","doi":"10.1016/j.smrv.2023.101764","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37121242","title":"Effectiveness of handwashing with soap for preventing acute respiratory infections in low-income and middle-income countries: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/37121242/","year":"2023","role":"Pooled research","what_it_shows":"Handwashing-with-soap promotion programs reduced respiratory infections in low- and middle-income settings. The review evaluates programs rather than one wash duration.","authors":"Ross I, Bick S, Ayieko P, Dreibelbis R, Wolf J, Freeman MC, Allen E, Brauer M, Cumming O.","doi":"10.1016/s0140-6736(23)00021-1","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37247191","title":"Impact on facial skin aging signs of a 1-year standardized photoprotection over a classical skin care routine in skin phototypes II-VI individuals: A prospective randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/37247191/","year":"2023","role":"Related, one-year result","what_it_shows":"Among 290 Brazilian women, twice-daily SPF 60 slowed progression of some facial aging signs versus usual care over one year. Cite only for that timeframe and regimen.","authors":"Flament F, Mercurio DG, Catalan E, Bouhadanna E, Delaunay C, Miranda DF, Passeron T.","doi":"10.1111/jdv.19230","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"37458579","title":"Randomized controlled trial on occupational graduated compression clinical and cost-effectiveness.","url":"https://pubmed.ncbi.nlm.nih.gov/37458579/","year":"2023","role":"Direct, occupational swelling","what_it_shows":"Graduated stockings countered increases in lower-leg volume in healthcare workers on standing shifts. Seventy-two participants completed data collection. The flight-clot outcome was outside this study.","authors":"Gianesini S, Vagnoni E, Cavicchi C, Chi YW, Pagani A, Tessari M, Zamboni P, Menegatti E.","doi":"10.23736/s0392-9590.23.05030-7","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"37969463","title":"Left lateral decubitus sleeping position is associated with improved gastroesophageal reflux disease symptoms: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/37969463/","year":"2023","role":"Overlapping review","what_it_shows":"The review found evidence linking left-side position to lower acid exposure and summarized the same device trial that reported symptom relief. It adds context without providing another independent device trial.","authors":"Simadibrata DM, Lesmana E, Amangku BR, Wardoyo MP, Simadibrata M.","doi":"10.12998/wjcc.v11.i30.7329","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"38305252","title":"Skeletal site-specific effects of jump training on bone mineral density in adults: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/38305252/","year":"2023","role":"Pooled research","what_it_shows":"Across jump programs, the clearest density improvement was at the femoral neck. The programs varied; the review does not establish fracture prevention.","authors":"Florence GE, Oosthuyse T, Bosch AN.","doi":"10.1080/02640414.2024.2312052","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"38494385","title":"The Effect of Progressive Muscle Relaxation Exercises on Sleep Quality in Cancer Patients Undergoing Chemotherapy: A Randomized Controlled Study.","url":"https://pubmed.ncbi.nlm.nih.gov/38494385/","year":"2024","role":"Direct, clinical population","what_it_shows":"Chemotherapy patients with poor sleep who practiced progressive muscle relaxation scored better on self-rated sleep than a usual-care group. The population limits extrapolation.","authors":"Sarı E, Gündogdu F, Semerci R.","doi":"10.1016/j.soncn.2024.151620","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"38569204","title":"Exercise snacks are a time-efficient alternative to moderate-intensity continuous training for improving cardiorespiratory fitness but not maximal fat oxidation in inactive adults: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/38569204/","year":"2024","role":"Tested schedule","what_it_shows":"The short stair-bout group improved peak oxygen uptake after six weeks. The paper also measured fat oxidation, which did not improve.","authors":"Yin M, Deng S, Chen Z, Zhang B, Zheng H, Bai M, Li H, Zhang X, Deng J, Liu Q, Little JP, Li Y.","doi":"10.1139/apnm-2023-0593","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"38612997","title":"Water Intake and Adiposity Outcomes among Overweight and Obese Individuals: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/38612997/","year":"2024","role":"Inconclusive water-specific result","what_it_shows":"Replacing sugary drinks with water was associated with an estimated 0.81 kg lower weight in the relevant subgroup. Its 95% interval ran from 1.66 kg lower to 0.03 kg higher and includes no difference.","authors":"Chen QY, Khil J, Keum N.","doi":"10.3390/nu16070963","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"39279635","title":"Consistent effect of eating rate on food and energy intake across twenty-four <i>ad libitum</i> meals.","url":"https://pubmed.ncbi.nlm.nih.gov/39279635/","year":"2024","role":"Related, different intervention","what_it_shows":"Researchers changed food texture to slow eating. Participants consumed less energy at those meals. This provides context for eating rate, while testing a different action from deliberately slowing down.","authors":"Heuven LAJ, van Bruinessen M, Tang CS, Stieger M, Lasschuijt MP, Forde CG.","doi":"10.1017/s0007114524001478","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39377163","title":"Dose and timing effects of caffeine on subsequent sleep: a randomized clinical crossover trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39377163/","year":"2025","role":"Direct dose–timing trial","what_it_shows":"Twenty-three men completed placebo and 100 mg or 400 mg conditions at 4, 8 or 12 hours before bed. The higher dose affected sleep initiation and architecture within 12 hours. No statistically clear disruption was detected with 100 mg.","authors":"Gardiner CL, Weakley J, Burke LM, Fernandez F, Johnston RD, Leota J, Russell S, Munteanu G, Townshend A, Halson SL.","doi":"10.1093/sleep/zsae230","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39808431","title":"Digital Meditation to Target Employee Stress: A Randomized Clinical Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39808431/","year":"2025","role":"Direct, tested prescription","what_it_shows":"In 1,458 stressed employees, assignment to an app providing ten minutes of daily meditation for eight weeks improved perceived stress compared with waiting list. Actual usage varied.","authors":"Radin RM, Vacarro J, Fromer E, Ahmadi SE, Guan JY, Fisher SM, Pressman SD, Hunter JF, Sweeny K, Tomiyama AJ, Hofschneider LT, Zawadzki MJ, Gavrilova L, Epel ES, Prather AA.","doi":"10.1001/jamanetworkopen.2024.54435","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39985031","title":"Smartphone screen time reduction improves mental health: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39985031/","year":"2025","role":"Direct, single sample","what_it_shows":"After three weeks, 111 students assigned to a daily two-hour phone cap or control differed on depressive symptoms, perceived stress, wellbeing and insomnia severity. The insomnia score differed by 2.59 points at the end. Several outcomes came from these same students.","authors":"Pieh C, Humer E, Hoenigl A, Schwab J, Mayerhofer D, Dale R, Haider K.","doi":"10.1186/s12916-025-03944-z","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"40038410","title":"The effects of social media abstinence on affective well-being and life satisfaction: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/40038410/","year":"2025","role":"Mixed findings","what_it_shows":"A systematic review of social-media breaks found no clear pooled benefit for positive affect, negative affect or life satisfaction. These related endpoints differ from the wellbeing scale of the one-week trial.","authors":"Lemahieu L, Vander Zwalmen Y, Mennes M, Koster EHW, Vanden Abeele MMP, Poels K.","doi":"10.1038/s41598-025-90984-3","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"40087042","title":"Effect of brief intense stair climbing on cardiorespiratory fitness and metabolic risk factors in inactive young men with obesity: A randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/40087042/","year":"2025","role":"Direct, single-session option","what_it_shows":"Young men with obesity completed a four-week vigorous stair program. Peak oxygen uptake improved relative to the pattern in controls. The study found no change in body composition or metabolic variables.","authors":"Han M, Yun J, Kuk JL, Lee S.","doi":"10.1016/j.numecd.2025.103902","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"40467388","title":"Optimisation of blinking exercises for dry eye disease.","url":"https://pubmed.ncbi.nlm.nih.gov/40467388/","year":"2025","role":"Direct, selected schedule","what_it_shows":"Short studies in adults with dry eye found fewer symptoms and incomplete blinks with the selected 15 close–squeeze–open repeats three times a day. Several objective tear-film measures showed no significant change.","authors":"Wolffsohn JS, Travé-Huarte S, Bahra I, Finch C, Anyaegbu U, Garcia-Porta N, Kingsnorth A.","doi":"10.1016/j.clae.2025.102453","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"40627390","title":"A meta-analysis of the effectiveness of gratitude interventions on well-being across cultures.","url":"https://pubmed.ncbi.nlm.nih.gov/40627390/","year":"2025","role":"Related, broader intervention","what_it_shows":"Across 163 samples, diverse gratitude exercises produced a small average wellbeing improvement. This estimate includes many exercises and should not be presented as the effect of writing three good things.","authors":"Choi H, Cha Y, McCullough ME, Coles NA, Oishi S.","doi":"10.1073/pnas.2425193122","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"40944180","title":"Blood Lipid Levels in Response to Almond Consumption: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/40944180/","year":"2025","role":"Direct pooled result","what_it_shows":"In 36 publications, daily almonds lowered LDL by about 5 mg/dL, total cholesterol by about 6 mg/dL, and ApoB by about 4.5 mg/dL relative to controls across varying amounts.","authors":"Musa-Veloso K, Gauntlett C, Geronimo K, Vicente I, Ho SPL.","doi":"10.3390/nu17172791","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"41633054","title":"Progressive muscle relaxation technique improves sleep quality and mental health: A systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/41633054/","year":"2026","role":"Pooled research","what_it_shows":"Another synthesis found better sleep quality after progressive muscle relaxation. Trial effects varied substantially, and the two reviews may include the same participants.","authors":"Donato KO, Falcão L, Nishizima A, Oliveira AS, Gonzalez JV, Ribeiro NN, Abbud C, Braga GA, Garrido G, Donato AO, Eckeli A, Cruz MME, Salles C.","doi":"10.1016/j.jpsychores.2026.112563","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"41922197","title":"The Optimal Dosage of Isometric Handgrip Exercise for Blood Pressure Reduction: Systematic Review and Meta-Analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/41922197/","year":"2026","role":"Direct pooled result","what_it_shows":"In 31 studies, systolic and diastolic pressure were lower by about 5.4 and 2.7 mmHg on average. Results differed markedly across studies. The four-set protocol is an evidence-informed example.","authors":"Lin CW, Jun IB, Igbo V, Babaniamansour A, Meng L, Lin CF, Jan YK.","doi":"10.1111/jch.70246","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42045803","title":"The Impact of Macronutrient Ordering on Postprandial Glycaemic Control in Diabetes: A Systematic Review.","url":"https://pubmed.ncbi.nlm.nih.gov/42045803/","year":"2026","role":"Pooled research","what_it_shows":"Studies in diabetes suggest smaller post-meal glucose excursions when carbohydrates come last. Heterogeneity and low certainty limit the inference.","authors":"McKenzie R, Sterling C, O'Hara H, Woodside J.","doi":"10.1002/edm2.70228","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42054579","title":"Single-session volunteering reduces loneliness in older adults: immediate and long-term effects.","url":"https://pubmed.ncbi.nlm.nih.gov/42054579/","year":"2026","role":"Direct, structured session","what_it_shows":"In a trial of 76 older adults, participants who helped nursing-home residents reported less loneliness within a day. The effect persisted at one month. The participants volunteered within a structured program.","authors":"Niu CC, Wu K, Yu J.","doi":"10.1093/geront/gnag083","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"42070794","title":"The Acute Effects of Interrupting Prolonged Sitting With Regular Activity Breaks on Postprandial Glucose and Insulin in Adults: A Systematic Review and Meta-Analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42070794/","year":"2026","role":"Direct pooled result","what_it_shows":"Across 39 pooled studies, activity breaks reduced the post-meal glucose and insulin response. Walking showed the largest subgroup effects. The comparison between break frequencies does not establish a uniquely best schedule.","authors":"Gale JT, Martin H, Haszard JJ, Peddie MC.","doi":"10.1111/obr.70152","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42127076","title":"The impact of walking on creative thinking: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42127076/","year":"2026","role":"Pooled research","what_it_shows":"Walking improved scores on idea-generation tasks, mostly in student samples. Results for convergent problem solving were uncertain.","authors":"Thabane A, Arora V, Boilard J, Sutoski A, Parpia S, Calic G, Busse JW, McKechnie T, Staibano P, Phillips M, Reiter-Palmon R, Bhandari M.","doi":"10.1371/journal.pone.0347878","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42405260","title":"The optimal dose of brisk walking for improving blood pressure in hypertensive patients: a systematic review and bayesian meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42405260/","year":"2026","role":"Direct pooled result","what_it_shows":"Across 17 trials in adults with hypertension, both pressure measures fell. The full paper reports a pooled diastolic difference of −4.67 mmHg (95% CI −6.26 to −3.08). Its suggested optimal dose was modeled across trials.","authors":"Wang J, Ma L, Lin Q, Yin Y.","doi":"10.7717/peerj.21478","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"42545422","title":"The effect of water immersion thermotherapy on sleep quality: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42545422/","year":"2026","role":"Mixed findings","what_it_shows":"A newer synthesis of immersion trials found no significant improvement in sleep latency. It is included because it qualifies the earlier positive result.","authors":"Chen H, Gao S, Chen W, Gao B.","doi":"10.1007/s00484-026-03281-7","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42586449","title":"Effects of short-bout accumulated exercise on postprandial metabolism in adults: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42586449/","year":"2026","role":"Supporting subgroup","what_it_shows":"Short bouts of accumulated activity reduced post-meal glucose and insulin versus sitting in 29 cohorts. Walking and shorter intervals appeared beneficial in exploratory subgroup analyses. Timing was not compared with a formal interaction test.","authors":"Gong J, Tan L, Wang Y, Yan J, Li Y.","doi":"10.1016/j.ctim.2026.103416","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42625730","title":"The effects of progressive muscle relaxation on sleep quality in adults: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42625730/","year":"2026","role":"Direct, clinical populations","what_it_shows":"Across 14 trials, self-rated sleep improved on average with relaxation. Trial effects varied widely. Table 1 includes a 30-minute twice-weekly program for eight weeks in people with lung cancer and a 40-minute three-times-weekly program for six weeks in women with breast cancer.","authors":"Li K, Chen S, Liu Y, Yu N.","doi":"10.3389/fpubh.2026.1906525","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"42627002","title":"Effects of breaking up prolonged sitting with light-intensity walking on postprandial glucose and lipid responses in sedentary adult men.","url":"https://pubmed.ncbi.nlm.nih.gov/42627002/","year":"2026","role":"Direct result and interval","what_it_shows":"Sixteen sedentary men completed five-hour test-drink conditions. Two-minute walks every 30 minutes reduced glucose exposure by 6.4% and insulin by 18.2% versus sitting. The three-hour app window is an adaptation.","authors":"Kim D, Kim E.","doi":"10.1080/02640414.2026.2722777","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"42743912","title":"Whole-grain consumption and cardiometabolic risk: a meta-analysis of randomized trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42743912/","year":"2026","role":"Pooled research","what_it_shows":"The review separately reports a small decrease in total cholesterol and LDL per 48 g/day of whole grains. Certainty differs between those outcomes.","authors":"Naghshi S, Kiani S, Ostadrahimi A, Jayedi A, Mobasseri M, Arefhosseini S, Tutunchi H, Aune D.","doi":"10.1093/eurheartj/ehag519","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42947012","title":"Effect of resistance, balance, and aerobic training on strength, mobility, balance, and quality of life in older adults with sarcopenia: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/42947012/","year":"2026","role":"Direct, varied exercise programs","what_it_shows":"Twelve trials involving 652 adults with sarcopenia found gains in strength and walking speed with exercise. The study table includes resistance exercise twice weekly for 12 weeks and combined resistance and aerobic exercise three times weekly for 12 weeks.","authors":"Alsubaie SF, Nambi G.","doi":"10.1186/s12877-026-08020-6","review_basis":"Publication abstract and relevant full-text results or methods","publication_type":"Review"},{"source_id":"8824651","title":"Effects of psyllium therapy on stool characteristics, colon transit and anorectal function in chronic idiopathic constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/8824651/","year":"1995","role":"Controlled trial","what_it_shows":"Adults with chronic constipation received psyllium or placebo for eight weeks. Stool frequency and consistency improved during psyllium treatment.","authors":"Ashraf W, Park F, Lof J, Quigley EM.","doi":"10.1111/j.1365-2036.1995.tb00433.x","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"9099655","title":"A clinical trial of the effects of dietary patterns on blood pressure. DASH Collaborative Research Group.","url":"https://pubmed.ncbi.nlm.nih.gov/9099655/","year":"1997","role":"Direct feeding trial","what_it_shows":"With sodium intake and body weight held constant, participants assigned the DASH combination diet saw greater reductions in systolic and diastolic pressure than those on the control diet.","authors":"Appel LJ, Moore TJ, Obarzanek E, Vollmer WM, Svetkey LP, Sacks FM, Bray GA, Vogt TM, Cutler JA, Windhauser MM, Lin PH, Karanja N.","doi":"10.1056/nejm199704173361601","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"FALL","title":"Environmental interventions for preventing falls in older people living in the community","url":"https://www.cochrane.org/evidence/CD013258_reducing-fall-hazards-within-environment","year":"2023","role":"Pooled research","what_it_shows":"Home assessment and actual hazard reduction reduced the rate of falls in higher-risk older adults living in the community. The effect differed by baseline risk.","authors":"","doi":"","review_basis":"Cochrane evidence summary","publication_type":"Review"},{"source_id":"NICE","title":"Urinary incontinence and pelvic organ prolapse in women: management, section 1.4","url":"https://www.nice.org.uk/guidance/ng123/chapter/recommendations","year":"2019","role":"Instruction guideline","what_it_shows":"Sections 1.4.4–1.4.5 recommend at least three months of supervised training for women with stress or mixed incontinence and at least eight contractions three times daily. This is guidance on the program rather than an independent effect estimate.","authors":"","doi":"","review_basis":"Guideline recommendations","publication_type":"Guideline"},{"source_id":"CDC-HANDWASH","title":"Hand Hygiene Frequently Asked Questions","url":"https://www.cdc.gov/clean-hands/faq/index.html","year":"2024","role":"Instruction source","what_it_shows":"CDC explains how to scrub all hand surfaces with soap for at least 20 seconds. This source supplies the technique.","authors":"","doi":"","review_basis":"Public guidance","publication_type":"Guideline"},{"source_id":"25574172","title":"Process Evaluation of Workplace Interventions with Physical Exercise to Reduce Musculoskeletal Disorders","url":"https://pubmed.ncbi.nlm.nih.gov/25574172/","year":"2014","role":"Instruction source","what_it_shows":"The companion report describes the same workplace intervention, including technique, progression, and sets for the two-minute and twelve-minute options.","authors":"","doi":"10.1155/2014/761363","review_basis":"Published exercise methods","publication_type":"Companion methods report"},{"source_id":"36715875","title":"After Dinner Rest a While, After Supper Walk a Mile? A Systematic Review with Meta-analysis on the Acute Postprandial Glycemic Response to Exercise Before and After Meal Ingestion in Healthy Subjects and Patients with Impaired Glucose Tolerance.","url":"https://pubmed.ncbi.nlm.nih.gov/36715875/","year":"2023","role":"Timing review","what_it_shows":"Acute studies generally favored exercising after eating for glucose. Exercise types and schedules varied. This review cannot establish the three-hour break schedule or the type 2 diabetes trial’s specific comparison.","authors":"Engeroff T, Groneberg DA, Wilke J.","doi":"10.1007/s40279-022-01808-7","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"19394473","title":"Almonds have a neutral effect on serum lipid profiles: a meta-analysis of randomized trials.","url":"https://pubmed.ncbi.nlm.nih.gov/19394473/","year":"2009","role":"Earlier, less precise review","what_it_shows":"An earlier synthesis found lower total cholesterol and a borderline LDL estimate whose interval reached zero. The later, larger synthesis provides the card’s modest LDL estimate. Their evidence bases can overlap.","authors":"Phung OJ, Makanji SS, White CM, Coleman CI.","doi":"10.1016/j.jada.2009.02.014","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"24235903","title":"Caffeine effects on sleep taken 0, 3, or 6 hours before going to bed.","url":"https://pubmed.ncbi.nlm.nih.gov/24235903/","year":"2013","role":"Earlier controlled timing study","what_it_shows":"The study tested 400 mg at bedtime or three or six hours beforehand. Sleep was disrupted versus placebo even six hours before bed. The separate 12-hour finding comes from the later trial.","authors":"Drake C, Roehrs T, Shambroom J, Roth T.","doi":"10.5664/jcsm.3170","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41212331","title":"Optimal resistance training prescriptions to improve muscle strength, physical function, and muscle mass in older adults diagnosed with sarcopenia: a systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/41212331/","year":"2025","role":"Resistance-specific evidence","what_it_shows":"Across 24 trials in 951 older adults with sarcopenia, resistance exercise improved several strength and function measures. Average grip-strength and gait-speed improvements fell below the review’s thresholds for clinically important change.","authors":"Yan R, Chen Y, Zhang R, He J, Lin W, Sun J, Li D.","doi":"10.1007/s40520-025-03235-w","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34569129","title":"The effect of progressive muscle relaxation on sleep quality and fatigue in patients with rheumatoid arthritis: A randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/34569129/","year":"2023","role":"Primary trial in a clinical population","what_it_shows":"People with rheumatoid arthritis assigned to six weeks of progressive muscle relaxation reported better sleep quality than controls. This is a primary example within a field already covered by reviews.","authors":"Kılıç N, Parlar Kılıç S.","doi":"10.1111/ijn.13015","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"39879231","title":"Effects of cold-water immersion on health and wellbeing: A systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/39879231/","year":"2025","role":"Review reusing the sick-leave trial","what_it_shows":"The review’s 29% lower sickness absence figure comes from the original shower trial. It provides no second independent test of that result. Other cold-immersion protocols answer different questions.","authors":"Cain T, Brinsley J, Bennett H, Nelson M, Maher C, Singh B.","doi":"10.1371/journal.pone.0317615","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"41837403","title":"Effects of meal sequence intervention on blood glucose response in healthy adults: a systematic review.","url":"https://pubmed.ncbi.nlm.nih.gov/41837403/","year":"2026","role":"Healthy-adult evidence","what_it_shows":"A review in healthy adults found that most studies reported a smaller acute glucose excursion when vegetables, fruit or protein preceded carbohydrates. The short feeding studies used several meal sequences.","authors":"Kim J, Jang EH, Lee S.","doi":"10.7762/cnr.2025.0027","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"21147704","title":"Kiwifruit improves bowel function in patients with irritable bowel syndrome with constipation.","url":"https://pubmed.ncbi.nlm.nih.gov/21147704/","year":"2010","role":"Related bowel-frequency outcome","what_it_shows":"In adults with constipation-predominant IBS, bowel movement frequency increased after four weeks of kiwifruit. This study measured defecation frequency, a broader outcome than complete spontaneous bowel movements.","authors":"Chang CC, Lin YT, Lu YT, Liu YS, Liu JF.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"17634169","title":"Pinto bean consumption reduces biomarkers for heart disease risk.","url":"https://pubmed.ncbi.nlm.nih.gov/17634169/","year":"2007","role":"Independent trial with a different portion","what_it_shows":"Sixteen adults with mild insulin resistance tried half a cup of pinto beans, black-eyed peas or carrots for eight weeks per condition. LDL fell more with pinto beans than carrots. The one-cup canned-bean card uses a different trial and comparator.","authors":"Winham DM, Hutchins AM, Johnston CS.","doi":"10.1080/07315724.2007.10719607","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"1964898","title":"Can eating baked beans lower plasma cholesterol?","url":"https://pubmed.ncbi.nlm.nih.gov/1964898/","year":"1990","role":"Different bean preparation and outcome","what_it_shows":"In 20 men with mildly high cholesterol, canned baked beans versus canned spaghetti did not clearly lower plasma total cholesterol. The abstract does not give an LDL result. This limits generalization to other canned products.","authors":"Cobiac L, McArthur R, Nestel PJ.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41578335","title":"Comparative effects of salt substitutes on blood pressure, cardiovascular events and mortality: a systematic review and network meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/41578335/","year":"2026","role":"Broader review with overlapping trials","what_it_shows":"Across 34 trials, some potassium-enriched formulations probably lowered systolic pressure. Cardiovascular event evidence was dominated by one large Chinese trial. Do not count the stroke trial twice.","authors":"Lai H, Nesrallah G, Guyatt GH, Vernooij RWM, Liu J, Zhao W, Hou L, Pan B, Huang J, Campbell NRC, Tian J, Yang K, Ge L, Johnston BC.","doi":"10.1186/s12916-026-04635-z","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"26269373","title":"Whole-grain and blood lipid changes in apparently healthy adults: a systematic review and meta-analysis of randomized controlled studies.","url":"https://pubmed.ncbi.nlm.nih.gov/26269373/","year":"2015","role":"Earlier pooled comparison","what_it_shows":"Whole-grain diets modestly lowered LDL and total cholesterol compared with non-whole-grain controls. The trial pool overlaps the period covered by the newer review.","authors":"Hollænder PL, Ross AB, Kristensen M.","doi":"10.3945/ajcn.115.109165","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"24749966","title":"Give your ideas some legs: the positive effect of walking on creative thinking.","url":"https://pubmed.ncbi.nlm.nih.gov/24749966/","year":"2014","role":"Primary experimental example","what_it_shows":"Four experiments compared walking and sitting on idea-generation tasks. Walking improved creative ideation during or shortly after activity. The result depended on the task.","authors":"Oppezzo M, Schwartz DL.","doi":"10.1037/a0036577","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"21387981","title":"The effect of different interdental cleaning devices on gingival bleeding.","url":"https://pubmed.ncbi.nlm.nih.gov/21387981/","year":"2011","role":"Different active comparator","what_it_shows":"After four weeks, two oral-irrigator groups had less gingival bleeding than a floss group with manual brushing. This does not duplicate the brushing-alone comparison.","authors":"Rosema NA, Hennequin-Hoenderdos NL, Berchier CE, Slot DE, Lyle DM, van der Weijden GA.","doi":"","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"31050195","title":"How effective is a powered toothbrush as compared to a manual toothbrush? A systematic review and meta-analysis of single brushing exercises.","url":"https://pubmed.ncbi.nlm.nih.gov/31050195/","year":"2020","role":"Overlapping review","what_it_shows":"An earlier review of single-brushing comparisons favored powered brushes over manual brushes for plaque removal. Trials can overlap with the later review.","authors":"Elkerbout TA, Slot DE, Rosema NAM, Van der Weijden GA.","doi":"10.1111/idh.12401","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"35389685","title":"Finding the \"sweet spot\" of smartphone use: Reduction or abstinence to increase well-being and healthy lifestyle?! An experimental intervention study.","url":"https://pubmed.ncbi.nlm.nih.gov/35389685/","year":"2023","role":"Different reduction target","what_it_shows":"An experiment reducing daily smartphone use by one hour found improvements in depressive symptoms and wellbeing. It used a relative reduction rather than a two-hour daily cap and does not validate the card’s insomnia score.","authors":"Brailovskaia J, Delveaux J, John J, Wicker V, Noveski A, Kim S, Schillack H, Margraf J.","doi":"10.1037/xap0000430","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"22451457","title":"Compression hosiery for occupational leg symptoms and leg volume: a randomized crossover trial in a cohort of hairdressers.","url":"https://pubmed.ncbi.nlm.nih.gov/22451457/","year":"2013","role":"Independent occupational crossover trial","what_it_shows":"In 108 hairdressers randomized to low-strength stockings and no-compression periods, lower-leg volume averaged 19 mL less with stockings. Symptoms also improved. This supports the swelling result in a second standing occupation.","authors":"Blazek C, Amsler F, Blaettler W, Keo HH, Baumgartner I, Willenberg T.","doi":"10.1258/phleb.2011.011108","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"36724699","title":"The effectiveness and equivalence of different versions of a brief online Best Possible Self (BPS) manipulation to temporary increase optimism and affect.","url":"https://pubmed.ncbi.nlm.nih.gov/36724699/","year":"2023","role":"Different practice duration","what_it_shows":"An online study compared versions of best-possible-self practice. Writing and imagery produced similar immediate improvements in optimism. It did not test how long the effect lasts.","authors":"Boselie JJLM, Vancleef LMG, van Hooren S, Peters ML.","doi":"10.1016/j.jbtep.2023.101837","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"29073407","title":"Restricted use of electronic media, sleep, performance, and mood in high school athletes--a randomized trial.","url":"https://pubmed.ncbi.nlm.nih.gov/29073407/","year":"2015","role":"Null result in a different population","what_it_shows":"A four-week restriction on electronic media after 10 pm did not improve sleep habits in high-school athletes who already slept well. The rule, population and baseline sleep differed from the card trial.","authors":"Harris A, Gundersen H, Mørk-Andreassen P, Thun E, Bjorvatn B, Pallesen S.","doi":"10.1016/j.sleh.2015.09.011","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41668954","title":"Evening smartphone exposure impairs sleep quality and next-day performance in elite soccer players: a randomized controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/41668954/","year":"2026","role":"Different exposure and comparison","what_it_shows":"Sixteen male elite soccer players compared two hours of pre-bed smartphone exposure with magazine reading. Sleep quality worsened during phone exposure. This does not establish the effects of a 30-minute cutoff on onset or bedtime arousal.","authors":"Dridi N, Souissi MA, Dridi R, Ceylan Hİ, Bragazzi NL, Salem A, Fekih S, Chtara M, Mkaouer B, Chtourou H, Dergaa I, Souissi N, Stefanica V, Żmijewski P, Morgans R.","doi":"10.5114/biolsport.2026.152348","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"23271615","title":"Intake of whole apples or clear apple juice has contrasting effects on plasma lipids in healthy volunteers.","url":"https://pubmed.ncbi.nlm.nih.gov/23271615/","year":"2013","role":"Related whole-fruit comparison","what_it_shows":"In 23 healthy volunteers, clear apple juice produced higher LDL than whole apples in a four-week crossover study. The whole-apple portion was 550 g daily. This differs from the card’s population and matched drink.","authors":"Ravn-Haren G, Dragsted LO, Buch-Andersen T, Jensen EN, Jensen RI, Németh-Balogh M, Paulovicsová B, Bergström A, Wilcks A, Licht TR, Markowski J, Bügel S.","doi":"10.1007/s00394-012-0489-z","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35449537","title":"Metabolic and Cardiovascular Benefits of Apple and Apple-Derived Products: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/35449537/","year":"2022","role":"Mixed pooled evidence","what_it_shows":"Across trials of apples and apple-derived products, pooled LDL was 2.8 mg/dL lower, with a 95% interval from 5.78 lower to 0.17 higher. The overall result was inconclusive and the review mixed product forms.","authors":"Kim SJ, Anh NH, Jung CW, Long NP, Park S, Cho YH, Yoon YC, Lee EG, Kim M, Son EY, Kim TH, Deng Y, Lim J, Kwon SW.","doi":"10.3389/fnut.2022.766155","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"39855242","title":"The effects of volunteering on loneliness among lonely older adults: the HEAL-HOA dual randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/39855242/","year":"2025","role":"Independent longer volunteering program","what_it_shows":"Older volunteers in a structured telephone program reported less loneliness than controls after a sustained intervention. Most effects were not sustained at later follow-up. This does not test one nursing-home visit.","authors":"Yeung DY, Jiang D, Warner LM, Choi NG, Ho RTH, Kwok JYY, Chou KL.","doi":"10.1016/j.lanhl.2024.100664","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"41366295","title":"Psyllium supplementation and lipid profiles: systematic review and dose-response meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/41366295/","year":"2025","role":"Later lipid review","what_it_shows":"A later synthesis also found lower LDL and total cholesterol with psyllium. It may reuse trials in the earlier review and offers no additional evidence on constipation.","authors":"Gholami Z, Paknahad Z.","doi":"10.1186/s12263-025-00786-5","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"SPACED-2021","title":"A Meta-Analytic Review of the Benefit of Spacing out Retrieval Practice Episodes on Retention","url":"https://doi.org/10.1007/s10648-020-09572-8","year":"2021","role":"Review of combined practice","what_it_shows":"A review of 29 studies found better later retention when retrieval sessions were spaced rather than massed. This supports the combined learning approach. The specific two-week interval remains a trial example.","authors":"Latimier A, Peyre H, Ramus F.","doi":"10.1007/s10648-020-09572-8","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"11377600","title":"Frequency and prevention of symptomless deep-vein thrombosis in long-haul flights: a randomised trial.","url":"https://pubmed.ncbi.nlm.nih.gov/11377600/","year":"2001","role":"Primary flight trial","what_it_shows":"Screening after long-haul flights found symptomless calf clots in the no-stocking group and none in those wearing stockings. This early trial illustrates the review evidence and should not be counted on top of it.","authors":"Scurr JH, Machin SJ, Bailey-King S, Mackie IJ, McDonald S, Smith PD.","doi":"10.1016/s0140-6736(00)04645-6","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34408031","title":"Soap versus sanitiser for preventing the transmission of acute respiratory infections in the community: a systematic review with meta-analysis and dose-response analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/34408031/","year":"2021","role":"Mixed soap-specific findings","what_it_shows":"In one review, the three soap-and-water trials showed no clear respiratory infection reduction compared with control. Sanitiser results were clearer. The settings and number of soap trials differ from the larger handwashing-promotion review.","authors":"Hoffmann T, Bakhit M, Krzyzaniak N, Del Mar C, Scott AM, Glasziou P.","doi":"10.1136/bmjopen-2020-046175","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"26237305","title":"Efficacy of water preloading before main meals as a strategy for weight loss in primary care patients with obesity: RCT.","url":"https://pubmed.ncbi.nlm.nih.gov/26237305/","year":"2015","role":"Independent primary-care trial","what_it_shows":"Among 84 adults with obesity who received weight-management advice, 500 mL of water before main meals was associated with 1.3 kg more weight loss over 12 weeks than the attention control. The adjusted interval included no difference.","authors":"Parretti HM, Aveyard P, Blannin A, Clifford SJ, Coleman SJ, Roalfe A, Daley AJ.","doi":"10.1002/oby.21167","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35285920","title":"Association of Low- and No-Calorie Sweetened Beverages as a Replacement for Sugar-Sweetened Beverages With Body Weight and Cardiometabolic Risk: A Systematic Review and Meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/35285920/","year":"2022","role":"Water-specific subgroup","what_it_shows":"Three trials in this review evaluated water in place of sugary drinks. Evidence for body weight was rated low certainty. Findings for low-calorie sweetened drinks cannot be attributed to water.","authors":"McGlynn ND, Khan TA, Wang L, Zhang R, Chiavaroli L, Au-Yeung F, Lee JJ, Noronha JC, Comelli EM, Blanco Mejia S, Ahmed A, Malik VS, Hill JO, Leiter LA, Agarwal A, Jeppesen PB, Rahelic D, Kahleová H, Salas-Salvadó J, Kendall CWC, Sievenpiper JL.","doi":"10.1001/jamanetworkopen.2022.2092","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37217328","title":"\"Three Good Things\" Digital Intervention Among Health Care Workers: A Randomized Controlled Trial.","url":"https://pubmed.ncbi.nlm.nih.gov/37217328/","year":"2023","role":"Different schedule and outcomes","what_it_shows":"Healthcare workers were prompted three times weekly to name good things. Positive affect showed a small improvement. Life satisfaction and depressive symptoms did not clearly differ between groups. This differs from nightly writing about why events happened.","authors":"Gold KJ, Dobson ML, Sen A.","doi":"10.1370/afm.2963","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"34962055","title":"App-based mindfulness meditation reduces perceived stress and improves self-regulation in working university students: A randomised controlled trial.","url":"https://pubmed.ncbi.nlm.nih.gov/34962055/","year":"2022","role":"Independent student trial","what_it_shows":"Working university students assigned to an eight-week mindfulness app reported lower stress than wait-listed students. It supports perceived stress in a different sample.","authors":"Schulte-Frankenfeld PM, Trautwein FM.","doi":"10.1111/aphw.12328","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"30676671","title":"A randomized controlled trial of bedtime music for insomnia disorder.","url":"https://pubmed.ncbi.nlm.nih.gov/30676671/","year":"2019","role":"Mixed findings across sleep measures","what_it_shows":"In adults with insomnia, bedtime music improved perceived sleep on a secondary measure. The primary comparison on insomnia severity was inconclusive, and objective sleep measures showed no change.","authors":"Jespersen KV, Otto M, Kringelbach M, Van Someren E, Vuust P.","doi":"10.1111/jsr.12817","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"32660334","title":"Olfactory Training for Postviral Olfactory Dysfunction: Systematic Review and Meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/32660334/","year":"2021","role":"Postviral training review","what_it_shows":"Across four pooled studies, trained participants were more likely than controls to improve by a clinically important amount on an odor test. Training protocols varied.","authors":"Kattar N, Do TM, Unis GD, Migneron MR, Thomas AJ, McCoul ED.","doi":"10.1177/0194599820943550","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"42311058","title":"Olfactory Training for COVID-19-Related Olfactory Dysfunction: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/42311058/","year":"2026","role":"Post-COVID subgroup","what_it_shows":"Ten randomized trials in post-COVID smell loss found a small average improvement in objective smell scores. The finding applies to this postviral subgroup across varied protocols.","authors":"Albazee E, Aldawas G, Alzeeby M, Alebrahim AH, Alwael A.","doi":"10.4274/tao.2026.2026-3-27","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31988085","title":"Increased fluid intake to prevent urinary tract infections: systematic review and meta-analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/31988085/","year":"2020","role":"Broader recurrence review","what_it_shows":"A review of increased fluid intake found fewer recurrent urinary infections overall. At 12 months the difference in the proportion with any recurrence was inconclusive. It pools different fluid interventions and does not independently verify the card’s exact water dose.","authors":"Scott AM, Clark J, Mar CD, Glasziou P.","doi":"10.3399/bjgp20x708125","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37682412","title":"The Effect of Sitting Duration on Peripheral Blood Pressure Responses to Prolonged Sitting, With and Without Interruption: A Systematic Review and Meta-Analysis.","url":"https://pubmed.ncbi.nlm.nih.gov/37682412/","year":"2024","role":"Broader sitting-break evidence","what_it_shows":"Pooled laboratory studies found that interrupting prolonged sitting attenuated increases in blood pressure. The interventions varied. It does not establish mood changes or a particular walking schedule.","authors":"Adams NT, Paterson C, Poles J, Higgins S, Stoner L.","doi":"10.1007/s40279-023-01915-z","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"11322712","title":"The short-term benefits of brief and long naps following nocturnal sleep restriction.","url":"https://pubmed.ncbi.nlm.nih.gov/11322712/","year":"2001","role":"Related nap duration","what_it_shows":"After restricted sleep, ten minutes of afternoon sleep improved subjective alertness immediately. Some testing after a 30-minute nap showed early grogginess. Time asleep differs from a 15-minute opportunity to nap.","authors":"Tietzel AJ, Lack LC.","doi":"10.1093/sleep/24.3.293","review_basis":"Publication abstract","publication_type":"Primary study"},{"source_id":"35631184","title":"Effects of Oat Beta-Glucan Intake on Lipid Profiles in Hypercholesterolemic Adults: A Systematic Review and Meta-Analysis of Randomized Controlled Trials.","url":"https://pubmed.ncbi.nlm.nih.gov/35631184/","year":"2022","role":"Overlapping lipid review","what_it_shows":"A review in adults with high cholesterol found lower average LDL with oat beta-glucan. Dose, product and study duration varied, and earlier reviews may include the same trials.","authors":"Yu J, Xia J, Yang C, Pan D, Xu D, Sun G, Xia H.","doi":"10.3390/nu14102043","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"34140663","title":"Isometric handgrip exercise training reduces resting systolic blood pressure but does not interfere with diastolic blood pressure and heart rate variability in hypertensive subjects: a systematic review and meta-analysis of randomized clinical trials.","url":"https://pubmed.ncbi.nlm.nih.gov/34140663/","year":"2021","role":"Endpoint-specific uncertainty","what_it_shows":"Across trials in people with treated hypertension, handgrip training lowered resting systolic pressure, while the diastolic estimate was imprecise. Keep the diastolic result qualified.","authors":"Almeida JPAS, Bessa M, Lopes LTP, Gonçalves A, Roever L, Zanetti HR.","doi":"10.1038/s41440-021-00681-7","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"37736087","title":"Tai Chi for fall prevention and balance improvement in older adults: a systematic review and meta-analysis of randomized controlled trials.","url":"https://pubmed.ncbi.nlm.nih.gov/37736087/","year":"2023","role":"Broader fall prevention evidence","what_it_shows":"A pooled analysis favored tai chi for preventing falls in older adults across differing programs. Total falls and balance outcomes cannot be substituted for repeat falling on the card.","authors":"Chen W, Li M, Li H, Lin Y, Feng Z.","doi":"10.3389/fpubh.2023.1236050","review_basis":"Publication abstract","publication_type":"Review"},{"source_id":"31331557","title":"Device and non-device-guided slow breathing to reduce blood pressure: A systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/31331557/","year":"2019","role":"Pooled research","what_it_shows":"17 studies in people with hypertension or prehypertension. Slow breathing lowered systolic pressure by about 5.6 mmHg and diastolic by about 3.0 mmHg, with high heterogeneity between studies.","authors":"Chaddha A, Modaff D, Hooper-Lane C, Feldstein DA.","doi":"10.1016/j.ctim.2019.03.005","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Systematic review and meta-analysis"},{"source_id":"12119224","title":"Humming greatly increases nasal nitric oxide","url":"https://pubmed.ncbi.nlm.nih.gov/12119224/","year":"2002","role":"Mechanism study","what_it_shows":"In ten healthy volunteers, nasal nitric oxide was about 15 times higher while humming than during quiet exhalation. No health outcome was measured.","authors":"Weitzberg E, Lundberg JO.","doi":"10.1164/rccm.200203-232OC","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"27351677","title":"Acupuncture for the prevention of episodic migraine","url":"https://pubmed.ncbi.nlm.nih.gov/27351677/","year":"2016","role":"Pooled research","what_it_shows":"22 trials, 4,985 people with episodic migraine. Acupuncture reduced headache frequency compared with no acupuncture; the advantage over sham acupuncture was small (50% vs 41% responders). Moderate-quality evidence.","authors":"Linde K, Allais G, Brinkhaus B, Fei Y, Mehring M, Vertosick EA, Vickers A, White AR.","doi":"10.1002/14651858.CD001218.pub3","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Cochrane systematic review"},{"source_id":"32536366","title":"A randomized controlled study of weighted chain blankets for insomnia in psychiatric disorders","url":"https://pubmed.ncbi.nlm.nih.gov/32536366/","year":"2020","role":"Controlled trial","what_it_shows":"120 adults with insomnia and major depression, bipolar disorder, generalized anxiety or ADHD. After 4 weeks, a heavy chain blanket lowered insomnia severity more than a light one (large effect; 59% vs 5% responded). No serious adverse events.","authors":"Ekholm B, Spulber S, Adler M.","doi":"10.5664/jcsm.8636","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"PHYSBEH-2017-STAIRS","title":"Stair walking is more energizing than low dose caffeine in sleep deprived young women","url":"https://doi.org/10.1016/j.physbeh.2017.03.013","year":"2017","role":"Controlled trial","what_it_shows":"Crossover study in 18 chronically sleep-deprived college women. Ten minutes of low-to-moderate stair walking (about 30 floors) increased feelings of energy more than 50 mg caffeine or placebo. The effect was short-lived and attention and memory did not improve.","authors":"Randolph DD, O'Connor PJ.","doi":"10.1016/j.physbeh.2017.03.013","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"26444654","title":"The drawing effect: Evidence for reliable and robust memory benefits in free recall","url":"https://pubmed.ncbi.nlm.nih.gov/26444654/","year":"2016","role":"Experimental studies","what_it_shows":"Seven laboratory experiments, mostly with university students. Words that people drew were recalled better than words they wrote out.","authors":"Wammes JD, Meade ME, Fernandes MA.","doi":"10.1080/17470218.2015.1094494","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"30346317","title":"Implementation of a Defecation Posture Modification Device: Impact on Bowel Movement Patterns in Healthy Subjects","url":"https://pubmed.ncbi.nlm.nih.gov/30346317/","year":"2019","role":"Uncontrolled crossover study","what_it_shows":"Healthy volunteers logged bowel movements for two weeks without and two weeks with a toilet footstool. With the stool, they reported shorter time, less straining and more complete emptying. Healthy adults only; self-reported.","authors":"Modi RM, Hinton A, Pinkhas D, et al.","doi":"10.1097/MCG.0000000000001143","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"35554601","title":"Abdominal Massage in Functional Chronic Constipation: A Randomized Placebo-Controlled Trial","url":"https://pubmed.ncbi.nlm.nih.gov/35554601/","year":"2022","role":"Controlled trial","what_it_shows":"Adults with functional chronic constipation. Abdominal massage improved constipation severity and quality of life more than a placebo treatment over four weeks. The session schedule reported in reviews (10 minutes, three times weekly) was not checked against the full text.","authors":"Doğan IG, Gürşen C, Akbayrak T, et al.","doi":"10.1093/ptj/pzac058","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Primary study"},{"source_id":"39531948","title":"Effectiveness of abdominal massage on chronic constipation in adults: A systematic review and meta-analysis","url":"https://pubmed.ncbi.nlm.nih.gov/39531948/","year":"2025","role":"Pooled research","what_it_shows":"Pooled randomized trials in adults with chronic constipation. The authors concluded abdominal massage was effective; trials were small and varied in technique.","authors":"","doi":"","review_basis":"Abstract and journal summaries read through search; full text not opened in this pass","publication_type":"Systematic review and meta-analysis"}]}$catalog$::jsonb then
    raise exception 'Catalog version collision. Preserve the existing release and allocate a new version.';
  end if;
end $check$;
